window.__D("text/zohar/c009",{"p":[[9520011386,"<p>וַיֹּאמֶר יְהוּדָה לְאוֹנָן בֹּא אֶל אֵשֶׁת אָחִיךָ וְגו'. רִבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (ישעיהו מ״א:כ״ה) הַעִירוֹתִי מִצָּפוֹן וַיַּאֲת מִמִּזְרַח שֶׁמֶשׁ יִקְרָא בִשְׁמִי וְיָבֹא סְגָנִים כְּמוֹ חֹמֶר וּכְמוֹ יוֹצֵר יִרְמָס טִיט. תָּא חֲזֵי, כַּמָּה אִינוּן בְּנִי נָשָׁא טִפְּשִׁין דְּלָא יָדְעִין וְלָא מִסְתַּכְּלִין לְמִנְדַע אָרְחוֹי דְקוּדְשָׁא בְּרִיךְ הוּא. דְּהָא כֻּלְּהוּ נַיְימִין, דְּלָא מִתְעָרֵי שֵׁינְתָא בְּחוֹרֵיהוֹן.</p>\n<p>תָּא חֲזֵי, קוּדְשָׁא בְּרִיךְ הוּא עֲבַד לֵיהּ לְבַר נָשׁ, כְּגַוְונָא דִלְעֵילָא. כֹּלָּא אִיהוּ בְּחָכְמְתָא. דְּלֵית לָךְ שַׁיְיפָא וְשַׁיְיפָא בְּבַר נָשׁ דְּלָא קָיְימָא בְּחָכְמְתָא עִלָּאָה. דְּהָא כֵּיוָן דְּאִתְתַּקַּן כָּל גּוּפָא בְּשַׁיְיפוֹי כְּדְקָא יְאוּת, קוּדְשָׁא בְּרִיךְ הוּא אִשְׁתַּתַּף (נ\"א אתתקף) בַּהֲדֵיהּ, וְאָעִיל בֵּיהּ נִשְׁמָתָא קַדִּישָׁא. בְּגִין לְאוֹלָפָא לֵיהּ לְבַר נָשׁ לְמֵהַךְ בְּאָרְחוֹי דְּאוֹרַיְיתָא וּלְמִיטַר פִּקּוּדוֹי, בְּגִין דְּיִתְתַּקַּן בַּר נָשׁ כְּדְקָא יְאוּת.</p>\n<p>(ס\"א ובגין דא בעוד) (ובגין ס\"א ובעוד) דְּאִית בֵּיהּ נִשְׁמָתָא קַדִּישָׁא מִבָּעֵי לֵיהּ לְבַר נָשׁ לְאַסְגָּאָה דִּיוּקְנָא דְמַלְכָּא עִלָּאָה בְּעַלְמָא. וְרָזָא דָא, דְּהָא הַהוּא נָהָר דְּנָגִיד וְנָפִיק לָא פָּסְקָן מֵימוֹי לְעָלְמִין. וְעַל דָּא מִבָּעֵי לֵיהּ לְבַר נָשׁ דְּלָא יַפְסִיק נַהֲרָא וּמְקוֹרָא דִּילֵיהּ בְּהַאי עָלְמָא (גליון נה\"ר רמז לקיימא קדישא דחתים בבשריה, דאיהו דוגמא דההוא נה\"ר רזא דצדיק דאתחבר בצד\"ק כחדא לעילא, בגין כך בעי בר נש לתתא לאתחברא באתתיה בקדושה בגין דאתתקף ביה בההוא עלמא). וְכָל זִמְנָא דְּבַר נָשׁ לָא יַצְלַח בְּהַאי עַלְמָא (ס\"א ועל דא מבעי ליה לבר נש דלא יפסיק נהרא ומקורא דיליה בהאי עלמא, ואי לא) קוּדְשָׁא בְּרִיךְ הוּא עָקַר לֵיהּ וְנָטַע לֵיהּ בְּכַמָּה זִמְנִין כְּמִלְּקַדְּמִין.</p>\n<p>תָּא חֲזֵי, מַה כְּתִיב, הַעִירוֹתִי מִצָּפוֹן וַיַּאת. הַעִירוֹתִי, דָּא אִתְעֲרוּתָא דְּזִוּוּגָא דְּבַר נָשׁ בְּהַאי עַלְמָא, דְּאִיהוּ אִתְעֲרוּתָא מִסִּטְרָא דְצָפוֹן. וַיַאת, דָּא הִיא נִשְׁמָתָא קַדִּישָׁא דְּאַתְיָא מִלְּעֵילָא, וְקוּדְשָׁא בְּרִיךְ הוּא מְשַׁדֵּר לָהּ מִלְּעֵילָא. אַתְיָא בְּהַאי עַלְמָא וְעָאלַת בְּגוֹ בְּנֵי נָשָׁא כִּדְקָאֲמָרָן.</p>\n<p>מִמִּזְרַח שֶׁמֶשׁ, דָּא אֲתַר דְּהַהוּא נָהָר דְּנָגִיד וְנָפִיק דְּמִתַּמָּן נָפְקַת נִשְׁמָתָא וְאִתְנְהִירַת. וְיָבֹא סְגָנִים (כמו חמר) אִלֵּין אִינוּן חֵילִין דְּעָלְמָא דְּאַתְיָין בְּגִין (ס\"א בגו) הַהוּא אִתְעֲרוּתָא דְּנִשְׁמָתִין. כְּמוֹ חוֹמֶר, כְּגַוְונָא דְּאִתְעַר בַּר נָשׁ בְּגוּפָא.</p>\n<p>דְּהָא בְּגִין דָּא, קוּדְשָׁא בְּרִיךְ הוּא עָבִיד זִווּגִין וְאַטִּיל נִשְׁמָתִין בְּעַלְמָא, וְחַבְרוּתָא אִשְׁתַּכַּח לְעֵילָא וְתַתָּא וּמְקוֹרָא דְּכֹלָּא הוּא (ס\"א יהא) בָּרוּךְ. וּבְּגִין כָּךְ קוּדְשָׁא בְּרִיךְ הוּא עֲבַד לֵיהּ לְבַר נָשׁ בְּגִין לְאִשְׁתַּדָּלָא בְּאָרְחוֹי, וְלָא יַפְסִיק מְקוֹרֵיהּ וּמַבּוּעָא דִילֵיהּ לְעָלְמִין.</p>\n<p>וְכָל מַאן דְּפָסִיק מְקוֹרֵיהּ, (מתתא ומיבש ליה כביכול כאלו גרים ליה לאתפסקא לעילא, כדין (איוב י״ד:י״א) אזלו מים מני ים ונהר יחרב ויבש, הואיל ובר נש אתקם לתתא כדוגמא דלעילא, מאן דמקוריה ימיש מלמעבד פירין, כגון דין דלא בעא למיתב איתתא, או נסיב לה דאשתדל ולא יכיל, אלו דתרין הפכין אינון דא מדא, (או ס\"א ההוא) דימיש מלמעבד פירין, לית ליה תקנה לעולם. (קהלת א׳:ט״ו) מעוות לא יכול לתקון, בגין דלא בעא למיסב איתתא ולאשתדלא בפריה ורביה, וההוא דאשתדל ונסב איתתא ולא יכיל, דא מתתקן בפריקיה דקריב ליה דהוא אחוי, וההוא דמית בלא בנין) כַּד נָפִיק מֵהַאי עַלְמָא הַהוּא בַּר נָשׁ לָא עָאל בְּפַרְגּוֹדָא וְלָא נָטִיל חוּלַק בְּהַהוּא עַלְמָא (ונשמתיה לא אתכלילת באתר דכל נשמתין אתכלילו, ואתגזר דיוקניה מתמן. הדא הוא דכתיב, (ויקרא כ״ב:ג׳) ונכרתה הנפש ההיא מלפני, הואיל וכדין הוא, ברא ליה קודשא בריך הוא פריק דיפרוק ליה מידא דמחבלין, ודא אחוי דקריב ליה שנאמר (דברים כ״ה:ה׳) כי ישבו אחים יחדיו וגו'. וכתיב בא אל אשת אחיך ויבם אותה וגו'. בגין דנשמתיה לא עאלת קמיה קודשא בריך הוא, אלא היא קימא לבר. בגין דלא זכה לאנהרא בהאי עלמא בההוא גופא. מאן דלא זכה בהאי אתר, יהך לאתר אחרא ויזכי ביה. כגוונא דא אעא דדליק ונהורא לא סליק יבטשון ליה ויסלק נהורא ביה וינהיר. אעא הוא אדם דכתיב (שם כ) כי האדם עץ השדה. רצונו לומר בר נש כד איהו בהאי עלמא ואזל ותאיב ואכיל ושתי ואזדווג באיתתא ולא זכי לבנין. דא הוא אעא דדליק ונהורא לא סליק, כלומר נשמתיה לא זכאת בההוא גופא לאתנהרא אלא איהי בחשוכא). <Nonei></i>תָּא חֲזֵי, כְּתִיב, (ישעיהו מ״ה:י״ח) לֹא תֹהוּ בְּרָאָהּ לְשֶׁבֶת יְצָרָהּ, דְּקוּדְשָׁא בְּרִיךְ הוּא בְּגִין דָּא עֲבַד לֵיהּ לְבַר נָשׁ כְּדְקָא יְאוּת כְּדְאֲמָרָן. וְקוּדְשָׁא בְּרִיךְ הוּא עֲבַד טִיבוּ עִם עַלְמָא. תָּא חֲזֵי, מַה כְּתִיב, (בראשית כ״ה:א׳) וַיּוֹסֶף אַבְרָהָם וַיִּקַּח אִשָּׁה וּשְׁמָהּ קְטוּרָה, רָזָא דְּנִשְׁמָתָא אָתַת לְאִתְתַּקָּנָא כְּמִלְקַדְּמִין.</p>\n<p>תָּא חֲזֵי, הַהוּא גוּפָא מַה כְּתִיב, (ישעיהו נ״ג:י׳) וַיְיָ חָפֵץ דַּכְּאוֹ הֶחלִי אִם תָּשִׂים אָשָׁם נַפְשׁוֹ יִרְאֶה זֶרַע יַאֲרִיךְ יָמִים וְחֵפֶץ יְיָ בְּיָדוֹ יִצְלָח. וַיְיָ חָפַץ דַּכְּאוֹ, הַאי קְרָא אִית לְאִסְתַּכָּלָא בֵּיהּ, אַמַּאי חָפֵץ בְּגִין דְּיִתְדַּכֵּי. אִם תָּשִׂים אָשָׁם, אִם יָשִׂים אָשָׁם מִבָּעֵי לֵיהּ, מַאי אִם תָּשִׂים. אֶלָּא לְנִשְׁמָתָא אַהֲדַר מִלָּה. אִי הַהִיא נִשְׁמָתָא בַּעְיָא לְאִתְתַּקָּנָא כְּדְקָא יָאוֹת, יִרְאֶה זֶרַע. בְּגִין דְּהַהִיא נִשְׁמָתָא אָזְלַת וְשָׁאטַת וְאִיהִי זְמִינָא לְאָעֳלָא בְּהַהוּא זֶרַע דְּאִתְעַסַּק בָּהּ בַּר נָשׁ בִּפְרִיָּה וּרְבִיָּה, וּכְדֵין יַאֲרִיךְ יָמִים. וְחֵפֶץ יְיָ דָּא אוֹרַיְיתָא בִּידֵיהּ אַצְלַח.</p>\n<p>תָּא חֲזֵי, אַף עַל גַּב דְּבַר נָשׁ אִשְׁתַּדַּל בְּאוֹרַיְיתָא יְמָמָא וְלֵילְיָא, וּמְקוֹרֵיהּ וּמַבּוּעֵיהּ קָיְימָא בֵּיהּ לְמַגָּנָא, לֵית לֵיהּ אֲתַר לְאֲעָלָא לְפַרְגּוֹדָא. וְהָא אִתְּמָר דְּבֵירָא דְמַיָא אִי הַהוּא מְקוֹרָא וּמַבּוּעָא לָא עָאל בֵּיהּ, לָאו אִיהוּ בְּאֵר, דְּבֵירָא וּמְקוֹרָא, כְּחֲדָא אִינוּן, וְרָזָא חָדָא אִיהוּ, וְאוֹקִימְנָא.</p>\n<p>כְּתִיב, (תהילים קכ״ז:ב׳) שָׁוְא לָכֶם מַשְׁכִּימֵי קוּם מֵאַחֲרֵי שֶׁבֶת אוֹכְלֵי לֶחֶם הָעֲצָבִים כֵּן יִתֵּן לִידִידוֹ שֵׁנָה. תָּא חֲזֵי, כַּמָּה חֲבִיבִין אִינוּן מִלֵּי דְאוֹרַיְיתָא. דְּכָל מִלָּה וּמִלָּה דְאוֹרַיְיתָא אִית בֵּיהּ רָזִין עִלָּאִין קַדִּישִׁין. וְהָא אִתְּמָר דְּכַד יָהַב קוּדְשָׁא בְּרִיךְ הוּא אוֹרַיְיתָא לְיִשְׂרָאֵל, כָּל גְּנִיזִין עִלָּאִין קַדִּישִׁין כֻּלְּהוּ יָהַב לְהוּ (וכלהו) בְּאוֹרַיְיתָא, וְכֻלְּהוּ אִתְיְהִיבוּ לְהוּ לְיִשְׂרָאֵל בְּשַׁעְתָּא דְּקַבִּילוּ אוֹרַיְיתָא בְּסִינַי.</p>\n<p>תָּא חֲזֵי, שָׁוְא לָכֶם מַשְׁכִּימֵי קוּם, אִלֵין אִינוּן יְחִידִים דְּאִשְׁתַּכָּחוּ, דְּלָאו אִינוּן דְּכַר וְנוּקְבָא כְּדְקָא יְאוּת, וְאַקְדְּמָן בְּצַפְרָא לַעֲבִידְתַּיְהוּ. כְּמָה דְאַתְּ אָמֵר, (קהלת ד׳:ח׳) יֵשׁ אֶחָד וְאֵין שֵׁנִי וְגו' וְאֵין קֵץ לְכָל עֲמָלוֹ. מֵאַחֲרֵי שֶׁבֶת. מְאַחֲרִין נַיְיחָא, כְּמָה דְאַתְּ אָמֵר, כִּי בוֹ שָׁבַת. בְּגִין דְּאִתְּתָא לְגַבֵּי בַּר נָשׁ אִיהִי נַיְיחָא לְגַבֵּיהּ וַדַּאי.</p>\n<p>אוֹכְלֵי לֶחֶם הָעֲצָבִים, מַאי לֶחֶם הָעֲצָבִים. דְּכַד בַּר נָשׁ אִית לֵיהּ בְּנִין, הַהוּא נַהֲמָא דְּאָכִיל, אָכִיל לֵיהּ בְּחֶדְוָה וּבִרְעוּתָא דְלִבָּא. וְהַהוּא דְּלֵית לֵיהּ בְּנִין, הַהוּא נַהֲמָא דְּאָכִיל אִיהוּ נַהֲמָא דַּעֲצִיבוּ. וְאִלֵּין אִינוּן אוֹכְלֵי לֶחֶם הָעֲצָבִים וַדַּאי.</p>\n<p>כֵּן יִתֵּן לִידִידוֹ שֵׁנָה, מַאי יִתֵּן לִידִידוֹ, דָּא הוּא דִּמְקוֹרֵיהּ מְבָרַךְ, דְּקוּדְשָׁא בְּרִיךְ הוּא יָהַב לֵיהּ שֵׁינָה בְּהַהוּא עַלְמָא כְּמָה דְאַתְּ אָמֵר, (משלי ג׳:כ״ד) וְשָׁכַבְתָּ וְעָרְבָה שְׁנָתֶךָ. בְּגִין דְּאִית לֵיהּ חוּלָקָא בְּעַלְמָא דְאָתֵי. בְּגִין דְּהַהוּא בַּר נָשׁ שָׁכִיב וְיִתְהַנֵּי בְּהַהוּא עַלְמָא דְאָתֵי כְּדְקָא יְאוּת.</p>\n<p>יֵשׁ אֶחָד וְאֵין שֵׁנִי וְגו'. יֵשׁ אֶחָד, דָּא הוּא בַּר נָשׁ דְּאִיהוּ יְחִידָאי בְּעַלְמָא, לָא יְחִידָאי כְּדְקָא יְאוּת, אֶלָּא דְּאִיהוּ בְּלָא זִוּוּגָא. וְאֵין שֵׁנִי, דְּלֵית עִמֵּיהּ סֶמֶךְ. גַּם בֵּן, דְּיוֹקִים שְׁמֵיהּ בְּיִשְׂרָאֵל לָא שָׁבַק. וְאָח (אין לו) לְאַיְיתָאָה לֵיהּ לְתִקּוּנָא.</p>\n<p>וְאֵין קֵץ לְכָל עֲמָלוֹ, דְּאִיהוּ עָמֵל תָּדִיר דְּאַקְדִּים יְמָמָא וְלֵילְיָא. גַּם עֵינוֹ לא תִשְׂבַּע עשֶׁר, וְלֵית לֵיהּ לִבָּא לְאַשְׁגָּחָא וּלְמֵימַר לְמִי אֲנִי עָמֵל וּמְחַסֵּר אֶת נַפְשִׁי <Nonei></i>מִטּוֹבָה. וְאִי תֵימָא דִּבְגִין דְּיֵיכוּל וְיִשְׁתֵּי יַתִּיר וְיַעֲבֵד מִשְׁתַּיָא בְּכָל יוֹמָא תָּדִיר, לָאו הָכִי. דְּהָא נַפְשָׁא לָא אִתְהַנִּי מִנֵּיהּ, אֶלָּא וַדַּאי אִיהוּ מְחַסֵּר לְנַפְשֵׁיהּ מִטִּיבוּ דִּנְהוֹרָא דְעַלְמָא דְאָתֵי. בְּגִין דְּדָא הִיא נַפְשָׁא חַסְרָא, דְּלָא אִשְׁתַּלִּימַת כְּדְקָא יְאוּת. תָּא חֲזֵי, כַּמָּה חָס קוּדְשָׁא בְּרִיךְ הוּא עַל עוֹבָדוֹי, בְּגִין דְּקָא בָּעֵי דְּיִתְתַּקַּן, וְלָא יִתְאֲבִיד מֵהַהוּא עַלְמָא דְאָתֵי כִּדְקָאֲמָרָן.</p>\n<p>רִבִּי חִיָּיא בָּעָא, הַאי דְאִיהוּ זַכָּאָה שְׁלֵימָא וְאִשְׁתְּדָּל בְּאוֹרַיְיתָא יוֹמֵי וְלֵילֵי וְכָל עוֹבָדוֹי לִשְׁמָא דְקוּדְשָׁא בְּרִיךְ הוּא, וְלָא זָכָה לִבְנִין בְּהַאי עַלְמָא כְּגוֹן דְּאִשְׁתַּדַּל בְּהוּ וְלָא זָכָה, אוֹ דְּהֲווּ לֵיהּ וּמִיתוּ. מַה אִינוּן לְעַלְמָא דְאָתֵי. אָמַר לֵיהּ רִבִּי יוֹסֵי, עוֹבָדוֹי וְהַהִיא אוֹרַיְיתָא, קָא מָגִינָן עֲלֵיהּ לְהַהוּא עַלְמָא.</p>\n<p>אָמַר רִבִּי יִצְחָק, עֲלַיְיהוּ וְעַל אִינוּן זַכָּאֵי קְשׁוֹט, (כגון רבי יוחנן דהוו ליה בנין ומיתו, וכגון רבי חזקיה דאיהו עקר) עֲלַיְיהוּ כְּתִיב, (ישעיהו נ״ו:ד׳) כֹּה אָמַר יְיָ לַסָּרִיסִים אֲשֶׁר יִשְׁמְרוּ אֶת שַׁבְּתוֹתַי וּבָחֲרוּ בַּאֲשֶׁר חָפָצְתִּי וּמַחֲזִיקִים בִּבְרִיתִי. מַה כְּתִיב בַּתְרֵיהּ, וְנָתַתִּי לָהֶם בְּבֵיתִי וּבְחוֹמוֹתַי יָד וָשֵׁם טוֹב מִבָּנִים וּמִבָּנוֹת שֵׁם עוֹלָם אֶתֵּן לוֹ אֲשֶׁר לֹא יִכָּרֵת. בְּגִין דְּאִלֵּין אִית לוֹן חוּלָקָא לְעַלְמָא דְאָתֵי. אָמַר לֵיהּ רִבִּי יוֹסֵי, יָאוֹת הוּא וְשַׁפִּיר.</p>\n<p>תָּא חֲזֵי, זַכָּאָה שְׁלִים דְּהֲווּ כָּל אִלֵּין בֵּיהּ, וְאִשְׁתְּלִים כְּדְקָא יְאוּת, וּמִית בְּלָא בְּנִין, וְהָא קָא יָרִית דּוּכְתֵּיהּ בְּהַהוּא עַלְמָא, אִתְּתֵיהּ בָּעְיָא לִיבוּמֵי אוֹ לָא. אִי תֵימָא דְּלִבָּעֵי לִיבוּמֵי, הָא בְּרֵיקַנְיָא אִיהוּ, דְּהָא אַתְרֵיהּ קָא יָרִית בְּהַהוּא עַלְמָא.</p>\n<p>אֶלָּא וַדַּאי בָּעְיָא לִיבוּמֵי, בְּגִין דְּלָא יַדְעִינָן אִי הֲוָה שְׁלִים בְּעוֹבָדוֹי אִי לָאו. וְהִיא אִי אִתְיַיבְּמַת לָא הֲוָה בְּרֵיקַנְיָא. בְּגִין דְּאֲתַר אִית לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא דְּהָא (ל) בַּר נָשׁ (ד) הֲוָה בְּעַלְמָא וּמִית בְּלָא בְּנִין וּפוּרָקָא לָא הֲוֵי לֵיהּ בְּעַלְמָא, כֵּיוָן דְּמִית הַאי זַכָּאָה שְׁלִים וְאִתְּתֵיה אִתְיַיבְּמַת, וְאִיהוּ אַתְרֵיהּ יָרִית. אֲתָא הַהוּא בַּר נָשׁ וְאִשְׁתַּלִּים הָכָא, וּבֵין כָּךְ וּבֵין כָּךְ קוּדְשָׁא בְּרִיךְ הוּא, אֲתַר זַמִּין לֵיהּ (לעלמא) (בעלמא) עַד דְּיֵימוּת הַאי זַכָּאָה שְׁלִים, וְיִשְׁתְּלִים אִיהוּ בְּעַלְמָא. הֲדָא הוּא דִכְתִיב (במדבר ל״ה:כ״ח) כִּי בְעִיר מִקְלָטוֹ יֵשֵׁב עַד מוֹת הַכֹּהֵן הַגָּדוֹל וְגו'.</p>\n<p>וְדָא הוּא דְּתָנִינָן, בְּנִין זְמִינִין אִינוּן לְצַדִּיקַיָא בְּמִיתַתְהוֹן, בְּחַיֵּיהוֹן לָא זָכוּ וּבְמִיתַתְהוֹן זָכוּ. וּבְגִין כָּךְ כָּל עוֹבָדוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא כֻּלְּהוּ קְשׁוֹט וּזְכוּ, (ס\"א וחייס) וְחַיִּים עַל כֹּלָּא.</p>\n<p>(קהלת ד׳:ט׳) טוֹבִים הַשְּׁנַיִם מִן הָאֶחָד אֲשֶׁר יֵשׁ לָהֶם שָׂכָר טוֹב בַּעֲמָלָם, אִלֵּין אִינוּן דְּמִתְעַסְּקִין בְּהַאי עַלְמָא לְאוֹלָדָא בְּנִין. דְּאִינוּן בְּנִין דְּשָׁבְקוּ, בְּגִינֵיהוֹן אִית לוֹן אֲגַר טַב בְּהַהוּא עַלְמָא, וּבְגִינֵיהוּ יַרְתִין אֲבָהָן דִּלְהוֹן חוּלָקָא בְּהַהוּא עַלְמָא וְאוּקְמוּהָ.</p>\n<p>תָּא חֲזֵי, קוּדְשָׁא בְּרִיךְ הוּא נָטַע אִילָנִין בְּהַאי עַלְמָא אִי אַצְלָחוּ יָאוֹת, לָא אַצְלָחוּ אַעֲקַר לוֹן וְשָׁתַל לוֹן אֲפִילּוּ כַּמָּה זִמְנִין. וּבְּגִין כָּךְ כָּל אָרְחוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא כֻּלְּהוּ לְטַב וּלְאַתְקָנָא עָלְמָא:</p>\n<p>בֹּא אֶל אֵשֶׁת אָחִיךָ וְיַבֵּם אוֹתָהּ, דְּהָא יְהוּדָה וְכֻלְּהוּ שִׁבְטִין הֲווּ יָדְעֵי דָּא. וְעִקְּרָא דְמִלְּתָא, וְהָקֵם זֶרַע. בְּגִין דְּהַהוּא זֶרַע אִצְטְרִיךְ לְאִתְתַּקָּנָא מִלָּה וּלְמִגְלַם גּוֹלָמָא לְתִקּוּנָא דְּלָא יִתְפְּרַשׁ גִּזְעָא מִשָּׁרְשֵׁיהּ כְּדְקָא יְאוּת, הֲדָא הוּא דִכְתִיב (איוב לה) וְאָדָם עַל עָפָר יָשׁוּב.</p>\n<p>וְכַד מִתְתַּקַּן לְבָתַר כְּדְקָא יָאוֹת, אִלֵּין מִשְׁתַּבְּחִין בְּהַהוּא עַלְמָא בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרָעֵי בְּהוּ. וּבְגִין כָּךְ כְּתִיב, (קהלת ד׳:ב׳) וְשַׁבֵּחַ אֲנִי אֶת הַמֵּתִים שֶׁכְּבָר מֵתוּ, דַּיְיקָא. מִן הַחַיִּים אֲשֶׁר הֵמָּה חַיִּים עֲדֶנָּה. מַאי עֲדֶנָּה, כְּמָה דְאַתְּ אָמֵר (בראשית י״ח:י״ב) אַחֲרֵי בְלוֹתִי הָיְתָה לִי עֶדְנָה. וּכְתִיב (איוב ל״ג:כ״ה) יָשׁוּב לִימֵי עֲלוּמָיו.</p>\n<p>וְטוֹב מִשְּׁנִיהֶם אֵת אֲשֶׁר עֲדֶן לא הָיָה (דלא שב לימי עלומיו) אֲשֶׁר לֹא רָאָה אֶת הַמַּעֲשֶׂה הָרַע אֲשֶׁר נַעֲשָׂה תַּחַת הַשֶּׁמֶשׁ. וְטוֹב מִשְּׁנִיהֶם אֶת אֲשֶׁר עֲדֶן לֹא הָיָה, דְּלָא שָׁב לִימֵי עֲלוּמָיו וְלָא אִצְטְרִיךְ לְאִתְתַּקָּנָא, וְלָא סָבִיל חוֹבִין קַדְמָאֵי, בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא <Nonei></i>יָהַב לֵיהּ אֲתַר מְתַקְנָא בְּהַהוּא עַלְמָא כְּדְקָא יָאוֹת.</p>\n<p>תָּא חֲזֵי, מַה כְּתִיב, (קהלת ח׳:י׳) וּבְכֵן רָאִיתִי רְשָׁעִים קְבוּרִים וְגו', כְּמָה דְּאִתְּמָר. בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא עָבִיד טִיבוּ וְלָא בָעָא לְשֵׁצָאָה עַלְמָא אֶלָּא כְּמָה דְאִתְּמָר, וְכָל אָרְחוֹי כֻּלְּהוּ קְשׁוֹט וּזְכוּ לְאוֹטָבָא לְהוּ בְּהַאי עַלְמָא וּבְעַלְמָא דְאָתֵי. זַכָּאָה חוּלְקֵהוֹן דְּצַדִּיקַיָיא דְּאִינוּן אָזְלֵי בְּאֹרַח קְשׁוֹט, עֲלַיְיהוּ כְּתִיב, (תהילים ל״ז:כ״ט) צַדִּיקִים יִרְשׁוּ אָרֶץ:</p>"],[9520011387,"<p>וַיֵּרַע בְּעֵינֵי יְיָ אֲשֶׁר עָשָׂה וַיָּמֶת גַּם אֹתוֹ. רִבִּי חִיָּיא פָּתַח, (קהלת י״א:ו׳) בַּבֹּקֶר זְרַע אֶת זַרְעֲךָ וְלָעֶרֶב אַל תַּנַּח יָדְךָ וְגו'. תָּא חֲזֵי, כַּמָּה אִתְחֲזֵי לֵיהּ לְבַר נָשׁ לְאִזְדַּהֲרָא מֵחוֹבוֹי, וּלְאִזְדַּהֲרָא בְּעוֹבָדוֹי קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא. בְּגִין דְּכַמָּה שְׁלִיחָן וְכַמָּה מְמַנָּן אִינוּן בְּעַלְמָא, דְּאִינוּן אָזְלִין וְשָׁיְיטָן, וְחָמָאן עוֹבָדֵיהוֹן דִּבְנֵי נָשָׁא, וְסָהֲדִין עֲלוֹי (ז\"ח עלייהו) וְכֹלָּא בְּסִפְרָא כְתִיבִין.</p>\n<p>וְתָּא חֲזֵי, בְּכָל אִינוּן חוֹבִין דְּאִסְתָּאַב בְּהוּ בַר נָשׁ בְּהַאי עַלְמָא, דָּא אִיהוּ חוֹבָא דְּאִסְתָּאַב בֵּיהּ בַר נָשׁ יַתִּיר בְּהַאי עַלְמָא וּבְעַלְמָא דְאָתֵי. מַאן דְּאוֹשִׁיד זַרְעֵיהּ בְּרֵיקַנְיָא, וְאַפִּיק זַרְעָא לְמַגָּנָא בִּידָא אוֹ בְּרַגְלָא וְאִסְתָּאַב בֵּיהּ. כְּמָה דְאַתְּ אָמֵר, (תהילים ה׳:ה׳) כִּי לֹא אֵל חָפֵץ רֶשַׁע אָתָּה לא יְגוּרְךָ רָע.</p>\n<p>בְּגִין דָא לָא עָאל לְפַרְגּוֹדָא, וְלָא חָמֵי סְבָר אַפֵּי עַתִּיק יוֹמִין, כְּמָה דְּתָנִינָן כְּתִיב הָכָא לא יְגוּרְךָ רָע, וּכְתִיב וַיְהִי עֵר בְּכוֹר יְהוּדָה רַע בְּעֵינֵי יְיָ. וּבְגִין כָּךְ כְּתִיב, (ישעיהו א׳:ט״ו-ט״ז) יְדֵיכֶם דָּמִים מָלֵאוּ. זַכָּאָה חוּלָקֵיהּ דְּבַר נָשׁ דְּדָחִיל לְמָארֵיהּ וִיהֵא נְטִיר מֵאוֹרַח בִּישָׁא, וְיַדְכֵּי גַרְמֵיהּ לְאִשְׁתַּדָּלָא בִּדְחִילוּ דְמָארֵיהּ.</p>\n<p>תָּא חֲזֵי, בַּבֹּקֶר זְרַע אֶת זַרְעֶךָ, הַאי קְרָא אוּקְמוּהָ. בַּבֹּקֶר, דָּא הוּא בְּזִמְנָא דְּבַר נָשׁ אִתְקַיֵּים בְּחֵילֵיהּ וִיהֵא בְּעוּלֵימוֹ, כְּדֵין אִשְׁתַּדַּל לְאוֹלָדָא בְּנִין בְּאִיתְּתָא דְּחַזְיָא לֵיהּ, דִּכְתִיב בַּבֹּקֶר זְרַע אֶת זַרְעֶךָ.</p>\n<p>דְּהָא כְּדֵין זִמְנָא אִיהוּ כְּמָה דְאַתְּ אָמֵר, (תהילים קכ״ז:ד׳) כְּחִצִּים בְּיַד גִּבּוֹר כֵּן בְּנִי הַנְּעוּרִים. בְּגִין דְּיָכִיל לְמֵילַף לְהוּ אָרְחוֹי דְקוּדְשָׁא בְּרִיךְ הוּא, וִיהֵא לֵיהּ אַגְרָא טָבָא לְעַלְמָא דְאָתֵי. דִּכְתִיב אַשְׁרֵי הַגֶּבֶר אֲשֶׁר מִלֵּא אֶת אַשְׁפָּתוֹ מֵהֶם לא יֵבשׁוּ כִּי יְדַבְּרוּ אֶת אוֹיְבִים בַּשָּׁעַר. לא יֵבוֹשׁוּ בְּהַהוּא עַלְמָא, בְּזִמְנָא דְמָארֵיהוֹן דְּדִינָא יֵיתוּן לְקַטְרְגָא עֲלוֹי. דְּלֵית לָךְ אַגְרָא טָבָא בְּהַהוּא עַלְמָא, כְּהַהוּא דְאוֹלִיף לֵיהּ לִבְרֵיהּ דְּחִילוּ דְמָרֵיהּ בְּאָרְחוֹי דְאוֹרַיְיתָא.</p>\n<p>תָּא חֲזֵי מַה אָמַר בְּאַבְרָהָם, דִּכְתִיב, (בראשית י״ח:י״ט) כִּי יְדַעְתִּיו לְמַעַן אֲשֶׁר יְצַוֶּה אֶת בָּנָיו וְאֶת בֵּיתוֹ אַחֲרָיו וְשָׁמְרוּ דֶּרֶךְ יְיָ לַעֲשׂוֹת צְדָקָה וּמִשְׁפָּט. וְעַל דָּא הַהוּא זְכוּ קָיְימָא לֵיהּ בְּהַהוּא עַלְמָא לְגַבֵּי כָּל מָארֵיהוֹן דְּדִינָא.</p>\n<p>וּבְגִין כָּךְ בַּבֹּקֶר זְרַע אֶת זַרְעֶךָ, וְלָעֶרֶב אַל תַּנַּח יָדֶךָ, אֲפִילּוּ בְּיוֹמֵי דְזִקְנָה, דְּאִיהוּ זִמְנָא דְסִיב בַר נָשׁ (לא יימא כבר אשתדלית ודי לי או כבר אשתדלית ולא יכילנא והשתא דאנא סיב לית אנא בעי ועם כל דא) מַה כְּתִיב אַל תַּנַּח יָדֶךָ לָא יִשְׁבּוֹק מִלְּאוֹלָדָא בְּהַאי עַלְמָא. מַאי טַעְמָא, בְּגִין דְּלָא תֵדַע אֵיזֶה יִכְשַׁר הַזֶּה אוֹ זֶה לִפְנֵי הָאֱלהִים. בְּגִין דִּיקוּמוּן בְּגִינֵיהּ בְּהַהוּא עַלְמָא.</p>\n<p>וְעַל דָּא כְּתִיב (תהילים קכ״ז:ג׳) הִנֵּה נַחֲלַת יְיָ בָּנִים, דָּא צְרוֹרָא דְנִשְׁמָתָא סִטְרָא דְעַלְמָא דְאָתֵי, וּלְהַאי נַחֲלָה מַאן זָכֵי לֵיהּ לְבַר נָשׁ לְאַעָלָא בְּהַהוּא נַחֲלַת יְיָ, בָּנִים. אִינוּן בְּנִין זָכָאן לֵיהּ לְנַחֲלַת יְיָ, וְעַל דָּא זַכָּאָה הַהוּא בַּר נָשׁ דְּזָכֵי לוֹן דְּיוֹלִיף לוֹן אָרְחוֹי דְאוֹרַיְיתָא כְּמָה דְּאִתְּמָר:</p>"],[9520011388,"<p>וַתָּסַר בִּגְדֵי אַלְמְנוּתָהּ מֵעָלֶיהָ וְגו', תָּא חֲזֵי, תָּמָר בַּת כֹּהֵן הֲוַת, וְכִי סַלְקָא דַעְתָּךְ דְּאִיהִי אָזְלָא בְּגִין לְאַזְנָאָה עִם חָמוּהָ, דְּהָא אִיהִי צְנִיעוּתָא אִשְׁתַּכְּחַת בָּהּ תָּדִיר. אֶלָּא אִיהִי צַדֶּקֶת הֲוַת וּבְחָכְמָה עָבְדַת הַאי, דְּהָא אִיהִי לָא אַפְקָרַת גַּרְמָהּ לְגַבֵּיהּ, אֶלָּא בְּגִין דִּידִיעָה יָדְעַת וְחָכְמְתָא אִסְתַּכָּלַת. וְעַל דָּא אִיהִי אָתַת לְגַבֵּיהּ לְמֶעְבַּד (עמיה) טִיבוּ וּקְשׁוֹט, וְעַל דָּא אָתַת (להדיה) וְאִשְׁתַּדְּלַת בְּעִסְקָא דָא.</p>\n<p>תָּא חֲזֵי, בְּגִין דְּאִיהִי יָדְעַת יְדִיעָה וְאִשְׁתַּדְּלַת בְּעִסְקָא דָא. קוּדְשָׁא בְּרִיךְ הוּא עֲבַד סִיּוּעָא תַּמָּן בְּהַהוּא עוֹבָדָא וְאִתְעֲבְּרַת מִיָּד. וְכֹלָּא הֲוָה <Nonei></i>מִנֵּיהּ. וְאִי תֵימָא אַמַּאי לָא אַיְיתֵי קוּדְשָׁא בְּרִיךְ הוּא אִינוּן בְּנִין מֵאִתְּתָא אוֹחֲרָא, אַמַּאי מִן דָּא. אֶלָּא וַדַּאי אִיהִי אִצְטְרִיכָא לְעוֹבָדָא דָא וְלָא אִתְּתָא אָחֳרָא.</p>\n<p>תְּרֵין נְשִׁין הֲווּ דְּמִנַּיְיהוּ אִתְבְּנֵי זַרְעָא דִיהוּדָה, וְאֲתוּ מִנַּיְיהוּ דָּוִד מַלְכָּא וּשְׁלֹמֹה מַלְכָּא וּמַלְכָּא מְשִׁיחָא. וְאִלֵּין תְּרֵין נְשִׁין דָּא כְּגַוְונָא דְּדָא, תָּמָר וְרוּת דְּמִיתוּ בַּעֲלַיְיהוּ בְּקַדְמִיתָא, וְאִינוּן אִשְׁתַּדְּלוּ לְעוֹבָדָא דָא.</p>\n<p>תָּמָר אִשְׁתַּדְּלַת לְגַבֵּי חָמוּהָ דְּאִיהוּ קָרִיב יַתִּיר לִבְנוֹי דְמִיתוּ. מַאי טַעְמָא אִיהִי אִשְׁתַּדְּלַת לְגַבֵּיהּ, דִּכְתִיב כִּי רָאֲתָה כִּי גָדַל שֵׁלָה וְהִיא לֹא נִתְּנָה לוֹ לְאִשָּׁה. וּבְגִין דָּא אִשְׁתַּדְּלַת בְּעוֹבָדָא דָא לְגַבֵּי חָמוּהָ.</p>\n<p>רוּת מִית בַּעֲלָהּ וּלְבָתַר אִשְׁתַּדְּלַת בְּעוֹבָדָא דָא לְגַבֵּיהּ דְּבֹעַז דִּכְתִיב, (רות ג׳:ז׳) וַתְּגַל מַרְגְּלוֹתָיו וַתִּשְׁכָּב. וְאִשְׁתַּדְּלַת בַּהֲדֵיהּ וּלְבָתַר אוֹלִידַת לֵיהּ לְעוֹבֵד. וְאִי תֵימָא אַמַּאי לָא נָפִיק עוֹבֵד מֵאִתְּתָא אָחֳרָא, אֶלָּא וַדַּאי הִיא אִצְטְרִיכַת וְלָא אִתְּתָא אָחֳרָא. וּמִתְּרֵין אִלֵּין אִתְבְּנִי וְאִשְׁתַּכְלִיל זַרְעָא דִיהוּדָה, וְתַרְוַוְיְיהוּ בְּכַשְׁרוּת עָבְדוּ לְמֶעְבַּד טִיבוּ עִם אִינוּן מֵיתַיָיא לְאִתְתַּקְּנָא עַלְמָא לְבָתַר.</p>\n<p>וְדָא הוּא כְּמָה דְאִתְּמָר (קהלת ד׳:ב׳) וְשַׁבֵּחַ אֲנִי אֶת הַמֵּתִים שֶׁכְּבָר מֵתוּ, דְּהָא כַּד הֲווּ חַיִּין בְּקַדְמִיתָא לָא הֲוָה בְּהוּ שְׁבָחָא (ז\"ח ולבתר הוה בהו שבחא), וְתַרְוַויְיהוּ אִשְׁתַּדְּלוּ לְמֶעְבַּד טִיבוּ וּקְשׁוֹט עִם אִנּוּן מֵיתַיָיא, וְקוּדְשָׁא בְּרִיךְ הוּא סִיֵּיעַ בְּהַהוּא עוֹבָדָא וְכֹלָּא הֲוָה כְּדְקָא יָאוֹת. זַכָּאָה אִיהוּ מַאן דְּאִשְׁתַּדַּל בְּאוֹרַיְיתָא יְמָמָא וְלֵילְיָא. כְּמָה דְאַתְּ אָמֵר, (יהושע א׳:ח׳) וְהָגִיתָ בוֹ יוֹמָם וָלַיְלָה לְמַעַן תִּשְׁמֹר לַעֲשׂוֹת כְּכָל הַכָּתוּב בּוֹ כִּי אָז תַּצְלִיחַ אֶת דְּרָכֶיךָ וְגו':</p>"],[9520011389,"<p>וְיוֹסֵף הוּרַד מִצְרַיְמָה וַיִּקְנֵהוּ פּוֹטִיפַר וְגו'. (מה כתיב לעיל ויכר יהודה ויאמר, איהו אמר לגבי אבוי הכר נא וגו', ועל דא ויכר יהודה. וכתיב והנה תאומים בבטנה. תאומין הוו מקדמת דנא אחין הוו. רבי חזקיה אמר, לא אשתמע הכי. אלא בנין אחרנין אתילידו. אמר רבי אבא, בגין כך אשתדלת לאשכחא אובדא דאתאביד. תא חזי מה כתיב, ויהי כמשיב ידו והנה יצא אחיו ותאמר מה פרצת עליך פרץ. רמז הכא פריצותא קדמאה דפריץ ההוא דמית עליה משמע דכתיב פרצת עליך פריצותא בגין דאצטריכת לאטרחא למרך ובגין כך פריצותא תעביד בשאר עמין עובדי עבודת כוכבים ומזלות. ועל דא ויקרא את שמו פרץ. ולבתר דכל עובדא דיהודה אתמר דיהודה זבין ליה ליוסף. ואיהו גרים ליה לכל האי. דאי יהודה הוה אמר נהדר ליה לאבונא הוו עבדין ליה אחוי הס ועל דא נחתו ליה אחוי משלטנותא דעליהו. לבתר דאתגלי מאחוי ואתא עליה כל דא אהדר ואמר ויוסף הורד מצרימה) מַאי הוּרַד. דְּאִסְתַּכַּם קוּדְשָׁא בְּרִיךְ הוּא בְּהַהוּא עוֹבָדָא לְקַיְימָא גְזֵרָה דִילֵיהּ דִּגְזַר בֵּין הַבְּתָרִים דִּכְתִיב, (בראשית ט״ו:י״ג) יָדוֹעַ תֵּדַע כִּי גֵר יִהְיֶה זַרְעֲךָ וְגו'. וַיִּקְנֵהוּ פּוֹטִיפַר לִסְטַר חֲטָאָה קָנָה לֵיהּ.</p>\n<p>פָּתַח וְאָמַר, (איוב ט׳:ז׳) הָאֹמֵר לַחֶרֶס וְלֹא יִזְרָח וּבְעַד כּוֹכָבִים יַחְתֹּם. תָּא חֲזֵי, שִׁבְעָה כֹּכְבַיָא עֲבַד קוּדְשָׁא בְּרִיךְ הוּא בִּרְקִיעָא, וְכָל רְקִיעָא וּרְקִיעָא אִית בֵּיהּ כַּמָּה שַׁמָּשִׁין מְמַנִּין לְשַׁמָּשָׁא לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>בְּגִין דְּלֵית לָךְ שַׁמָּשָׁא אוֹ מְמַנָּא דְּלֵית לֵיהּ פּוּלְחָנָא וְשִׁמּוּשָׁא לְמָארֵיהּ, וְקָיְימֵי כָּל חַד וְחַד עַל הַהוּא שִׁמּוּשָׁא דְּאִתְפַּקְדָא בֵּיהּ, וְכָל חַד יָדַע עֲבִידְתֵּיהּ לְשַׁמָּשָׁא.</p>\n<p>מִנְּהוֹן מְשַׁמְּשֵׁי בִּשְׁלִיחוּתָא דְמָרֵיהוֹן וְאִתְפַּקְּדָן בְּעַלְמָא עַל כָּל עוֹבָדֵיהוֹן דִּבְנֵי נָשָׁא, וּמִנְּהוֹן דְּקָא מְשַׁבְּחִין לֵיהּ וְאִינוּן (הא) אִתְפַּקְּדָן עַל שִׁירָתָא. וְאַף עַל גַּב דְּאִינוּן אִתְפַּקְּדָן בְּהַאי, לֵית לָךְ כָּל חֵילָא בִּשְׁמַיָיא וְכֹכָבִין וּמַזָּלֵי דְּכֻלְּהוּ לָא מְשַׁבְּחָן לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>דְּהָא בְּשַׁעְתָּא דְּעָאל לֵילְיָא כְּדֵין אִתְפַּרְשָׁן תְּלַת סִטְרִין מַשִּׁרְיָין לִתְלַת סִטְרֵי עַלְמָא, וּבְכָל סִטְרָא וְסִטְרָא אֶלֶף אַלְפִין וְרִבּוֹא רִבְבָן וְכֻלְּהוּ מְמַנָּן עַל <Nonei></i>שִׁירָתָא.</p>\n<p>תְּלַת מַשִּׁרְיָין אִינוּן, וְחַד חֵיוָתָא קַדִּישָׁא מְמַנָּא עֲלַיְיהוּ וְקָיְימָא עֲלַיְיהוּ, וְכֻלְּהוּ קָא מְשַׁבְּחָן לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא עַד דְּאָתֵי צַפְרָא, כַּד אָתֵי צַפְרָא, כָּל אִינוּן דְּבִסְטַר דָּרוֹם וְכָל כֹּכְבַיָא דְּנָהֲרֵי, כֻּלְּהוּ מְשַׁבְּחָן וְאָמְרֵי שִׁירָתָא לְקוּדְשָׁא בְּרִיךְ הוּא כְּמָה דְאַתְּ אָמֵר, (איוב ל״ח:ז׳) בְּרָן יַחַד כֹּכְבֵי בֹקֶר וַיָּרִיעוּ כָּל בְּנֵי אֱלֹהִים. בְּרָן יַחַד כֹּכְבֵי בֹקֶר, אִלֵּין כֹּכְבַיָא דְּבִסְטַר דָּרוֹם כְּמָה דְאַתְּ אָמֵר, (בראשית י״ט:כ״ז) וַיַּשְׁכֵּם אַבְרָהָם בַּבֹּקֶר. וַיָּרִיעוּ כָּל בְּנֵי אֱלהִים, אִלֵּין אִינוּן דְּבִסְטַר שְׂמָאלָא דְּאִתְכְּלִילוּ בִּימִינָא.</p>\n<p>וּכְדֵין צַפְרָא נָהִיר, וְיִשְׂרָאֵל נָטְלֵי שִׁירָתָא וּמְשַׁבְּחָן לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא בִּימָמָא, תְּלַת זִמְנִין בִּימָמָא, לָקֳבֵל תְּלַת זִמְנִין דְּלֵילְיָא. וְקָיְימִין אִלֵּין לָקֳבֵיל אִלֵּין, עַד דְּיִסְתַּלַּק יְקָרָא דְּקוּדְשָׁא בְּרִיךְ הוּא בִּימָמָא וּבְלֵילְיָא כְּדְקָא יְאוּת, וְקוּדְשָׁא בְּרִיךְ הוּא אִסְתַּלַּק בְּהוּ בְּשִׁית אִלֵּין.</p>\n<p>הַהוּא חֵיוָתָא קַדִּישָׁא דְּקָיְימָא עֲלַיְיהוּ לְעֵילָא קָיְימָא עַל יִשְׂרָאֵל לְתַתָּא בְּגִין לְאַתְקָנָא כֹּלָּא כְּדְקָא יְאוּת. מַה כְּתִיב בָּהּ (משלי ל״א:ט״ו) וַתָּקָם בְּעוֹד לַיְלָה וַתִּתֵּן טֶרֶף לְבֵיתָהּ וְחֹק לְנַעֲרוֹתֶיהָ. וַתִּתֵּן טֶרֶף לְבֵיתָהּ אִלֵּין אִינוּן מַשִּׁירְיָין דִּלְעֵילָא, וְחֹק לְנַעֲרוֹתֶיהָ אִלֵּין מַשִּׁרְיָין דְּיִשְׂרָאֵל לְתַתָּא, וּבְגִין כָּךְ יְקָרָא דְקוּדְשָׁא בְּרִיךְ הוּא אִסְתַּלַּק מִכָּל סִטְרִין מֵעֵילָא וּמִתַּתָּא. וְעַל דָּא כֹּלָּא הֲוָה (ס\"א הוא) בִּרְשׁוּתֵיהּ קַיְימָא, וְכֹלָּא אִיהוּ בִּרְעוּתֵיהּ.</p>\n<p>(איוב ט׳:ז׳) הָאוֹמֵר לַחֶרֶס וְלא יִזְרָח. רִבִּי שִׁמְעוֹן אָמַר, דָּא יוֹסֵף. וּבְעַד כּוֹכָבִים יַחְתּוֹם, אִלֵּין אִינוּן אֲחוֹי דִּכְתִיב בְּהוּ וַאֲחַד עָשָׂר כּוֹכָבִים מִשְׁתַּחֲוִים לִי. דָּבָר אַחֵר הָאוֹמֵר לַחֶרֶס, דָּא יַעֲקֹב, בְּשַׁעְתָּא דְּאָמְרוּ לוֹ הַכֶּר נָא. וְלא יִזְרָח, בְּשַׁעְתָּא דְּאִסְתַּלְקַת שְׁכִינְתָּא מִנֵּיהּ. וּבְעַד כֹּכָבִים יַחְתּוֹם, בְּגִין בְּנוֹי אִתְחַתַּם וְאַסְתִּים נְהוֹרָא דִּילֵיהּ, שִׁמְשָׁא אִתְחַשַׁךְ וְכֹכְבַיָא לָא נְהִירוּ בְּגִין דְּיוֹסֵף אִתְפָּרַשׁ מֵאֲבוֹי. וְתָּא חֲזֵי, מֵהַהוּא יוֹמָא דְהַהוּא עוֹבָדָא דְיוֹסֵף, אִתְפְּרַשׁ יַעֲקֹב מִשִּׁמּוּשָׁא דְּעַרְסָא וְאִשְׁתָּאַר אֲבֵלָא עַד הַהוּא יוֹמָא דְּאִתְבַּשַּׂר בְּשׂוֹרָה דְיוֹסֵף:</p>"],[9520011390,"<p>וַיְהִי יְיָ אֶת יוֹסֵף וַיְהִי אִישׁ מַצְלִיחַ וַיְהִי בְּבֵית אֲדוֹנָיו וְגו'. רִבִּי יוֹסֵי פָּתַח, (תהילים ל״ז:כ״ח) כִּי ה' אוֹהֵב מִשְׁפָּט וְלֹא יַעֲזֹב אֶת חֲסִידָיו לְעוֹלָם נִשְׁמָרוּ. הַאי קְרָא אוּקְמוּהָ בְּאַבְרָהָם, אֶת חֲסִידָיו, חֲסִידוֹ כְּתִיב, וְהָא אִתְּמָר.</p>\n<p>תָּא חֲזֵי, בְּכָל אֲתַר דְּצַדִּיקַיָא אָזְלֵי, קוּדְשָׁא בְּרִיךְ הוּא נָטִיר לוֹן וְלָא שָׁבִיק לוֹן. דָּוִד אָמַר, (תהילים כ״ג:ד׳) גַּם כִּי אֵלֵךְ בְּגֵיא צַלְמָוֶת לֹא אִירָא רָע כִּי אַתָּה עִמָּדִי שִׁבְטְךָ וּמִשְׁעַנְתְּךָ וְגו'. בְּכָל אֲתַר דְּצַדִּיקַיָא אָזְלֵי, שְׁכִינְתָּא אָזְלָא עִמְּהוֹן וְלָא שָׁבִיק לוֹן.</p>\n<p>יוֹסֵף אָזַל בְּגֵיא צַלְמָוֶת וְנָחֲתוּ לֵיהּ לְמִצְרַיִם, שְׁכִינְתָא הֲוַת עִמֵּיהּ. הֲדָא הוּא דִּכְתִיב, וַיְהִי יְיָ אֶת יוֹסֵף. וּבְגִין דְּהֲוַת עִמֵּיהּ שְׁכִינְתָּא בְּכָל מַה דְּהֲוָה עָבִיד הֲוָה מַצְלַח בִּידֵיהּ. דְּאָפִילּוּ מַאי דְהֲוָה בִּידֵיהּ וְהֲוָה תָּבַע לֵיהּ מָארֵיהּ בְּגַוְונָא אָחֳרָא, הֲוָה מִתְהַפֵּךְ בִּידֵיהּ לְהַהוּא גַוְונָא דִּרְעוּתָא דְמָארֵיהּ הֲוָה רָעֵי בֵּיהּ. כְּמָה דְאַתְּ אָמֵר, וַיַּרְא אֲדוֹנָיו כִּי יְיָ אִתּוֹ וְכָל אֲשֶׁר הוּא עוֹשֶׂה יְיָ מַצְלִיחַ בְּיָדוֹ, מַצְלִיחַ בְּיָדוֹ וַדַּאי, כִּי יְיָ אִתּוֹ.</p>\n<p>תָּא חֲזֵי, וַיֵּדַע אֲדֹנָיו כִּי יְיָ אִתּוֹ לָא כְּתִיב, אֶלָּא וַיַּרְא אֲדֹנָיו, דְּהָא בְּעֵינוֹי הֲוָה חָמֵי עוֹבָדָא דְנִסִּין בְּכָל יוֹמָא דְּקוּדְשָׁא בְּרִיךְ הוּא עָבִיד בִּידֵיהּ, וְעַל דָּא וַיְבָרֶךְ יְיָ אֶת בֵּית הַמִּצְרִי בִּגְלַל יוֹסֵף. קוּדְשָׁא בְּרִיךְ הוּא נָטִיר לוֹן לְצַדִּיקַיָא וּבְגִינֵהוֹן נָטַר לוֹן לְרַשִּׁיעַיָא, דְּהָא רַשִּׁיעַיָא מִתְבָּרְכִין בְּגִינֵהוֹן דְּצַדִּיקַיָא. כְּגַוְונָא דָא כְּתִיב, (שמואל ב ו׳:י״ב) וַיְבָרֶךְ יְיָ אֶת בֵּית עוֹבֵד אֱדוֹם הַגִּתֵּי בַּעֲבוּר אֲרוֹן הָאֱלהִים.</p>\n<p>צַדִּיקַיָא, אָחֳרָנִין מִתְבָּרְכִין בְּגִינַייהוּ, וְאִינוּן לָא יָכְלוּ לְאִתְּזְנָא (ס\"א לאשתזבא) בִּזְכוּתַיְיהוּ, וְהָא אוּקְמוּהָ. יוֹסֵף אִתְבָּרֵךְ מָארֵיהּ בְּגִינֵיהּ, וְאִיהוּ לָא יָכִיל לְאִשְׁתְּזָבָא בִּזְכוּתֵיהּ מִנֵּיהּ וּלְנָפְקָא לְחֵירוּ.</p>\n<p>וּלְבָתַר אָעִיל לֵיהּ בְּבֵית הַסֹּהַר כְּמָה דְאַתְּ אָמֵר (תהילים ק״ה:י״ח-י״ט) עִנּוּ בַכֶּבֶל רַגְלוֹ בַּרְזֶל בָּאָה נַפְשׁוֹ, עַד דִּלְבָתַר קוּדְשָׁא בְּרִיךְ הוּא אַפִּיק לֵיהּ לְחֵירוּ וְשַׁלְטֵיהּ עַל כָּל אַרְעָא דְמִצְרָיִם. וּבְגִין כָּךְ כְּתִיב וְלא יַעֲזֹב אֶת חֲסִידָיו לְעוֹלָם <Nonei></i>נִשְׁמָרוּ, חֲסִידוֹ כְּתִיב וְאִתְּמָר. וְקוּדְשָׁא בְּרִיךְ הוּא אָגִין עֲלַיְיהוּ דְּצַדִּיקַיָא, בְּעַלְמָא דֵין וּבְעַלְמָא דְאָתֵי. דִּכְתִיב, (תהילים ה׳:י״ב) וְיִשְׂמְחוּ כָל חוֹסֵי בָךְ לְעוֹלָם יְרַנִּנוּ וְתָסֵךְ עָלֵימוּ וְיַעְלְצוּ בְךָ אוֹהֲבֵי שְׁמֶךָ:</p>"],[9520011391,"<p>וַיְהִי אַחַר הַדְּבָרִים הָאֵלֶּה וַתִּשָּׂא אֵשֶׁת אֲדֹנָיו אֶת עֵינֶיהָ אֶל יוֹסֵף. רִבִּי חִיָּיא פָּתַח וְאֲמַר, (תהילים ק״ג:כ׳) בָּרְכוּ יְיָ מַלְאָכָיו גִּבּוֹרֵי כֹחַ עוֹשֵׂי דְבָרוֹ לִשְׁמוֹעַ בְּקוֹל דְּבָרוֹ. תָּא חֲזֵי, כַּמָּה אִצְטְרִיךְ לֵיהּ לְבַר נָשׁ לְאִסְתַּמְּרָא מֵחוֹבוֹי, וּלְמֵיהַךְ בְּאֹרַח מִתְתַּקְּנָא. בְּגִין דְּלָא יִסְטֵי לֵיהּ הַהוּא יֵצֶר הָרָע, דְּאִיהוּ מְקַטְרְגָא לֵיהּ כָּל יוֹמָא וְיוֹמָא, כְּמָה דְאִתְּמָר.</p>\n<p>וּבְגִין דְּאִיהוּ מְקַטְרְגָא לֵיהּ תָּדִיר, בָּעֵי בַּר נָשׁ לְאִתְתַּקְּפָא עֲלֵיהּ, וּלְאִסְתַּלְּקָא עֲלֵיהּ בְּאֲתַר תָּקִּיפוּ. דְּבָעֵי לְמֶהֱוֵי גָּבַר עֲלֵיהּ, וּלְאִשְׁתַּתְּפָא בְּאֲתַר דִּגְבוּרָה. בְּגִין דְּכַד בַר נָשׁ אִתְקַף עֲלֵיהּ, כְּדֵין אִיהוּ בִּסְטַר גְּבוּרָה, וְאִתְדָּבַּק בֵּיהּ לְאִתְתַּקְּפָא. וּבְגִין דְּהַהוּא יֵצֶר הָרָע תַּקִּיף, בָּעֵי בַר נָשׁ דִּיהֵא תַּקִּיף מִינֵיהּ.</p>\n<p>וְאִלֵּין בְּנֵי נָשָׁא דְּאִתְתַּקְּפוּ עֲלֵיהּ, אִקְרוּן גִּבּוֹרֵי כֹחַ, לְאִשְׁתַּכְּחָא זִינָא עִם זִינֵיהּ. וְאִלֵּין אִינוּן מַלְאָכָיו דְּקוּדְשָׁא בְּרִיךְ הוּא, דְאַתְיָין מִסִּטְרָא דִגְבוּרָה קַשְׁיָא, לְאִתְתַּקְּפָא עֲלֵיהּ, גִּבּוֹרֵי כֹּחַ עוֹשֵׂי דְבָרוֹ. בָּרְכוּ יְיָ מַלְאָכָיו, כְּיוֹסֵף, דְּאִקְרֵי צַדִּיק וְגִבּוֹר וְנָטַר בְּרִית קַדִּישָׁא דְּאִתְרְשִׁים בְּגַוֵּיהּ.</p>\n<p>רִבִּי אֶלְעָזָר אָמַר, וַיְהִי אַחַר הַדְּבָרִים הָאֵלֶּה, מַאי הִיא, הָא אוּקְמוּהָ אֲתַר דָּא דְּיֵצֶר הָרָע מְקַטְרֵג, דְּאִיהוּ דַרְגָּא אַחַר הַדְּבָרִים. בְּגִין דְּיוֹסֵף יָהַב לֵיהּ דּוּכְתָּא לְקַטְרָגָא, דְּהֲוָה יוֹסֵף מְסַלְסֵל בְּשַׂעֲרֵיהּ וְאַתְקִין גַּרְמֵיהּ וְקַשִּׁיט לֵיהּ, כְּדֵין אִתְיְהִיב דּוּכְתָּא לַיֵצֶר הָרָע לְקַטְרְגָא. דְּאָמַר, וּמַה אֲבוֹי דְּאִיהוּ מִתְאַבֵּל עֲלֵיהּ, וְיוֹסֵף מְקַשִּׁיט גַּרְמֵיהּ, וּמְסַלְסֵל בְּשַׂעֲרֵיהּ, כְּדֵין אִתְגָּרֵי בֵּיהּ דּוּבָּא וְקַטְרִיג לֵיהּ:</p>\n<p>וַיְהִי אַחַר הַדְּבָרִים הָאֵלֶּה. תָּא חֲזֵי, בְּזִמְנָא דְּקוּדְשָׁא בְּרִיךְ הוּא אַשְׁגַּח בֵּיהּ בְּעַלְמָא, לְמֵידַן יָתֵיהּ, וְאַשְׁכַּח חַיָּיבִין בְּעַלְמָא, מַה כְּתִיב, (דברים י״א:י״ז) וְעָצַר אֶת הַשָּׁמַיִם וְלֹא יִהְיֶה מָטָר וְהָאֲדָמָה לֹא תִתֵּן אֶת יְבוּלָהּ, וּכְדֵין וַאֲבַדְתֶּם מְהֵרָה. דְּהָא בְּגִין חוֹבִין דִּבְנֵי נָשָׁא, שְׁמַיָא וְאַרְעָא אִתְעֲצָרוּ, וְלָא נָהֲגֵי נִמּוּסֵיהוֹן כְּדְקָא יְאוּת.</p>\n<p>וְתָּא חֲזֵי, אִינוּן דְּלָא נָטְרוּ לְהַאי קְיָימָא דְקוּדְשָׁא, גָּרְמֵי פְּרִישׁוּ בֵּין יִשְׂרָאֵל לַאֲבוּהוֹן דְּבִשְׁמַיָא, בְּגִין דִּכְתִיב וְסַרְתֶּם וַעֲבַדְתֶּם אֱלֹהִים אֲחֵרִים וְהִשְׁתַּחֲוִיתֶם לָהֶם, וּכְתִיב וְעָצַר אֶת הַשָּׁמַיִם וְלֹא יִהְיֶה מָטָר. דְּהַאי אִיהוּ כְּמַאן דְּסָגִיד לֵאלָהָא אָחֳרָא, דִּמְשַׁקֵּר בְּהַאי אָת קְיָימָא קַדִּישָׁא.</p>\n<p>וְכַד קְיָימָא קַדִּישָׁא אִתְנְטִיר בְּעַלְמָא כְּדְקָא יָאוֹת, כְּדֵין קוּדְשָׁא בְּרִיךְ הוּא יָהִיב בִּרְכָאן לְעֵילָא לְאַתְרָקָא בְּעַלְמָא. כְּמָה דְאַתְּ אָמֵר, (תהילים ס״ח:י׳) גֶּשֶׁם נְדָבוֹת תָּנִיף אֱלהִים נַחֲלָתְךָ וְנִלְאָה אַתָּה כוֹנַנְתָּה. גֶּשֶׁם נְדָבוֹת, דָּא גֶּשֶׁם דִּרְעוּתָא. כַּד אִתְרָעֵי קוּדְשָׁא בְּרִיךְ הוּא בִּכְנְסֶת יִשְׂרָאֵל, וּבָעֵי לַאֲרָקָא לָהּ בִּרְכָאן, כְּדֵין נַחֲלָתְךָ וְנִלְאָה אַתָּה כוֹנַנְתָּה.</p>\n<p>נַחֲלָתְךָ, אִינוּן יִשְׂרָאֵל, דְּאִינוּן אַחְסַנְתֵּיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא. כְּמָה דְאַתְּ אָמֵר, (דברים ל״ב:ט׳) יַעֲקֹב חֶבֶל נַחֲלָתוֹ. וְנִלְאָה, דָּא כְּנֶסֶת יִשְׂרָאֵל, דְּאִיהִי נִלְאָה בְּאַרְעָא אָחֳרָא, דְּאִיהִי צַחְיָא לְמִשְׁתֵּי, וּכְדֵין אִיהִי נִלְאָה. וְכַד הַהוּא גֶשֶׁם דִּרְעוּתָא אִתְיְהִיב, כְּדֵין אַתָּה כּוֹנַנְתָּה.</p>\n<p>וְעַל דָּא, שְׁמַיָא וְאַרְעָא, וְכָל חֵילֵיהוֹן, כֻּלְּהוּ קָיְימָא עַל קִיּוּמָא דָא. דִּכְתִיב (ירמיהו ל״ג:כ״ה) אִם לֹא בְרִיתִי יוֹמָם וָלַיְלָה חֻקּוֹת שָׁמַיִם וָאָרֶץ לֹא שָׂמְתִּי. וּבְּגִין כָּךְ בָּעֵי לְאִזְדַּהֲרָא בְּדָא, וְהָא אוּקְמוּהָ. וּבְגִין כָּךְ כְּתִיב, וַיְהִי יוֹסֵף יְפֵה תֹאַר וִיפֵה מַרְאֶה, וּבַתְרֵיהּ כְּתִיב וַתִּשָּׂא אֵשֶׁת אֲדֹנָיו אֶת עֵינֶיהָ אֶל יוֹסֵף.</p>"],[9520011392,"<p>וַיְהִי כְּדַבְּרָהּ אֵלָיו יוֹם יוֹם. רִבִּי אֶלְעָזָר פָּתַח וְאֲמַר, (משלי ו׳:כ״ד) לִשְׁמָרְךָ מֵאֵשֶׁת רָע וְגו', זַכָּאִין אִינוּן צַדִּיקַיָּא, דְּיָדְעֵי אָרְחוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא, לְמֵיזַל בְּהוּ. בְּגִין דְּאִינוּן מִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא יְמָמָא וְלֵילְיָא. דְּכָל מַאן דְּאִשְׁתַּדַּל בְּאוֹרַיְיתָא יוֹמֵי וְלֵילֵי, אַחְסִין תְּרֵין עָלְמִין, עַלְמָא עִלָּאָה, וְעַלְמָא <Nonei></i>תַּתָּאָה. אַחְסִין הַאי עַלְמָא, אַף עַל גַּב דְּלָא אִתְעַסַּק בָּהּ בַּר נָשׁ לִשְׁמָהּ, וְאַחְסִין הַהוּא עַלְמָא עִלָּאָה, כַּד אִתְעַסַּק בָּהּ בַּר נָשׁ לִשְׁמָהּ.</p>\n<p>תָּא חֲזֵי, מַה כְּתִיב, (משלי ג׳:ט״ז) אֹרֶךְ יָמִים בִּימִינָהּ בִּשְׂמֹאלָהּ עשֶׁר וְכָבוֹד. אֹרֶךְ יָמִים בִּימִינָהּ, מַאן דְּאָזִיל לִימִינָא דְאוֹרַיְיתָא, אָרְכָא דְחַיִּין אִיהוּ לְעַלְמָא דְאָתֵי. דְּזָכֵי תַּמָּן לִיקָרָא דְאוֹרַיְיתָא, דְּאִיהוּ יְקָרָא וְכִתְרָא, לְאִתְעַטְּרָא עַל כֹּלָּא. דְּכִתְרָא דְאוֹרַיְיתָא בְּהַהוּא עַלְמָא אִיהוּ. בִּשְׂמֹאלָהּ עשֶׁר וְכָבוֹד, בְּהַאי עַלְמָא, דְּאַף עַל גַּב דְּלָא אִתְעַסַּק בָּהּ לִשְׁמָהּ, זָכֵי בְּהַאי עַלְמָא בְּעוּתְרָא וִיקָרָא.</p>\n<p>דְּהָא רִבִּי חִיָּיא כַּד אֲתָא מֵהָתָם לְאַרְעָא דְיִשְׂרָאֵל, קָרָא בְּאוֹרַיְיתָא, עַד דְּהֲווּ אַנְפּוֹי נְהִירִין כְּשִׁמְשָׁא. וְכַד הֲווּ קָיְימִין קַמֵּיהּ כָּל אִינוּן דְּלָעָאן בְּאוֹרַיְיתָא. הֲוָה אָמַר, דָּא אִשְׁתַּדַּל בְּאוֹרַיְיתָא לִשְׁמָהּ, וְדָא לָא אִשְׁתַּדַּל לִשְׁמָהּ, וְהֲוָה צַלֵּי עַל הַהוּא דְּאִתְעַסַּק לִשְׁמָהּ, דְּלֶיהוֵי הָכִי תָּדִיר, וְיִזְכֵּי לְעַלְמָא דְאָתֵי. וְצַלֵּי עַל הַהוּא דְּלָא אִתְעַסַּק בָּהּ לִשְׁמָהּ, דְּיֵיתֵי לְאִתְעַסְּקָא בָּהּ לִשְׁמָהּ, וְיִזְכֵּי לְחַיֵּי עָלְמָא.</p>\n<p>יוֹמָא חַד, חָמָא חַד תַּלְמִיד דְּהֲוָה לָעֵי בְּאוֹרַיְיתָא, וְאַנְפּוֹי מוֹרִיקָן. אָמַר, וַדַּאי מְהַרְהֵר בְּחֶטְאָה אִיהוּ דְּנָא. אָחִיד לֵיהּ לְקַמֵּיהּ, וְאַמְשִׁיךְ עֲלֵיהּ בְּמִלִּין דְּאוֹרַיְיתָא, עַד דְּאִתְיַישַׁב רוּחֵיהּ בְּגַוֵּיהּ. מִן הַהוּא יוֹמָא וּלְהָלְאָה, שַׁוֵּי עַל רוּחֵיהּ, דְּלָא יִרְדֹּף בָּתַר אִינוּן הִרְהוּרִין בִּישִׁין, וְיִשְׁתַּדַּל בְּאוֹרַיְיתָא לִשְׁמָהּ.</p>\n<p>אָמַר רִבִּי יוֹסֵי, כַּד חָמֵי בַר נָשׁ דְּהִרְהוּרִין בִּישִׁין אַתְיָין לְגַבֵּיהּ, יִתְעַסַּק בְּאוֹרַיְיתָא, וּכְדֵין יִתְעַבְרוּן מִנֵּיהּ. אָמַר רִבִּי אֶלְעָזָר, כַּד הַהוּא סִטְרָא בִּישָׁא אָתֵי לְמִפְתֵּי לֵיהּ לְבַר נָשׁ, יְהֵא מָשִׁיךְ לֵיהּ לְגַבֵּי אוֹרַיְיתָא, וְיִתְפְּרַשׁ מִנֵּיהּ.</p>\n<p>תָּא חֲזֵי, דְּהָא תָּנִינָן, דְּכַד הַאי סִטְרָא בִישָׁא קָיְימָא קַמֵּיהּ דְקוּדְשָׁא בְּרִיךְ הוּא לְאַסְטָאָה עַל עַלְמָא בְּגִין עוֹבָדִין בִּישִׁין. קוּדְשָׁא בְּרִיךְ הוּא חָס עַל עַלְמָא, וְיָהִיב עֵיטָא לִבְנֵי נָשָׁא, לְאִשְׁתְּזָבָא מִנֵּיהּ. וְלָא יָכִיל לְשַׁלְטָאָה עֲלֵיהוֹן וְלָא עַל עוֹבָדֵיהוֹן, וּמַאי אִיהוּ עֵיטָא, לְאִשְׁתַּדְּלָא בְּאוֹרַיְיתָא, וְאִשְׁתֵּזָבוּ מִנֵּיהּ. מְנָלָן, דִּכְתִיב, (משלי ו׳:כ״ג) כִּי נֵר מִצְוָה וְתוֹרָה אוֹר וְדֶרֶךְ חַיִּים תּוֹכְחוֹת מוּסָר. מַה כְּתִיב בַּתְרֵיהּ לִשְׁמָרְךָ מֵאֵשֶׁת רָע מֵחֶלְקַת לָשׁוֹן נָכְרִיָּה.</p>\n<p>וְדָא הוּא סִטְרָא מְסָאֲבָא, סִטְרָא אָחֳרָא. דְאִיהִי קָיְימָא תָּדִיר קַמֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא, לְאַסְטָאָה עַל חוֹבֵיהוֹן דִּבְנֵי נָשָׁא. וְקָיְימָא תָּדִיר לְאַסְטָאָה לְתַתָּא לִבְנִי נָשָׁא. קָיְימָא תָּדִיר לְעֵילָא, בְּגִין לְאַדְכָּרָא חוֹבֵיהוֹן דִּבְנִי נָשָׁא, וּלְאַסְטָאָה לוֹן עַל עוֹבָדֵיהוֹן. וּבְגִין דְּאִתְיְהִיבוּ בִּרְשׁוּתֵיהּ, כְּמָה דְּעֲבַד לֵיהּ לְאִיּוֹב.</p>\n<p>וְכֵן קָיְימָא עֲלַיְיהוּ לְאַסְטָאָה וּלְאַדְכָּרָא חוֹבֵיהוֹן בְּכָל מַה דְּעֲבָדוּ, בְּאִינוּן זִמְנִין דְּקוּדְשָׁא בְּרִיךְ הוּא קָיְימָא עֲלַיְיהוּ בְּדִינָא. כְּדֵין קָאִים לְאַסְטָאָה לוֹן וּלְאַדְכָּרָא חוֹבֵיהוֹן. וְקוּדְשָׁא בְּרִיךְ הוּא חָס עֲלַיְיהוּ דְיִשְׂרָאֵל, וְיָהַב לוֹן עֵיטָא לְאִשְׁתְּזָבָא מִנֵּיהּ. וּבְמָּה, בַּשּׁוֹפָר בְּיוֹמָא דְרֹאשׁ הַשָּׁנָה, וּבְיוֹמָא דְכִפּוּרֵי בְּשָׂעִיר הַמִּשְׁתַּלֵּחַ דְּיָהֲבִין לֵיהּ, בְּגִין לְאִתְפְּרָשָׁא מִנַּיְיהוּ, וּלְאִשְׁתַּדְּלָא בְּהַהוּא חוּלָקֵיהּ, וְהָא אוּקְמוּהָ.</p>\n<p>תָּא חֲזֵי, מַה כְּתִיב, (משלי ה׳:ה׳) רַגְלֶיהָ יוֹרְדוֹת מָוֶת שְׁאוֹל צְעָדֶיהָ יִתְמוֹכוּ. וּבְרָזָא דִּמְהֵימְנוּתָא מַה כְּתִיב, (משלי ג׳:י״ז) דְּרָכֶיהָ דַרְכֵי נוֹעַם וְכָל נְתִיבוֹתֶיהָ שָׁלוֹם. וְאִלֵּין אִינוּן אָרְחִין וּשְׁבִילִין דְּאוֹרַיְיתָא, וְכֹלָּא חַד. הַאי שָׁלוֹם וְהַאי מָוְת, וְכֹלָּא הִפּוּכָן דָּא מִן דָּא.</p>\n<p>זַכָּאָה חוּלְקֵהוֹן דְּיִשְׂרָאֵל, דְּאִינוּן מִתְדַּבְּקִין בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא כְּדְקָא חָזֵי, וְיָהִיב לוֹן עֵיטָא לְאִשְׁתְּזָבָא מִכָּל סִטְרִין אָחֳרָנִין דְּעַלְמָא. בְּגִין דְּאִינוּן עַמָּא קַדִּישָׁא לְאַחְסַנְתֵּיהּ וְחוּלָקֵיהּ, וְעַל דָּא יָהִיב לוֹן עֵיטָא בְּכֹלָּא. זַכָּאִין אִינוּן בְּעַלְמָא דֵין, וּבְעַלְמָא דְאָתֵי.</p>\n<p>תָּא חֲזֵי, כַּד הַאי סִטְרָא בִּישָׁא נָחַת וְשָׁאט בְּעַלְמָא, וְחָמֵי עוֹבָדִין דִּבְנֵי נָשָׁא, דְּאִינוּן כֻּלְּהוּ סָטְאִין אָרְחַיְיהוּ בְּעַלְמָא. סָלִיק לְעֵילָא וְאַסְטִין לוֹן, וְאִלְמָלֵא דְּקוּדְשָׁא בְּרִיךְ הוּא חָיִיס עַל עוֹבָדֵי יְדוֹי, לָא יִשְׁתָּאֲרוּן בְּעַלְמָא.</p>\n<p>מַה כְּתִיב וַיְהִי כְּדַבְּרָהּ אֶל יוֹסֵף יוֹם יוֹם. כְּדַבְּרָהּ, <Nonei></i>דְסָלְקָא וְסָאטֵי בְּכָל יוֹמָא וְיוֹמָא, וְאָמַר קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, כַּמָּה בִּישִׁין כַּמָּה דִּלְטוֹרִין, בְּגִין לְשֵׁיצָאָה בְּנִי עַלְמָא.</p>\n<p>מַה כְּתִיב, וְלֹא שָׁמַע אֵלֶיהָ לִשְׁכַּב אֶצְלָהּ לִהְיוֹת עִמָּהּ. וְלא שָׁמַע אֵלֶיהָ, בְּגִין דְּאִיהוּ חָיִיס עַל עַלְמָא. לִשְׁכַּב אֶצְלָהּ, מַהוּ לִשְׁכַּב אֶצְלָהּ. בְּגִין לְנָסְבָא שָׁלְטָנוּ, לְשַׁלְּטָאָה עַל עַלְמָא, וְשָׁלְטָנוּ לָא שָׁלְטָא, עַד דְּאִתְיְהִיב לֵיהּ רְשׁוּ.</p>\n<p>דָּבָר אַחֵר לִשְׁכַּב אֶצְלָהּ, כְּמָה דְאַתְּ אָמֵר, (ויקרא ט״ו:ל״ג) וּלְאִישׁ אֲשֶׁר יִשְׁכַּב עִם טְמֵאָה. לִהְיוֹת עִמָּהּ לְמֵיהַב לָהּ רְבוּ וּבִרְכָאן וְסִיַּיעְתָּא. דְּאִלְּמָלֵא סִיּוּעָא הֲוָה לָהּ מִלְּעֵילָא, לָא אִשְׁתָּאַר בְּעַלְמָא אֲפִילּוּ חַד. אֲבָל בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא חָיִיס עַל עַלְמָא, אִשְׁתָּאַר עַלְמָא בְּקִיּוּמֵיהּ.</p>\n<p>רִבִּי אַבָּא אָמַר, כֹּלָּא אִיהוּ אָרְחָא חָדָא, אֲבָל יֵצֶר הָרָע הוּא דְקָא אָזִיל וּמְפַתֵּי לוֹן לִבְנֵי נָשָׁא, בְּגִין לְאַסְטָאָה אָרְחַיְיהוּ וּלְאִתְדַּבְּקָא בְּהוּ, בְּכָל יוֹמָא וְיוֹמָא, וּבְכָל עִידָן וְעִידָן. סָטֵי לֵיהּ לְבַר נָשׁ מֵאָרְחָא דִקְשׁוֹט, בְּגִין לְדַחְיָיא לֵיהּ מֵאָרְחָא דְחַיֵּי, לְאַמְשָׁכָא לֵיהּ לַגֵּיהִנֹּם.</p>\n<p>זַכָּאָה אִיהוּ מַאן דְּעָבִיד וְנָטִיר (נ\"א זכאה מאי עביד, נטיר) אָרְחוֹי וּשְׁבִילוֹי, בְּגִין דְּלָא יִתְדַּבַּק בֵּיהּ. הַיְינוּ דִכְתִיב וַיְהִי כְּדַבְּרָהּ אֶל יוֹסֵף יוֹם יוֹם וְלא שָׁמַע אֵלֶיהָ, כְּמָּה (נ\"א במה) דְּאִיהִי אֲמְרַת לֵיהּ בְּכָל יוֹמָא. דְּהָא רוּחַ מְסָאֲבָא, יֵצֶר הָרָע, אִיהוּ מְפַתֵּי לֵיהּ לְבַר נָשׁ, בְּכָל יוֹמָא, לִשְׁכַּב אֶצְלָהּ, גּוֹ גֵּיהִנֹּם, וּלְאִתְדָּנָא תַּמָּן, לִהְיוֹת עִמָּהּ.</p>\n<p>תָּא חֲזֵי, כַּד בַר נָשׁ אִתְדָּבַּק בְּהַהוּא סִטְרָא, אִתְמְשַׁךְ אֲבַתְרָהּ, וְאִסְתָּאַב עִמָּהּ בְּהַאי עַלְמָא, וְאִסְתָּאַב עִמָּהּ בְּעַלְמָא אָחֳרָא. תָּא חֲזֵי, הַאי סִטְרָא מְסָאֲבָא, מְנוּוָלָא אִיהוּ, לִכְלוּכָא אִיהוּ. כְּדִּכְתִיב, (ישעיהו ל׳:כ״ב) צֵא תֹּאמַר לוֹ, צוֹאָה מַמָּשׁ. וּבֵיהּ אִתְדָּן מַאן דְּאַסְטֵי אָרְחוֹי מִן אוֹרַיְיתָא, וּבֵיהּ אִתְדָנוּ אִינוּן חַיָּיבִין דְּעַלְמָא, דְּלֵית לוֹן מְהֵימְנוּתָא בְּקוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>מַה כְּתִיב, וַיְהִי כְּהַיּוֹם הַזֶּה וַיָּבֹא הַבַּיְתָה לַעֲשׂוֹת מְלַאכְתּוֹ וְאֵין אִישׁ מֵאַנְשֵׁי הַבַּיִת שָׁם בַּבָּיִת. וַיְהִי כְּהַיּוֹם הַזֶּה, יוֹמָא דְיֵצֶר הָרָע שָׁלְטָא בְּעַלְמָא, וְנָחֲתָא לְאַסְטָאָה לִבְנֵי נָשָׁא. אֵימָתַי, יוֹמָא דְאָתֵי בַּר נָשׁ לְאֲתָבָא בִּתְיוּבְתָּא עַל חוֹבוֹי, אוֹ לְאִשְׁתַּדְּלָא בְּאוֹרַיְיתָא, וּלְמֶעְבַּד פִּקּוּדֵי דְאוֹרַיְיתָא. וּכְדֵין בְּהַהוּא זִמְנָא נָחֲתָא, בְּגִין לְאַסְטָאָה לִבְנֵי עָלְמָא.</p>\n<p>וַיָּבֹא הַבַּיְתָה לַעֲשׂוֹת מְלַאכְתּוֹ, בְּגִין לְאִשְׁתַּדְּלָא בְּאוֹרַיְיתָא וּלְמֶעְבַּד פִּקּוּדֵי דְאוֹרַיְיתָא, דְּאִיהוּ מְלַאכְתּוֹ דְּבַר נָשׁ בְּהַאי עַלְמְא. וְכֵיוָן דְּעֲבִידְתָּא דְּבַר נָשׁ בְּהַאי עַלְמָא, הוּא עֲבִידְתָּא דְּקוּדְשָׁא בְּרִיךְ הוּא. בָּעֵי לֵיה לְבַר נָשׁ, לְמֶהֱוֵי תַּקִּיפָא כְּאַרְיָא בְּכָל סִטְרוֹי, בְּגִין דְּלָא יִשְׁלוֹט עֲלוֹי סִטְרָא אָחֳרָא, וְלָא יָכִיל לְמִפְתֵּי לֵיהּ. מַה כְּתִיב וְאֵין אִישׁ, לֵית גְּבַר דְּיֵקוּם לְקֳבְלֵיהּ דְּיֵצֶר הָרָע, וְיִגַּח בֵּיהּ קְרָבָא כְּדְקָא יָאוֹת.</p>\n<p>מַאי אוֹרְחֵיהּ דְּיֵצֶר הָרָע, כֵּיוָן דְּחָמֵי דְּלֵית בַּר נָשׁ קָאִים לְקֳבְלֵיהּ וּלְאַגָּחָא בֵּיהּ קְרָבָא, מִיָּד: וַתִּתְפְּשֵׂהוּ בְּבִגְדוֹ לֵאמֹר שִׁכְבָה עִמִּי. וַתִּתְפְּשֵׂהוּ בְּבִגְדוֹ, בְּגִין דְּכַד שַׁלִּיט יֵצֶר הָרָע עֲלֵיהּ דְּבַר נָשׁ, אַתְקִין לֵיהּ, וְקַשִּׁיט לֵיהּ לְבוּשׁוֹי, מְסַלְסֵל בְּשַׂעֲרֵיהּ. הֲדָא הוּא דִכְתִיב וַתִּתְפְּשֵׂהוּ בְּבִגְדוֹ לֵאמֹר שִׁכְבָה עִמִּי, אִתְדָּבַּק עִמִּי.</p>\n<p>מַאן דְּאִיהוּ זַכָּאָה, אִתְתַּקַּף לְקֳבְלֵיהּ, וְאַגַּח בֵּיהּ קְרָבָא. מַה כְּתִיב, וַיַּעֲזֹב בִּגְדוֹ בְּיָדָהּ וַיָּנָס וַיֵּצֵא הַחוּצָה, יִשְׁבּוֹק לֵיהּ, וְיִתְתַּקַּף לְקֳבְלֵיהּ. (ס\"א ואגח ביה קרבא) וְיֵעֲרוֹק מִנֵּיהּ, בְּגִין לְאִשְׁתְּזָבָא מִנֵּיהּ, וְלָא יִשְׁלוֹט עֲלוֹי.</p>\n<p>אָמַר רִבִּי יִצְחָק, זְמִינִין אִינוּן צַדִּיקַיָא לְמֶחמֵי לְיֵצֶר הָרָע, כְּחַד טוּרָא רַבְרְבָא, וְיִתְמְהוּן וְיֵימְרוּן. אֵיךְ יָכִילְנָא לְאַכְּפְיָא לֵיהּ לְטוּרָא רַבְרְבָא הָדֵין עִלָּאָה. וּזְמִינִין רַשִּׁיעַיָא לְמֶחֱמֵי לֵיהּ לְיֵצֶר הָרָע, דַּקִּיק כְּחוּטָא דְּשַׂעֲרָא, וְיִתְמְהוּן וְיֵימְרוּן. הֵיךְ לָא יָכִילְנָא לְאַכְּפְיָא לְחוּטָא דְשַׂעֲרָא כְּדָא דַּקִּיק. אִלֵּין יִבְכּוּן וְאִלֵּין יִבְכּוּן. וְקוּדְשָׁא בְּרִיךְ הוּא יְבַעֵר לֵיהּ מֵעַלְמָא, וְיִכּוֹס לֵיהּ לְעֵינַיְיהוּ, וְלָא יִשְׁלוֹט עוֹד בְּעַלְמָא, וְיֶחמוּן צַדִּיקַיָא וְיֶחֱדוּן. כְּמָה דְאַתְּ אָמֵר, (תהילים ק״מ:י״ד) אַךְ צַדִּיקִים יוֹדוּ לִשְׁמֶךָ יֵשְׁבוּ יְשָׁרִים אֶת פָּנֶיךָ.</p>"],[9520011393,"<p><Nonei></i>וַיְהִי אַחַר הַדְּבָרִים הָאֵלֶּה חָטְאוּ מַשְׁקֵה מֶלֶךְ מִצְרַיִם וְגו'. רִבִּי יְהוּדָה פָּתַח, (עמוס ג׳:ד׳) הֲיִשְׁאַג אַרְיֵה בַּיַּעַר וְטֶרֶף אֵין לוֹ הֲיִתֵּן כְּפִיר קוֹלוֹ מִמְּעוֹנָתוֹ בִּלְתִּי אִם לָכָד. הֲיִשְׁאַג אַרְיֵה בַּיַּעַר. תָּא חֲזֵי, כַּמָּה אִית לוֹן לִבְנֵי נָשָׁא לְאַשְׁגָּחָא בְּפוּלְחָנָא דְּקוּדְשָׁא בְּרִיךְ הוּא. דְּכָל מַאן דְּאִשְׁתַּדַּל בְּאוֹרַיְיתָא, וּבְפוּלְחָנָא דְקוּדְשָׁא בְּרִיךְ הוּא, דַּחַלְתֵּיהּ וְאֵימָתֵיהּ הוּא עַל כֹּלָּא. דְּהָא כַּד בָּרָא קוּדְשָׁא בְּרִיךְ הוּא עַלְמָא, עֲבַד כָּל בִּרְיָין דְּעַלְמָא, כָּל חַד וְחַד בְּדִיוּקְנֵיהּ כְּדְקָא חָזֵי לֵיהּ. וּלְבָתַר בָּרָא לֵיהּ לְבַר נָשׁ בְּדִיוּקְנָא עִלָּאָה, וְשַׁלְטֵיהּ עַל כֻּלְּהוּ, בְּדִיוּקְנָא דָא.</p>\n<p>דְּכָל זִמְנָא דְּבַר נָשׁ קָאִים בְּעַלְמָא, כָּל אִינוּן בִּרְיָין דְּעַלְמָא זָקְפִין רֵישָׁא, וּמִסְתַּכְּלָן בְּדִיוּקְנָא עִלָּאָה דְּבַר נָשׁ. כְּדֵין כֻּלְּהוּ דַּחֲלִין וְזָעִין מִקַּמֵּיהּ, כְּמָה דְאַתְּ אָמֵר, (בראשית ט׳:ב׳) וּמוֹרַאֲכֶם וְחִתְּכֶם יִהְיֶה עַל כָּל חַיַּת הָאָרֶץ וְעַל כָּל עוֹף הַשָּׁמַיִם וְגו', וְהַנֵּי מִילֵי, כַּד מִסְתַּכְּלָן וְחָמָאן בֵּיהּ, הַאי דִיוּקְנָא, וְנִשְׁמָתָא בֵּיהּ.</p>\n<p>אָמַר רִבִּי אֶלְעָזָר, אַף עַל גַּב דְּנִשְׁמָתָא לָאו בֵּיהּ, צַדִּיקַיָא לָא מִשְׁתַּנְיָין מִכְּמָה דְּהֲוָה דְיוּקְנְהוֹן בְּקַדְמִיתָא. וְכַד בַּר נָשׁ לָא אָזִיל בְּאָרְחוֹי דְאוֹרַיְיתָא, הַאי דִיוּקְנָא קַדִּישָׁא אִתְחַלַּף לֵיהּ. וּכְדֵין חֵיוַת בְּרָא וְעוֹפָא דִשְׁמַיָא יָכְלִין לְשַׁלְּטָאָה עֲלֵיהּ, בְּגִין דְּאִתְחַלַּף לֵיהּ הַאי דִיוּקְנָא קַדִּישָׁא, אִתְחַלַּף לֵיהּ הַאי דִיוּקְנָא דְבַר נָשׁ.</p>\n<p>וְתָּא חֲזֵי, קוּדְשָׁא בְּרִיךְ הוּא אַחְלַף עוֹבָדִין דִּלְעֵילָא וְתַתָּא, בְּגִין לְאַהֲדָרָא מִלִּין לְאַתְרַיְיהוּ, וּלְאִשְׁתַּכְּחָא רְעוּתֵיהּ בְּכָל עוֹבָדֵי דְעַלְמָא. דָּנִיֵּאל לָא אִשְׁתַּנֵּי דִיוּקְנֵיהּ כַּד אַפִּילוּ לֵיהּ בְּגוּבָא דְאַרְיְוָתָא, וּבְגִין כָּךְ אִשְׁתֵּזִיב. אָמַר רִבִּי חִזְקִיָּה, אִי הָכִי, הָא כְּתִיב, (דניאל ו׳:כ״ג) אֱלָהִי שְׁלַח מַלְאֲכֵיהּ וּסֲגַר פּוּם אַרְיָוָתָא וְלָא חַבְּלוּנִי. מַשְׁמַע דִּבְגִין מַלְאָכָא דְּאַסְגַּר לְפוּמַיְיהוּ, לָא אִתְחַבַּל.</p>\n<p>אָמַר לֵיהּ, בְּגִין דָא לָא אִתְחַבַּל, דְּהָא הַהוּא דִיוּקְנֵיהּ דְּבַר נָשׁ זַכָּאָה, אִיהוּ מַלְאָכָא מַמָּשׁ, דִּסְגִיר פּוּמָא, וְקָשִׁיר לוֹן, לְנַטְרָא לֵיהּ, דְּלָא יְחַבְּלוּן לֵיהּ. וּבְּגִין כָּךְ אֱלָהִי שְׁלַח מַלְאֲכֵיהּ, הַהוּא דְּכָל דִּיוּקְנִין דְּעַלְמָא מִתְחַקְּקָן בֵּיהּ, וְאִיהוּ אַתְקִיף דִּיוּקְנִי בִּי, וְלָא יָכִילוּ לְשַׁלְטָאָה בִּי, וְסָגַר פּוּמַיְיהוּ, וְעַל דָּא שָׁלַח מַלְאֲכֵיהּ וַדַּאי.</p>\n<p>וְהַאי מַלְאֲכָא, הַהוּא דְּכָל דִּיוּקְנִין מִתְחַקְּקָן בֵּיהּ. דִּכְתִיב, (תהילים ק״י:ו׳) יָדִין בַּגּוֹיִם מָלֵא גְוִיּוֹת, אִיהוּ דְּלָא אִשְׁתַּנֵּי קַמֵּיהּ כָּל דִּיוּקְנִין דְּעַלְמָא. וְעַל דָּא מִבָּעֵי לֵיהּ לְבַר נָשׁ, לְאִסְתַּמְּרָא אָרְחוֹי וּשְׁבִילוֹי, בְּגִין דְּלָא יֶחטָא קַמֵּיהּ דְּמָארֵיהּ, וְיִתְקַיַּים בְּדִיוּקְנָא דְאָדָם.</p>\n<p>תָּא חֲזֵי, יְחֶזְקֵאל נָטַר פּוּמֵיהּ מִמַּאֲכָלֵי דְאִיסּוּרֵי, דִּכְתִיב, (יחזקאלד) וְלָא בָּא בְּפִי בְּשַׂר פִּגּוּל, זָכָה וְאִקְרֵי בֶּן אָדָם. דָּנִיֵּאל מַה כְּתִיב בֵּיהּ, (דניאל א׳:ח׳) וַיָּשֶׂם דָּנִיֵּאל עַל לִבּוֹ אֲשֶׁר לא יִתְגָּאַל בְּפַת בַּג הַמֶּלֶךְ וּבְיֵין מִשְׁתָּיו, זָכָה הוּא, וְאִתְקְיַּים בִּדִיוּקְנֵיהּ דְּאָדָם. בְּגִין דְּכָל מִלִּין דְּעַלְמָא, כֻּלְּהוּ דַּחֲלִין מִקַּמֵּי דִּיוּקְנָא דְאָדָם, דְּאִיהוּ שַׁלִּיטָא עַל כֻּלְּהוּ, וְאִיהוּ מַלְכָּא עַל כֹּלָּא.</p>\n<p>אָמַר רִבִּי יוֹסֵי, בְּגִין דָּא אִצְטְרִיךְ לֵיהּ לְבַר נָשׁ, לְאִסְתַּמְּרָא מֵחוֹבוֹי, וְלָא יִסְטֵי לִימִינָא וְלִשְׂמָאלָא. וְעִם כָּל דָּא, בָּעֵי לֵיהּ לְבַר נָשׁ לְמִבְדַּק בְּחוֹבוֹי בְּכָל יוֹמָא וְיוֹמָא. דְּהָא כַּד בַר נָשׁ קָאִים מֵעַרְסֵיהּ, תְּרֵין סַהֲדִין קָיְימִין קַמֵּיהּ, וְאָזְלֵי בַּהֲדֵיהּ כָּל יוֹמָא.</p>\n<p>בָּעֵי בַּר נָשׁ לְמֵיקַם, אִינוּן סַהֲדֵי אָמְרִין לֵיהּ בְּשַׁעְתָּא דְּאַפְתַּח עֵינוֹי, (משלי ד׳:כ״ה) עֵינֶיךָ לְנֹכַח יַבִּיטוּ וְעַפְעַפֶּיךָ יַיְשִׁירוּ נְגְדֶּךָ. קָם וְאַתְקִין רַגְלוֹי לְמֵהַךְ, אִינוּן סַהֲדִין אָמְרִין לֵיהּ, (שם) פַּלֵּס מַעְגַּל רַגְלֶךָ וְגו'. וְעַל דָּא כַּד אָזִיל בַר נָשׁ, בְּכָל יוֹמָא, בָּעֵי לֵיהּ לְאִסְתַּמְּרָא מֵחוֹבוֹי.</p>\n<p>בְּכָל יוֹמָא וְיוֹמָא, כַּד אָתֵי לֵילְיָא, בָּעֵי לְאִסְתַּכְּלָא וּלְמִבְדַּק, בְּכָל מַה דְּעֲבַד כָּל הַהוּא יוֹמָא. בְּגִין דְּיֵיתוּב מִנַּיְיהוּ, וְיִסְתַּכֵּל בְּהוּ תָּדִיר, בְּגִין דְּיֵיתוּב קַמֵּי מָארֵיהּ. כְּמָה דְאַתְּ אָמֵר (תהילים נ״א:ה׳) וְחַטָּאתִי נֶגְדִּי תָמִיד, בְּגִין דְּיֵיתוּב מִנַּיְיהוּ.</p>\n<p>וְתָּא חֲזֵי, בְּזִמְנָא דְּהֲווּ יִשְׂרָאֵל בְּאַרְעָא קַדִּישָׁא, לָא אִשְׁתַּכַּח בִּידַיְיהוּ חוֹבָא, כְּמָה דְּאוּקְמוּהָ. בְּגִין דְּאִינוּן קָרְבָּנִין, דְּהֲווּ מַקְרִבִין בְּכָל יוֹמָא, <Nonei></i>הֲווּ מְכַפְּרֵי עֲלַיְיהוּ. הַשְׁתָּא דְּאִתְגָּלוֹן יִשְׂרָאֵל מֵאַרְעָא, וְלֵית מַאן דִּמְכַפֵּר עֲלַיְיהוּ, אוֹרַיְיתָא הִיא מְכַפְּרָא עֲלַיְיהוּ, וְעוֹבָדִין דְּכַשְׁרָן, בְּגִין דִּשְׁכִינְתָּא עִמְּהוֹן בְּגָלוּתָא. וּמַאן דְּאִיהוּ לָא מִסְתַּכַּל בְּאָרְחוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא, גָּרִים לִשְׁכִינְתָּא לְאִתְכַּפְיָא בְּגוֹ עַפְרָא, כְּמָה דְאַתְּ אָמֵר, (ישעיהו כ״ו:ה׳) יַשְׁפִּילֶנָּה יַשְׁפִּילָהּ עַד אָרֶץ וְגו'.</p>\n<p>אָמַר רִבִּי יִצְחָק, וְכֵן מַאן דְּאִשְׁתַּדַּל בְּאוֹרַיְיתָא וּבְעוֹבָדִין דְּכַשְׁרָן, גָּרִים לָהּ לְכְּנֶסֶת יִשְׂרָאֵל, לַאֲרָמָא רֵישָׁא בְּגוֹ גָלוּתָא. זַכָּאָה חוּלָקֵיהוֹן דְּאִינוּן דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא יְמָמָא וְלֵילֵי.</p>\n<p>תָּא חֲזֵי, גִּלְגֵּל קוּדְשָׁא בְּרִיךְ הוּא גִּלְגּוּלִין בְּעַלְמָא, בְּגִין לַאֲרָמָא רֵישָׁא דְצַדִּיקַיָיא, דְּהָא בְּגִין דְּיָרִים יוֹסֵף רֵישֵׁיהּ בְּעַלְמָא, עַל דְּאִשְׁתַּכַּח זַכָּאָה קַמֵּיהּ, אַרְגִּיז רִבּוֹנָא עַל עַבְדוֹי. כְּמָה דְאַתְּ אָמֵר חָטְאוּ מַשְׁקֵה מֶלֶךְ מִצְרַיִם וְהָאוֹפֶה לַאֲדוֹנֵיהֶם לְמֶלֶךְ מִצְרַיִם. וְכֹלָּא בְּגִין לַאֲרָמָא רֵישָׁא דְיוֹסֵף זַכָּאָה. וְתָּא חֲזֵי, עַל יְדָא דְחֶלְמָא, אִתְכַּפְיָיא מֵעִם אֲחוֹי, וְעַל יְדָא דְחֶלְמָא אִתְרַבֵּי עַל אֲחוֹי, וְאִתְרַבֵּי עַל כָּל עַלְמָא:</p>\n<p>וַיַּחַלְמוּ חֲלוֹם שְׁנֵיהֶם אִישׁ חֲלוֹמוֹ בְּלַיְלָה אֶחָד אִישׁ כְּפִתְרוֹן וְגו', תָּא חֲזֵי, דְּהָא אִתְּמָר דְּכָל חֶלְמִין אָזְלִין בָּתַר פּוּמָא, יוֹסֵף כַּד פָּשַׁר לְהוּ חֶלְמָא, אַמַּאי פָּשַׁר לְהַאי פִּישְׁרָא טָבָא, וּלְהַאי פִּישְׁרָא בִּישָׁא. אֶלָּא, אִינוּן חֶלְמִין עֲלֵיהּ דְּיוֹסֵף הֲוָה, וּבְגִין דְּיָדַע מִלָּה עַל עִקָּרָא וְשָׁרְשָׁא דִילָהּ, בְּגִין כָּךְ פָּשַׁר חֶלְמָא לְהוּ כְּמָה דְאִצְטְרִיךְ. לְכָל חַד וְחַד פָּשַׁר לְהוֹן פִּישְׁרָא, לְאַהֲדָרָא מִלָּה עַל אַתְרֵיהּ.</p>\n<p>מַה כְּתִיב וַיֹּאמֶר אֲלֵיהֶם יוֹסֵף הֲלֹא לֵאלהִים פִּתְרוֹנִים סַפְּרוּ נָא לִי. מַאי טַעְמָא, בְּגִין דְּהָכִי מִבָּעֵי לֵיהּ לְמִפְשַׁר חֶלְמָא, לְפָקְדָא פִּישְׁרָא לְקוּדְשָׁא בְּרִיךְ הוּא, בְּגִין דְּתַמָּן אִיהוּ קִיּוּמָא דְּכֹלָּא, וּבֵיהּ קָיְימָא פִּישְׁרָא.</p>\n<p>תָּא חֲזֵי, הָא אִתְּמָר דְּדַרְגָּא דְחֶלְמָא לְתַתָּא אִיהוּ, וְאִיהוּ דַרְגָּא שְׁתִיתָאָה. בְּגִין דְּהָא מֵאֲתַר דִּנְבוּאָה שַׁרְיָא עַד הַאי דַּרְגָּא דְחֶלְמָא, שִׁיתָּא דַרְגִּין אִינוּן. וְסָלְקָא פִּישְׁרָא מִדַּרְגָּא דְחֶלְמָא, לְדַרְגָּא אָחֳרָא. חֶלְמָא אִיהוּ דַרְגָּא דִלְתַתָּא, וּפִישְׁרָא קָיְימָא עֲלַיְיהוּ. וּפִישְׁרָא קָיְימָא בְּדִבּוּר, וְעַל דָּא בְּדִבּוּר קָיְימָא מִלָּה. דִּכְתִיב הֲלֹא לֵאלהִים פִּתְרוֹנִים, הֲלא לֵאלהִים וַדַּאי.</p>"],[9520011394,"<p>תָּא חֲזֵי, מַה כְּתִיב, וַיְסַפֵּר שַׂר הַמַּשְׁקִים אֶת חֲלוֹמוֹ לְיוֹסֵף וְגו'. רִבִּי אֶלְעָזָר פָּתַח וְאֲמַר, (מלכים ב ב׳:ט׳) וַיְהִי בְּעָבְרָם וְאֵלִיָּהוּ אָמַר אֶל אֱלִישָׁע שְׁאַל מָה אֶעֱשֶׂה לָךְ בְּטֶרֶם אֶלָּקַח מֵעִמָּךְ וַיֹּאמֶר אֱלִישָׁע וִיהִי נָא פִּי שְׁנַיִם בְּרוּחֲךָ אֵלָי. הָכָא אִית לְאִסְתַּכָּלָא, וְהַאי קְרָא תְּוָוהָא אִיהוּ. וְאֵלִיָּהוּ אָמַר אֶל אֱלִישָׁע שְׁאַל מָה אֶעֱשֶׂה לָךְ, וְכִי בִּרְשׁוּתֵיהּ קָיְימָא, וְהָא בִּרְשׁוּתֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא אִיהוּ. וְתוּ, דֶּאֱלִישָׁע הָכִי נָמֵי אִיהוּ הֲוָה יָדַע, מַאי טַעְמָא אָמַר, וִיהִי נָא פִּי שְׁנַיִם בְּרוּחֲךָ אֵלַי.</p>\n<p>אֶלָּא וַדַּאי, מַאן דְּאָחִיד בִּשְׁמַיָא וְאַרְעָא וְכָל עָלְמִין, הֵיךְ לָא יְהֵא בִּרְשׁוּתֵיהּ דָּא. וַדַּאי אֵלִיָּהוּ, וּשְׁאָר צַדִּיקִים, קוּדְשָׁא בְּרִיךְ הוּא עָבִיד רְעוּתְהוֹן דְּצַדִּיקַיָּיא תָּדִיר. דִּכְתִיב, (תהילים קמ״ה:י״ט) רְצוֹן יְרֵאָיו יַעֲשֶׂה, וְכָל שֶׁכֵּן דְּהַהוּא רוּחָא קַדִּישָׁא, דִּי עֲלֵיהּ, יָרִית לֵיהּ לְצַדִּיקָא דֶּאֱלִישָׁע, דְּהֲוָה שַׁמָּשָׁא דִילֵיהּ. וְהָא קוּדְשָׁא בְּרִיךְ הוּא אָמַר לֵיהּ (מלכים א י״ט:ט״ז) וְאֶת אֱלִישָׁע בֶּן שָׁפָט מֵאָבֵל מְחוֹלָה תִּמְשַׁח לְנָבִיא תַּחְתֶּיךָ, וְעַל דָּא הֲוָה לֵיהּ לֶאֱלִישָׁע לְיָרְתָא לֵיהּ.</p>\n<p>פִּי שְׁנַיִם בְּרוּחֲךָ, מַאי פִּי שְׁנַיִם בְּרוּחֲךָ אֵלַי, וְכִי סַלְקָא דַעְתָּךְ, דְּעַל חַד תְּרֵין שָׁאִיל, וּמַה דְּלָא הֲוָה בִּרְשׁוּתֵיהּ, הֵיךְ שָׁאַל מִינֵיהּ. אֶלָּא, אִיהוּ לָא שָׁאִיל רוּחַ עַל חַד תְּרֵין, אֶלָא (איהו) הָכִי שָׁאַל מִינֵּיהּ, בְּהַהוּא רוּחָא דְּהֲוָה לֵיהּ, דְּיַעֲבִיד (ד\"א ל\"ג חד) תְּרֵין נִמּוּסִין בְּעַלְמָא, בְּהַהוּא רוּחָא.</p>\n<p>מַה כְּתִיב וַיֹּאמֶר הִקְשֵׁיתָ לִשְׁאוֹל אִם תִּרְאֶה אוֹתִי לֻקָּח מֵאִתָּךְ יְהִי לְךָ כֵן וְאִם אַיִן לא יִהְיֶה. מַאי טַעְמָא אִם תִּרְאֶה אוֹתִי. אֶלָּא אָמַר לֵיהּ, אִם תֵּיכוּל לְמֵיקַם עַל עִקָּרָא דְרוּחָא דִּשָׁבַקְנָא לָךְ, בְּשַׁעְתָּא דְּאִתְנָסִיבְנָא מִינָךְ, יְהֵא לְךָ כְּדֵין. דְהָא כָּל הַהוּא עִקָּרָא דְרוּחָא בְּשַׁעְתָּא דְיִסְתַּכֵּל בֵּיהּ, כַּד חָמֵי לֵיהּ לְאֵלִיָּהוּ, יֶהֱוֵי דְבֵיקוּתָא בֵּיהּ, כְּדְקָא יְאוּת.</p>\n<p><Nonei></i>תָּא חֲזֵי, הַאי מַאן דְּאִסְתַּכַּל בְּמָּה דְאוֹלִיף מֵרַבֵּיהּ, וְחָמֵי לֵיהּ בְּהַהוּא חָכְמְתָא, יָכִיל לְאִתּוֹסְפָא בְּהַהוּא רוּחָא יַתִּיר. תָּא חֲזֵי, דְהָא יוֹסֵף בְּכָל מַה דְּאִיהוּ עָבִיד, הֲוֵי חָמֵי בְּרוּחָא דְחָכְמְתָא לְהַהוּא דִיוּקְנָא דְּאֲבוֹי, הֲוָה מִסְתַּכַּל. וּבְגִין כָּךְ הֲוָה מִסְתַּיְיעָא לֵיהּ מִלְּתָא, וְאִתּוֹסְפָא לֵיהּ רוּחָא אָחֳרָא, בִּנְהִירוּ עִלָּאָה יַתִּיר.</p>\n<p>בְּשַׁעְתָּא דְּאָמַר לֵיהּ הַהוּא רָשָׁע, וְהִנֵּה גֶּפֶן לְפָנָי, אִזְדַּעְזַע יוֹסֵף. דְּלָא הֲוָה יָדַע עַל מַה תֵּיתֵי מִלָּה, כֵּיוָן דְּאָמַר וּבַגֶּפֶן שְׁלשָׁה שָׂרִיגִים, מִיָּד אִתְעַר רוּחֵיהּ, וְאִתּוֹסַף בִּנְהִירוּ, וְאִסְתַּכַּל בְּדִיוּקְנָא דְּאֲבוֹי, כְּדֵין אִתְנְהִיר רוּחֵיהּ, וְיָדַע מִלָּה.</p>\n<p>מַה כְּתִיב, וּבַגֶּפֶן שְׁלשָׁה שָׂרִיגִים. אָמַר יוֹסֵף, הָא וַדַּאי בְּשׂוֹרָה דְחֶדְוָה בִּשְׁלִימוּ אִיהוּ, מַאי טַעְמָא, בְּגִין דְּהַאי גֶפֶן עַל כְּנֶסֶת יִשְׂרָאֵל אִתְחֲזֵי לֵיהּ, וְאִתְבַּשַּׂר יוֹסֵף בְּהַאי. וּבַגֶּפֶן שְׁלשָׁה שָׂרִיגִים, אִלֵּין אִינוּן תְּלָתָא דַרְגִּין עִלָאִין, דְּנָפְקֵי מֵהַאי גֶפֶן, כַּהֲנֵי לֵיוָאֵי וְיִשְׂרְאֵלֵי.</p>\n<p>וְהִיא כְפוֹרַחַת עָלְתָה נִצָּהּ, דְּהָא בְגִינֵיהוֹן סָלְקָא כְּנֶסֶת יִשְׂרָאֵל, וְאִתְבָּרְכַת מֵעִם מַלְכָּא עִלָּאָה. הִבְשִׁילוּ אַשְׁכְּלוֹתֶיהָ עֲנָבִים, אִלֵּין אִינוּן צַדִּיקַיָא דְעַלְמָא, דְּאִינוּן כַּעֲנָבִים מְבוּשָׁלִים כְּדְקָא חָזֵי. דָּבָר אַחֵר הִבְשִׁילוּ אַשְׁכְּלוֹתֶיהָ עֲנָבִים, דָּא הוּא יַיִן דְּאִתְנְטִיר בְּעִנְבַיְיהוּ מִשֵּׁשֶׁת יְמֵי בְרֵאשִׁית.</p>\n<p>עַד הָכָא אִתְבַּשַּׂר יוֹסֵף בְּחֶלְמֵיהּ, מִכָּאן וּלְהָלְאָה חֶלְמָא אִיהוּ דִילֵיהּ, בְּגִין דְּאִית חֶלְמִין לֵיהּ, וּלְאַחֲרָנִין. וָאֶקַח אֶת הָעֲנָבִים, דְּאִיהוּ לֵיהּ לְגַרְמֵיהּ.</p>\n<p>תָּנִינָן, (שמות קמד א) הַאי מַאן דְּחָמֵי עִנְבִין חִוָּורִין בְּחֶלְמָא, סִימָן יָפֶה לוֹ, אוּכָמֵי לָא. מַאי טַעְמָא, בְּגִין דְּאִיהוּ רָזָא דִתְרֵין דַּרְגִּין יְדִיעָן, אִינוּן אוּכָמֵי וְחִוָּורֵי. הַאי אִיהוּ טַב, וְהַאי אִיהוּ דְּלָא טַב, וְכֻלְּהוּ עִנְבִין בְּרָזָא דִמְהֵימְנוּתָא תַּלְיָין. וְעַל דָּא מִתְפַּרְשָׁן בְּחָכְמְתָא, הֵן לְטַב, הֵן לְבִישׁ. אִלֵּין צְרִיכִין רַחֲמֵי, וְאִלֵּין אַשְׁגָּחוּתָא דְרַחֲמֵי.</p>\n<p>תָּא חֲזֵי, אָדָם הָרִאשׁוֹן, אִנְתְּתֵיהּ סָחֲטָא לֵיהּ עִנְבִין, וְגָרִימַת לֵיהּ מוֹתָא, וּלְכָל יִשְׂרָאֵל, וּלְכָל עַלְמָא. נֹחַ אֲתָא לְהַנֵּי עִנְבִין, וְלָא אִתְנְטַר כְּדְקָא יְאוּת, מַה כְּתִיב, (בראשיתט) וַיֵּשְׁתְּ מִן הַיַּיִן וַיִּשְׁכָּר וַיִּתְגָּל בְּתוֹךְ אָהֳלֹה, בְּהֵ\"א. בְּנֵי אַהֲרֹן, שָׁתוּ חַמְרָא מִנַּיְיהוּ, וְקָרִיבוּ קָרְבָּנָא בְּהַהוּא חַמְרָא, וּמִיתוּ, וְהָא אִתְּמָר. וּבְגִין כָּךְ כְּתִיב, (דברים ל״ב:ל״ב) עֲנָבֵימוֹ עִנְבֵי רֹאשׁ אַשְׁכְּלוֹת מְרוֹרוֹת לָמּוֹ, בְּגִין דְּאִינוּן עִנְבִין גָּרְמֵי הַאי.</p>\n<p>חָמָא עִנְבִין דְּאִינוּן טָבִין, בְּהַהוּא כֶּרֶם, דְּקָא סָלְקִין נַיְיחָא וְרֵיחָא בְּדַרְגִּין שְׁלֵימִין, כְּדְקָא יְאוּת. וְעַל דָּא יוֹסֵף יָדַע מִלָּה, וְאִסְתַּכַּל בְּעִקָּרָא, וּפָשַׁר חֶלְמָא עַל בּוּרְיֵיהּ. בְּגִין דְּאִתְבַּשַּׂר בְּהַהוּא חֶלְמָא, כְּדְקָא יְאוּת. וּבְגִין כָּךְ פָּשַׁר פִּשְׁרָא לְטַב, וְאִתְקְיַּים הָכִי.</p>\n<p>מַה כְּתִיב. וַיַּרְא שַׂר הָאוֹפִים כִּי טוֹב פָּתָר וַיֹּאמֶר אֶל יוֹסֵף אַף אֲנִי בַּחֲלוֹמִי וְהִנִּה שְׁלשָׁה סַלֵּי חֹרִי עַל רֹאשִׁי. תָּא חֲזֵי, אֲרוּרִין אִינוּן רַשִּׁיעַיָא, דְּכָל עוֹבָדֵיהוֹן כֻּלְּהוֹן לְבִישׁ. וְכָל אִינוּן מִלִּין דְאִינוּן אָמְרִין, כֻּלְּהוּ לְבִישׁ, וּלְאַבְאָשָׁא.</p>\n<p>כֵּיוָן דְּפָתַח פּוּמֵיהּ בְּאַף, מִיָּד דָּחִיל יוֹסֵף, וְיָדַע דְּכָל מִלּוֹי אִינוּן לְאַבְאָשָׁא, וּבְשׂוֹרָה דְּבִישׁ בְּפוּמֵיהּ. וְהִנִּה שְׁלשָׁה סַלֵּי חֹרִי עַל רֹאשִׁי, כְּדֵין יָדַע יוֹסֵף דְּאִתְבַּשַּׂר עַל חֲרִיבוּ דְּבֵי מַקְדְּשָׁא, וְיִשְׂרָאֵל בְּגָלוּתָא, דְּיִתְגָּלוּן מֵאַרְעָא קַדִּישָׁא.</p>\n<p>חָמֵי מַה כְּתִיב, וּבַסַּל הָעֶלְיוֹן מִכָּל מַאֲכַל פַּרְעֹה מַעֲשֵׂה אוֹפֶה וְהָעוֹף אוֹכֵל אוֹתָם מִן הַסַּל מֵעַל רֹאשִׁי. אִלֵּין אִינוּן שְׁאָר עַמִין, דְּמִתְכַּנְשֵׁי עֲלַיְיהוּ דְיִשְׂרָאֵל, וְקָטְלֵי לוֹן, וְחָרְבֵי בֵיתַיְיהוּ, וּמְפַזְּרֵי לוֹן לְאַרְבַּע סִטְרֵי דְעַלְמָא. וְכֹלָּא אִסְתַּכַּל יוֹסֵף, וְיָדַע דְּהַהוּא חֶלְמָא עַל יִשְׂרָאֵל, כַּד יְהוֹן בְּחִיּוּבָא קַמֵּי מַלְכָּא, מִיָּד פָּשַׁר לֵיהּ פִּשְׁרָא לְבִישׁ, וְאִתְקְיַּים בֵּיהּ.</p>\n<p>וְתָּא חֲזֵי, תְּרֵין דַּרְגִּין אִלֵּין, דְּקָא חָמָא הַאי, וְחָמָא הַאי. דָּא חָמָא (דהא) <Nonei></i>כַּד סָלִיק, וְקָא שַׁלִּיט דַּרְגָּא עִלָּאָה, וְאִתְנְהִיר סִהֲרָא. וְדָא חָמָא, דְּאִתְחַשַּׁךְ וְשַׁלִּיט עֲלָהּ חִיוְיָא בִישָׁא. וּבְגִין כָּךְ אִסְתַּכַּל יוֹסֵף בְּהַהוּא חֶלְמָא, וּפָשַׁר לֵיהּ פִּשְׁרָא לְבִישׁ. וְעַל דָּא, כֹּלָּא בְּפִישְׁרָא קָיְימָא, וְדָא וְדָא חָמוּ, בְּאִלֵּין תְּרֵין דַּרְגִּין, דְּשַׁלִּיט דָּא, וְשַׁלִּיט דָּא.</p>"],[9520011395,"<p>רִבִּי יְהוּדָה פָּתַח, (תהילים נ״א:י״ב) לֵב טָהוֹר בְּרָא לִי אֱלהִים וְרוּחַ נָכוֹן חַדֵּשׁ בְּקִרְבִּי, הַאי קְרָא אוּקְמוּהָ, אֲבָל לֵב טָהוֹר, כְּמָה דְאַתְּ אָמֵר, (מלכים א ג׳:ט׳) וְנָתַתָּ לְעַבְדְּךָ לֵב שׁוֹמֵעַ וְגו', וּכְתִיב (משלי ט״ו:ט״ו) וְטוֹב לֵב מִשְׁתֶּה תָּמִיד, וּבְגִין כָּךְ לֵב טָהוֹר וַדַּאי.</p>\n<p>וְרוּחַ נָכוֹן חַדֵּשׁ בְּקִרְבִּי, דָּא הוּא רוּחַ נָכוֹן וַדַּאי. כְּמָה דְאַתְּ אָמֵר, (בראשית א׳:ב׳) וְרוּחַ אֱלֹהִים מְרַחֶפֶת עַל פְּנִי הַמָּיִם. וְאִתְעָרוּ, זֶה רוּחוֹ שֶׁל מָשִׁיחַ. וְאִתְעָרוּ, (יחזקאל י״א:י״ט) וְרוּחַ חֲדָשָׁה אֶתֵּן בְּקִרְבְּכֶם. וְצַלֵּי דָוִד, הַהוּא רוּחַ נָכוֹן, חַדֵּשׁ בְּקִרְבִּי.</p>\n<p>בְּגִין דְּאִית מִסִּטְרָא אָחֳרָא, לֵב טָמֵא וְרוּחַ עִוְעִים, דְּאַסְטֵי לִבְנֵי עַלְמָא, וְדָא הוּא רוּחַ טוּמְאָה, דְּאִקְרֵי רוּחַ עִוְעִים. כְּמָה דְאַתְּ אָמֵר, (ישעיהו י״ט:י״ד) יְיָ מָסַךְ בְּקִרְבָּהּ רוּחַ עִוְעִים. וְעַל דָּא וְרוּחַ נָכוֹן חַדֵּשׁ בְּקִרְבִּי. מַאי חָדֵּשׁ. דָּא חִדּוּשָׁא דְּסִיהֲרָא. בְּשַׁעְתָּא דְּאִתְחַדַּשׁ סִיהֲרָא, דָּוִד מֶלֶךְ יִשְׂרָאֵל חַי וְקַיָּים וּבְגִין כָּךְ חָדֵּשׁ.</p>\n<p>רִבִּי אֶלְעָזָר וְרִבִּי יוֹסֵי הֲווּ אָזְלֵי בְאָרְחָא. אָמַר רִבִּי יוֹסֵי לְרִבִּי אֶלְעָזָר, הַאי דִּכְתִיב, (מלכים א כ״ב:כ״א-כ״ב) וַיֵּצֵא הָרוּחַ וַיַּעֲמֹד לִפְנֵי יְיָ וַיֹּאמֶר אֲנִי אֲפַתֶּנּוּ וַיֹּאמֶר יְיָ אֵלָיו בְּמָּה וַיֹּאמֶר אֵצֵא וְהָיִיתִי רוּחַ שֶׁקֶר בְּפִי כָּל נְבִיאָיו וַיֹּאמֶר תְּפַתֶּה וְגַם תּוּכָל צֵא וַעֲשֵׂה כֵן. וְתָנִינָן דְּהֲוָה רוּחַ נָבוֹת הַיִּזְרְעֵאלִי. וְכִי נִשְׁמָתִין, כֵּיוָן דְּסָלְקִין וְקָיְימִין לְעֵילָא, אִינוּן יָכְלִין לְאֲתָבָא בְּהַאי עַלְמָא, וּמִלָּה תְּמִיהָה, דְּאָמַר אֵצֵא וְהָיִיתִי רוּחַ שֶׁקֶר בְּפִי וְגו'.</p>\n<p>וְתוּ, מַאי טַעְמָא אִתְעֲנַשׁ עֲלֵיהּ אַחְאָב, דְּהָא דִינָא דְאוֹרַיְיתָא, דְּשַׁוֵּי שְׁמוּאֵל קַמַּיְיהוּ דְיִשְׂרָאֵל, הָכִי הוּא. דִּכְתִיב, (שמואל א ח׳:י״ד) אֶת שְׂדוֹתֵיכֶם וְכַרְמֵיכֶם וְזֵיתֵיכֶם הַטּוֹבִים יִקָּח. וְאִי אַחְאָב נָטַל הַהוּא כֶּרְם בְּנָבוֹת, דִּינָא הֲוָה. וְתוּ, דְּהֲוָה יָהִיב לֵיהּ כַּרְמָא אָחֳרָא, אוֹ דַּהֲבָא, וְלָא בָעָא.</p>\n<p>אָמַר לֵיהּ, יָאוֹת שְׁאַלְתְּ. תָּא חֲזֵי, הַאי רוּחַ דְּקָאֲמְרוּ דְאִיהוּ רוּחַ דְּנָבוֹת, הָכָא אִית לְאִסְתַּכָּלָא. וְכִי רוּחָא דְנָבוֹת יָכִיל לְסַלְּקָא וּלְקַיְּימָא קַמֵּיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, לְמִתְבַּע שִׁקְרָא. דִּכְתִיב וַיֵּצֵא הָרוּחַ. וְאִי צַדִּיקָא הוּא, אֵיךְ יִבָּעֵי שִׁקְרָא בְּהַהוּא עַלְמָא, דְּאִיהוּ עַלְמָא דִקְשׁוֹט. וּמַה בְּהַאי עַלְמָא, לָא בָעֵי זַכָּאָה שִׁקְרָא, בְּהַהוּא עַלְמָא, לָא כָל שֶׁכֵּן. וְאִי לָאו זַכָּאָה אִיהוּ, הֵיךְ יָכִיל לְקָיְימָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>אֶלָּא וַדַּאי נָבוֹת לָאו זַכָּאָה הֲוָה כָּל כָּךְ לְקָיְימָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, אֶלָּא רוּחָא אָחֳרָא הֲוָה, דְּשָׁלְטָא בְּעַלְמָא. דְּדָא הוּא רוּחָא דְּקָיְימָא תָּדִיר וְסָלְקָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא. וְדָא הוּא דְאַסְטֵי לִבְנִי עַלְמָא בְּשִׁקְרָא. וּמַאן דְּאִיהוּ רָגִיל בְּשִׁקְרָא, אִשְׁתַּדַּל תָּדִיר בְּשִׁקְרָא. וְעַל דָּא אָמַר אֵצֵא וְהָיִיתִי רוּחַ שֶׁקֶר וְגו'. וְעַל דָּא קוּדְשָׁא בְּרִיךְ הוּא אָמַר לֵיהּ, צֵא וַעֲשֵׂה כֵן. פּוּק מֵהָכָא, כְּמָה דְאוּקְמוּהָ דִּכְתִיב, (תהילים ק״א:ז׳) דּוֹבֵר שְׁקָרִים לא יִכּוֹן לְנֶגֶד עֵינָי. וּבְגִין דָּא אִיהוּ רוּחַ שֶׁקֶר וַדַּאי.</p>\n<p>וְתוּ, עַל מַה דְּקָטַל לֵיהּ לְנָבוֹת וְנָטַל כַּרְמָא דִילֵיהּ, קָטוּלָא אַמַּאי קָטִיל לֵיהּ. אֶלָּא עַל דְּקָטִיל לֵיהּ בְּלָא דִינָא, אִתְעַנַּשׁ. קָטַל לֵיהּ בְּלָא דִינָא, וְנָסִיב כַּרְמָא דִילֵיהּ. וּבְגִין כָּךְ כְּתִיב, (מלכים א כ״א:י״ט) הֲרָצַחְתָּ וְגַם יָרַשְׁתָּ, וְעַל דָּא אִתְעַנַּשׁ. וְתָּא חֲזֵי, כַּמָּה אִינוּן בְּנֵי נָשָׁא בְּעַלְמָא, דְאַסְטֵי לוֹן הַאי רוּחַ שִׁקְרָא בְּשִׁקְרָא. וְשַׁלִּיט אִיהוּ בְּעַלְמָא בְּכַמָּה סִטְרִין וּבְכַמָּה עוֹבָדִין, וְהָא אוֹקִימְנָא מִלֵּי.</p>\n<p>וְעַל דָּא דָּוִד מַלְכָּא בָּעָא לְאִסְתַּמְרָא מִנֵּיהּ, ובָעָא לְאֲפָקָא מִגּוֹ מְסָאֲבוּ. דִּכְתִיב, (תהילים נ״א:י״ב) לֵב טָהוֹר בְּרָא לִי אֱלֹהִים וְרוּחַ נָכוֹן חַדֵּשׁ בְּקִרְבִּי. דָּא הוּא רוּחַ נָכוֹן, וְאָחֳרָא אִיהוּ רוּחַ שֶׁקֶר. וְעַל דָּא תְּרֵין דַּרְגִּין אִינוּן, חַד קַדִּישָׁא, וְחַד מְסָאֲבָא.</p>\n<p>פָּתַח וְאֲמַר, (יואל ב׳:י״א) וַיְיָ נָתַן קוֹלוֹ לִפְנֵי חֵילוֹ כִּי רַב מְאֹד מַחֲנִהוּ וְכִי עָצוּם עוֹשֵׂה דְבָרוֹ וְגו', הַאי קְרָא אוּקְמוּהָ. אֲבָל וַיְיָ, בְּכָל אֲתַר הוּא וּבֵי דִינֵיהּ. נָתַן קוֹלוֹ, דָּא הוּא קָלָא דִּכְתִיב, (דברים ד׳:י״ב) קוֹל דְּבָרִים. וּכְתִיב הָתָם, (שמות ד׳:י׳) לֹא אִישׁ דְּבָרִים. מַאן אִישׁ דְּבָרִים. כְּמָה דְאַתְּ אָמֵר, (דברים ל״ג:א׳) אִישׁ הָאֱלֹהִים. לִפְנֵי חֵילוֹ, אִלֵּין אִינוּן יִשְׂרָאֵל.</p>\n<p>כִּי רַב מְאֹד מַחֲנֵהוּ, כְּמָה דְאַתְּ אָמֵר (איוב כ״ה:ג׳) הֲיֵשׁ מִסְפָּר לִגְדוּדָיו. <Nonei></i>דְּכַמָּה מְמַנָּן וּשְׁלִיחָן אִית לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, וְכֻלְּהוּ קָיְימֵי לְאַסְטָאָה עֲלַיְיהוּ דְיִשְׂרָאֵל (זהר חדש ל\"ג בגין לאסתאבא להו). וְעַל דָּא קוּדְשָׁא בְּרִיךְ הוּא אִזְדַּמַּן קַמַּיְיהוּ דְיִשְׂרָאֵל בְּגִין לְנַטְרָא לְהוּ, וְלָא יָכִילוּ לְקַטְרְגָא לְהוּ.</p>\n<p>כִּי עָצוּם עוֹשֵׂה דְבָרוֹ. מַאן עָצוּם, דָּא הוּא זַכָּאָה הַהוּא דְּאִשְׁתַּדַּל בְּאוֹרַיְיתָא קַדִּישָׁא יְמָמָא וְלֵילֵי. דָּבָר אַחֵר כִּי עָצוּם, דָּא הוּא מְקַטְרְגָא דְּאִשְׁתַּכַּח קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא וְאִיהוּ תַּקִּיפָא כְּפַרְזְלָא תַּקִּיפָא כְּטִינָרָא. עוֹשֵׂה דְבָרוֹ, דְּנָטִיל רְשׁוּת מִלְּעֵילָא וְנָטִיל נִשְׁמָתָא מִתַּתָּא.</p>\n<p>כִּי גָדוֹל יוֹם יְיָ וְנוֹרָא מְאֹד וּמִי יְכִילֶנּוּ. דְּאִיהוּ שַׁלִּיט עַל כֹּלָּא, וְעִלָּאָה וְתַקִּיפָא עַל כֻּלְּהוּ, וְכֻלְּהוּ תְּחוֹת שָׁלְטָנֵיהּ. זַכָּאִין אִינוּן צַדִּיקַיָּיא, דְקוּדְשָׁא בְּרִיךְ הוּא אִתְרָעֵי בְּהוּ תָּדִיר, לְזַכָּאָה לוֹן לְעַלְמָא דְאָתֵי וּלְמֶחֱדֵי לְהוּ בְּחֵידוּ דְצַדִּיקַיָיא דִּזְמִינִין לְמֶחדֵי בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא. דִּכְתִיב, (תהילים ה׳:י״ב) וְיִשְׂמְחוּ כָל חוֹסֵי בָךְ לְעוֹלָם יְרַנִּנוּ וְתָסֵךְ עָלֵימוֹ וְיַעְלְצוּ בְךָ אוֹהֲבֵי שְׁמֶךָ. בָּרוּךְ יְיָ לְעוֹלָם אָמֵן ואָמֵן:</p>"],[9520011396,"<p>וַיְהִי מִקֵּץ, רִבִּי חִיָּיא פָּתַח וְאֲמַר, (איוב כ״ח:ג׳) קֵץ שָׂם לַחשֶׁךְ וּלְכָל תַּכְלִית הוּא חוֹקֵר אֶבֶן אֹפֶל וְצַלְמָוְת, הַאי קְרָא אִתְּמָר. קֵץ שָׂם לַחשֶׁךְ, דָּא אִיהוּ קֵץ דִּשְׂמָאלָא, דְּאִיהוּ שָׁאט בְּעַלְמָא, וְשָׁאט לְעֵילָא, וְקָיְימָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, וְאַסְטֵי, וְקַטְרִיג עַל עַלְמָא, וְהָא אִתְּמָר. וּלְכָל תַּכְלִית הוּא חוֹקֵר, דְּהָא כָּל עוֹבָדוֹי לָאו אִינוּן לְטַב, אֶלָּא לְשֵׁיצָאָה תָּדִיר וּלְמֶעְבַּד כְּלָיָה בְּעָלְמָא.</p>\n<p>אֶבֶן אֹפֶל וְצַלְמָוֶת, דָּא אֶבֶן נֶגֶף, דְּבָהּ כָּשְׁלִין חַיָּיבִין, וְקָיְימָא בְּהַאי דְאִקְרֵי, (איוב י׳:כ״ב) אֶרֶץ עֵפָתָהּ כְּמוֹ אֹפֶל. תָּא חֲזֵי, אִית אֶרֶץ חַיִּים לְעֵילָא, וְהַאי אִיהוּ אֶרֶץ יִשְׂרָאֵל. (ד\"א ואית ארץ לתתא ונקרא) אֹפֶל וְצַלְמָוֶת, אֹפֶל דְּנַפְקָא מֵאֶרֶץ עֵפָתָה. מַאי (ס\"א ארץ) אֶבֶן אֹפֶל וְצַלְמָוֶת, דָּא הוּא קֵץ דְּאִיהוּ מִסִּטְרָא דְחשֶׁךְ, זוּהֲמָא דְּדַהֲבָא, וְהָא אִתְּמָר.</p>\n<p>תָּא חֲזֵי, כַּמָּה אִית לוֹן לִבְנֵי נָשָׁא לְאִסְתַּכָּלָא בְּפוּלְחָנָא דְקוּדְשָׁא בְּרִיךְ הוּא, וּלְאִשְׁתַּדְּלָא בְּאוֹרַיְיתָא יְמָמָא וְלֵילֵי. בְּגִין דְּיִנְדְּעוּן וְיִסְתַּכְּלוּן בְּפוּלְחָנֵיהּ. דְּהָא אוֹרַיְיתָא אִיהִי מַכְרְזָא בְּכָל יוֹמָא קַמֵּיהּ דְּבַר נָשׁ וְאָמְרָה, (משלי ט׳:ט״ז) מִי פֶּתִי יָסוּר הֵנָּה חֲסַר לֵב וְאָמְרָה לוֹ, וְהָא אוֹקִימְנָא מִלֵּי.</p>\n<p>וְכַד בַּר נָשׁ אִשְׁתַּדַּל בְּאוֹרַיְיתָא, וְאִתְדָּבַּק בָּהּ, זָכֵי לְאִתְתַּקְפָא בְּאִילָנָא דְחַיֵּי, דִּכְתִיב, (משלי ג׳:י״ח) עֵץ חַיִּים וְגו'. וְתָּא חֲזֵי, כַּד בַּר נָשׁ אִתְתַּקַּף בְּאִילָנָא דְחַיֵּי בְּהַאי עַלְמָא, אִתְתַּקַּף בֵּיהּ לְעַלְמָא דְאָתֵי. דְּהָא כַּד נִשְׁמָתִין נָפְקִין מֵהַאי עַלְמָא, הָכִי אִתְתַּקְּנָן לְהוּ דַּרְגִּין לְעַלְמָא דְאָתֵי.</p>\n<p>תָּא חֲזֵי, אִילָנָא דְחַיֵּי, אִיהוּ בְּכַמָּה דַרְגִּין מִתְפָּרְשָׁן דָּא מִן דָּא, וְכֻלְּהוּ חַד. דְּהָא בְּאִילָנָא דְחַיֵּי אִית דַּרְגִּין אִלֵּין עַל אִלֵּין. עַנְפִין, וְעָלִין, קְלִיפִין, (ס\"א נופא) גּוּפָא דְאִילָנָא, שָׁרָשִׁין. וְכֹלָּא הוּא אִילָנָא. כְּגַוְונָא דָא, כָּל מַאן דְּאִשְׁתַּדַּל בְּאוֹרַיְיתָא, אִיהוּ אִתְתַּקַּן וְאִתְתַּקַּף בְּאִילָנָא דְחַיֵּי.</p>\n<p>וְכָל בְּנֵי דִּמְהֵימְנוּתָא יִשְׂרָאֵל, כֻּלְּהוֹן מִתְתַּקְּפִין בְּאִילָנָא דְחַיֵּי, כֻּלְּהוּ אֲחִידִין בְּאִילָנָא מַמָּשׁ. מִנְּהוֹן בְּהַהוּא (ס\"א נופא) גוּפָא דְּבֵיהּ, מִנְּהוֹן אֲחִידָן בְּעַנְפִין, מִנְּהוֹן בְּעָלִין, מִנְּהוֹן בְּשָׁרָשִׁין. אִשְׁתַּכָּחוּ דְּכֻלְּהוּ אֲחִידָן בְּאִילָנָא דְחַיֵּי. וְאִינוּן דְּמִשְׁתַּדְּלִין בְּאוֹרַיְיתָא <Nonei></i>כֻּלְּהוּ אֲחִידָן בְּגוּפָא דְאִילָנָא. וּבְּגִין כָּךְ מַאן דְּאִשְׁתַּדַּל בְּאוֹרַיְיתָא, אִיהוּ אָחִיד בְּכֹלָּא, וְהָא אוּקְמוּהָ וְאִתְּמָר.</p>\n<p>וַיְהִי מִקֵּץ, מַאי מִקֵּץ. רִבִּי שִׁמְעוֹן אָמַר, אֲתַר דְּלֵית בָּהּ זְכִירָה, וְדָא הוּא קֵץ דִּשְׂמָאלָא. מַאי טַעְמָא, בְּגִין דִּכְתִיב, (בראשית מ׳:י״ד) כִּי אִם זְכַרְתַּנִי אִתְּךָ כַּאֲשֶׁר יִיטַב לָךְ. וְכִי הָכִי אִתְחֲזֵי לֵיהּ לְיוֹסֵף צַדִּיקָא, דְּאִיהוּ אָמַר כִּי אִם זְכַרְתַּנִי אִתְּךָ. אֶלָּא כֵּיוָן דְּאִסְתַּכַּל יוֹסֵף בְּחֶלְמֵיהּ. אָמַר, וַדַּאי חֶלְמָא דִזְכִירָה אִיהוּ. וְאִיהוּ טָעָה בְּהַאי, דְּהָא בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא הֲוֵי כֹלָּא.</p>\n<p>וְעַל דָּא אֲתַר דְּהֲוָה בֵּיהּ נַשְׁיוּ קָם קַמֵּיהּ, מַה כְּתִיב וְלֹא זָכַר שַׂר הַמַּשְׁקִים אֶת יוֹסֵף וַיִּשְׁכָּחֵהוּ. כֵּיוָן דְּאָמַר וְלֹא זָכַר שַׂר הַמַּשְׁקִים, מַהוּ וַיִּשְׁכָּחֵהוּ. אֶלָּא וַיִּשְׁכָּחֵהוּ אֲתַר דְּאִית בֵּיהּ שִׁכְחָה, וְדָא הוּא קֵץ דְּסִטְרָא דְּחשֶׁךְ. שְׁנָתַיִם יָמִים, מַאי שְׁנָתַיִם. דְּתָב דַּרְגָּא, לְדַרְגָּא דְּאִית בֵּיהּ זְכִירָה.</p>\n<p>וּפַרְעֹה חוֹלֵם וְהִנֵּה עוֹמֵד עַל הַיְאֹר, דָּא חֶלְמָא דְיוֹסֵף הֲוָה. בְּגִין דְּכָל נָהָר, דְּיוֹסֵף הַצַּדִּיק אִיהוּ. וְרָזָא דָּא הֲוֵי, הַאי מַאן דְּחָמֵי נָהָר בַּחֲלוֹם, חָמֵי שָׁלוֹם. דִּכְתִיב, (ישעיהו ס״ו:י״ב) הִנְנִי נוֹטֶה אֵלֶיהָ כְּנָהָר שָׁלוֹם:</p>"],[9520011397,"<p>וַיְהִי מִקֵּץ שְׁנָתַיִם. רִבִּי חִיָּיא פָּתַח וְאֲמַר, (משלי כ״ט:ד׳) מֶלֶךְ בַּמִּשְׁפָּט יַעֲמִיד אֶרֶץ וְאִישׁ תְּרוּמוֹת יֶהֶרְסֶנָּה, תָּא חֲזֵי, כַּד בָּרָא קוּדְשָׁא בְּרִיךְ הוּא עַלְמָא עִלָּאָה, אַתְקִין כֹּלָּא כְּדְקָא יְאוּת, וְאַפִּיק נְהוֹרִין עִלָּאִין מְנַהֲרִין לְכָל סִטְרִין, וְכֹלָּא אִיהוּ חַד. וּבָרָא שָׁמַיִם דִלְעֵילָא וְאֶרֶץ דִּלְעֵילָא, לְאִתְתַּקְנָא כֻּלְּהוּ כְּחֲדָא, לְתוֹעַלְתָּא דְתַתָּאֵי.</p>\n<p>תָּא חֲזֵי, מֶלֶךְ בַּמִּשְׁפָּט יַעֲמִיד אֶרֶץ. מַאן מֶלֶךְ, דָּא קוּדְשָׁא בְּרִיךְ הוּא. בַּמִּשְׁפָּט, דָּא יַעֲקֹב, דְּאִיהוּ קִיּוּמָא דְאַרְעָא. וְעַל דָּא, ו' אִתְּזָן מִן ה' עִלָּאָה, ה' תַּתָּאָה אִתְּזָנַת מִן ו', דְּקִיּוּמָא דְאַרְעָא אִיהוּ בְּמִשְׁפָּט. דְּהָא מִשְׁפָּט יַעֲמִיד אֶרְץ בְּכָל תִּקּוּנוֹי, וְזָן לָהּ.</p>\n<p>דָּבָר אַחֵר, מֶלֶךְ, דָּא קוּדְשָׁא בְּרִיךְ הוּא. בַּמִּשְׁפָּט, דָּא יוֹסֵף. יַעֲמִיד אֶרֶץ, דִּכְתִיב (בראשית מ״א:נ״ז) וְכָל הָאָרֶץ בָּאוּ מִצְרַיְמָה לִשְׁבּוֹר אֶל יוֹסֵף. וּבְגִין דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרָעֵי בֵּיהּ בְּיַעֲקֹב, עֲבַד לֵיהּ לְיוֹסֵף שַׁלִּיטָא עַל אַרְעָא.</p>\n<p>רִבִּי יוֹסֵי אָמַר, מֶלֶךְ, דָּא יוֹסֵף. בַּמִּשְׁפָּט יַעֲמִיד אֶרֶץ, דָּא יַעֲקֹב. דְּהָא עַד לָא אֲתָא יַעֲקֹב לְמִצְרַיִם, לָא הֲוָה קִיּוּמָא בְּאַרְעָא, מִגּוֹ כַּפְנָא. כֵּיוָן דְּאֲתָא יַעֲקֹב לְמִצְרַיִם, בִּזְכוּתֵיהּ אִסְתַּלַּק כַּפְנָא, וְאִתְקְיַּים אַרְעָא.</p>\n<p>דָּבָר אַחֵר, מֶלֶךְ בַּמִּשְׁפָּט יַעֲמִיד אֶרֶץ, דָּא דָּוִד מַלְכָּא, דִּכְתִיב, (שמואל ב ח׳:ט״ו) וַיְהִי דָּוִד עוֹשֶׂה מִשְׁפָּט וּצְדָקָה לְכָל עַמּוֹ, וְאִיהוּ קִיֵּים אַרְעָא, וּבִזְכוּתֵיהּ קָיְימָא לְבָתַר דְּנָא. וְאִישׁ תְּרוּמוֹת יֶהֶרְסֶנָּה, דָּא רְחַבְעָם.</p>\n<p>תָּא חֲזֵי, קוּדְשָׁא בְּרִיךְ הוּא בְּגִינֵיהוֹן דְּצַדִּיקַיָא, אַף עַל גַּב דְּפוּרְעֲנוּתָא אִתְגְּזַר עַל עַלְמָא, מִתְעַכְּבָא בְּגִינֵיהוֹן וְלָא שָׁלְטָא עַל עַלְמָא. כָּל יוֹמוֹי דְּדָוִד מַלְכָּא אִתְקָיְימָא אַרְעָא בְּגִינֵיהּ, לְבָתַר דְּמִית אִתְקָיְימָא בִּזְכוּתֵיהּ. דִּכְתִיב, (מלכים ב כ׳:ו׳) וְגַנּוֹתִי עַל הָעִיר הַזֹּאת לְהוֹשִׁיעָהּ לְמַעֲנִי וּלְמַעַן דָּוִד עַבְדִּי. כְּגַוְונָא דָּא, כָּל יוֹמוֹי דְיַעֲקֹב וְכָל יוֹמוֹי דְיוֹסֵף, לָא שָׁלְטָא פּוּרְעֲנוּתָא בְּעַלְמָא.</p>\n<p>תָּא חֲזֵי, מֶלֶךְ בַּמִּשְׁפָּט יַעֲמִיד אֶרֶץ, דָּא יוֹסֵף. וְאִישׁ תְּרוּמוֹת יֶהֶרְסֶנָּה, דָּא פַּרְעֹה. דְּהָא בְּגִין דְּאַקְשֵׁי לִבֵּיהּ לְגַבֵּי דְּקוּדְשָׁא בְּרִיךְ הוּא, חָרִיב אַרְעָא דְמִצְרַיִם. וּבְקַדְמִיתָא עַל יְדָא דְיוֹסֵף אִתְקְיַּים אַרְעָא בְּהַהוּא חֶלְמָא דְּחָלַם. דִּכְתִיב, וַיְהִי מִקֵּץ שְׁנָתַיִם יָמִים וְגו'.</p>\n<p>וַיְהִי מִקֵּץ וְגו'. רִבִּי אֶלְעָזָר פָּתַח וְאֲמַר, (תהילים י״ח:מ״ז) חַי יְיָ וּבָרוּךְ צוּרִי וְיָרוּם אֱלֹהֵי יִשְׁעִי. אֱלוֹהֵי כְּתִיב, בְּוי\"ו. הַאי קְרָא אִית לְאִסְתַּכָּלָא בֵּיהּ. חַי יְיָ, דָּא חַי צַדִּיקָא יְסוֹדָא דְעַלְמָא, דְּאִקְרֵי חַי דְעָלְמִין. וּבָרוּךְ צוּרִי, דָּא (ס\"א הוד) הוּא דִכְתִיב (תהילים קמ״ד:א׳) בָּרוּךְ יְיָ צוּרִי, וְדָא עַלְמָא דְאִתְקְיַּים עֲלֵיהּ צַדִּיקָא דָא. וְיָרוּם אֱלהֵי יִשְׁעִי. וְיָרוּם דָּא עַלְמָא עִלָּאָה. אֱלוֹהֵי בְּוא\"ו, דָּא שָׁמַיִם, כְּמָה דְאַתְּ אָמֵר, (תהלים קטז) הַשָּׁמַיִם שָׁמַיִם לַיְיָ.</p>\n<p>תָּא חֲזֵי, (כמה דאת אמר) (תהילים ס״ח:כ׳) בָּרוּךְ אֲדֹנָ\"י יוֹם יוֹם יַעֲמָס לָנוּ. בָּרוּךְ אֲדֹנָ\"י, בְּאָלֶ\"ף דָּלֶ\"ת נוּ\"ן יוּ\"ד, וְהַאי קְרָא רָזָא דְּחָכְמְתָא אִיהוּ. יוֹם יוֹם, אֵלּוּ שְׁנָתַיִם יָמִים, כְּמָה דְאַתְּ אָמֵר <Nonei></i>וַיְהִי מִקֵּץ שְׁנָתַיִם יָמִים וּפַרְעֹה חוֹלֵם וְהִנֵּה עוֹמֵד עַל הַיְאוֹר, רָזָא אִיהוּ, כְּמָה דְאִתְּמָר דָּא יוֹסֵף. דְּנָהָר (ס\"א דכל נהר) דָּא, יוֹסֵף הַצַּדִּיק הוּא.</p>\n<p>וְהִנֵּה מִן הַיְאוֹר עוֹלוֹת שֶׁבַע פָּרוֹת יְפוֹת מַרְאֶה וּבְרִיאוֹת בָּשָׂר וַתִּרְעֶינָה בָּאָחוּ. וְהִנֵּה מִן הַיְאוֹר, דְּהָא מִנָּהָר דָּא אִתְבָּרְכָאן כָּל אִינוּן דַּרְגִּין דִּלְתַתָּא. בְּגִין דְּהַהוּא נָהָר דְּנָגִיד וְנָפִיק, אִיהוּ אַשְׁקֵי וְזָן לְכֹלָּא. וְיוֹסֵף אִיהוּ נָהָר, לְאִתְבָּרְכָא כָּל אַרְעָא דְמִצְרַיִם בְּגִינֵיהּ.</p>\n<p>וְתָּא חֲזֵי, הַהוּא נָהָר, שֶׁבַע דַּרְגִין אִתְשַׁקְיָין וְאִתְבָּרְכָן מִנֵּיהּ, וְאִלֵּין אִינוּן יְפוֹת מַרְאֶה וּבְרִיאוֹת בָּשָׂר. וַתִּרְעֶינָה בָּאָחוּ, בְּחִבּוּרָא בְּאַחְוָותָא דְּלָא אִשְׁתַּכַּח בְּהוּ פִּירוּדָא. וְכֻלְּהוּ לְשַׁבָּחָא קָיְימִין, דְּהָא כָּל הַנֵּי דַרְגִּין שֶׁבַע דְּקָאֲמָרָן, רָזָא אִיהוּ. כְּמָה דְאַתְּ אָמֵר, (אסתר ב׳:ט׳) וְאֵת שֶׁבַע הַנְּעָרוֹת הָרְאוּיוֹת לָתֵת לָהּ מִבֵּית הַמֶּלֶךְ וְגו'. וְעַל דָּא שֶׁבַע פָּרוֹת יְפוֹת מַרְאֶה, וְלָקֳבֵל דָּא כְּתִיב שִׁבְעַת הַסָּרִיסִים הַמְשָׁרְתִים אֶת פְּנֵי הַמֶּלֶךְ וְגו'.</p>\n<p>רִבִּי יִצְחָק אָמַר, שֶׁבַע פָּרוֹת הַטּוֹבוֹת, דַּרְגִּין אִינוּן עִלָּאִין עַל אָחֳרָנִין. וְשֶׁבַע הַפָּרוֹת הָרָעוֹת, דַּרְגִּין אָחֳרָנִין דִּלְתַתָּא. אִלֵּין מִסִּטְרָא דִקְדוּשָׁה, וְאִלֵּין מִסִּטְרָא דִּמְסָאֲבָא.</p>\n<p>שֶׁבַע הַשִּׁבֳּלִים, רִבִּי יְהוּדָה אָמַר, אִלֵּין קֳדָמָאי אִינוּן טָבִין, בְּגִין דְּאִינוּן מִסִּטְרָא דִימִינָא דִּכְתִיב בֵּיהּ כִּי טוֹב. וְאִלֵּין בִּישִׁין אִינוּן לְתַתָּא מִנַּיְיהוּ. שֶׁבַע הַשִּׁבֳּלִים אִינוּן מִסִּטְרָא דְּדַכְיוּ, וְאִלֵּין מִסִּטְרָא דִּמְסָאֲבוּ, וְכֻלְּהוּ דַּרְגִּין קָיְימִין אִלֵּין עַל אִלֵּין, וְאִלֵּין לָקֳבֵל אִלֵּין, וְכֻלְּהוּ קָא חָמָא פַּרְעֹה בְּחֶלְמֵיהּ.</p>\n<p>אָמַר רִבִּי יֵיסָא, וְכִי לְהַהוּא חַיָּיבָא דְפַרְעֹה אַחְזְיָין לֵיהּ כָּל הַנִּי. אָמַר לֵיהּ רִבִּי יְהוּדָה, כְּגַוְונָא דִלְהוֹן חָמָא. דְּכַמָּה דַּרְגִּין עַל דַּרְגִּין, אִלֵּין לָקֳבֵל אִלֵּין, וְאִלֵּין עַל אִלֵּין, וְאִיהוּ חָמָא בְּאִינוּן דַּרְגִּין דִּלְתַתָּא.</p>\n<p>וְהָא תָּנִינָן, דְּהָא כְּמָה דְאִיהוּ בַּר נָשׁ, הָכִי אַחְזְיוּ לֵיהּ בְּחֶלְמֵיהּ, וְהָכִי חָמֵי. וְנִשְׁמָתָא הָכִי סָלְקַת לְאִשְׁתְּמוֹדְעָא. כָּל חַד וְחַד כְּפוּם דַּרְגֵּיהּ כְּדְקָא חָזֵי לֵיהּ, וּבְגִין כָּךְ פַּרְעֹה חָמָא כְּדְקָא חָזֵי לֵיהּ, וְלָא יַתִּיר:</p>\n<p>וַיְהִי מִקֵּץ וְגו', רִבִּי חִזְקִיָּה פָּתַח וְאָמַר, (קהלת ג׳:א׳) לַכֹּל זְמַן וְעֵת לְכָל חֵפֶץ תַּחַת הַשָּׁמָיִם. תָּא חֲזֵי, כָּל מַה דְּעֲבַד קוּדְשָׁא בְּרִיךְ הוּא לְתַתָּא, לְכֹלָּא שַׁוֵּי זִמְנָא וּזְמַן קָצוּב. זְמַן שַׁוֵּי לִנְהוֹרָא וְלַחֲשׁוֹכָא, זִמְנָא שַׁוֵּי לִנְהוֹרָא דִּשְׁאָר עַמִּין, דְּאִינוּן שָׁלְטִין הַשְׁתָּא עַל עַלְמָא. וְזִמְנָא שַׁוֵּי לַחֲשׁוֹכָא, דְּאִיהוּ גָלוּתָא דְיִשְׂרָאֵל תְּחוֹת שָׁלְטָנוּתָא דִלְהוֹן. זִמְנָא שַׁוֵּי קוּדְשָׁא בְּרִיךְ הוּא לְכֹלָּא, בְגִין כָּךְ לַכֹּל זְמַן וְעֵת לְכָל חֵפֶץ. מַאי וְעֵת לְכָל חֵפֶץ. זִמְנָא וְעִדָּן הוּא לְכֹלָּא, לְכָל הַהוּא רְעוּתָא דְּאִשְׁתַּכַּח לְתַתָּא.</p>\n<p>דָּבָר אַחֵר וְעֵת לְכָל חֵפֶץ, מַאי עֵת. כְּדִכְתִיב, (תהילים קי״ט:קכ״ו) עֵת לַעֲשׂוֹת לַיְיָ הֵפֵרוּ תוֹרָתֶךָ. וּכְתִיב, (ויקרא יז) וְאַל יָבֹא בְכָל עֵת אֶל הַקֹּדֶשׁ. וְאִיהוּ דַרְגָּא מְמַנָּא, וְהָא אוּקְמוּהָ. וּבְגִין כָּךְ עֵת אִיהוּ מְמַנָּא, לְכָל חֵפֶץ תַּחַת הַשָּׁמָיִם. וַיְהִי מִקֵּץ שְׁנָתַיִם יָמִים, מִסִּטְרָא דְהַהוּא קֵץ דְּחשֶׁךְ חָמָא פַּרְעֹה בְּחֶלְמֵיהּ, וּמִתַּמָּן יָדַע וְאִתְגְּלִי לֵיהּ הַהוּא חֶלְמָא.</p>"],[9520011398,"<p>וַיְהִי בַבֹּקֶר וַתִּפָּעֶם רוּחוֹ וַיִּשְׁלַח וַיִּקְרָא אֶת כָּל חַרְטֻמֵּי מִצְרַיִם וְאֶת כָּל חֲכָמֶיהָ וְגו'. וַתִּפָּעֶם רוּחוֹ. מַאי וַתִּפָּעֶם. רִבִּי יוֹסֵי אָמַר, הָא אוּקְמוּהָ בְּפַרְעֹה כְּתִיב וַתִּפָּעֶם, וּבִנְבוּכַדְנֶצַּר כְּתִיב, (דניאל ב׳:ד׳) וַתִּתְפָּעֶם, וְאוּקְמוּהָ דְּהָא בְּפַרְעֹה כְּתִיב וַתִּפָּעֶם, בְּגִין דְּהֲוָה יָדַע חֶלְמָא, וּפִשְׁרָא לָא הֲוָה יָדַע, אֲבָל נְבוּכַדְנֶצַּר, חָמָא חֶלְמָא, וְחָמָא פִּשְׁרָא, וְאִתְנְשֵׁי כֹּלָּא מִנֵּיהּ.</p>\n<p>אֲבָל תָּא חֲזֵי, וַתִּפָּעֶם רוּחוֹ, כְּמָה דְאַתְּ אָמֵר, (שופטים יג) לְפַעֲמוֹ, דְּהֲוָה אָתֵי רוּחָא וְאָזִיל, וְאָתֵי וְאָזִיל. וְלָא הֲוָה מִתְיַישְׁבָא עִמֵּיהּ עֲדַיִין כְּדְקָא יְאוּת. וְעַל דָּא כְּתִיב, (שופטים י״ג:כ״ה) וַתָּחֶל רוּחַ יְיָ לְפַעֲמוֹ, דִּכְדֵין הֲוָה שֵׁירוּתָא. אוּף הָכָא רוּחֵיהּ אִתְעַר בֵּיהּ, וְאָזִיל וְאִתְעַר, וְלָא הֲוָה מִתְיַשְּׁבָא עִמֵּיהּ לְמִנְדַע. נְבוּכַדְנֶצַּר וַתִּתְפָּעֶם רוּחוֹ, בְּאִתְעֲרוּתָא הֲוָה אִתְעַר עַל חַד תְּרִין, (תייבין) וְאָזְלִין וְתָיְיבִין, וְדָא הוּא כְּמָה דְאַתְּ אָמֵר, (במדבר כ״ד:א׳) כְּפַעַם בְּפַעַם. פַּעַם בְּהַאי, <Nonei></i>וּפַעַם בְּהַאי, וְלָא מִתְיַשְּׁבָא דַּעְתֵּיהּ וְרוּחֵיהּ.</p>\n<p>וַיִּשְׁלַח וַיִּקְרָא אֶת כָּל חַרְטוּמֵי מִצְרַיִם, אִלֵּין חֳרָשִׁין. וְאֶת כָּל חֲכָמֶיהָ, אִלֵּין חַכִּימִין בְּטַיְירָא, וְכֻלְּהוּ הֲווּ מִסְתַּכְּלָן לְמִנְדַע וְלא יָכִילוּ לְאַדְבָּקָא.</p>\n<p>אָמַר רִבִּי יִצְחָק, אַף עַל גַּב דְּאִתְּמָר דְּלָא אַחְזְיָין לֵיהּ לְבַר נָשׁ אֶלָּא בְּהַהוּא דַרְגָּא דִילֵיהּ, שָׁאנִי לִמְלָכִים, דְּאַחְזְיָין לוֹן מִלִּין עִלָּאִין, וּמְשַׁנְיָין מִבְּנֵי נָשָׁא אָחֳרָנִין. כְּמָה דְמַלְכָּא דַּרְגֵּיהּ עִלָּאָה עַל כָּל שְׁאָר אָחֳרָנִין, הָכִי נָמֵי אַחֲזִיאוּ לֵיהּ בְּדַרְגָּא עִלָּאָה עַל כָּל שְׁאָר אָחֳרָנִין. כְּמָה דְאַתְּ אָמֵר אֶת אֲשֶׁר הָאֱלהִים עוֹשֶׂה הֶרְאָה אֶת פַּרְעֹה. (רלח א) אֲבָל לִשְׁאָר בְּנֵי נָשָׁא, לָא גָלֵי לוֹן קוּדְשָׁא בְּרִיךְ הוּא מַה דְּאִיהוּ עָבַד, בַּר לִנְבִיאֵי אוֹ לַחֲסִידֵי אוֹ לְחַכִּימֵי דָרָא, וְהָא אוּקְמוּהָ.</p>\n<p>תָּא חֲזֵי, כְּתִיב, אוֹתִי הֵשִׁיב עַל כַּנִּי וְאוֹתוֹ תָּלָה, מִכָּאן דְּחֶלְמָא אָזִיל בָּתַר פִּישְׁרָא. הֵשִׁיב עַל כַּנִּי מַאן, אֶלָּא דָּא יוֹסֵף. וְאוֹתוֹ תָלָה, בְּהַהוּא פִּישְׁרָא דְּקָא פָּשַׁר לֵיהּ, וּכְתִיב וַיְהִי כַּאֲשֶׁר פָּתַר לָנוּ כֵּן הָיָה:</p>"],[9520011399,"<p>וַיִּשְׁלַח פַּרְעֹה וַיִּקְרָא אֶת יוֹסֵף וַיְרִיצֻהוּ מִן הַבּוֹר וְגו'. רִבִּי אַבָּא פָּתַח וְאָמַר, (תהילים קמ״ז:י״א) רוֹצֶה יְיָ אֶת יְרֵאָיו אֶת הַמְיַחֲלִים לְחַסְדּוֹ. כַּמָּה קוּדְשָׁא בְּרִיךְ הוּא, אִתְרָעֵי בְּהוּ בְּצַדִּיקַיָא, בְּגִין דְּצַדִּיקַיָא אִינוּן עַבְדִּין (שלמא ועבדי) שְׁלָמָא לְעֵילָא, וְעַבְדֵי שְׁלָמָה לְתַתָּא, וְאָעֳלִין כַּלָּה בְּבַעֲלָהּ. וּבְגִין כָּךְ קוּדְשָׁא בְּרִיךְ הוּא אִתְרָעֵי בְּהוּ, בְּאִנּוּן דְּדַחֲלִין לֵיהּ וְעָבְדִין רְעוּתֵיהּ.</p>\n<p>לַמְיַחֲלִים לְחַסְדּוֹ, מַאן אִינוּן מְיַחֲלִים לְחַסְדּוֹ. הוֵי אֵימָא אִינוּן דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא בְּלֵילְיָא, וְאִשְׁתַּתְּפוּ בַּהֲדֵי שְׁכִינְתָּא. וְכָד אָתֵי צַפְרָא, אִינוּן מְחַכָּאן לְחַסְדּוֹ. וְהָא אוּקְמוּהָ, בְּזִמְנָא דְּבַר נָשׁ אִשְׁתַּדַּל בְּאוֹרַיְיתָא בְּלֵילְיָא, חוּטָא דְחֶסֶד אִתְמְשִׁיךְ עֲלֵיהּ בִּימָמָא. כְּדִכְתִיב, (תהילים מ״ב:ט׳) יוֹמָם יְצַוֶּה יְיָ חַסְדּוֹ וּבַלַיְלָה שִׁירֹה עִמִּי. מַאי טַעְמָא יוֹמָם יְצַוֶּה יְיָ חַסְדּוֹ, מִשּׁוּם דְּבַלַּיְלָה שִׁירֹה עִמִּי. וּבְּגִין כָּךְ רוֹצֶה יְיָ אֶת יְרֵאָיו כְּתִיב, וְלֹא בִירֵאָיו. כְּמַאן דְּרָעֵי בִּרְעוּתֵיהּ לְאַחֲרָא, וְאִתְרְעֵי לֵיהּ לְאִתְפַּיְיסָא בַּהֲדֵיהּ. וּבְגִין כָּךְ רוֹצֶה יְיָ אֶת יְרֵאָיו, וְלֹא בִּירֵאָיו.</p>\n<p>כְּגַוְונָא דָא, יוֹסֵף הֲוָה עָצִיב בַּעֲצִיבוּ דְרוּחָא, בַּעֲצִיבוּ דְלִבָּא, דְּהֲוָה אָסִיר תַּמָּן. כֵּיוָן דְּשַׁדַּר פַּרְעֹה בְּגִינֵיהּ, מַה כְּתִיב. וַיְרִיצוּהוּ, אִתְפַּיְיסוּ לֵיהּ וְאַהֲדָרוּ לֵיהּ מִלִּין דְּחֶדְוָה, מִלִּין לְמֶחֱדֵי לִבָּא, בְּגִין דְּהֲוָה עָצִיב מִן בֵּירָא. תָּא חֲזֵי, בְּקַדְמִיתָא נָפַל בְּבֵירָא, בְּבֵירָא אִסְתַּלַּק לְבָתַר.</p>\n<p>רִבִּי שִׁמְעוֹן אָמַר, עַד לָא אֵירַע לְיוֹסֵף הַהוּא עוֹבָדָא, לָא אִקְרֵי צַדִּיק. כֵּיוָן דְּנָטַר הַהוּא בְּרִית קַיָּימָא, אִקְרֵי צַדִּיק. וְהַהוּא דַּרְגָּא דִּבְרִית קַדִּישָׁא אִתְעַטַּר בַּהֲדֵיהּ, וּמַאי דְּהֲוָה (עביד) בַּבּוֹר בְּקַדְמִיתָא, אִסְתַּלַּק בַּהֲדֵיהּ, וּכְתִיב וַיְרִיצֻהוּ מִן הַבּוֹר. אִסְתַּלַּק מִן דָּא, וְאִתְעַטַּר בִּבְאֵר מַיִם חַיִּים.</p>\n<p>וַיִּשְׁלַח פַּרְעֹה וַיִּקְרָא אֶת יוֹסֵף, לִקְרֹא לְיוֹסֵף מִבָּעֵי לֵיהּ. אֶלָּא וַיִּקְרָא אֶת יוֹסֵף, דָּא קוּדְשָׁא בְּרִיךְ הוּא, דִּכְתִיב, (תהילים ק״ה:י״ט) עַד עֵת בֹּא דְבָרוֹ אִמְרַת יְיָ צְרָפָתְהוּ. עַד עֵת בֹּא דְבָרוֹ, הֲדָא הוּא דִכְתִיב וַיּקְרָא אֶת יוֹסֵף, כְּתִיב הָכָא וַיִּקְרָא אֶת יוֹסֵף, וּכְתִיב הָתָם וַיִּקְרָא אֶל משֶׁה: וַיְגַלַּח וַיְחַלֵּף שִׂמְלוֹתָיו, בְּגִין יְקָרָא דְמַלְכָּא, וְהָא אוּקְמוּהָ.</p>\n<p>רִבִּי אֶלְעָזָר פָּתַח, (תהילים ק״ה:כ״ג) וַיָּבֹא יִשְׂרָאֵל מִצְרַיִם וְיַעֲקֹב גָּר בְּאֶרֶץ חָם. תָּא חֲזֵי, דְּקוּדְשָׁא בְּרִיךְ הוּא מְגַלְגֵּל גִּלְגּוּלִין בְּעַלְמָא, וּמְקַיֵּים אֱסָרִין וְקִיּוּמִין, בְּגִין לְקַיְימָא קִיּוּמָא וּגְזֵרָה דְּאִיהוּ גָּזִיר.</p>\n<p>דְּהָא תְּנַן, אִלְּמָלֵא חֲבִיבוּ וּרְחִימוּ דְּרָחִים קוּדְשָׁא בְּרִיךְ הוּא לַאֲבָהָן, הֲוָה אִתְחֲזֵי לְנָחֲתָא יַעֲקֹב לְמִצְרַיִם בְּשַׁלְשְׁלֵי דְּפַרְזְלָא. וּבִרְחִימוּ דִלְהוֹן, שַׁלְטֵיהּ לְיוֹסֵף בְּרֵיהּ, וְעֲבַד לֵיהּ מַלְכָּא דְשַׁלִּיטָא עַל כָּל אַרְעָא, וְנָחֲתוּ כֻּלְּהוּ שִׁבְטִין בִּיקָרָא, וְיַעֲקֹב כְּמַלְכָּא.</p>\n<p>תָּא חֲזֵי, מַה כְּתִיב, וַיָּבֹא יִשְׂרָאֵל מִצְרַיִם וְיַעֲקֹב גָּר בְּאֶרֶץ חָם, כֵּיוָן דִּכְתִיב וַיָּבֹא יִשְׂרָאֵל מִצְרַיִם, לָא יְדַעְנָא דְּיַעֲקֹב גָּר בְּאֶרֶץ חָם, אַמַּאי אִצְטְרִיךְ הָא. אֶלָּא וַיָּבֹא יִשְׂרָאֵל מִצְרַיִם, דָּא קוּדְשָׁא בְּרִיךְ הוּא. וְיַעֲקֹב גָּר בְּאֶרֶץ חָם, דָּא יַעֲקֹב, דְּהָא בְּגִינֵיהּ דְּיַעֲקֹב וּבְנוֹי, אֲתָא שְׁכִינְתָּא לְמִצְרַיִם. וְקוּדְשָׁא בְּרִיךְ הוּא גִּלְגֵּל גִּלְגּוּלִין, <Nonei></i>וְאָחִית לֵיהּ לְיוֹסֵף בְּקַדְמִיתָא. דְּבִזְכוּתֵיהּ אִתְקְיַּים בְּרִית בַּהֲדֵיהּ, וְשַׁלְטֵיהּ עַל כָּל אַרְעָא.</p>\n<p>מַה כְּתִיב, שָׁלַח מֶלֶךְ וַיַּתִּירֵהוּ מוֹשֵׁל עַמִּים וַיְפַתְּחֵהוּ. רִבִּי שִׁמְעוֹן אָמַר, כְּתִיב, (תהילים קמ״ו:ז׳) יְיָ מַתִּיר אֲסוּרִים וְגו', (והא) וְהָכָא כְּתִיב, שָׁלַח מֶלֶךְ וַיַּתִּירֵהוּ, אַמַּאי מוֹשֵׁל עַמִּים וַיְפַתְּחֵהוּ. אֶלָּא, שָׁלַח מֶלֶךְ, דָּא קוּדְשָׁא בְּרִיךְ הוּא. מוֹשֵׁל עַמִּים, דָּא קוּדְשָׁא בְּרִיךְ הוּא. שָׁלַח מֶלֶךְ, מֶלֶךְ עִלָּאָה שָׁלַח וַיַּתִּיִרִהוּ, וּמַאן אִיהוּ דְּשָׁלַח (ליה), דָּא מַלְאָךְ הַגּוֹאֵל, דְּאִיהוּ מוֹשֵׁל עַמִּים, דְּאִיהוּ מוֹשֵׁל עַל תַּתָּאֵי. וְכֹלָּא מֵעִם קוּדְשָׁא בְּרִיךְ הוּא אִיהוּ.</p>\n<p>וַיְרִיצֻהוּ חָסֵר וא\"ו, וּמַאן אִיהוּ, דָּא קוּדְשָׁא בְּרִיךְ הוּא. בְּגִין דְּהָא לֵית מַאן דְּאָסִיר וּפַתַּח, בַּר קוּדְשָׁא בְּרִיךְ הוּא, דִּכְתִיב, (איוב י״ב:י״ד) יִסְגֹּר עַל אִישׁ וְלֹא יִפָּתֵחַ. וּכְתִיב, (איוב לה) וְהוּא יַשְׁקִיט וּמִי יַרְשִׁיעַ וְיַסְתֵּר פָּנִים וּמִי יְשׁוּרֶנּוּ וְעַל גּוֹי וְעַל אָדָם יָחַד, דְּהָא כֹּלָּא בֵּיהּ. וּכְתִיב, (דניאל ד׳:ל״ב) וּכְמִצְבְּיֵהּ עָבֵד בְּחֵיל שְׁמַיָא וְדָיְירֵי אַרְעָא וְלָא אִיתַי דִי יְמַחֵי בִידֵיהּ וְיֵאמַר לֵיהּ מָה עֲבַדְתְּ. וּבְגִין כָּךְ כְּתִיב, וַיְרִיצֻהוּ מִן הַבּוֹר וְגו'.</p>\n<p>מַאי וַיְרִיצֻהוּ. כְּמָה דְאַתְּ אָמֵר, (איוב ל״ג:כ״ו) יֶעְתַּר אֶל אֱלוֹהַּ וַיִּרְצֵהוּ. כְּגַוְונָא דָא וַיְרִיצֻהוּ מִן הַבּוֹר, וּלְבָתַר וַיָּבֹא אֶל פַּרְעֹה. דָּבָר אַחֵר וַיְרִיצֻהוּ, דְּאַמְשִׁיךְ עֲלֵיהּ חוּטָא דְחֶסֶד, לְמֵיהַב לֵיהּ חִנָּא קַמֵּיהּ דְּפַרְעֹה. (מה כתיב), אֱלֹהִים יַעֲנֶה אֶת שְׁלוֹם פַּרְעֹה, בְּגִין לְאַקְדָּמָא לֵיהּ שָׁלוֹם וּלְמִפְתַּח בְּשָׁלוֹם.</p>\n<p>רִבִּי אַבָּא אָמַר, תָּא חֲזֵי, בְּהַהוּא רָשָׁע דְּפַרְעֹה. דְּאִיהוּ אָמַר, (שמות ה׳:ב׳) לא יָדַעְתִּי אֶת יְיָ, וּפַרְעֹה חַכִּים הֲוָה מִכָּל חֳרָשׁוֹי. אֶלָּא וַדַּאי שְׁמָא דְּאֱלֹהִים הֲוָה יָדַע, דְּהָא כְּתִיב, הֲנִמְצָא כָזֶה אִישׁ אֲשֶׁר רוּחַ אֱלהִים בּוֹ. וּבְגִין דְּמשֶׁה לָא אֲתָא לְגַבֵּיהּ אֶלָּא בִּשְׁמָא דַּיְיָ וְלֹא בִּשְׁמָא דְּאֱלהִים. וְדָא הֲוָה קַשְׁיָא קַמֵיהּ מִכֹּלָּא, דְּאִיהוּ הֲוָה יָדַע דְּהָא שְׁמָא דָא אִיהוּ שַׁלִּיט בְּאַרְעָא. וּבִשְׁמָא דַּיְיָ לָא הֲוָה יָדַע, וְעַל דָּא קַשְׁיָא קַמֵּיהּ שְׁמָא דָא.</p>\n<p>וְדָא הוּא דִכְתִיב (שמות ט׳:י״ב) וַיְחֲזֵק יְיָ אֶת לֵב פַּרְעֹה, דְּמִלָּה דָא הֲוָה אַתְקִיף לִבֵּיהּ, וְאַקְשֵׁי לֵיהּ. וְעַל דָּא משֶׁה לא אוֹדַע לֵיהּ מִלָּה דִּשְׁמָא אָחֳרָא, אֶלָא שְׁמָא דַּיְיָ בִּלְחוֹדוֹי, וְאוּקְמוּהָ.</p>\n<p>פָּתַח וְאָמַר, (תהילים קי״ג:ה׳) מִי כַּיְיָ אֱלֹקֵינוּ הַמַּגְבִּיהִי לָשָׁבֶת וְגו'. מִי כַּיְיָ אֱלֹקֵינוּ הַמַּגְבִּיהִי לָשָׁבֶת, דְּאִסְתַּלַּק מֵעַל כָּרְסֵי יְקָרֵיהּ, (ס\"א על כרסי יקריה לעילא) וְלָא אִתְגְּלִי לְתַתָּא. בְּשַׁעְתָּא דְּלָא אִשְׁתַּכָּחוּ זַכָּאִין בְּעַלְמָא, הָא אִיהוּ אִסְתַּלַּק מִנַּיְיהוּ, וְלָא אִתְגְּלִי לְהוּ. הַמַּשְׁפִּילִי לִרְאוֹת, בְּשַׁעְתָּא דְּזַכָּאִין אִינוּן דְּאִשְׁתַּכָּחוּ בְּעַלְמָא. קוּדְשָׁא בְּרִיךְ הוּא נָחִית בְּדַרְגּוֹי לְקִבְלֵהוֹן דְּתַתָּאֵי, לְאַשְׁגָּחָא עַל עַלְמָא, לְאוֹטָבָא לְהוּ.</p>\n<p>דְּהָא כַּד זַכָּאִין לָא אִשְׁתַּכָּחוּ בְּעַלְמָא, אִיהוּ אִסְתַּלַּק, וְאַסְתִּיר אַנְפִּין מִנַּיְיהוּ, וְלא אַשְׁגַּח עֲלַיְיהוּ. בְּגִין דְּצַדִּיקַיָּיא אִינוּן יְסוֹדָא וְקִיּוּמָא דְעַלְמָא, דִּכְתִיב, (משלי י׳:כ״ה) וְצַדִּיק יְסוֹד עוֹלָם.</p>\n<p>וְעַל דָּא קוּדְשָׁא בְּרִיךְ הוּא לָא גַּלֵּי שְׁמֵיהּ קַדִּישָׁא, בַּר לְיִשְׂרָאֵל בִּלְחוֹדוֹי, דְּאִינוּן חוּלַק עַדְבֵיהּ וְאַחְסַנְתֵּיהּ. וְעַלְמָא פָּלִיג לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לִמְמַנָּן תְּרִיסִין, וְהָא אִתְּמָר. דִּכְתִיב, (דברים ל״ב:ט׳) בְּהַנְחֵל עֶלְיוֹן גּוֹיִם וְגו'. וּכְתִיב, כִּי חֵלֶק יְיָ עַמּוֹ יַעֲקֹב חֶבֶל נַחֲלָתוֹ.</p>\n<p>רִבִּי חִיָּיא וְרִבִּי יוֹסֵי הֲווּ אָזְלֵי בְאָרְחָא. אָמַר רִבִּי יוֹסֵי לְרִבִּי חִיָּיא, תְּוַוהְנָא עַל הַאי דְּקָאֲמַר שְׁלֹמֹה, כָּל מִלּוֹי (מילין) סְתִימִין וְלָא אִתְיָידְעוּן, דְּהָא קֹהֶלֶת סָתִים (מילין) סְתִימִין.</p>\n<p>פָּתַח וְאָמַר, (קהלת א׳:ח׳) כָּל הַדְּבָרִים יְגֵעִים לא יוּכַל אִישׁ לְדַבֵּר לא תִשְׂבַּע עַיִן לִרְאוֹת וְלֹא תִמָּלֵא אֹזֶן מִשְׁמוֹעַ. כָּל הַדְּבָרִים יְגֵעִים, וְכִי כָּל הַדְּבָרִים יְגֵעִים אִינוּן לְמַלָּלָא, דְּקָאֲמַר לֹא יוּכַל אִישׁ לְדַבֵּר. וְלֹא תִשְׂבַּע עַיִן לִרְאוֹת וְלא תִמָּלֵא אֹזֶן מִשְׁמוֹעַ, מַאי טַעְמָא אִלֵּין. אֶלָּא בְּגִין דִּתְרֵין מִנְהוֹן, וְאִינוּן עַייְנִין וְאוּדְנִין, לָא קַיָּימִין בִּרְשׁוּתֵיהּ דְּבַר נָשׁ, וּפוּמָא אִיהוּ בִּרְשׁוּתֵיהּ. וְכָל (מה) אִלֵּין תְּלַת לָא יָכְלִין לְאַשְׁלָמָא כֹּלָּא, וּלְאַדְבָּקָא כֹּלָּא.</p>\n<p>אָמַר רִבִּי חִיָּיא, הָכִי הוּא, דְּדִבּוּרָא דְּבַר נָשׁ לָא יָכִיל לְמַלָּלָא, וְעַיְינִין לְמֶחֱמֵי, וְאוּדְנִין לְמִשְׁמַע, וְאֵין כָּל חָדָשׁ תַּחַת הַשֶּׁמֶשׁ. וְתָּא חֲזֵי, אֲפִילוּ בִּרְיָין וְקַסְטוֹרִין, דְּעֲבַד קוּדְשָׁא בְּרִיךְ הוּא תַּחַת הַשֶּׁמֶשׁ, לָא יָכְלִין לְמַלָּלָא כָּל מִלִּין דְּעַלְמָא, וְעֵינָא לָא יָכִיל <Nonei></i>לְמִשְׁלַט וּלְמֶחמֵי, וְאוּדְנָא לְמִשְׁמָע. וּבְגִין כָּךְ שְׁלֹמֹה דְּהֲוָה יָדַע כָּל מִלָּה, הֲוָה אָמַר דָּא.</p>\n<p>וְתָּא חֲזֵי, כָּל עוֹבָדִין דְּעַלְמָא, בְּכַמָּה קַסְטְרִין תַּלְיָין, וְכָל בְּנֵי עַלְמָא לָא יָדְעִין, וְלָא מַשְׁגִּיחִין עַל מַה קָּיְימֵי בְּעַלְמָא, וְאֲפִילּוּ שְׁלֹמֹה מַלְכָּא, דְּהֲוָה חֲכִּים מִכָּל בְּנֵי עַלְמָא, לָא יָכִיל לְקָיְימָא בְּהוּ.</p>\n<p>פָּתַח וְאֲמַר, (קהלת ג׳:י״א) אֶת הַכֹּל עָשָׂה יָפֶה בְּעִתּוֹ גַּם אֶת הָעוֹלָם נָתַן בְּלִבָּם מִבְּלִי אֲשֶׁר לֹא יִמְצָא הָאָדָם אֶת הַמַּעֲשֶׂה אֲשֶׁר עָשָׂה הָאֱלֹהִים וְגו'. תָּא חֲזֵי, זַכָּאִין אִינוּן דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא וְיָדְעֵי לְאִסְתַּכָּלָא בְּרוּחָא (ס\"א ברזא) דְחָכְמָתָא. אֶת הַכֹּל עָשָׂה יָפֶה בְּעִתּוֹ, כָּל עוֹבָדִין דְּעֲבַד קוּדְשָׁא בְּרִיךְ הוּא בְּעַלְמָא, בְּכָל עוֹבָדָא וְעוֹבָדָא, אִית דַּרְגָּא מְמַנָּא עַל הַהוּא עוֹבָדָא בְּעַלְמָא, הֵן לְטַב הֵן לְבִישׁ. מִנְּהוֹן דַּרְגִּין לִימִינָא, וּמִנְהוֹן דַּרְגִּין לִשְׂמָאלָא. אָזִיל בַּר נָשׁ לִימִינָא, הַהוּא עוֹבָדָא דְּעָבִיד, הַהוּא דַרְגָּא מְמַנָּא (ס\"א דימינא) לְהַהוּא סִטְרָא, (עבידי) וְעָבִיד לֵיהּ סִיּוּעָא, וְכַמָּה אִינוּן דִּמְסַיְיעֵי לֵיהּ. אָזַל בַּר נָשׁ לִשְׂמָאלָא, וְעָבִיד עוֹבָדוֹי, הַהוּא עוֹבָדָא דְּעָבִיד, מְמַנָּא (ס\"א דרגא דשמאלא) אִיהוּ לְהַהוּא סִטְרָא, וְקָא מְקַטְרֵג לֵיהּ, וְאוֹבִיל לֵיהּ לְהַהוּא סִטְרָא, וְאַסְטֵי לֵיהּ. וּבְּגִין כָּךְ הַהוּא עוֹבָדָא דְּעָבִיד בַּר נָשׁ כְּדְקָא חָזֵי, הַהוּא מְמַנָּא דִסְטַר יְמִינָא קָא מְסַיֵּיעַ לֵיהּ. וְדָא הוּא בְּעִתּוֹ, יָפֶה בְּעִתּוֹ, דְּהַהוּא עוֹבָדָא מִתְקַשְּׁרָא בְּעִתּוֹ, כְּדְקָא חָזֵי לֵיהּ.</p>\n<p>גַּם אֶת הָעוֹלָם נָתַן בְּלִבָּם. כָּל עַלְמָא, וְכָל עוֹבָדוֹי דְעַלְמָא, לָאו אִינוּן אֶלָּא בִּרְעוּתָא דְלִבָּא, כַּד סָלִיק בִּרְעוּתָא (דלבא, וכד סליק ברעותא) דְבַר נָשׁ. זַכָּאִין אִנּוּן צַדִּיקַיָּא דְּאַמְשִׁיכוּ עוֹבָדִין טָבִין, לְאוֹטָבָא לוֹן וּלְכָל עַלְמָא, וְאִינוּן יָדְעִין לְאִתְדַּבְּקָא בְּעֵת שָׁלוֹם. וּבְחֵילָא דִצְדָקָה דְּעָבְדִין לְתַתָּא, אִינוּן מָשְׁכִין לְהַהוּא דַרְגָּא דְּאִקְרֵי כָּל, לְאַנְהָרָא בְּעִתּוֹ.</p>\n<p>וַוי לוֹן לְחַיָּיבַיָא דְּלָא יָדְעִין עֵת דְּהַהוּא עוֹבָדָא, וְלָא מַשְׁגִּיחִין לְמֶעְבַּד עוֹבָדֵיהוֹן בְּעַלְמָא עַל תִּקּוּנָא דְאִצְטְרִיךְ לֵיהּ לְעַלְמָא. וּלְאַתְקָנָא עוֹבָדָא בְּהַהוּא דַרְגָּא דְּאִתְחֲזֵי לֵיהּ. מַאי טַעְמָא, בְּגִין דְּלָא יָדְעִין.</p>\n<p>וְעַל דָּא אִתְיְיהִיב כֹּלָּא בִּרְעוּתְהוֹן דִּבְנֵי נָשָׁא. דִּכְתִיב, מִבְּלִי אֲשֶׁר לֹא יִמְצָא הָאָדָם אֶת הַמַּעֲשֶׂה אֲשֶׁר עָשָׂה הָאֱלהִים מֵרֹאשׁ וְעַד סוֹף. וּבְגִין כָּךְ דְּאִינוּן עוֹבָדִין לָא אִתְעֲבִידוּ לְאַתְקָנָא בְּדַרְגַּיְיהוּ כִּדְקָחָזֵי, דְּיִתְכְּלִיל עוֹבָדָא דָא בְּדַרְגָּא דָא, כֹּלָּא כְּתִקּוּנָא אֶלָּא כְּפוּם רְעוּתָא דְּבַר נָשׁ. מַה כְּתִיב בַּתְרֵיהּ יָדַעְתִּי כִּי אֵין טוֹב בָּם כִּי אִם לִשְׂמוֹחַ וְלַעֲשׂוֹת טוֹב בְּחַיָּיו. יָדַעְתִּי כִּי אֵין טוֹב בָּם, בְּאִינוּן עוֹבָדִין, דְּלָא אִתְעֲבִידוּ כְּדְקָא יְאוּת. כִּי אִם לִשְׂמוֹחַ, בְּכָל מַה דְּיֵיתֵי עֲלוֹי, וּלְמֵיהַב הוֹדָאָה לְקוּדְשָׁא בְּרִיךְ הוּא. וְלַעֲשׂוֹת טוֹב בְּחַיָּיו, דְּהָא אִי הַהוּא עוֹבָדָא גָרִים לֵיהּ בִּישָׁא, בְּגִין הַהוּא דַרְגָּא דְקָא מְמַנָּא עֲלוֹי, אִית לֵיהּ לְמֶחדֵי בֵּיהּ, וּלְאוֹדָאָה עֲלֵיהּ. דְּאִיהוּ גָּרִים לֵיהּ לְנַפְשֵׁיהּ, וְאִיהוּ אָזִיל בְּלָא יְדִיעָא, כְּצִיפֳרָא דָא בְּגוֹ קוּסְטִירָא.</p>\n<p>וְכָל דָּא מְנָלָן, דִּכְתִיב, (קהלתט) כִּי גַּם לֹא יֵדַע הָאָדָם אֶת עִתּוֹ, כַּדָּגִים שֶׁנֶּאֱחָזִים בִּמְצוֹדָה רָעָה וְכַצִּפֳּרִים הָאֲחֻזוֹת בַּפָּח כָּהֵם יוּקָשִׁים בְּנֵי הָאָדָם לְעֵת רָעָה כְּשֶׁתִּפּוֹל עֲלֵיהֶם פִּתְאוֹם. כִּי גַּם לא יָדַע הָאָדָם אֶת עִתּוֹ. מַאי עִתּוֹ, עִתּוֹ דְּהַהוּא עוֹבָדָא דְּקָא עָבִיד. כְּמָה דְאַתְּ אָמֵר, אֶת הַכֹּל עָשָׂה יָפֶה בְּעִתּוֹ, וּבְגִין כָּךְ אִינוּן כַּצִּפֳּרִים הָאֲחוּזוֹת בַּפָּח. וּבְגִין כָּךְ זַכָּאִין אִינוּן דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא, וְיָדְעֵי אוֹרְחוֹי וּשְׁבִילוֹי דְּאוֹרַיְיתָא דְּמַלְכָּא עִלָּאָה, לְמֵיהַךְ בָּהּ בְּאֹרַח קְשׁוֹט.</p>\n<p>וְתָּא חֲזֵי, לְעוֹלָם אַל יִפְתַּח בַּר נַשׁ פּוּמֵיהּ לְבִישׁ, דְּאִיהוּ לָא יָדַע מַאן נָטִיל הַהִיא מִלָּה. וְכַד לָא יָדַע בַּר נָשׁ אִתְכְּשַׁל בָּהּ. וְצַדִּיקַיָא כַּד פָּתְחֵי פּוּמַיְיהוּ כֻּלְּהוּ שְׁלָם. תָּא חֲזֵי, יוֹסֵף כַּד שָׁרָא לְמַלָּלָא לְפַרְעֹה. מַה כְּתִיב, אֱלהִים יַעֲנֶה אֶת שְׁלוֹם פַּרְעֹה. אָמַר רִבִּי יְהוּדָה, הָא אִתְּמָר. דְּקוּדְשָׁא בְּרִיךְ הוּא חָס עַל שְׁלָמָא דְמַלְכוּתָא, כְּמָה דְאַתְּ אָמֵר, (שמות ו׳:י״ג) וַיְצַוִּם אֶל בְּנִי יִשְׂרָאֵל וְאֶל פַּרְעֹה מֶלֶךְ מִצְרַיִם <Nonei></i>וְאוּקְמוּהָ.</p>"],[9520011400,"<p>רִבִּי חִיָּיא אָמַר, פַּרְעֹה בָּעָא לְנַסָּאָה לֵיהּ לְיוֹסֵף, וְאַחְלַף לֵיהּ חֶלְמָא. וְיוֹסֵף בְּגִין דְּהֲוָה יָדַע דַּרְגִּין, אִסְתַּכַּל בְּכָל מִלָּה וּמִלָּה. וְאָמַר, כָּךְ חֲמִיתָא, כָּל מִלָּה וּמִלָּה כְּדְקָא חָזֵי.</p>\n<p>הֲדָא הוּא דִּכְתִיב וַיֹּאמֶר פַּרְעֹה אֶל יוֹסֵף אַחֲרֵי הוֹדִיעַ אֱלֹהִים אוֹתְךָ אֶת כָּל זֹאת אֵין נָבוֹן וְחָכָם כָּמוֹךָ. אַחֲרֵי הוֹדִיעַ אֱלֹהִים, אַחֲרַי הֲוֵית בְּהַהִיא שַׁעְתָּא דַּחֲלָמִית חֶלְמָא, תַּמָּן הֲוֵית שְׁכִיחַ. וּבְגִין כָּךְ אָמַר (ס\"א אמת את כל זאת ידעת, ואיך ידעת פשריה) אֶת כָּל זֹאת יָדַעְתְּ חֶלְמָא הֵיךְ הֲוָה, וְיָדַעְתְּ פִּשְׁרֵיהּ.</p>\n<p>אָמַר רִבִּי יִצְחָק, אִי הָכִי יוֹסֵף אָמַר כֹּלָּא, חֶלְמָא וּפִשְׁרָא. כְּדָנִיֵּאל דְּאָמַר חֶלְמָא וּפִשְׁרֵיהּ. אָמַר לֵיהּ, לָאו הַאי כְּהַאי (ז\"ח ל\"ג דהא). יוֹסֵף אִסְתַּכַּל מִגּוֹ מִלּוּלָא דְפַרְעֹה דְּהֲוָה אָמַר בְּדַרְגִּין יְדִיעָן, וְחָמָא לֵיהּ דְּקָא טָעָה, וְאָמַר לֵיהּ לָאו הָכִי, אֶלָּא הָכִי הוּא. בְּגִין דְּדַרְגִּין כְּסִדְרָן אַתְיָין. אֲבָל דָּנִיֵּאל לָא אִסְתַּכַּל מִגּוֹ מִלּוּלָא דִּנְבוּכַדְנְצַּר כְּלוּם. (דלא) וְכֹלָּא קָאֲמַר לֵיהּ חֶלְמָא וּפִשְׁרֵיהּ.</p>\n<p>מַה כְּתִיב בְּדָנִיֵּאל, (דניאל ב׳:י״ט) אֱדַיִן לְדָנִיֵּאל בְּחֶזְוָא דִי לֵילְיָא רָזָא גֲלִי בְּחֶזְוָא דִי לֵילְיָא. מַאן חֶזְוָא דִי לֵילְיָא, דָּא גַבְרִיאֵל, דְּאִיהוּ חֶזְוָא חֵיזוּ מִן חֵיזוּ.</p>\n<p>תָּא חֲזֵי, מַה כְּתִיב, (יחזקאל מ״ג:ב׳) וְהִנֵּה כְּבוֹד אֱלקֵי יִשְׂרָאֵל בָּא מִדֶּרֶךְ הַקָּדִים וְקוֹלוֹ כְּקוֹל מַיִם רַבִּים וְהָאָרֶץ הֵאִירָה מִכְּבוֹדוֹ. מַה כְּתִיב בַּתְרֵיהּ, וּכְמַרְאֵה הַמַּרְאֶה אֲשֶׁר רָאִיתִי בְּבֹאִי לְשַׁחֵת אֶת הָעִיר וּמַרְאוֹת כַּמַּרְאֶה אֲשֶׁר רָאִיתִי אֶל נְהַר כְּבָר וָאֶפֹּל אֶל פָּנָי. כָּל אִלֵּין מַרְאוֹת, אִינוּן שִׁית, דְּאִינוּן מַרְאוֹת וְחֵיזוּ דְּחֶזְוָא. חֵיזוּ אִית לֵיהּ, לְאִתְחֲזָאָה בֵּיהּ גְּוָונִין דִּלְעֵילָא, וְאִתְחֲזוּן בְּהַהוּא חֵיזוּ. וְאִית חֵיזוּ לְחֵיזוּ, וְחֵיזוּ לְחֵיזוּ, דָּא עַל דָּא. וְכֻלְּהוּ קָיְימִין בְּדַרְגִּין יְדִיעָן וְשָׁלְטֵי, וְאִקְרוּן חֵיזוּ דְלֵילְיָא, וּבְהוּ מִתְפָּרְשִׁין כָּל חֶלְמִין דְּעַלְמָא, וְאִלֵּין אִינוּן כְּגַוְונָא דִלְעֵילָא עֲלַיְיהוּ.</p>\n<p>וּבְּגִין כָּךְ דָּנִיֵּאל בְּחֶזְוָא דְלֵילְיָא רָזָא גֲלִי. אִתְגְּלִי לָא כְּתִיב, אֶלָּא רָזָא גֲלִי, חַד מֵאִלֵּין דַּרְגִּין, גַּלֵּי לֵיהּ הַהוּא חֶלְמָא וּפִשְׁרֵיהּ. אֲבָל יוֹסֵף, מִגּוֹ מִלּוֹי דְפַרְעֹה, אִסְתַּכַּל בְּדַרְגִּין עִלָּאִין וְקָאֲמַר.</p>\n<p>וּבְגִין כָּךְ פַּקְדֵיהּ עַל כָּל אַרְעָא דְמִצְרַיִם, בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא, מִדִּילֵיהּ דְּיוֹסֵף קָא יָהִיב לֵיהּ. פּוּמָא דְלָא נָשַׁק לַעֲבֵירָה, כְּתִיב וְעַל פִּיךָ יִשַּׁק כָּל עַמִי. יָדָא דְלָא קָרִיב לַעֲבֵירָה, כְּתִיב וַיִּתֵּן אוֹתָהּ עַל יַד יוֹסֵף. צַוָּאר דְּלָא קָרִיב לַעֲבֵירָה, כְּתִיב וַיָּשֶׂם רְבִיד הַזָּהָב עַל צַוָּארוֹ. גּוּפָא דְּלָא קָרִיב לַעֲבֵירָה, וַיַּלְבֵּשׁ אֹתוֹ בִּגְדֵי שֵׁשׁ. רֶגֶל דְּלָא רָכִיב לַעֲבֵירָה, כְּתִיב וַיַּרְכֵּב אֹתוֹ בְּמִרְכֶּבֶת הַמִּשְׁנֶה אֲשֶׁר לוֹ. הַמַּחֲשָׁבָה דְּלָא חָשַׁב, נִקְרָא נָבוֹן וְחָכָם. לֵב שֶׁלֹּא הִרְהֵר, וַיִּקְרְאוּ לְפָנָיו אַבְרֵךְ. וְכֹלָּא מִדִּילֵיהּ נָטַל.</p>\n<p>מַה כְּתִיב. וַיֵּצֵא יוֹסֵף מִלִּפְנִי פַרְעֹה וַיַּעֲבֹר בְּכָל אֶרֶץ מִצְרָיִם. אָמַר רִבִּי חִזְקִיָּה, מַאי טַעְמָא וַיַּעֲבוֹר בְּכָל אֶרֶץ מִצְרַיִם. בְּגִין לְשַׁלְטָאָה, דְּמַכְרְזֵי קַמֵּיה הָכִי. וּבְגִין לְמִכְנַשׁ עִבּוּרָא בְּכָל אֲתַר וַאֲתַר. רִבִּי אֶלְעָזָר אָמַר, כָּנַשׁ יוֹסֵף עִיבּוּר בְּכָל אֲתַר, בְּגִין דְּלָא יִתְרַקַּב.</p>\n<p>אָמַר רִבִּי שִׁמְעוֹן, כָּל מַה דְּעֲבַד קוּדְשָׁא בְּרִיךְ הוּא, כֹּלָּא אִיהוּ לְגַלְגְּלָא גִּלְגּוּלִין, בְּגִין דְּבָעֵי לְקָיְימָא קִיּוּמָא. תָּא חֲזֵי, כַּד בָּרָא קוּדְשָׁא בְּרִיךְ הוּא עַלְמָא, אַיְיתֵי כָּל מַה דְּאִצְטְרִיךְ עַלְמָא בְּקַדְמִיתָא, וּלְבָתַר אַיְיתֵי לֵיהּ לְבַר נָשׁ לְעַלְמָא, וְאַשְׁכַּח מְזוֹנָא.</p>\n<p>(ז\"ח ל\"ג תא חזי) כְּגַוְונָא דָא, קוּדְשָׁא בְּרִיךְ הוּא אָמַר לְאַבְרָהָם, (בראשית ט״ו:י״ג) יָדוֹעַ תֵּדַע כִּי גֵּר יִהְיֶה זַרְעֲךָ בְּאֶרֶץ לֹא לָהֶם וְגו', וְאַחֲרֵי כֵן יֵצְאוּ בִּרְכוּשׁ גָּדוֹל. כַּד אֲתָא יוֹסֵף לְאַרְעָא דְמִצְרַיִם, לָא אִשְׁתְּכַח בָּהּ רְכוּשׁ גָּדוֹל. גִּלְגֵּל גִּלְגוּלִין, וְאַיְיתֵי כַּפְנָא עַל עַלְמָא. וְכָל עַלְמָא הֲווּ מַיְיתִין כַּסְפָּא וְדַהֲבָא לְמִצְרַיִם, וְאִתְמְלֵי כָל אַרְעָא דְמִצְרַיִם כַּסְפָּא וְדַהֲבָא. לְבָתַר דְּאִתְתַּקַּן כֹּלָּא רְכוּשׁ גָּדוֹל, אַיְיתֵי יַעֲקֹב לְמִצְרַיִם.</p>\n<p>דְּהָכִי אָרְחֵי דְּקוּדְשָׁא בְּרִיךְ הוּא, בְּקַדְמִיתָא בָּארֵי (ס\"א אק1דים) אַסְוָותָא, וּלְבָתַר מָחֵי. כָּךְ בְּקַדְמִיתָא אַתְקִין רְכוּשׁ גָּדוֹל, וּלְבָתַר <Nonei></i>אַיְיתֵי לוֹן לְגָלוּתָא. וְעַל דָּא גִּלְגֵּל גִּלְגּוּלִין וְאַיְיתֵי כַּפְנָא עַל כָּל עַלְמָא, בְּגִין דְּלֵיהווּ מַיְיתִין כַּסְפָּא וְדַהֲבָא כָּל עַלְמָא לְמִצְרַיִם.</p>\n<p>תָּא חֲזֵי, בְּגִין (כך) יוֹסֵף דְּאִיהוּ צַדִּיק, אִיהִי גָּרִים עוּתְרָא כַּסְפָּא וְדַהֲבָא, לְנַטְלָא יִשְׂרָאֵל. כְּדִכְתִיב, (תהילים ק״ה:ל״ז) וַיּוֹצִיאֵם בְּכֶסֶף וְזָהָב וְאֵין בִּשְׁבָטָיו כּוֹשֵׁל. וּמִן יְדָא דְּצַדִּיק, אֲתָא דָא לְיִשְׂרָאֵל. וְכֹלָּא לְמִזְכֵּי לוֹן לְעַלְמָא דְאָתֵי.</p>\n<p>פָּתַח וְאָמַר, (קהלת ט׳:ט׳) רְאֵה חַיִּים עִם אִשָּׁה אֲשֶׁר אָהַבְתָּ וְגו'. תָּא חֲזֵי, הַאי קְרָא בְּרָזָא עִלָּאָה אִיהוּ, וְאוּקְמוּהָ. רְאֵה חַיִּים, אִלֵּין חַיִּין דְּעַלְמָא דְּאָתֵי, דְּזַכָאָה הוּא בַּר נָשׁ דְּזָכֵי בֵּיהּ כְּדְקָא יְאוּת.</p>\n<p>עִם אִשָּׁה אֲשֶׁר אָהַבְתָּ, דָּא כְּנֶסֶת יִשְׂרָאֵל, בְּגִין דְּבָהּ כְּתִיב אַהֲבָה. דִּכְתִיב, (ירמיהו ל״א:ג׳) וְאַהֲבַת עוֹלָם אֲהַבְתִּיךָ, אֵימָתַי. בְּשַׁעְתָּא דְסִטְרָא דִימִינָא אָחִיד בָּהּ. דִּכְתִיב, (ירמיהו ל״א:ג׳) עַל כֵּן מְשַׁכְתִּיךְ חָסֶד.</p>\n<p>(קהלת ט׳:ט׳) כָּל יְמֵי חַיֵּי הֶבְלְךָ, בְּגִין דְּאִיהִי אִתְקַשְּׁרַת בַּחַיִּים, וְאִיהִי עוֹלָם דְּחַיִּין שָׁרְיָין בֵּיהּ. דְּהָא עַלְמָא דָא, לָא שַׁרְיָין בֵּיהּ חַיִּים. בְּגִין דְּאִינוּן תַּחַת הַשֶּׁמֶשׁ, וְלָא מָטָאן הָכָא אִינוּן נְהוֹרִין דְּהַהוּא שִׁמְשָׁא, וְאִסְתַּלָּקוּ מֵעַלְמָא מִיּוֹמָא דְּאִתְחָרִיב בֵּי מַקְדְּשָׁא. דִּכְתִיב, (ישעיהו י״ג:י׳) חָשַׁךְ הַשֶּׁמֶשׁ בְּצֵאתוֹ וְגו'. מַאי חָשַׁךְ הַשֶּׁמֶשׁ, דְּסָלִיק נְהוֹרֵיהּ וְלָא נָהִיר. כְּמָה דְאַתְּ אָמֵר (ישעיהו נ״ז:א׳) הַצַּדִּיק אָבַד וְגו'.</p>\n<p>כִּי הוּא חֶלְקְךָ בַּחַיִּים, דָּא הוּא שִׁמְשָׁא בְּסִיהֲרָא, וּבְעִינָן לְמֵיעַל סִיהֲרָא בְּשִׁמְשָׁא וְשִׁמְשָׁא בְּסִיהֲרָא, דְּלָא לְאַפְרָשָׁא לוֹן. וְדָא הוּא חוּלָקָא דְּבַר נָשׁ, לְמֵיעַל בְּהוּ לְעַלְמָא דְאָתֵי.</p>\n<p>מַה כְּתִיב בַּתְרֵיהּ, (קהלת ט׳:י׳) כָּל אֲשֶׁר תִּמְצָא יָדְךָ לַעֲשׂוֹת בְּכֹחֲךָ עֲשֵׂה כִּי אֵין מַעֲשֶׂה וְחֶשְׁבּוֹן וְדַעַת וְחָכְמָה בַּשְׁאוֹל אֲשֶׁר אַתָּה הוֹלֵךְ שָׁמָּה. הַאי קְרָא אִית לְאִסְתַּכָּלָא בֵּיהּ. כָּל אֲשֶׁר תִּמְצָא יָדְךָ לַעֲשׂוֹת, וְכִי הוּתְּרָה רְצוּעָה לְמֶעְבַּד בַּר נָשׁ כָּל מַה דְּיָכִיל. אֶלָּא, לַעֲשׂוֹת בְּכֹחֲךָ כְּתִיב, מַאי בְּכֹחֲךָ. דָּא נִשְׁמָתֵיהּ דְּבַר נָשׁ, דְּאִיהִי חֵילָא דְּבַר נָשׁ, לְמִזְכֵּי בָהּ לְעַלְמָא דֵין וּלְעַלְמָא דְאָתֵי.</p>\n<p>דָּבָר אַחֵר בְּכֹחֲךָ, דָּא הִיא אִשָּׁה דְקָאֲמָרָן, דְּאִיהִי חֵילָא לְאִתְתַקְפָא בָּהּ, בְּעַלְמָא דֵין וּבְעַלְמָא דְאָתֵי. וּבָעֵי בַּר נָשׁ לְמִזְכֵּי בָהּ בְּהַאי עַלְמָא בְּהַאי חֵילָא, בְּגִין דְּיִתְתַּקַּף בָּהּ בְּהַהוּא עַלְמָא.</p>\n<p>מַאי טַעְמָא. בְּגִין דִּלְבָתַר דְּיִפּוּק בַּר נָשׁ מֵהַאי עַלְמָא, לֵית בֵּיהּ חֵילָא לְמֶעְבַּד מִידִּי וְלוֹמַר, הַשְׁתָּא, מִכָּאן וּלְהָלְאָה אַעֲבִיד עוֹבָדִין טָבִין. דְּוַדַּאי אֵין מַעֲשֶׂה וְחֶשְׁבּוֹן וְדַעַת וְחָכְמָה בַּשְׁאוֹל אֲשֶׁר וגו'. אִי לָא זָכֵי בַּר נָשׁ בְּהַאי עַלְמָא, לָא יִזְכֵּי בֵּיהּ לְבָתַר בְּהַהוּא עַלְמָא. וְאוּקְמוּהָ, מַאן דְּלָא אַתְקִין זְוָודִין לְמֵיהַךְ מֵהַאי עַלְמָא, לָא יֵיכוּל בְּהַהוּא עַלְמָא. וְאִית עוֹבָדִין טָבִין דְּעָבִיד בַּר נָשׁ בְּהַאי עַלְמָא, דְּיֵיכוּל מִנַּיְיהוּ הָכָא. וְכֹלָּא אִשְׁתָּאַר לְעַלְמָא דְאָתֵי וּלְאִתְּזְנָא מִנַּיְיהוּ.</p>\n<p>תָּא חֲזֵי, יוֹסֵף זָכָה בְּהַאי עַלְמָא וְזָכָה בְּעַלְמָא דְאָתֵי, בְּגִין דְּבָעָא לְאִתְאַחֲדָא בְּאִשָּׁה יִרְאַת יְיָ. כְּמָה דְאַתְּ אָמֵר, (בראשית ל״ט:ט׳) וְחָטָאתִי לֵאלהִים. וּבְגִין כָּךְ זָכָה לְמִשְׁלַט בְּהַאי עַלְמָא, וְזָכָה לוֹן לְיִשְׂרָאֵל.</p>\n<p>מַה כְּתִיב, (בראשית מ״ז:י״ד) וַיְלַקֵּט יוֹסֵף אֶת כָּל הַכֶּסֶף. וְהָכִי אִתְחֲזֵי, דְּהָא הַהוּא נָהָר דְנָגִיד וְנָפִיק, אִיהוּ לָקִיט כֹּלָּא, וְכָל עוּתְרָא בֵּיהּ קָיְימָא. וְדָא הִיא רָזָא דִּכְתִיב, (בראשית א׳:י״ז) וַיִּתֵּן אֹתָם אֱלֹהִים בִּרְקִיעַ הַשָּׁמַיִם, וְכֹלָּא אִיהוּ כְּדְקָא יְאוּת, וַדַּאי יוֹסֵף בָּעֵי לְמִשְׁלַט עַל מַלְכוּתָא.</p>\n<p>וְתָּא חֲזֵי, כְּתִיב, וַיַּרְכֵּב אוֹתוֹ בְּמִרְכֶּבֶת הַמִּשְׁנֶה. מַאן מִרְכֶּבֶת הַמִּשְׁנֶה. קוּדְשָׁא בְּרִיךְ הוּא עָבִיד לֵיהּ לַצַּדִּיק שַׁלִּיטָא, בְּגִין דְּהָא מִנֵּיהּ אִתְּזַן עַלְמָא, וְאִצְטְרִיךְ לְאִתְּזָנָא. וְקוּדְשָׁא בְּרִיךְ הוּא אִית לֵיהּ רְתִיכָא עִלָּאָה, וְאִית לֵיהּ רְתִיכָא תַּתָּאָה. רְתִיכָא תַּתָּאָה אִיהִי מִרְכֶּבֶת הַמִּשְׁנֶה, וְיוֹסֵף צַדִּיק אִקְרֵי, וְלֵיהּ אִתְחֲזֵי לְמֶהוֵי רָכִיב עַל מִרְכֶּבֶת הַמִּשְׁנֶה אֲשֶׁר לוֹ, לְקוּדְשָׁא בְּרִיךְ הוּא. וְכֹלָּא אִיהוּ בְּרָזָא עִלָאָה, לְמֶהֱוֵי כְּגַוְונָא דִלְעֵילָא.</p>\n<p>תָּא חֲזֵי, וַיִּקְרְאוּ לְפָנָיו אַבְרֵךְ, מַאי אַבְרֵךְ. קְשִׁירוּ דְּאִתְקַּשַּׁר שִׁמְשָׁא בְּסִיהֲרָא, וְכֹלָּא כָּרְעִין לָקֳבֵל אֲתַר דָּא. וְנָתוֹן אוֹתוֹ עַל כָּל עַלְמָא, וְכֻלְּהוּ אוֹדָן לְגַבֵּיהּ, <Nonei></i>וּבְגִין דָּא כֹּלָּא בְּרָזָא עִלָּאָה אִיהוּ.</p>\n<p>תָּא חֲזֵי, קוּדְשָׁא בְּרִיךְ הוּא עָבַד מַלְכוּתָא דְאַרְעָא, כְּעֵין מַלְכוּתָא דִרְקִיעָא, וְכֹלָּא דָא כְּגַוְונָא דָא. וְכָל מַה דְּאִתְעֲבִיד בְּאַרְעָא קָיְימָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא בְּקַדְמִיתָא. תָּא חֲזֵי, מַלְכוּתָא קַדִּישָׁא, לָא קַבִּיל מַלְכוּתָא שְׁלֵימָתָא, עַד דְּאִתְחַבַּר בַּאֲבָהָן. בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא עָבַד לָהּ לְמַלְכוּ עִלָּאָה, לְאִתְנַהֲרָא מֵרָזָא דְּאֲבָהָן.</p>\n<p>וְכַד יוֹסֵף הַצַּדִּיק נָחַת לְמִצְרַיִם בְּקַדְמִיתָא, אִיהוּ מָשִׁיךְ לָהּ לִשְׁכִינְתָּא לְבָתַר עִמֵּיהּ, דְּהָא שְׁכִינְתָּא לָא אָזְלָא אֶלָּא בַּתְרָא דְצַדִּיק. וּבְגִין כָּךְ אִתְמְשַׁךְ יוֹסֵף לְמִצְרַיִם בְּקַדְמִיתָא, וְנָטִיל כָּל עוּתְרָא דְעַלְמָא כְּדְקָא יְאוּת, וּלְבָתַר נָחֲתַת שְׁכִינְתָא לְמִצְרַיִם, וְכֻלְּהוּ שִׁבְטִין בַּהֲדָהּ.</p>\n<p>וּבְגִינֵי כָּךְ, יוֹסֵף דְּנָטַר לֵיהּ לַבְּרִית, זָכָה לְאִתְעַטְּרָא בְּאַתְרֵיהּ, וְזָכָה לְמַלְכוּתָא דִלְעֵילָא, וּלְמַלְכוּתָא דִלְתַתָּא. וְעַל דָּא כָּל מַאן דְּנָטַר בְּרִית קַדִּישָׁא, כְּאִילּוּ קִיֵּים אוֹרַיְיתָא קַדִּישָׁא כּוֹלָה, דְּהָא בְּרִית שָׁקִיל כְּכָל אוֹרַיְיתָא:</p>"],[9520011401,"<p>וַיַּרְא יַעֲקֹב כִּי יֵשׁ שֶׁבֶר בְּמִצְרַיִם וַיֹּאמֶר יַעֲקֹב לְבָנָיו וְגו'. רִבִּי חִיָּיא פָּתַח וְאֲמַר, (זכריה י״ב:א׳) מַשָּׂא דְבַר יְיָ עַל יִשְׂרָאֵל נְאֻם יְיָ נוֹטֶה שָׁמַיִם וְיוֹסֵד אָרֶץ וְיוֹצֵר רוּחַ אָדָם בְּקִרְבּוֹ. הַאי קְרָא אִית לְאִסְתַּכָּלָא בֵּיהּ. מַשָּׂא דְּבַר יְיָ, בְּכָל הַנֵּי אֲתַר דְּקָאֲמַר מַשָּׂא, מַשָּׂא אַמַּאי. אֶלָּא, בְּכָל אֲתַר דְּאִיהוּ עַל דִּינָא דִּשְׁאָר עַמִּין וְאָמַר מַשָּׂא, לְטַב. בְּכָל אֲתַר דְּאִיהוּ עַל יִשְׂרָאֵל וְאָמַר מַשָּׂא, לְבִישׁ.</p>\n<p>בְּכָל אֲתַר דְּאִיהוּ עַל דִּינָא דִשְׁאָר עַמִין, לְטַב. בְּגִין דְּמַשָּׂא מָטוּלָא אִיהוּ. כִּבְיָכוֹל מָטוּלָא אִיהוּ עֲלֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, שָׁלוֹם דְּעַמִּין עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת. וְכַד אִתְגְּזַר דִּינָא עֲלַיְיהוּ מַעֲבַר מִנֵּיהּ הַהוּא מָטוּלָא דְּאִיהוּ סָבִיל עֲלַיְיהוּ. בְּכָל אֲתַר דְּדִינָא אִתְגְּזַר עֲלַיְיהוּ דְּיִשְׂרָאֵל, וְאָמַר מַשָּׂא, כִּבְיָכוֹל מָטוּלָא אִיהוּ עֲלֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא. וּבְּגִין כָּךְ מַשָּׂא מֵהַאי גִיסָא, וּמֵהַאי גִיסָא, מָטוּלָא אִיהוּ.</p>\n<p>כֵּיוָן דְּאָמַר נוֹטֶה שָׁמַיִם וְיוֹסֵד אָרֶץ, אַמַּאי אִצְטְרִיךְ וְיוֹצֵר רוּחַ אָדָם בְּקִרְבּוֹ. וְכִי לָא הֲוֵינָא יָדְעֵי דְּאִיהוּ יוֹצֵר רוּחַ אָדָם. אֶלָּא לְאַחֲזָאָה דַרְגָּא יְדִיעָא, דְּכָל רוּחִין וְנִשְׁמָתִין דְּעַלְמָא, בְּהַהוּא דַּרְגָּא קָיְימִין.</p>\n<p>רִבִּי שִׁמְעוֹן אָמַר, הַאי קְרָא קַשְׁיָא, אִי אָמַר וְיוֹצֵר רוּחַ אָדָם וְלָא יַתִּיר יָאוֹת, אֲבָל בְּקִרְבּוֹ מַהוּ. אֶלָּא רָזָא אִיהוּ בִּתְרֵין סִטְרִין, דְּהָא מֵהַהוּא נָהָר דְּנָגִיד וְנָפִיק, מִתַּמָּן נָפְקֵי וּפָרְחֵי נִשְׁמָתִין כֻּלְּהוּ, וְאִתְכְּנִישׁוּ בְּאֲתַר חָד. וְהַהוּא דַרְגָּא אִיהוּ יוֹצֵר רוּחַ אָדָם בְּקִרְבּוֹ. וְהַאי כְּאִתְּתָא דְאִתְעַבְּרָא מִן דְּכוּרָא, וְהַהוּא וְלָדָא צָרַת לָהּ בִּמְעָהָא. עַד דְּאִצְטַיֵּיר כֹּלָּא בְּצִיּוּרָא שְׁלִימוּ בִּמְעָהָא. כָּךְ וְיוֹצֵר רוּחַ אָדָם בְּקִרְבּוֹ, בְּקִרְבּוֹ קָיְימָא. עַד דְּאִתְבְּרֵי בַּר נָשׁ בְּעַלְמָא וְיָהִיב לֵיהּ.</p>\n<p>דָּבָר אַחֵר, וְיוֹצֵר רוּחַ אָדָם בְּקִרְבּוֹ, בְּקִרְבּוֹ דְּאָדָם מַמָּשׁ. בְּגִין דְּכַד אִתְבְּרֵי בַר נָשׁ, וְקוּדְשָׁא בְּרִיךְ הוּא יָהַב לֵיהּ נִשְׁמָתֵיהּ, וְנָפִיק לַאֲוִירָא דְעַלְמָא. הַהוּא רוּחָא דִּבְגַוֵּיהּ, לָא אַשְׁכַּח גּוּפָא לְאִתְפַּשְּׁטָא בְּגַוֵּיהּ, וְקָיְימָא בְּסִטְרָא חַד בְּגַוֵּיהּ.</p>\n<p>וְכַד בַּר נָשׁ אִתְפַּשַׁט גּוּפֵיהּ, הַהוּא רוּחָא אִתְפַּשַּׁט, וְיָהִיב בֵּיהּ חֵילָא, וְכֵן כְּגַוְונָא דְגוּפָא אִתְרַבֵּי, הָכִי רוּחָא יָהִיב חֵילָא בֵּיהּ, לְאִתְתַּקְּפָא בַּר נַשׁ בַּהֲדֵיהּ. וּבְגִין כָּךְ יוֹצֵר רוּחַ אָדָם בְּקִרְבּוֹ מַמָּשׁ.</p>\n<p>וְאִי תֵימָא יוֹצֵר רוּחַ אָדָם מַהוּ, בְּגִין דְהַהוּא רוּחָא, אִצְטְרִיךְ חֵילָא דִלְעֵילָא יַתִּיר לְאִסְתַּיְיעָא בַּהֲדֵיהּ. וְעַל דָּא קוּדְשָׁא בְּרִיךְ הוּא אִיהוּ יוֹצֵר רוּחַ אָדָם בְּקִרְבּוֹ, וְיָהִיב לֵיהּ סִיּוּעָא בְּבַר נָשׁ.</p>\n<p>תָּא חֲזֵי, כַּד הַהוּא רוּחָא אִצְטְרִיךְ סִיּוּעָא, כְּגַוְונָא דְאִיהוּ הַהוּא בַּר נָשׁ, וּכְגַוְונָא דְּהַהוּא גוּפָא אִתְתַּקַּן, הָכִי נָמֵי הַהוּא רוּחָא מְתַקְנִין לֵיהּ, וְאוֹסְפִין לֵיהּ רוּחָא לְאִתְתַּקְּנָא. וְדָא הוּא יוֹצֵר רוּחַ אָדָם בְּקִרְבּוֹ.</p>\n<p>וְתָּא חֲזֵי, כֵּיוָן דְּאִתְאֲבִיד יוֹסֵף מֵאֲבוֹי, יַעֲקֹב אָבִיד הַהוּא תּוֹסֶפֶת רוּחָא דְּהֲוָה לֵיהּ, וְאִסְתַּלְּקַת מִנֵּיהּ שְׁכִינְתָּא. לְבָתַר מַה כְּתִיב, (בראשית מ״ה:כ״ז) וַתְּחִי רוּחַ יַעֲקֹב אֲבִיהֶם. וְכִי עַד הַשְׁתָּא <Nonei></i>מִית הֲוָה. אֶלָּא הַהוּא תּוֹסֶפֶת רוּחָא אִסְתַּלַּק מִנֵּיהּ שְׁכִינְתָּא, וְלָא הֲוָה בְּגַוֵּיהּ. בְּגִין דְּעִצְבוֹנָא דְּהֲוָה בֵּיהּ גָּרְמָא לֵיהּ, (ואי גרמא ליה הא) (ס\"א דלא) לָא הֲוָה רוּחֵיהּ בְּקִיּוּמֵיהּ. וּבְגִין כָּךְ וַתְּחִי רוּחַ יַעֲקֹב אֲבִיהֶם.</p>\n<p>וְהָכָא (כתיב וירא יעקב), דְּעַד כְּעָן לָא אִתְבַּשַּׂר, מְנָא הֲוָה יָדַע. אֶלָּא וַיַּרְא יַעֲקֹב, דְּחָמָא לְכָל דָּיְירֵי אַרְעָא דְּאָזְלֵי לְמִצְרַיִם, וּמַיְיתָן עִבּוּרָא (הדא הוא דכתיב וירא יעקב).</p>\n<p>רִבִּי יִצְחָק אָמַר, תָּא חֲזֵי, דָּוִד מַלְכָּא זָכָה לְאִתְחַבְּרָא בַּאֲבָהָן, וְיָרִית דּוּכְתֵּיהּ בְּגַוַּויְיהוּ. הֲדָא הוּא דִּכְתִיב, אֶבֶן מָאֲסוּ הַבּוֹנִים הָיְתָה לְרֹאשׁ פִּנָּה.</p>\n<p>(נדפס וארא לא א) רִבִּי יֵיסָא וְרִבִּי חִזְקִיָּה הֲווּ אָזְלֵי מִקַּפּוֹטְקִיָּא לְלוֹד, וְהֲוָה עִמְּהוֹן חַד יוּדָאי בְּמָטוּל דְּקַפְטִירָא דְחַמְרָא, עַד דְּהֲווּ אָזְלֵי, אָמַר רִבִּי יֵיסָא לְרִבִּי חִזְקִיָּה, אַפְתַּח פּוּמָךְ וְאֵימָא חַד מִלָּה מֵאִינוּן מִילֵי מַעַלְיָיתָא דְאוֹרַיְיתָא, דְאַתְּ אֲמֵר בְּכָל יוֹמָא קַמֵּי בּוּצִינָא קַדִּישָׁא.</p>\n<p>פָּתַח וְאֲמַר, (משלי ג׳:י״ז) דְּרָכֶיהָ דַרְכֵי נוֹעַם וְכָל נְתִיבוֹתֶיהָ שָׁלוֹם. דְּרָכֶיהָ דַרְכֵי נֹעַם, אִלֵּין אָרְחִין דְּאוֹרַיְיתָא. דְּמַאן דְּאָזִיל בְּאָרְחֵי דְאוֹרַיְיתָא, קוּדְשָׁא בְּרִיךְ הוּא אַשְׁרֵי עֲלֵיהּ נְעִימוּתָא דִשְׁכִינְתָּא, דִּי לָא תַעֲדֵי מִנֵּיהּ לְעָלְמִין. וְכָל נְתִיבוֹתֶיהָ שָׁלוֹם, דְּכֻלְּהוּ נְתִיבִין דְּאוֹרַיְיתָא כֻּלְּהוּ שְׁלָם, שְׁלָם לֵיהּ לְעֵילָא, שְׁלָם לֵיהּ לְתַתָּא. שְׁלָם לֵיהּ בְּעַלְמָא דֵין, שְׁלָם לֵיהּ בְּעַלְמָא דְאָתֵי.</p>\n<p>אָמַר הַהוּא יוּדָאי, אִיסִירָא (אסתרא) בְּקִיסְטְרָא בְּהַאי קְרָא אִשְׁתַּכַּח, אָמְרוּ לֵיהּ, מִנַיִן לָךְ. אָמַר לוֹן, מֵאַבָּא שְׁמַעְנָא, וְאוֹלִיפְנָא הָכָא בְּהַאי קְרָא מִלָּה (טבא). פָּתַח וְאֲמַר, הַאי קְרָא בִּתְרֵין גְּוָונִין אִיהוּ, וּבִתְרֵין סִטְרִין. קָרֵי בֵּיהּ דְּרָכִים, וְקָרֵי בֵּיהּ נְתִיבוֹת. קָרֵי בֵּיהּ נֹעַם, וְקָרֵי בֵּיהּ שָׁלוֹם. מַאן דְּרָכִים, וּמַאן נְתִיבוֹת. מַאן נֹעַם, וּמַאן שָׁלוֹם.</p>\n<p>אֶלָּא דְּרָכֶיהָ דַרְכֵי נֹעַם. הַיְינוּ דִכְתִיב, (ישעיהו מ״ג:ט״ז) הַנּוֹתֵן בַּיָּם דָּרֶךְ, דְּהָא בְּכָל אֲתַר דְּאִקְרֵי בְּאוֹרַיְיתָא דֶרֶךְ, הוּא אוֹרַח פְּתִיחָא לְכֹלָּא. כְּהַאי אָרְחָא, דְּאִיהוּ פְּתִיחַ לְכָל בַּר נָשׁ. כָּךְ דְּרָכֶיהָ דַרְכֵי נֹעַם, אִילֵין דְּרָכִים דְּאִינוּן פְּתִיחָן מֵאֲבָהָן, דְּכָרָאן בְּיַמָּא רַבָּא, וְעָאלִין בְּגַוֵּיהּ, וּמֵאִינוּן אוֹרְחִין מִתְפַּתְּחִין לְכָל עֵיבַר וּלְכָל סִטְרֵי עַלְמָא.</p>\n<p>וְהַאי נֹעַם, הוּא נְעִימוּ דְּנָפַק מֵעַלְמָא דְאָתֵי. וּמֵעַלְמָא דְאָתֵי נָהֲרִין כָּל בּוּצִינִין, וּמִתְפַּרְשָׁן לְכָל עֵיבַר. וְהַהוּא טִיבוּ וְהַהוּא נְהוֹרָא דְּעַלְמָא דְאָתֵי, דְּיָנְקִין (נ\"א דירתין) אֲבָהָן, אִקְרֵי נֹעַם. דָּבָר אַחֵר, עַלְמָא דְאָתֵי אִקְרֵי נֹעַם, וְכַד אִתְעַר עַלְמָא דְאָתֵי, כָּל חֵדוּ וְכָל טִיבוּ וְכָל נְהוֹרִין וְכָל חֵירוּ דְעַלְמָא אִתְעַר, וּבְגִינִי כָּךְ אִקְרֵי נֹעַם.</p>\n<p>וְעַל דָּא תָּנִינָן, חַיָּיבִין דְּגֵיהִנֹּם, בְּשַׁעְתָּא דְּעָאל שַׁבַּתָּא, נָיְיחִין כֻּלְּהוּ, וְאִית לְהוּ חֵירוּת וְנַיְיחָא. בְּשַׁעְתָּא דְּנָפִיק שַׁבַּתָּא, אִית לָן לְאִתְעָרָא חֵידוּ עִלָּאָה עֲלָנָא, דְּנִשְׁתֵּזִיב מֵהַהוּא עוֹנָשָׁא דְחַיָּיבַיָא דְּאִתְדָּנוּ (ס\"א דאהדרו) מֵהַהִיא שַׁעְתָּא וּלְהָלְאָה. וְאִית לָן לְאִתְעָרָא וְלֵימָא, (תהילים צ׳:י״ז) וִיהִי נֹעַם יְיָ אֱלֹקֵינוּ עָלֵינוּ. דָּא הוּא נֹעַם עִלָּאָה, חֵידוּ (ס\"א חירו) דְּכֹלָּא, וְעַל דָּא דְּרָכֶיהָ דַרְכֵי נֹעַם.</p>\n<p>וְכָל נְתִיבוֹתֶיהָ שָׁלוֹם, מַאן נְתִיבוֹתֶיהָ. אִלֵּין אִינוּן שְׁבִילִין דְּנָפְקִין מִלְּעֵילָא, וְכֻלְּהוּ נָקִיט לוֹן בְּרִית יְחִידָאי, דְּאִיהוּ אִקְרֵי שָׁלוֹם, שְׁלָמָא דְבֵיתָא. וְאָעִיל לוֹן לְיַמָא רַבָּא, כַּד אִיהוּ בְּתוּקְפֵיהּ, וּכְדֵין יָהִיב לֵיהּ שְׁלָמָא. הֲדָא הוּא דִכְתִיב וְכָל נְתִיבוֹתֶיהָ שָׁלוֹם (ע\"כ). תָּא חֲזֵי, יוֹסֵף בְּרִית שָׁלוֹם הֲוָה, וְהֲוָה בְּמִצְרַיִם מַלְכָּא, וְשַׁלִּיט עַל אַרְעָא. וְיַעֲקֹב בְּגִין דְּאִסְתַּלַּק מִנֵּיהּ שְׁכִינְתָּא, לָא הֲוָה יָדַע.</p>\n<p>וְעִם כָּל דָּא, יַעֲקֹב הֲוָה לֵיהּ תַּבְרָא, בְּגִין לְמִזְבַּן עִבּוּרָא בְּמִצְרַיִם. וְחָמָא דְּאִיהוּ תְּבִירָא עַל תְּבִירָא, דְּיֵחֲתוּן בְּנוֹי לְמִצְרַיִם. וַיֹּאמֶר יַעֲקֹב לְבָנָיו לָמָּה תִּתְרָאוּ, בְּגִין דְּלָא תַחֲמוּן גּוּפַיְיכוּ, אֶלָּא כִּרְעֵבִין, כְּגוּבְרִין דְּלֵית לוֹן שָׂבְעָא.</p>\n<p>אָמַר רִבִּי חִזְקִיָּה, וַדַּאי רָזָא הָכָא. דְּהָא בְּכָל זִמְנָא דְצַעֲרָא אִיהוּ בְּעַלְמָא, לָא בָּעֵי בַּר נָשׁ, לְאַחֲזָאָה גַרְמֵיהּ בְּשׁוּקָא, בְּגִין דְּלָא יִתָּפֵס בְּחוֹבוֹי. וְעַל דָּא אָמַר לָמָּה תִּתְרָאוּ, וְהָא אִתְּמָר.</p>\n<p>דָּבָר אַחֵר וַיַּרְא יַעֲקֹב כִּי יֵשׁ <Nonei></i>שֶׁבֶר בְּמִצְרַיִם, עִבּוּר מַמָּשׁ. דְּהָא קוּדְשָׁא בְּרִיךְ הוּא עַל דָּא שַׁדַּר כַּפְנָא בְּעַלְמָא, בְּגִין לְנַחֲתָא לְיַעֲקֹב וּבְנוֹי לְתַמָּן, וְעַל דָּא חָמָא בְּנֵי אַרְעָא, דְּהֲווּ מַיְיתִין מִתַּמָּן עִבּוּר.</p>\n<p>וַיַּרְא יַעֲקֹב כִּי יֵשׁ שֶׁבֶר בְּמִצְרַיִם, בְּשַׁעְתָּא דְמִית יִצְחָק, אָתוּ יַעֲקֹב וְעֵשָׂו לְמִפְלַג. וְעֵשָׂו נָפַק מֵחוּלָקֵיהּ דְּאַרְעָא וּמִכֹּלָּא, וְיַעֲקֹב דְּיִסְבּוֹל גָּלוּתָא יִטּוֹל כֹּלָּא. וְעַל דָּא חָמָא הַהוּא תְּבִירָא דְּהֲוָה לֵיהּ בְּמִצְרַיִם, הוּא וּבְנוֹי לְמִסְבַּל גָּלוּתָא. וְעַל דָּא וַיֹּאמֶר יַעֲקֹב לְבָנָיו לָמָּה תִתְרָאוּ. מִקַּמֵי דִינָא דִלְעֵילָא, דְּלָא יִשְׁתַּכַּח עֲלַיְיכוּ מְקַטְרְגָא. וַיֹּאמֶר הִנֵּה שָׁמַעְתִּי כִּי יֵשׁ שֶׁבֶר בְּמִצְרַיִם רְדוּ שָׁמָּה. הָא אוּקְמוּהָ רד\"ו, חוּשְׁבַּן דָּא הֲווּ יִשְׂרָאֵל בְּמִצְרַיִם:</p>"],[9520011402,"<p>וְיוֹסֵף הוּא הַשַּׁלִּיט עַל הָאָרֶץ וְגו', רִבִּי יֵיסָא פָּתַח וְאֲמַר, (תהילים כ״ז:ו׳) וְעַתָּה יָרוּם רֹאשִׁי עַל אוֹיְבַי סְבִיבוֹתַי וְאֶזְבְּחָה בְּאָהֳלוֹ זִבְחֵי תְרוּעָה אָשִׁירָה וַאֲזַמְּרָה לַיְיָ. תָּא חֲזֵי, כַּד קוּדְשָׁא בְּרִיךְ הוּא אִתְרָעֵי בֵּיהּ בְּבַר נָשׁ, זָקִיף לֵיהּ עַל כָּל בְּנֵי עַלְמָא. וְעָבִיד לֵיהּ רֵישָׁא דְכֹלָּא, וְכֻלְּהוּ שָׂנְאוֹי אִתְכַּפְיָין תְּחוֹתוֹי.</p>\n<p>דָּוִד מַלְכָּא, שָׂנְאוּ לֵיהּ אֲחוֹי, דָּחוּ לֵיהּ מִנַּיְיהוּ. קוּדְשָׁא בְּרִיךְ הוּא אָרִים לֵיהּ עַל כָּל בְּנֵי עַלְמָא. אֲתָא חֲמוֹי, עָרַק מִקַּמֵיהּ. קוּדְשָׁא בְּרִיךְ הוּא אָרִים לֵיהּ עַל כָּל מַלְכוּתֵיהּ, וְכֻלְּהוּ הֲווּ כָּרְעִין וְסָגְדִין קַמֵּיהּ. וְיוֹסֵף דָּחוּ לֵיהּ אֲחוּי, לְבָתַר כֻּלְּהוּ כָּרְעוּ וּסְגִידוּ קַמֵּיהּ. הֲדָא הוּא דִכְתִיב וַיָּבֹאוּ אֲחֵי יוֹסֵף וַיִּשְׁתַּחֲווּ לוֹ אַפַּיִם אָרְצָה.</p>\n<p>דָּבָר אַחֵר, וְעַתָּה יָרוּם רֹאשִׁי, מַאי וְעַתָּה, כְּמוֹ וְאַתָּה. רִבִּי יְהוּדָה אָמַר, הָא אִתְּמָר, עֵת דְּאִיהוּ דַרְגָּא עִלָּאָה, וּמַאן אִיהוּ הַהוּא עֵת. דָּא ה\"א, וְאִקְרֵי עַתָּה. וְעַתָּה, דָּא אִיהוּ וּבֵי דִינֵיהּ.</p>\n<p>יָרוּם רֹאשִׁי, לַאֲרָמָא לָהּ בִּיקָרָא וּמַלְכוּתָא. עַל אוֹיְבַי סְבִיבוֹתַי, אִלֵּין שְׁאָר מַלְכֵי אַרְעָא. וְאֶזְבְּחָה בְּאָהֳלוֹ, דָּא יְרוּשָׁלַ ם. בְּאָהֳלוֹ, דָּא אֹהֶל מוֹעֵד. זִבְחֵי תְרוּעָה, לְמִשְׁמַע כָּל עַלְמָא. אָשִׁירָה וַאֲזַמְּרָה, מֵהַהוּא סִטְרָא דִתְרוּעָה הִיא. דְּהָא מִתַּמָּן, מֵהַהוּא סִטְרָא דִתְרוּעָה, הִיא אַתְיָא שִׁירָה וְתוּשְׁבַּחְתָּא.</p>\n<p>דָּבָר אַחֵר, וְעַתָּה יָרוּם רֹאשִׁי, דָּא כְּנֶסֶת יִשְׂרָאֵל. עַל אוֹיְבַי סְבִיבוֹתַי, דָּא עֵשָׂו וְכָל אֲפַרְכִין דִּילֵיהּ. וְאֶזְבְּחָה בְּאָהֳלוֹ, אִלֵּין יִשְׂרָאֵל. זִבְחֵי תְרוּעָה, דִּכְתִיב, (תהילים נ״א:י״ט) זִבְחֵי אֱלהִים רוּחַ נִשְׁבָּרָה, בְּגִין לְאַעֲבָרָא דִינָא מֵעַלְמָא. אָשִׁירָה וַאֲזַמְּרָה, לְאוֹדָאָה וּלְשַׁבְּחָא לְקוּדְשָׁא בְּרִיךְ הוּא, בְּלָא פְּסִיקוּ לְעוֹלָם.</p>\n<p>דָּבָר אַחֵר, וְעַתָּה יָרוּם רֹאשִׁי, בְּכֹלָּא, יֵצֶר טוֹב עַל יֵצֶר רָע. דִּכְתִיב, עַל אוֹיְבַי סְבִיבוֹתַי, דָּא יֵצֶר הָרָע, דְּאִיהוּ סַחֲרָנֵיהּ דְּבַר נָשׁ, וְאִיהוּ שָׂנְאֵיהּ בְּכֹלָּא. וְאֶזְבְּחָה בְאָהֳלוֹ זִבְחֵי תְרוּעָה, דָּא אוֹרַיְיתָא, דְּאִתְיְהִיבַת מִסִּטְרָא דְאֶשָּׁא, כְּדִכְתִיב (דברים לג) מִימִינוֹ אֵשׁ דָּת לָמוֹ. דְּהָא בְּגִין אוֹרַיְיתָא, יָרוּם רֵישֵׁיהּ, וְאִתָּבְרוּ כָּל שָׂנְאוֹי קֳדָמוֹי. כְּדִכְתִיב, (תהילים י״ח:מ׳) תַכְרִיעַ קָמַי תַּחְתָּי.</p>\n<p>דָּבָר אַחֵר וְעַתָּה יָרוּם רֹאשִׁי, לְאִתְכְּלָלָא בַּאֲבָהָן, דְּהָא דָוִד מַלְכָּא, אִית לֵיהּ לְאִתְדַּבָּקָא בַּאֲבָהָן, וּכְדֵין יִתְרוֹמֵם וְסָלִיק לְעֵילָא, וְאִיהוּ בְּחַד קִשּׁוּרָא בְּהוּ. עַל אוֹיְבַי סְבִיבוֹתַי, אִלֵּין אִינוּן דְּבִסְטַר שְׂמָאלָא, כֻּלְּהוּ מָארֵי דִינִין, דְּמִתְכַּוְּנִין לְחַבָּלָא. וּכְדֵין שִׁמְשָׁא אִתְחַבַּר בְּסִיהֲרָא, וְהֲוֵי כֹּלָּא חָד.</p>\n<p>תָּא חֲזֵי כְּתִיב, וְיוֹסֵף הוּא הַשַּׁלִּיט עַל הָאָרֶץ, דָּא שִׁמְשָׁא דְּשַׁלִּיט בְּסִיהֲרָא, וְנָהִיר לָהּ וְזָן לָהּ. הוּא הַמַּשְׁבִּיר לְכָל עַם הָאָרֶץ, דְּהָא הַהוּא נָהָר דְּנָגִיד וְנָפִיק, מִנֵּיהּ אִתְזָנוּ כֻּלְּהוּ, וּמִתַּמָּן פָּרְחִין נִשְׁמָתִין לְכֹלָּא. וּבְגִין דָּא, כֻּלְּהוּ סָגְדִין לְגַבֵּיהּ דְּהַהוּא אֲתַר, דְּהָא לֵית לָךְ מִלָּה בְּעַלְמָא, דְּלָא תָּלֵי בְּמַזָּלָא וְאוּקְמוּהָ:</p>"],[9520011403,"<p>וַיַּכֶּר יוֹסֵף אֶת אֶחָיו וְהֵם לֹא הִכִּירוּהוּ. רִבִּי אֶלְעָזָר פָּתַח וְאֲמַר, (תהילים מ״ט:ו׳) לָמָּה אִירָא בִּימֵי רָע עֲוֹן עֲקֵבַי יְסֻבֵּנִי. תָּא חֲזֵי, תְּלַת אִינוּן דְּדָחֲלִין וְלָא יָדְעִין מִמַּה דָּחֲלִין, וְאוּקְמוּהָ. אֲבָל אִית מַאן דְּדָחִיל, וְלָא יָדַע מִמַּה אִיהוּ דָּחִיל, בְּגִין אִינוּן חֶטְאֵי. דְּלָא יָדַע דְּאִינוּן חֲטָאִין, וְלָא אַשְׁגַּח בְּהוּ, וְאִיהוּ דָּחִיל מִימֵי רָע.</p>\n<p>מַאן אִינוּן יְמֵי רָע, אִלֵּין אִינוּן יוֹמִין דְּאִינוּן אִזְדַּמְּנָן בְּהַהוּא <Nonei></i>רָע. וּמַאן אִינוּן, (ד\"א איהו) דָּא יֵצֶר הָרָע, דְּאִיהוּ אִקְרֵי רָע. וְאִית לֵיהּ יוֹמִין יְדִיעָן, דְּאִתְיְהִיב לֵיהּ רְשׁוּ בְּעַלְמָא, לְאַסְטָאָה לְכָל אִינוּן דִּמְסָאֲבֵי אָרְחַיְיהוּ. דְּמַאן דְּאָתֵי לְאִסְתָּאֲבָא, מְסָאֲבֵי לֵיהּ. וְאִלֵּין אִינוּן אִקְרוּן יְמֵי רָע, וְאִלֵּין מְמַנָּן עַל אִינוּן חוֹבִין דְּדָשִׁין בְּהוּ בְּנִי נָשָׁא בַּעֲקֵבַיְיהוּ.</p>\n<p>תָּא חֲזֵי, כָּל אִינוּן דִּמְסָאֲבֵי אָרְחַיְיהוּ, כַּמָּה חֲבִילֵי טְהִירִין אִזְדַּמְּנָן לְגַבַּיְיהוּ, וּמְסָאֲבֵי לְהוּ. בְּאָרְחָא דְבָעֵי בַּר נָשׁ לְמֵיהַךְ, בְּהַהוּא אָרְחָא מְדַבְּרִין לֵיהּ מַמָּשׁ. אָתֵי בַּר נָשׁ לְאִתְדַּכָּאָה, כַּמָּה אִינוּן דִּמְסַיְיעִין לֵיהּ.</p>\n<p>הָא תָּנִינָן, דְּכַד בַּר נָשׁ קָם בְּצַפְרָא, בָּעֵי לְאַסְחָאָה יְדוֹי, מִגּוֹ (לעיל נג א) נַטְלָא דְמַיָא, דְּאִיהוּ מָאנָא לִיטּוֹל מִנֵּיהּ מַיָא. מִגּוֹ מַאן דְּאַסְחֵי יְדוֹי בְּקַדְמִיתָא, כְּמָה דְאוּקְמוּהָ. וְתָּא חֲזֵי, בְּגִין נַטְלָא דָא, אוֹקִימְנָא מִלָּה.</p>\n<p>וְתוּ, דְּבָעְיָא לֵיהּ לְבַר נָּשׁ, לְנַטְלָא יְדָא יְמִינָא בִּשְׂמָאלָא. בְּגִין לְשַׁלְטָאָה יְמִינָא עַל שְׂמָאלָא, וְיִסְתְּחֵי יְמִינָא מִן שְׂמָאלָא, וּבְגִין כָּךְ אִיהוּ נְטִילָא. וְעַל דָּא, מַאן דְּנָטִיל יְדוֹי, יִטּוֹל יְמִינָא בִּשְׂמָאלָא, לְאַשְׁלָטָא יְמִינָא עַל שְׂמָאלָא. בְּגִין דְּלָא יָהִיב דּוּכְתָּא לְיֵצֶר הָרָע לְשַׁלְּטָאָה כְּלַל, וְהָא אוֹקִימְנָא.</p>\n<p>תָּא חֲזֵי, בְּשַׁעְתָּא דְדִינָא בִּישָׁא שָׁלְטָא, לָא אָתִיב יְדֵיהּ מִלְאַבְאָשָׁא. וּבְשַׁעְתָּא דִּימִינָא שָׁלְטָא עַל עַמִין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת לְתַבְרָא לוֹן, חָיִיס קוּדְשָׁא בְּרִיךְ הוּא עֲלַיְיהוּ, וְלָא שָׁצֵי לוֹן.</p>\n<p>וּבְּגִין כָּךְ, כָּל מַאן דְּאִיהוּ חָטֵי, בְּאִינוּן חֶטְאִין דְּדָשׁ בְּהוּ בְּרַגְלוֹי, לָא יָדַע בְּהוּ, וְדָחִיל תְּדִירָא. דָּוִד מַלְכָּא הֲוָה אִסְתַּמַר תָּדִיר מֵחוֹבִין אִלֵּין, וְכַד הֲוָה נָפִיק לִקְרָבָא, הֲוָה מְפַשְׁפֵּשׁ לוֹן. וְעַל דָּא לָא דָחִיל לַאֲגָחָא עִמְּהוֹן קְרָבָא.</p>\n<p>וְתָּא חֲזֵי, אַרְבַּע מַלְכִין הֲווּ, מַאן דְּשָׁאִיל דָּא לָא שָׁאִיל דָּא. דָּוִד אָמַר, (תהילים י״ח:ל״ח) אֶרְדּוֹף אוֹיְבַי וְאַשִּׂיגֵם וְלֹא אָשׁוּב עַד כַּלּוֹתָם. מַאי טַעְמָא, בְּגִין דְּהֲוָה אִסְתַּמַּר מֵאִלֵּין חוֹבִין, וְלָא יָהִיב דּוּכְתָּא לְשַׂנְאוֹי לְשַׁלְּטָאָה. וְעַל דָּא בָּעֵי לְמִרְדַּף אֲבַּתְרַיְיהוּ תָּדִיר, וְלָא יִרְדְּפוּן אִינוּן אֲבַתְרֵיהּ לְמִתְבַּע חוֹבוֹי, וְיִפּוֹל בִּידַיְיהוּ.</p>\n<p>אָסָא הֲוָה דָּחִיל יַתִּיר, אַף עַל גַּב דְּהֲוָה מְפַשְׁפֵּשׁ בְּחֶטְאוֹי, וְלָא כְדָוִד מַלְכָּא. אִיהוּ בָּעֵי לְמִרְדַּף אֲבַּתְרַיְיהוּ, וְלָא יַגִּיחַ לוֹן, וְיִקְטוֹל לוֹן קוּדְשָׁא בְּרִיךְ הוּא, וְכָךְ הֲוָה. דִּכְתִיב, (דברי הימים ב י״ד:י״ב) וַיִּרְדְּפֵם אָסָא וְהָעָם אֲשֶׁר עִמּוֹ וְגו', וּכְתִיב וַיִּגּוֹף יְיָ אֶת הַכּוּשִׁים לִפְנֵי אָסָא וְלִפְנִי יְהוּדָה וַיָּנוּסוּ הַכּוּשִׁים. (וכן) דָּוִד מַה כְּתִיב בֵּיהּ, (שמואל א ל׳:י״ז) וַיַּכֵּם דָּוִד מֵהַנֶּשֶׁף וְעַד הָעֶרֶב לְמָחֳרָתָם. אֲבָל אָסָא אִיהוּ רָדִיף וְקוּדְשָׁא בְּרִיךְ הוּא מָחֵי.</p>\n<p>יְהוֹשָׁפָט מֶלֶךְ יְהוּדָה, אוּף הָכִי נָמֵי הֲוָה שָׁאִיל. וְאֲמַר, לָא יָכִילְנָא לְמִרְדַּף וְלָא לְקָטְלָא. אֶלָּא אֲנָא אֲזַמֵּר, וְאַתְּ קְטֵיל לוֹן. בְּגִין דְּלָא הֲוָה מְפַשְׁפֵּשׁ כָּל כָּךְ כְּאָסָא. וְקוּדְשָׁא בְּרִיךְ הוּא עֲבַד לֵיהּ הָכִי. דִּכְתִיב, (דברי הימים ב כ׳:כ״ב) וּבְעֵת הֵחֵלּוּ בְרִנָה וּתְהִלָּה נָתַן יְיָ מְאָרְבִים עַל בְּנִי עַמּוֹן מוֹאָב וְהַר שֵׂעִיר הַבָּאִים לִיהוּדָה וַיִּנָּגֵפוּ.</p>\n<p>חִזְקִיָּה מֶלֶךְ יְהוּדָה, אוּף הָכִי נָמֵי אָמַר. אֲנָא לָא יָכִילְנָא, לָא לְזַמָּרָא, וְלָא לְמִרְדַּף, וְלָא לַאֲגָחָא קְרָבָא. בְּגִין דְּדָחִיל מֵאִלֵּין חוֹבִין דְּקָאֲמָרָן. מַה כְּתִיב, (מלכים ב י״ט:ל״ה) וַיְהִי בַלַיְלָה הַהוּא וַיֵּצֵא מַלְאַךְ יְיָ וַיַּךְ בְּמַחֲנִה אַשּׁוּר מֵאָה וּשְׁמוֹנִים וַחֲמִשָּׁה אֶלֶף וַיַּשְׁכִּימוּ בַבֹּקֶר וְהִנֵּה כֻלָּם פְּגָרִים מֵתִים. וְחִזְקִיָּה הֲוָה יָתִיב בְּבֵיתֵיהּ וְשָׁכִיב בְּעַרְסֵיהּ, וְקוּדְשָׁא בְּרִיךְ הוּא קָטִיל לוֹן.</p>\n<p>וּמַה צַּדִּיקִים אִלֵּין הֲווּ דָּחֲלִין מֵאִלֵּין חוֹבִין, שְׁאָר בְּנִי עַלְמָא עַל אַחַת כַּמָּה וְכַמָּה. בְּגִין כָּךְ אִית לֵיהּ לְבַר נָשׁ לְאִסְתַּמְּרָא מֵאִלֵּין חוֹבִין, וּלְפַשְׁפְּשָׁא בְּהוֹן כִּדְקָאֲמָרָן. בְּגִין דְּלָא יִשְׁלְטוּן עֲלוֹי אִינוּן יְמֵי רָע, דְּלָא מְרַחֲמֵי עֲלֵיהּ.</p>\n<p>תָּא חֲזֵי, וַיַּכֶּר יוֹסֵף אֶת אֶחָיו. בְּשַׁעְתָּא דְּנָפְלוּ בְּיָדֵיהּ, אִיהוּ רָחִים עֲלַיְיהוּ, בְּגִין דְּאִיהוּ שְׁלִים. וְהֵם לא הִכִּירוּהוּ, דְּאִינוּן שִׁמְעוֹן וְלֵוִי, אָתוּ מִסִּטְרָא דְּדִינָא קַשְׁיָא, וְעַל דָּא לָא רְחִימוּ עֲלֵיהּ. דְּהָא כָּל אִינוּן מָארֵיהוֹן דְּדִינָא קַשְׁיָא, לָא מְרַחֲמֵי עֲלַיְיהוּ דִבְנֵי נָשָׁא בְּשַׁעְתָּא דְּנָפְלֵי בִּידַיְיהוּ.</p>\n<p>וּבְגִין כָּךְ אָמַר דָּוִד, (תהילים מ״ט:ו׳) לָמָּה אִירָא. יָרֵאתִי לָא כְּתִיב, אֶלָּא אִירָא, (אלא) דְּאִית (נ\"א דלית) לִי לְמִדְחַל <Nonei></i>מֵאִינוּן יְמֵי רָע, כִּדְקָאֲמָרָן. עֲוֹן עֲקֵבַי יְסֻבֵּנִי, מַאן עֲקֵבַי. אִלֵּין אִינוּן בְּרָזָא דִּמְהֵימְנוּתָא. דִּכְתִיב, (בראשית כ״ה:כ״ו) וְיָדוֹ אוֹחֶזֶת בַּעֲקֵב עֵשָׂו, דָּא הוּא עֲקֵיבָא. וְאִינוּן עֲקֵיבִין דְּמִסְתַּכְּלִין בְּהוּ תָּדִיר בְּהַהוּא חוֹבָא דְּדָשׁ בֵּיהּ בַּר נָשׁ תָּדִיר בַּעֲקֵבוֹי.</p>\n<p>תָּא חֲזֵי, מַה כְּתִיב, (ישעיהו ה׳:י״ח) הוֹי מוֹשְׁכֵי הֶעָוֹן בְּחַבְלֵי הַשָּׁוְא וְכַעֲבוֹת הָעֲגָלָה חַטָּאָה. בְּחַבְלֵי הַשָּׁוְא, דְּדָשׁ בֵּיהּ בַּעֲקֵבָא וְלָא חַיִּישׁ עֲלֵיהּ. וּלְבָתַר אִתְתַּקַּף וְאִתְעֲבִיד (בחבלי השוא) כַּעֲבוֹת הָעֲגָלָה, וְאִתְתַּקַּף הַהוּא חֶטְאָה. וְאַסְטֵי לֵיהּ בְּהַאי עַלְמָא וּבְעַלְמָא דְאָתֵי.</p>\n<p>זַכָּאִין אִינוּן צַדִּיקַיָיא, דְּיָדְעִין לְאִסְתַּמְּרָא מֵחוֹבֵיהוֹן, וְאִינוּן מְפַשְׁפְּשִׁין תָּדִיר בְּעוֹבָדַיְיהוּ. בְּגִין דְּלָא יִשְׁתַּכַּח עֲלַיְיהוּ מְקַטְרְגָא בְּהַאי עַלְמָא, וְלָא יִסְטוּן עֲלַיְיהוּ לְעַלְמָא דְאָתֵי. דְּהָא אוֹרַיְיתָא מְתַקְנָא לְהוּ אָרְחִין וּשְׁבִילִין לְמֵיהַךְ בְּהוּ, דִּכְתִיב, (משלי ג׳:י״ז) דְּרָכֶיהָ דַרְכֵי נֹעַם וְכָל נְתִיבוֹתֶיהָ שָׁלוֹם:</p>"],[9520011404,"<p>וַיִּזְכּוֹר יוֹסֵף אֶת הַחֲלוֹמוֹת אֲשֶׁר חָלַם לָהֶם וְגו'. רִבִּי חִיָּיא פָּתַח וְאֲמַר, (משלי כ״ד:י״ז) בִּנְפוֹל אוֹיִבְךָ אַל תִּשְׂמַח וּבִכָּשְׁלוֹ אַל יָגֵל לִבֶּךָ. תָּא חֲזֵי, קוּדְשָׁא בְּרִיךְ הוּא עֲבַד לֵיהּ לְבַר נָשׁ, דְּיִזְכֵּי לִיקָרָא דִילֵיהּ, וּלְשַׁמָּשָׁא קַמֵּיהּ תְּדִירָא, וּלְאִשְׁתַּדְּלָא בְּאוֹרַיְיתָא יְמָמָא וְלֵילֵי. בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרָעֵי בָּהּ בְּאוֹרַיְיתָא תָּדִיר.</p>\n<p>וְכֵיוָן דְּבָרָא קוּדְשָׁא בְּרִיךְ הוּא לְאָדָם, יָהַב קַמֵּיהּ אוֹרַיְיתָא, וְאוֹלֵיף לֵיהּ בָּהּ לְמִנְדַע אָרְחָהָא. מְנָלָן, דִּכְתִיב, (איוב כ״ח:כ״ז-כ״ח) אָז רָאָהּ וַיְסַפְּרָהּ הכִינָהּ וְגַם חֲקָרָהּ. וּלְבָתַר, וַיֹּאמֶר לָאָדָם הֵן יִרְאַת יְיָ הִיא חָכְמָה וְסוּר מֵרָע בִּינָה. כֵּיוָן דְּאִסְתַּכַּל בָּהּ וְלָא נָטִיר לָהּ, עֲבַר עַל פִּקּוּדָא דְמָארֵיהּ וְאִתְפַּס בְּחוֹבֵיהּ.</p>\n<p>וְכָל אִינוּן דְּעָבְרוּ עַל מִלָּה חָדָא דְאוֹרַיְיתָא, אִתְּפָסוּ בָהּ. שְׁלמֹה מַלְכָּא דְּאִתְחַכַּם עַל כָּל בְּנֵי עַלְמָא, עֲבַר עַל מִלָּה חָדָא דְאוֹרַיְיתָא, וְגָרִים לֵיהּ לְאִתְעֲבָרָא מַלְכוּתֵיהּ מִנֵּיה, וּלְאִתְפַּלְּגָא מַלְכוּתָא מִן בְּנוֹי. מַאן דְּאַעֲבַר עַל אוֹרַיְיתָא עַל אַחַת כַּמָּה וְכַמָּה.</p>\n<p>וְיוֹסֵף דְּהֲוָה יָדַע אוֹרַיְיתָא, וַאֲחוֹי נָפְלוּ בִּידֵיהּ, אַמַּאי גִּלְגֵּל עֲלַיְיהוּ כָּל גִּלְגּוּלָא דָא. וְהָא אִיהוּ יָדַע אוֹרַיְיתָא דְּאוֹלִיף לֵיהּ אֲבוֹי. אֶלָּא, חַס וְשָׁלוֹם דְּיוֹסֵף גִּלְגֵל עֲלַיְיהוּ גִּלְגּוּלִין לְנַקְמָא מִנַּיְיהוּ. אֶלָּא כָּל דָּא לָא עֲבַד, אֶלָּא לְאַיְיתָאָה לַאֲחוּהָ בִּנְיָמִן לְגַבֵּיהּ, דְּתִאוּבְתֵּיהּ הֲוָה לְגַבֵּיה. וְאִיהוּ לָא שָׁבַק לַאֲחוֹי לְמִנְפַּל, דְּהָא כְּתִיב, וַיְצַו יוֹסֵף וַיְמַלְּאוּ אֶת כְּלֵיהֶם בָּר וְגו', וְכָל דָּא בְּגִין דְּלָא יִנְפְּלוּן.</p>\n<p>רִבִּי יְהוּדָה אָמַר, כַּד בְּרָא קוּדְשָׁא בְּרִיךְ הוּא לְסִיהֲרָא, הֲוָה אִסְתַּכַּל בָּהּ תָּדִיר, כְּדִּכְתִיב, (דברים י״א:י״ב) תָּמִיד עֵינִי יְיָ אֱלהֶיךָ בָּהּ, אַשְׁגָּחוּתָא דִילֵיהּ בָּהּ תָּדִיר, וּכְתִיב אָז רָאָהּ, דְּהָא שִׁמְשָׁא בְּאַשְׁגָּחוּתָא דִילֵיהּ בָּהּ, אִתְנְהִיר. וַיְסַפְּרָהּ, מַאי וַיְסַפְּרָהּ, כְּמָה דְאַתְּ אָמֵר, (איוב כ״ח:ו׳) מְקוֹם סַפִּיר אֲבָנֶיהָ.</p>\n<p>הֱכִינָהּ, דְּאִיהִי יָתְבָא בְּתִקּוּנָא, בִּתְרֵיסַר תְּחוּמִין, מִתְפַּלְּגָא (שמות נח ב) בְּשִׁבְעִין קְסִירִין. אַתְקִין לָהּ בְּשִׁבְעָה סַמְכִין עִלָּאִין, לְאִתְנַהֲרָא וּלְיַתְבָא עַל שְׁלִימוּ. וְגַם חֲקָרָהּ, לְאַשְׁגָּחָא עֲלָהּ תָּדִיר, זִמְנָא בָּתַר זִמְנָא, דְּלָא פָּסִיק לְעָלְמִין.</p>\n<p>וּלְבָתַר אַזְהַר לֵיהּ לְבַר נָשׁ, וְאֲמַר וַיֹּאמֶר לָאָדָם הֵן יִרְאַת יְיָ הִיא חָכְמָה וְסוּר מֵרָע בִּינָה. דְּהַאי מִתְעַטְּרָא עַל תַּתָּאי, לְדַחֲלָא וּלְמִנְדַע לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא בְּגִינָהּ. וְסוּר מֵרָע בִּינָה, בְּרִירוּ מִפְּסָלוּתָא, דְּלָא לְמִקְרַב בַּהֲדֵיהּ. וּכְדֵין אַשְׁגָּחוּתָא (נ\"א אשכחותא) דְבִינָה, לְמִנְדַע וּלְאִסְתַּכְּלָא בִּיקָרָא דְמַלְכָּא עִלָּאָה.</p>\n<p>רִבִּי יוֹסֵי קָם בְּלֵילְיָא חַד לְאִשְׁתַּדְּלָא בְּאוֹרַיְיתָא, וְהֲוָה תַּמָּן עִמֵּיהּ חַד יוּדָאי, דְּאָעֳרַע בֵּיהּ בְּהַהוּא בֵיתָא. פָּתַח רִבִּי יוֹסֵי וְאֲמַר, (משלי י׳:ב׳-ג׳) לֹא יוֹעִילוּ אוֹצְרוֹת רֶשַׁע וּצְדָקָה תַּצִּיל מִמָּוֶת. לֹא יוֹעִילוּ אוֹצְרוֹת רֶשַׁע, אִלֵּין אִינוּן דְּלָא מִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא, וְאָזְלֵי בָּתַר מִלֵּי דְעַלְמָא, וּלְמִכְנַשׁ אוֹצְרִין דְּחִיּוּבָא. מַה כְּתִיב, וְאָבַד הָעשֶׁר הַהוּא בְּעִנְיַן רָע. בְּגִין דְּאִינוּן אוֹצְרוֹת רֶשַׁע.</p>\n<p>וּצְדָקָה תַּצִּיל מִמָּוֶת, אִלֵּין דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא, וְיָדְעִין אוֹרְחָהָא לְאִשְׁתַּדְּלָא (לאסתכלא) בָהּ. דְּהָא אוֹרַיְיתָא עֵץ חַיִּים אִקְרֵי, וְאִתְקְרִיאַת צְדָקָה. דִּכְתִיב, וּצְדָקָה תִּהְיֶה לָנוּ. דָּבָר אַחֵר, וּצְדָקָה תַּצִּיל מִמָּוֶת, דָּא צְדָקָה מַמָּשׁ, וּבִתְרֵין גְּוָונִין אִיהוּ, וּבִתְרֵין סִטְרִין. קָרֵי בֵּיהּ אוֹרַיְיתָא, <Nonei></i>וְקָרֵי בֵּיהּ צְדָקָה, וְכֹלָּא חַד.</p>\n<p>אָמַר הַהוּא יוּדָאי, וְקָרֵי בֵּיהּ שָׁלוֹם. אָמַר רִבִּי יוֹסֵי, הָכִי הוּא וַדַּאי דְאִקְרֵי שָׁלוֹם. קָם הַהוּא יוּדָאי, וְאִשְׁתַּתַּף בַּהֲדֵיהּ, פָּתַח הַהוּא יוּדָאי וְאֲמַר, (משלי כ״ח:י״ט) עוֹבֵד אַדְמָתוֹ יִשְׂבַּע לָחֶם וּמְרַדֵּף רֵקִים יִשְׂבַּע רֵישׁ. הַאי קְרָא קַשְׁיָא, וְכִי שְׁלֹמֹה מַלְכָּא דְּאִיהוּ חַכִּים מִכָּל בְּנֵי עַלְמָא, הֵיךְ אָמַר דְּיִשְׁתָּדַּל בַּר נָשׁ לְמִפְלַח אַרְעָא וּלְאִשְׁתַּדְּלָא אֲבַתְרֵיהּ, וְיִשְׁבּוֹק חַיֵּי עָלְמָא.</p>\n<p>אֶלָּא רָזָא אִיהוּ. פָּתַח וְאֲמַר, (בראשית ב׳:ט״ו) וַיִּקַּח יְיָ אֱלֹהִים אֶת הָאָדָם וַיַּנִּיחֵהוּ בְגַן עֵדֶן לְעָבְדָהּ וּלְשָׁמְרָהּ, וְאוּקְמוּהָ בְּרָזָא דְקָרְבָּנִין אִיהוּ. תָּא חֲזֵי, לְעָבְדָהּ, דָּא מַלְכָּא עִלָּאָה. וּלְשָׁמְרָהּ, דָּא מַלְכָּא תַּתָּאָה. עַלְמָא עִלָּאָה, וְעַלְמָא תַּתָּאָה. לְעָבְדָהּ (דדכורא) בְּרָזָא דְזָכוֹר, וּלְשָׁמְרָהּ בְּרָזָא דְשָׁמוֹר.</p>\n<p>וּבְּגִין כָּךְ, עוֹבֵד אַדְמָתוֹ, דָּא גַן עֵדֶן. דְּאִצְטְרִיךְ לְמֶעְבַּד וּלְמִפְלַח, וּלְאַמְשָׁכָא לָהּ בִּרְכָאן מִלְּעֵילָא. וְכַד אִתְבָּרְכָא וְאִתְמַשְּׁכָא לָהּ בִּרְכָאן מִלְּעֵילָא, אִיהוּ נָמֵי אִתְבָּרֵךְ בַּהֲדָהּ. תָּא חֲזֵי, דְּכַהֲנָא דִּמְבָרֵךְ, מִתְבָּרֵךְ. כְּמָה דְאַתְּ אָמֵר, (במדבר ו׳:כ״ז) וַאֲנִי אֲבָרַכֵם. וּבְגִין כָּךְ, עוֹבֵד אַדְמָתוֹ יִשְׂבַּע לָחֶם, דָּא הוּא מְזוֹנָא דִלְעֵילָא. וּמְרַדֵּף רֵקִים, מַאן דְּיִתְדַּבַּק בְּסִטְרָא אָחֳרָא, דְּאִיהוּ מְרַדֵּף רֵקִים. יִשְׂבַּע רֵישׁ ודַּאי. אָמַר רִבִּי יוֹסֵי, זַכָּאָה אַנְתְּ, דְּזָכִית לְהַאי מִלָּה.</p>\n<p>תוּ פָּתַח וְאָמַר קְרָא אֲבַתְרֵיהּ, (משלי כ״ח:כ׳) אִישׁ אֱמוּנוֹת רַב בְּרָכוֹת, דָּא הוּא בַּר נָשׁ דִּמְהֵימְנוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא בֵּיהּ, כְּגוֹן רִבִּי יֵיסָא סָבָא. דְּאַף עַל גַּב דְּהֲוָה לֵיהּ מֵיכְלָא דְהַהוּא יוֹמָא לְמֵיכַל, לָא הֲוָה מַתְקִין לֵיהּ עַד דְּשָׁאִיל מְזוֹנֵיהּ קַמֵּי מַלְכָּא קַדִּישָׁא. לְבָתַר דְּצַלֵּי צְלוֹתֵיהּ וְשָׁאִיל מְזוֹנֵיהּ קַמֵּי מַלְכָּא, כְּדֵין הֲוָה מְתַקִּין. וְהֲוָה אָמַר תָּדִיר, לָא נְתַקִּין, עַד דְּיִנָּתְנוּן מִבֵּי מַלְכָּא.</p>\n<p>וְאָץ לְהַעֲשִׁיר לֹא יִנָּקֶה, בְּגִין דְּלָא בָּעָא לְאִשְׁתַּדְּלָא בְּאוֹרַיְיתָא, דְּאִיהִי חַיִּין דְּעַלְמָא דֵין, וְחַיִּין דְּעַלְמָא דְאָתֵי. הַשְׁתָּא דְאִיהִי שַׁעְתָּא לְאִשְׁתַּדְּלָא בְּאוֹרַיְיתָא, נִשְׁתַּדֵּל.</p>\n<p>פָּתַח הַהוּא גַבְרָא בְּרָזָא דְחֶלְמָא וְאֲמַר, וַיִּזְכּוֹר יוֹסֵף אֶת הַחֲלוֹמוֹת אֲשֶׁר חָלַם לָהֶם וְגו'. וַיִּזְכּוֹר יוֹסֵף אֶת הַחֲלוֹמוֹת, וְכִי יוֹסֵף אַמַּאי (נ\"א אמר או) אַדְכַּר לוֹן אִינוּן חֲלוֹמוֹת דְּחָלַם לְהוּ. וּמַה סַגְיָא לֵיהּ אִלּוּ לָא אַדְכַּר לְהוּ, דְּהָא יוֹסֵף חַכִּים הֲוָה, וּכְתִיב, כָּל עָרוּם יַעֲשֶׂה בְדָעַת וּכְסִיל יִפְרֹשׂ אִוֶּלֶת.</p>\n<p>אֲבָל, כֵּיוָן דְּחָמָא דְאִינוּן אָתּוּ, וְסָגְדֵי לֵיהּ אַפִּין עַל אַרְעָא. כְּדֵין אִדְכַּר מִמַּה דְּחָלַם לְהוּ, כַּד הֲוָה עִמְּהוֹן. דִּכְתִיב, וְהִנֵּה קָמָּה אֲלֻמָּתִי וְגַם נִצָּבָה וְהִנֵּה תְסֻבֶּינָה אֲלֻמּוֹתֵיכֶם וַתִּשְׁתַּחֲוֶינָה לַאֲלֻמָּתִי. אֲמַר יוֹסֵף בְּשַׁעְתָּא דְחָמָא דְּכָרְעִין אֲחוֹי קַמֵּיהּ. דִּכְתִיב, וַיָּבֹאוּ אֲחֵי יוֹסֵף וַיִּשְׁתַּחֲווּ לוֹ אַפַּיִם אַרְצָה, כְּדֵין וַיִּזְכּוֹר יוֹסֵף אֶת הַחֲלוֹמוֹת אֲשֶׁר חָלַם. דְּהָא חָמָא דְּהֲווּ קָיְימֵי (מתקיימי).</p>\n<p>תוּ, וַיִּזְכּוֹר יוֹסֵף אֶת הַחֲלוֹמוֹת אֲשֶׁר חָלַם, אַדְכַּר לוֹן. בְּגִין דְּלֵית נַשְׁיוּ קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, דְּהָא חֶלְמָא דְּאִיהוּ טָבָא, בָּעֵי בַר נָשׁ לְאַדְכָּרָא לֵיהּ דְּלָא יִתְנְשֵׁי, וּכְדֵין אִתְקְיַּים. דְּהָא כְּמָה דְאִתְנְשֵׁי קַמֵּיהּ דְּבַר נָשׁ, הָכִי אִתְנְשֵׁי עֲלֵיהּ.</p>\n<p>תָּא חֲזֵי, חֶלְמָא דְּלָא אִתְפַּשַּׁר, כְּאִגַּרְתָּא דְּלָא מִתְקַרְיָא, וְתָּא חֲזֵי, בְּגִין דְּלָא אִדְכַּר, כְּמַאן דְּלָא יָדַע לֵיהּ. וְעַל דָּא, מַאן דְּאִתְנְשֵׁי מִנֵּיהּ חֶלְמָא וְלָא יָדַע לֵיהּ, לָא קָיְימָא עֲלֵיהּ לְאִתְקָיְימָא. וּבְגִין דָּא יוֹסֵף הֲוָה דָּכִיר חֶלְמֵיהּ, בְּגִין לְאִתְקַיְּימָא. בְּגִין דְּלָא יִתְנְשֵׁי חֶלְמָא מִנֵּיהּ לְעָלַם, וְהֲוָה מְחַכֶּה לֵיהּ תָּדִיר. וַיֹּאמֶר אֲלֵיהֶם מְרַגְּלִים אַתֶּם, אִיהוּ דָּכִיר חֶלְמָא. אֲבָל מִלָּה לָא אָמַר לוֹן, אֶלָּא מְרַגְּלִים אַתֶּם.</p>\n<p>פָּתַח רִבִּי יוֹסֵי וְאֲמַר, (קהלת ה׳:ב׳) כִּי בָא הַחֲלוֹם בְּרוֹב עִנְיָן וְקוֹל כְּסִיל בְּרוֹב דְּבָרִים. כִּי בָא הַחֲלוֹם בְּרוֹב עִנְיָן, הָא אוּקְמוּהָ. דְּכַמָּה אִינוּן סְמִיכִין בְּחֶלְמָא, וּמְמַנָּן דַּרְגִּין עַל דַּרְגִּין. עַד דְּחָלְמִין מִנְהוֹן קְשׁוֹט כֻּלְּהוּ, וּמִנְּהוֹן דְּאִית בְּהוֹן קְשׁוֹט וּכְדִיבוּ. אֲבָל לְאִינוּן זַכָּאֵי קְשׁוֹט, לָא אִתְגְּלִי לוֹן מִלִּין כְּדִיבָן כְּלוּם, אֶלָּא כֻּלְּהוּ קְשׁוֹט.</p>\n<p>תָּא חֲזֵי, דָּנִיֵּאל מַה כְּתִיב בֵּיהּ, (דניאל ב׳:י״ט) אֱדַיִן לְדָנִיֵּאל בְּחֶזְוָא דִי לֵילְיָא <Nonei></i>רָזָא גַּלֵּי. וּכְתִיב, (דניאל ז׳:א׳) דָּנִיֵּאל חֵלֶם חֲזָה וְחֶזְוֵי רֵאשֵׁהּ עַל מִשְׁכְּבֵיהּ בֵּאדַיִן חֶלְמָא כְתַב. וְאִי אִית בֵּיהּ מִלִּין כְּדִיבָן, אַמַּאי אִיכְתִּיב בֵּין כְּתוּבִים. אֶלָּא אִינוּן זַכָּאֵי קְשׁוֹט, בְּשַׁעְתָּא דְּנִשְׁמַתְהוֹן סָלְקִין. לָא מִתְחַבְּרָן בְּהוּ, אֶלָּא מִלִּין קַדִּישִׁין. דְּאוֹדְעִין לֵיהּ מִלֵּי דִקְ שׁוֹט, מִלִּין קָיְימָן דְּלָא מְשַׁקְרָן לְעָלְמִין.</p>\n<p>וְאִי תֵימָא, הָא תְּנַן דְּדָוִד מַלְכָּא לָא חָמָא חֶלְמָא טָבָא. הָא אִשְׁתְּמַע דְּהֲוָה חָמֵי דָּוִד מִלִּין דְּלָא קְשׁוֹט. אֶלָּא וַדַּאי, כָּל יוֹמוֹי הֲוָה מִשְׁתַּדֵּל לְאוֹשְׁדָא דָמִין, וְאַגַּח קְרָבִין, וְכָל חֶלְמוֹי לָא הֲווּ אֶלָּא חֶלְמִין בִּישִׁין. חוּרְבָא וְשׁוֹמְמוּתָא וְדָמָא וְאוֹשִׁידוּ דְּדָמִין, וְלָא חֶלְמָא דִשְׁלָם.</p>\n<p>וְאִי תֵימָא, לְבַר נָשׁ טַב אַחֲזִיאוּ לֵיהּ חֶלְמָא בִּישָׁא, הָכִי הוּא וַדַּאי. כָּל אִינוּן בִּישִׁין דְּזַמִּינִין לְאִתְדַּבְּקָא עַל אִינוּן דְּעָבְרֵי עַל פִּתְגָמֵי דְאוֹרַיְיתָא, וְאִינוּן עוֹנָשִׁין דְּזַמִּינִין לְאִתְעֲנָשָׁא בְּהַהוּא עַלְמָא, כֻּלְּהוּ חָמֵי. בְּגִין דְּכָל שַׁעְתָּא יְהֵא דְחִילוּ דְמָרֵיהּ עֲלֵיהּ, וְהָא אִתְעָרוּ. דִּכְתִיב, (קהלת ג׳:י״ד) וְהָאֱלהִים עָשָׂה שֶׁיִּירְאוּ מִלְפָנָיו, זֶה חֲלוֹם רָע. וְעַל דָּא, לְהַהוּא זַכָּאָה, אַחֲזִיוּ לֵיהּ חֶלְמָא בִּישָׁא, כְּמָה דְאִתְּמָר.</p>\n<p>תָּא חֲזֵי, דְּהָא תָּנִינָן, דְּהַהוּא בַּר נָשׁ דְּחָמֵי חֶלְמָא, בָּעֵי לֵיהּ לְמִפְתַּח פּוּמֵיהּ בֵּיהּ קַמֵּי בְּנֵי נָשָׁא דְּרַחֲמֵי לֵיהּ. בְּגִין דְּיִסְתַּלַּק רְעוּתָא דִלְהוֹן לְגַבֵּיהּ לְטַב, וְיִפְתְּחוּן פּוּמַיְיהוּ לְטַב, וְיִשְׁתַּכַּח רְעוּתָא וּמִלָּה כֹּלָּא לְטַב. רְעוּתָא דְאִיהִי מַחֲשָׁבָה, שֵׁרוּתָא דְכֹלָּא, וּמִלָּה דְאִיהִי סִיּוּמָא דְכֹלָּא. וְעַל דָּא אִשְׁתַּכַּח דְּהָא שְׁלִימוּ אִיהוּ בְּרָזָא עִלָּאָה. וּבְגִין כָּךְ אִתְקְיַּים כֹּלָּא, וּבְעִינָן רְחִימִין דְּבַר נָשׁ (נ\"א רחימין עליה דבר נש בגין) לְאִתְקַיְּימָא בְּהַהוּא פִּשְׁרָא טָבָא, וְכֹלָּא אִיהוּ כְּדְקָא יְאוּת.</p>\n<p>וּבְּגִין כָּךְ קוּדְשָׁא בְּרִיךְ הוּא אוֹדַע לֵיהּ לְבַר נָשׁ, כָּל חַד וְחַד, בְּהַהוּא דַרְגָּא דִילֵיהּ, כְּמָה דְאִיהוּ. וּבְהַהוּא גַוְונָא דְּכָל חַד וְחַד, אָמַר דִּיהֵא חֶלְמָא. אָמַר הַהוּא יוּדָאי, וַדַּאי דְחֶלְמָא לָאו אִיהוּ אֶלָּא לְבַר נָשׁ זַכָּאָה, דְּאִיהוּ חָמָא חֶלְמָא כְּדְקָא חָזֵי.</p>\n<p>וְתָּא חֲזֵי, דְּכַד בַּר נָשׁ נָאִים עַל עַרְסֵיהּ, נִשְׁמָתֵיהּ נָפְקָא וְשַׁטְיָא בְּעַלְמָא לְעֵילָא, וְעָאלַת בְּאַתְרָא דְּעָאלַת. וְכַמָּה חֲבִילֵי טְהִירִין, קָיְימִין וְאָזְלִין בְּעַלְמָא, וּפָגְעִין בָּהּ בְּהַהִיא נִשְׁמָתָא. אִי זַכָּאָה הִיא, סַלְקָא לְעֵילָא וְחָמַאת מַה דְּחָמַאת. וְאִי לָאו, אִתְאַחֲדַת בְּהַהוּא סִטְרָא, וּמוֹדִיעִין לָהּ מִלִּין כְּדִיבָן, אוֹ מִלִּין דְּזַמִּינִין לְמֵיתֵי לִזְמַן קָרִיב. וְכַד אִתְעַר הַהִיא נִשְׁמָתָא דְּבֵיהּ, אִיהִי מוֹדְעָא לֵיהּ מַה דְּחָמַאת.</p>\n<p>וְעַל דָא, לְבַר נָשׁ דְּלָאו אִיהוּ זַכָּאָה, מוֹדִיעִין לֵיהּ חֶלְמָא טָבָא דְּלָאו אִיהוּ קְשׁוֹט. כֹּלָּא בְּגִין לְאַסְטָאָה לֵיהּ מֵהַהוּא אֹרַח קְשׁוֹט. כֵּיוָן דְּאִיהוּ אַסְטֵי אוֹרְחֵיהּ מֵאֹרַח קְשׁוֹט, מְסָאֲבִין לֵיהּ. דְּכָל מַאן דְּאָתֵי לְאִתְדַּכָּאָה, מְדַכְּאִין לֵיהּ. וּמַאן דְּאָתֵי לְאִסְתַּאֲבָא, מְסָאֲבִין לֵיהּ. הָא וַדַּאי אִתְּמָר הָכִי.</p>\n<p>יָתְבוּ עַד דְּסָלִיק צַפְרָא, אָמַר רִבִּי יוֹסֵי, וַדַּאי לָא זָכַר שְׁמֵיהּ דְּיוֹסֵף בְּאִינוּן דְּגָלִים. דִּכְתִיב, (במדבר ב׳:י״ח) דֶּגֶל מַחֲנֵה אֶפְרַיִם, וְלָא כְּתִיב דֶּגֶל מַחֲנֵה יוֹסֵף. בְּגִין דְּאִתְגָּאֵי עַל אֲחוֹי, וְהָא אִתְּמָר.</p>\n<p>אָמַר הַהוּא יוּדָאי, וַדַּאי שְׁמַעְנָא דְּיוֹסֵף אִיהוּ בְּעַלְמָא דִּדְכוּרָא, וְכֻלְּהוּ שִׁבְטִין בְּעַלְמָא דְנוּקְבָא אִינוּן. וְעַל דָּא לָא אִתְכְּלִיל יוֹסֵף עִמְּהוֹן, בְּגִין דְּאִיהוּ בְּעַלְמָא דִּדְכוּרָא עִמְּהוֹן (נ\"א ל\"ג עמהון).</p>\n<p>מַה כְּתִיב, כֻּלָּנוּ בְּנֵי אִישׁ אֶחָד נָחְנוּ. נָחְנוּ, אֲנַחְנוּ מִבָּעֵי לֵיהּ. אַמַּאי חָסֵר א'. אֶלָּא, בְּגִין דְּרָזָא דִבְרִית לָא אִשְׁתַּכַּח עִמְּהוֹן, אִסְתַּלַּק מִתַּמָּן א'. דְּהָא א' דְּכוּרָא אִיהוּ. וְעַל דָּא ב' אִיהִי נוּקְבָא, א' דְּכוּרָא. וּבְגִין דָּא אִסְתַּלַּק א' מִתַּמָּן, וְאִשְׁתָּאֲרוּ אִינוּן נוּקְבֵי לְגַבֵי שְׁכִינְתָּא.</p>\n<p>וּלְבָתַר אָמְרוּ, כֵּנִים אֲנַחְנוּ, אִתּוֹסַף א'. אָמְרוּ וְלָא יָדְעֵי מַה קָאֲמְרוּ. בְּגִין דְּיוֹסֵף אִשְׁתַּכַּח תַּמָּן, וְאַשְׁלִימוּ מִלָּה, וְאָמְרוּ אֲנַחְנוּ. מְנָלָן, דִּכְתִיב וַיֹּאמְרוּ שְׁנֵים עָשָׂר עֲבָדֶיךָ אַחִים אֲנָחְנוּ, וְיוֹסֵף אִיהוּ בְּחוּשְׁבָּנָא, כַּד עָאל בְּחוּשְׁבָּנָא, אָמְרוּ אֲנָחְנוּ. וְכַד לָא עָאל בְּחוּשְׁבָּנָא, אָמְרוּ נָחְנוּ.</p>\n<p>אָמַר רִבִּי יוֹסֵי, כָּל הָנֵּי מִלִּין דְּקָאֲמָרָן הָכָא, קוּדְשָׁא בְּרִיךְ הוּא אִתְרָעֵי בְּהוּ, דְּהָא שְׁכִינְתָּא <Nonei></i>לָא אַעֲדֵי מֵהָכָא. כְּדִכְתִיב, (מלאכי ג׳:ט״ז) אָז נִדְבְּרוּ יִרְאֵי יְיָ אִישׁ אֶל רֵעֵהוּ וַיַּקְשֵׁב יְיָ וַיִּשְׁמָע וַיִּכָּתֵב סֵפֶר זִכָּרוּן לְפָנָיו לְיִרְאֵי יְיָ וּלְחוֹשְׁבֵי שְׁמוֹ:</p>"],[9520011405,"<p>וַיֶּאֱסוֹף אוֹתָם אֶל מִשְׁמָר שְׁלשֶׁת יָמִים. אָמַר רִבִּי אֶלְעָזָר, הָנֵּי תְּלַת יוֹמִין אַמַּאי. אֶלָּא הָנֵּי תְּלַת יוֹמִין, לָקֳבֵיל תְּלַת יוֹמִין דִּשְׁכֶם. דִּכְתִיב, (בראשית לה) וַיְהִי בַּיּוֹם הַשְּׁלִישִׁי בִּהְיוֹתָם כּוֹאֲבִים.</p>\n<p>תָּא חֲזֵי, מַה כְּתִיב בֵּיהּ, וַיֹּאמֶר אֲלֵיהֶם יוֹסֵף בַּיּוֹם הַשְּׁלִישִׁי זֹאת עֲשׂוּ וִחְיוּ. לְאַחֲזָאָה דְּלָא עָבַד אִיהוּ, כְּמָה דְּאִינוּן עָבְדוּ בִשְׁכֶם. דְּגָרְמוּ לְאַנְשֵׁי שְׁכֶם לְקַבְּלָא עֲלַיְיהוּ הַאי זֹאת, רָזָא דִבְרִית. וּלְבָתַר דְּעֲבָדוּ קִיּוּמָא דָא, קָטִילוּ לוֹן, וְלָא אִשְׁתָּאַר מִנְּהוֹן חַד. וְאִיהוּ מַה כְּתִיב, זֹאת עֲשׂוּ וִחְיוּ. מַאי טַעְמָא, בְּגִין דְּאֶת הָאֱלהִים אֲנִי יָרֵא, נָטִיר קְיָימָא. וְכָל גִּלְגּוּלָא דָא לָא הֲוָה אֶלָּא בְּגִינֵיהּ דְּבִנְיָמִין:</p>\n<p>וַיֹּאמְרוּ אִישׁ אֶל אָחִיו אֲבָל אֲשֵׁמִים אֲנַחְנוּ עַל אָחִינוּ וְגו'. וַיֹּאמְרוּ אִישׁ אֶל אָחִיו, דָּא שִׁמְעוֹן וְלֵוִי, כְּמָה דְּהֲוָה בְּקַדְמִיתָא. דִּכְתִיב, (בראשית ל״ז:י״ט) וַיֹּאמְרוּ אִישׁ אֶל אָחִיו הִנֵּה בַּעַל הַחֲלוֹמוֹת הַלָּזֶה בָּא. מַה לְּהַלָּן שִׁמְעוֹן וְלֵוִי, אוּף הָכָא שִׁמְעוֹן וְלֵוִי.</p>\n<p>תָּא חֲזֵי, מַאן אִישׁ וּמַאן אָחִיו. אֶלָּא אִישׁ, דָּא שִׁמְעוֹן, כְּתִיב הָכָא אִישׁ, וּכְתִיב הָתָם (במדבר כ״ה:ו׳) וְהִנֵּה אִישׁ מִבְּנֵי יִשְׂרָאֵל בָּא. מַה לְּהַלָּן מִשִּׁמְעוֹן, אוּף הָכָא נָמֵי שִׁמְעוֹן. וּבְגִין דְּאַהֲדַר בִּתְשׁוּבָה, בָּכָה וְאִתְנֶחָם עַל דָּא. וְאָמַר לְלֵוִי, אֲבָל אֲשֵׁמִים אֲנַחְנוּ. עַל דָּא אִתְבְּנֵי מַזָּלֵיהּ שׁוֹר, כְּגַוְונָא דְּמַזְּלֵיהּ דְּיוֹסֵף שׁוֹר. דִּכְתִיב, (דברים ל״ג:י״ז) בְּכוֹר שׁוֹרוֹ הָדָר לוֹ, וּמַזָּלֵיהּ דְּשִׁמְעוֹן שׁוֹר אִיהוּ.</p>"],[9520011406,"<p>וְעַל דָּא, וַיִּקַּח מֵאִתָּם אֶת שִׁמְעוֹן, בְּגִין דְּלָא יְקַטְרֵג בַּהֲדֵיהּ דְּלֵוִי. בְּגִין דְּשִׁמְעוֹן וְלֵוִי, כַּד מִתְחַבְּרָן תַּרְוַיְיהוּ יָכְלֵי לְקַטְרְגָא: וַיֶּאֱסוֹר אוֹתוֹ לְעֵינֵיהֶם, הָא אוּקְמוּהָ, לְעֵינֵיהֶם אֲסָרוֹ. וּלְבָתַר דְנָפְקוּ הֲוָה מַאֲכִיל לֵיהּ, וּמַשְׁקֵי לֵיהּ.</p>\n<p>וְאִי תֵימָא דִּרְעוּתָא דְיוֹסֵף אִיהוּ, בְּגִין דִּכְתִיב, (משלי כ״ה:כ״א) אִם רָעֵב שׂוֹנַאֲךָ הַאֲכִילֵהוּ לֶחֶם וְאִם צָמֵא הַשְׁקֵהוּ מַיִם. אִי הָכִי, יוֹסֵף דְּאִיהוּ זַכָּאָה, הֵיכִי עָבִיד הָכִי. דְּהָא כְּתִיב, (משלי כ״ה:כ״ב) כִּי גֶחָלִים אַתָּה חוֹתֶּה עַל רֹאשׁוֹ וַיְיָ יְשַׁלֶּם לָךְ.</p>\n<p>אֶלָּא, חַס וְשָׁלוֹם דְּיוֹסֵף לְהָכִי הוּא דְּחָיִישׁ. אֶלָּא כְּבַר נָשׁ לְאֲחוֹי, הָכִי נָמֵי הֲוָה עָבִיד. אִתְנְהִיג עִמֵּיהּ בְּאַחְוָה, וְלָא בְּגַוְונָא אָחֳרָא. וְלָא עִמֵּיהּ בִּלְחוֹדוֹי, אֶלָּא עִם כָּל אֲחוֹי. כְּמָה דִכְתִיב, וַיְצַו יוֹסֵף וַיְמַלְּאוּ אֶת כְּלֵיהֶם בָּר וּלְהָשִׁיב כַּסְפֵּיהֶם אִישׁ אֶל שַׂקּוֹ וְלָתֵת לָהֶם צֵדָה לַדֶּרֶךְ וַיַּעַשׂ לָהֶם כֵּן, בְּגִין לְאַנְהָגָא עִמְּהוֹן בְּאַחְוָה.</p>\n<p>רִבִּי יוֹסֵי פָּתַח וְאֲמַר, (נחום א׳:י״ב) אִם שְׁלֵמִים וְכֵן רַבִּים וְכֵן נָגֹזוּ וְעָבָר וְעִנִּיתִיךָ לא אֲעַנֵּךְ עוֹד, הַאי קְרָא אוּקְמוּהָ. דְּכַד עַמָּא כֻּלְּהוּ אִית בְּהוּ שְׁלָם, וְלָא אִית בְּהוּ מָארֵי דְבָבוּ. קוּדְשָׁא בְּרִיךְ הוּא חָיִיס עֲלַיְיהוּ, וְדִינָא לָא שָׁלְטָא בְּהוּ. וְאַף עַל גַּב דְּכֻלְּהוּ פָּלְחֵי לְכּוֹכָבִים וּמַזָּלוֹת, וְאִינוּן בִּשְׁלָם, דִּינָא לָא שַׁלִּיט עֲלַיְיהוּ, וְאוּקְמוּהָ. דִּכְתִיב, (הושע ד׳:י״ז) חֲבוּר עֲצַבִּים אֶפְרָיִם הַנַּח לוֹ.</p>\n<p>וְכֵן נָגֹזוּ וְעָבָר, מַאי וְכֵן נָגֹזוּ, וְנָגֹזוּ מִבָּעֵי לֵיהּ. אֶלָּא, דָּא הוּא רֵישָׁא דִקְרָא דְאִיהוּ שְׁלָם, אוּף הָכָא שְׁלָם. וּמַאי אִיהוּ, דָּא צְדָקָה. בְּגִין דִּצְדָקָה דָא הוּא שָׁלוֹם, וּמַאן דְּאַסְגֵּי בִּצְדָקָה, אַסְגֵּי שְׁלָם לְעֵילָא, וְאַסְגֵּי שְׁלָם לְתַתָּא. וּבְגִין כָּךְ וְכֵן נָגֹזוּ וְעָבָר, דְּגָזְזֵי מָמוֹנְהוֹן בִּצְדָקָה. וְעָבָר, וְעָבְרוּ מִבָּעֵי לֵיהּ, מַאי וְעָבָר. אֶלָּא דָּא הוּא דִינָא דְרוּגְזָא, כְּמָה דְאַתְּ אָמֵר, (ישעיה כו) עַד יַעֲבָר זָעַם, עָבַר דִּינָא מֵעֲלַיְיהוּ.</p>\n<p>דָּבָר אַחֵר, כֹּה אָמַר יְיָ אִם שְׁלֵמִים, אִלֵּין יִשְׂרָאֵל. דְּקוּדְשָׁא בְּרִיךְ הוּא יָהַב לוֹן בְּרִית קַיָּימָא לְנַטְרָא לֵיהּ תָּדִיר, וּלְמֶהֱוֵי בֵּיהּ בַּר נָּשׁ שְׁלִים בְּכָל סִטְרִין לְעֵילָא וְתַתָּא. וְאִי לָא נָטִיר לֵיהּ בַּר נָשׁ תָּדִיר, הָא אִיהוּ פָּגִים, פָּגוּם בְּכֹלָּא. מְנָלָן, דִּכְתִיב, (בראשית י״ז:א׳) הִתְהַלֵּךְ לְפָנַי וֶהְיֵה תָמִים. מַאי תָּמִים, שְׁלִים. דְּעַד לָא אִתְקְיַּים בֵּיהּ בְּרִית, אִיהוּ פָּגִים.</p>\n<p>וּבְגִין כָּךְ, אִם שְׁלֵמִים וְכֵן רַבִּים. אִם שְׁלֵמִים דְּנָטְרֵי פִּקּוּדָא דָא, לְמֶהֱוֵי שְׁלֵימִין, דְּלָא יְהוֹן פְּגִימִין, וְכֵן רַבִּים, יִפְשׁוּן <Nonei></i>וְיִסְגּוּן בֵּיהּ. בְּגִין דְּנִשְׁמָתִין לָא נָפְקֵי לְעַלְמָא, אֶלָא בְּהַאי בְּרִית. וְכֵן נָגֹזוּ, הַאי אִם שְׁלֵמִים דְּנָטְרֵי לֵיהּ תָּדִיר, נָגֹזוּ מַאן דְּאִתְגְּזַר וְקִבֵּל עֲלֵיהּ קְיָימָא דָא. וְעָבָר, מַאי וְעָבָר. הַהוּא זוּהֲמָא דְעָרְלָה, דְּהֲוָה בֵּיהּ בְּקַדְמִיתָא.</p>\n<p>דָּבָר אַחֵר, כֹּה אָמַר יְיָ אִם שְׁלֵמִים וְכֵן רַבִּים, אִלֵּין בְּנִי יַעֲקֹב. דְּהָא כָּל זִמְנָא דְּהֲווּ לְגַבֵּיהּ דְּיוֹסֵף, אִינוּן שְׁלֵמִים, דְּקָיְימֵי בַּהֲדֵיהּ דִּבְרִית. וְכֵן נָגֹזוּ, דְּאָזְלוּ וְשָׁבְקוּ לֵיהּ לְיוֹסֵף וּלְשִׁמְעוֹן. וְעָבָר, כְּדֵין דִּינָא שַׁרְיָא בְּגִינַיְיהוּ (נ\"א שכינתא שרייא בינייהו), כְּמָה דְאַתְּ אָמֵר, (שמות י״ב:כ״ג) וְעָבַר יְיָ לִנְגוֹף אֶת מִצְרַיִם.</p>\n<p>תָּא חֲזֵי, אִית דִּינָא קַשְׁיָא, וְאִית דִּינָא רַפְיָא. דִּינָא קַשְׁיָא תַּקִּיף, דִּינָא רַפְיָא חֲלָשׁ, וְכַד יָנְקָא הַאי דִינָא רַפְיָא, מִדִּינָא קַשְׁיָא, כְּדֵין אִתְתַּקַּף, וְאִיהוּ תַּקִּיף.</p>\n<p>בְּשַׁעְתָּא דְּאִתְעֲבִיד דִּינָא עַל יִשְׂרָאֵל, אִתְעֲבִיד בְּהַאי דִינָא רַפְיָא, וְלָא אִתְתַּקַּף בְּהַהוּא דִּינָא קַשְׁיָא. וְכַד דִּינָא אִתְעֲבִיד עֲלַיְיהוּ דְּעַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, אִתְתַּקַּף הַאי דִינָא רַפְיָא, בְּדִינָא קַשְׁיָא דִלְעֵילָא, בְּגִין לְאִתְתַּקְפָא. הֲדָא הוּא דִּכְתִיב, וְעָבַר יְיָ לִנְגוֹף אֶת מִצְרַיִם. וְעָבַר, דְּאִתְמְלֵי עֶבְרָה וְזַעֲמָא, וְאִתְתַּקַּף בְּדִינָא קַשְׁיָא, אוּף הָכָא וְעָבַר. וְתָּא חֲזֵי, בְּשַׁעְתָּא דְּמִתְכַּנְּשֵׁי עֲשָׂרָה בְּבֵי כְּנִישְׁתָּא, וְחַד מִנַּיְיהוּ אִשְׁתְּמִיט, כְּדֵין קוּדְשָׁא בְּרִיךְ הוּא אַרְגִּיז עֲלֵיהּ.</p>\n<p>דָּבָר אַחֵר וְכֵן נָגֹזוּ, כַּד מִתְעַבְּרֵי מִנַּיְיהוּ אִינוּן עוֹבָדִין בִּישִׁין, כְּדֵין וְעָבָר. מַאי וְעָבָר, רִבִּי שִׁמְעוֹן אָמַר, בְּזִמְנָא דְנִשְׁמָתָא נָפְקַת מֵהַאי עַלְמָא, בְּכַמָּה דִינִין אִתְדָּנַת עַד לָא תִיעוּל לְאַתְרָהּ. לְבָתַר, כָּל אִינוּן נִשְׁמָתִין אִית לוֹן לְמֶעֱבַר, בְּהַךְ נְהַר דִּינוּר דְּנָגִיד וְנָפִיק, וּלְאִסְתַּחָאָה תַּמָּן. וּמַאן אִיהוּ דְּיָקוּם תַּמָּן, וְיַעֲבַר בְּלָא דְחִילוּ. כְּמָה דְאַתְּ אָמֵר, (תהילים כ״ד:ג׳) מִי יַעֲלֶה בְּהַר יְיָ וְגו'. וְנִשְׁמָתָא דְּזַכָּאָה אַעֲבַר בְּלָא דְחִילוּ וְיָקוּם בִּמְקוֹם קָדְשׁוֹ.</p>\n<p>וּמַאן דְּאִשְׁתַּדַּל בִּצְדָקָה בְּהַאי עַלְמָא, וְיִתֵּן מִמָּמוֹנֵיהּ בִּצְדָקָה. כְּדֵין, וְעָבַר בְּהַהוּא אֲתַר, וְלָא דָחִיל, וְכָרוֹזָא קָרֵי לָהּ לְהַהִיא נִשְׁמָתָא, (נחום א׳:י״ב) וְעִנִּיתִיךָ לא אֲעַנֵּךְ עוֹד. מַאן דְּזָכָה לְמֶעֱבַר בְּהַאי, לֵית לֵיהּ דִּינָא יַתִּיר כְּלָל.</p>\n<p>תָּא חֲזֵי, כָּל דָּא דְּיוֹסֵף עִם אֲחוֹי, וְכָל הַנִּי מִילֵי, אַמַּאי אִצְטְרִיךְ. אֶלָּא אוֹרַיְיתָא דִקְשׁוֹט אִיהִי אוֹרַיְיתָא, וְכָל אָרְחָהָא אָרְחִין קַדִּישִׁין. וְלֵית לָךְ מִלָּה בְּאוֹרַיְיתָא דְּלָאו אִית בָּהּ רָזִין עִלָּאִין וְקַדִּישִׁין, וְאָרְחִין לִבְנֵי נָשָׁא לְאִתְתַּקְפָא בְּהוּ.</p>\n<p>פָּתַח וְאֲמַר, (משלי כ׳:כ״ב) אַל תֹּאמַר אֲשַׁלְּמָה רָע וְגו'. תָּא חֲזֵי, קוּדְשָׁא בְּרִיךְ הוּא עָבִיד לֵיהּ לְבַר נָשׁ, לְאִתְתַּקְפָא בָּהּ בְּאוֹרַיְיתָא, וּלְמֵיהַךְ בְּאֹרַח קְשׁוֹט, וְלִסְטַר יְמִינָא, וְלָא יְהַךְ לִסְטַר שְׂמָאלָא. וּבְגִין דְּבָעֵי לְהוּ (דישראל) לְמֵיהַךְ לִסְטַר יְמִינָא, אִית לוֹן לְאַסְגָּאָה רְחִימוּ דָּא עִם דָּא, וְלָא יְהֵא דְבָבוּ דָּא עִם דָּא. בְּגִין דְּלָא לְאַכְּחָשָׁא יְמִינָא, דְּאִיהוּ אֲתַר דְּיִשְׂרָאֵל מִתְדַּבְּקָן בֵּיהּ.</p>\n<p>וְתָא חֲזֵי, בְגִין כָּךְ אִיהוּ יֵצֶר טוֹב וְיֵצֶר רָע, וְיִשְׂרָאֵל בָּעְיָין לְאִתְתַּקְפָא לְיֵצֶר טוֹב עַל יֵצֶר רָע, בְּאִינוּן עוֹבָדִין דְּכָשְׁרָן, וְאִי סָטֵי בַּר נָשׁ לִשְׂמָאלָא, כְּדֵין אִתְתַּקַּף יֵצֶר רָע עַל יֵצֶר טוֹב. וּמַאן דְּהֲוָה פָּגִים, אַשְׁלִים לֵיהּ בְּחֶטְאוֹי, דְּהָא לָא אִשְׁתַּלִּים דָּא מְנוּוָלָא, אֶלָּא בְּחֶטְאִין דִּבְנֵי נָשָׁא.</p>\n<p>וּבְגִין כָּךְ בָּעֵי בַּר נָשׁ לְאִזְדַּהֲרָא, דְּלָא יִשְׁתַּלִּים הַהוּא יֵצֶר רַע בְּחֶטְאוֹי, וְיִסְתַּמַּר תָּדִיר. דְּהָא יֵצֶר טוֹב בָּעֵי לְאַשְׁלָמָא לֵיהּ בִּשְׁלֵימוּת תָּדִיר, וְלא יֵצֶר הָרָע. וּבְגִין כָּךְ, אַל תֹּאמַר אֲשַׁלְּמָה רַע קַּוֵה אֶל יְיָ וְיוֹשַׁע לָךְ.</p>\n<p>דָּבָר אַחֵר אַל תֹּאמַר אֲשַׁלְּמָה רַע, כְּדִכְתִיב, (תהילים ל״ח:כ״א) וּמְשַׁלְּמֵי רָעָה תַּחַת טוֹבָה, לְמַאן דְּשַׁלִּים לֵיהּ טוֹבָה, דְּלא יַשְׁלֵים לֵיהּ רָע, בְּגִין (דחילו דקודשא בריך הוא. כמה דאת אמר, זאת עשו וחיו. ואוף איהו הוי תדיר עביד) דִּכְתִיב, (משלי י״ז:י״ג) מֵשִׁיב רָעָה תַּחַת טוֹבָה לֹא תָמוּשׁ רָעָה מִבֵּיתוֹ. אֲפִילּוּ לְמַאן דְּאַשְׁלִימוּ לֵיהּ בִּישִׁין, לָא אִית לֵיהּ לְאַשְׁלָמָא בִּישָׁא, חֲלַף הַהוּא בִישָׁא דְּשַׁלִּימוּ לֵיהּ. אֶלָּא, קַוֵּה לַיְיָ וְיוֹשַׁע לָךְ.</p>\n<p>וְהַאי קְרָא אוּקְמוּהָ, בְּיוֹסֵף זַכָּאָה, דְּלָא בָּעָא לְאַשְׁלָמָא בִּישָׁא לַאֲחוֹי, בְּשַׁעְתָּא דְּנָפְלוּ בִּידוֹי. קַוֵּה לַיְיָ וְיוֹשַׁע לָךְ, בְּגִין דְּהוּא הֲוָה <Nonei></i>דָּחִיל לְקוּדְשָׁא בְּרִיךְ הוּא. דִּכְתִיב, זֹאת עֲשׂוּ וִחְיוּ וְגו'. (ואוף) וְאִיהוּ תָּדִיר הֲוָה מְחַכֶּה לְקוּדְשָׁא בְּרִיךְ הוּא. (ס\"א כמה דאת אמר, קוה ליי ויושע לך).</p>\n<p>רִבִּי אַבָּא פָּתַח וְאֲמַר, (משלי כ׳:ה׳) מַיִם עֲמוּקִים עֵצָה בְּלֵב אִישׁ וְאִישׁ תְּבוּנָה יִדְלֶנָּה. מַיִם עֲמוּקִים עֵצָה בְּלֵב אִישׁ, דָּא קוּדְשָׁא בְּרִיךְ הוּא. בְּגִין דְּאִיהוּ עָבִיד עֵצוֹת, דְּאַיְיתֵי טַעֲמִין לְגַלְגְּלָא גִּלְגּוּלִין עַל עַלְמָא עַל יְדָא דְיוֹסֵף, לְקַיְימָא הַהוּא גְזֵרָה, דְּגָזַר כַּפְנָא עַל אַרְעָא (נ\"א עלמא). וְאִישׁ תְּבוּנָה יִדְלֶנָּה, דָּא יוֹסֵף. דְּגָלֵי אִינוּן עֲמִיקִין, דְּגָזַר קוּדְשָׁא בְּרִיךְ הוּא עַל עַלְמָא.</p>\n<p>תָּא חֲזֵי, יוֹסֵף לא דַי לֵיהּ דְּאִיהוּ לָא שַׁלִּים בִּישָׁא לַאֲחוֹי, אֶלָא דְּעֲבַד עִמְּהוֹן טִיבוּ וּקְשׁוֹט. וְכָךְ אָרְחֵיהוֹן דְּזַכָּאֵי תָּדִיר. בְּגִין דָּא קוּדְשָׁא בְּרִיךְ הוּא חָיִיס עֲלַיְיהוּ תָּדִיר, בְּעַלְמָא דֵין וּבְעַלְמָא דְאָתֵי.</p>\n<p>מַיִם עֲמוּקִים עֵצָה בְּלֶב אִישׁ, דָּא יְהוּדָה. וְהָא אוּקְמוּהָ, בְּשַׁעְתָּא דְּאִתְקָרִיב לְגַבֵּיהּ דְּיוֹסֵף, עַל עִסְקָא דְבִנְיָמִין. וְאִישׁ תְּבוּנָה יִדְלֶנָּה, דָּא יוֹסֵף.</p>\n<p>רִבִּי אַבָּא הֲוָה יָתִיב אֲתַרְעָא דְּאַבָּבָא דְלוֹד, חָמָא חַד בַּר נָשׁ דְּהֲוָה אָתֵי, וְיָתִיב בְּחַד קוּלְטָא דְּתָלָא דְאַרְעָא, וְהֲוָה לָאֵי מֵאָרְחָא, וְיָתִיב וְנָאִים תַּמָּן. אַדְּהָכִי חָמֵי חַד חִוְיָא, דְּהֲוָה אָתֵי לְגַבֵּיהּ, נָפַק קוֹסְטְפָא דְגוּרְדְּנָא, וְקָטִיל לֵיהּ לְחִוְיָא. כַּד אִתְעַר הַהוּא בַּר נָשׁ, חָמָא הַהוּא חִוְיָא לְקֳבְלֵיהּ, דְּהֲוָה מִית. אִזְדַּקַּף הַהוּא בַּר נָשׁ, וְנָפַל הַהוּא קוּלְטָא לְעוּמְקָא דִּתְחוֹתוֹי וְאִשְׁתֵּזִיב.</p>\n<p>אֲתָא רִבִּי אַבָּא לְגַבֵּיהּ, אָמַר לֵיהּ, אֵימָא לִי מָאן עוֹבָדָךְ. דְּהָא קוּדְשָׁא בְּרִיךְ הוּא רָחִישׁ לָךְ אִלֵּין תְּרֵין נִסִּין, לָאו אִינוּן לְמַגָּנָא.</p>\n<p>אָמַר לֵיהּ הַהוּא בַּר נָשׁ, כָּל יוֹמָאי לָא אַשְׁלִים לִי בַּר נָשׁ בִּישָׁא בְּעַלְמָא, דְּלָא אִתְפַּיַּיסְנָא בַּהֲדֵיהּ, וּמָחִילְנָא לֵיהּ. וְתוּ, אִי לָא יָכִילְנָא לְאִתְפַּיְיסָא בַּהֲדֵיהּ, לָא סָלִיקְנָא לְעַרְסִי, עַד דְּמָחִילְנָא לֵיהּ, וּלְכָל אִינוּן דִּמְצַעֲרוּ לִי, וְלָא חַיְישָׁנָא כָּל יוֹמָא לְהַהוּא בִּישָׁא דְּאַשְׁלִים לִי. וְלָאו דִּי לִי דָא, אֶלָּא דִּמְהַהוּא יוֹמָא וּלְהָלְאָה, אִשְׁתַּדַּלְנָא לְמֶעְבַּד עִמְּהוֹן טָבָא.</p>\n<p>בָּכָה רִבִּי אַבָּא וְאֲמַר, יַתִּיר עוֹבָדוֹי דְּדֵין מִיּוֹסֵף, דְּיוֹסֵף הֲווּ אֲחוֹי וַדַּאי, וְהֲוָה לֵיהּ לְרַחֲמָא עֲלוֹי. אֲבָל מַה דְּעֲבִיד דָּא, יַתִּיר הוּא מִיּוֹסֵף. יָאוֹת הוּא דְקוּדְשָׁא בְּרִיךְ הוּא יַרְחִישׁ לֵיהּ נִיסָּא עַל נִיסָּא.</p>\n<p>פָּתַח וְאֲמַר, (משלי י׳:ט׳) הוֹלֵךְ בַּתֹּם יֵלֶךְ בֶּטַח וּמְעַקֵּשׁ דְּרָכָיו יִוָּדֵעַ. הוֹלֵךְ בַּתּוֹם יֵלֶךְ בֶּטַח, דָּא הַהוּא בַּר נָשׁ, דְּאָזִיל בְּאָרְחִין דְּאוֹרַיְיתָא. יֵלֶךְ בֶּטַח, דְּלָא יָכִילוּ נִזְקֵי דְעַלְמָא לְאַבְאָשָׁא לֵיהּ. וּמְעַקֵּשׁ דְּרָכָיו יִוָּדֵעַ, מַאן יִוָּדֵעַ. דָּא הוּא מַאן דְּאַסְטֵי מֵאָרְחָא דִקְשׁוֹט, וּבָעֵי גַבֵּי דְחַבְרֵיהּ. יִוָּדֵעַ, מַהוּ יִוָּדֵעַ, יִשְׁתְּמוֹדַע אִיהוּ בְּעֵינֵיהוֹן דְּכָל מָארֵי דְּדִינָא, דְּלָא יִתְאֲבִיד מִנַּיְיהוּ דִּיוּקְנָא דְהַהוּא בַּר נָשׁ. בְּגִין לְאַיְיתָאָה לֵיהּ לְאַתְרָא דְּיִנְקְמוּן מִנֵּיהּ, וּבְגִין כָּךְ יִוָּדֵעַ.</p>\n<p>וְתָּא חֲזֵי, הַהוּא דְּאָזִיל בְּאֹרַח קְשׁוֹט, קוּדְשָׁא בְּרִיךְ הוּא חָפֵי עֲלֵיהּ, בְּגִין דְּלָא אִתְיְדַע, וְלָא אִשְׁתְּמוֹדַע, לְגַבֵּי מָארֵיהוֹן דְּדִינָא. אֲבָל מְעַקֵּשׁ דְּרָכָיו יִוָּדֵעַ, וְיִשְׁתְּמוֹדַע לְגַבַּיְיהוּ. זַכָּאִין אִינוּן בְּנֵי נָשָׁא דְּאָזְלֵי בְּאֹרַח קְשׁוֹט, וְאָזְלֵי לְרוֹחֲצָן עַל עַלְמָא. דְּלָא דָּחֲלֵי אִינוּן בְּעַלְמָא דֵין, וְלָא בְּעַלְמָא דְאָתֵי:</p>"],[9520011407,"<p>וַיִּירְאוּ הָאֲנָשִׁים כִּי הוּבְאוּ בֵּית יוֹסֵף. רִבִּי יוֹסֵי אָמַר, וַוי לוֹן לִבְנֵי נָשָׁא, דְּלָא יָדְעֵי וְלָא מִסְתַּכְּלִין בְּאָרְחֵי דְאוֹרַיְיתָא. וַוי לוֹן בְּשַׁעְתָּא דְּקוּדְשָׁא בְּרִיךְ הוּא יֵיתֵי לְמִתְבַּע לוֹן דִּינָא עַל עוֹבָדֵיהוֹן, וְיָקוּם גּוּפָא וְנַפְשָׁא לְמֵיהַב חוּשְׁבָּנָא מִכָּל עוֹבָדֵיהוֹן, עַד לָא יִתְפָּרְשׁוּן נַפְשָׁא מִן גּוּפָא.</p>\n<p>וְהַהוּא יוֹמָא, יוֹמָא דְּדִינָא אִיהוּ, יוֹמָא דְּסִפְרִין פְּתִיחָן, וּמָארֵיהוֹן דְּדִינָא קָיְימִין. בְּגִין דְּהַהוּא זִמְנָא, קָיְימָא נָחָשׁ בְּקִיּוּמֵיהּ, לְנַשְׁכָא לֵיהּ. וְכָל שַׁיְיפֵי מִתְרַגְּשִׁין לְגַבֵּיהּ, וְנִשְׁמָתָא אִתְפָּרְשָׁא מִן גּוּפָא, וְאָזְלָא וְשַׁטְיָא. וְלָא יָדְעַת לְאָן אָרְחָא תְּהַךְ, וּלְאָן אֲתַר סָלְקִין לָהּ.</p>\n<p>וַוי לְהַהוּא יוֹמָא, יוֹמָא דְרוּגְזָא וּנְאִיצוּ הַהוּא יוֹמָא, בְגִין כָּךְ אִבָּעֵי לֵיהּ לְבַר נָשׁ, לְאַרְגָּזָא יִצְרֵיהּ כָּל יוֹמָא, לְאַדְכָּרָא קַמֵּיהּ הַהוּא יוֹמָא, דְּיֵיקוּם בְּדִינָא דְמַלְכָּא, דְּקָא עָאלִין לֵיהּ תְּחוֹת אַרְעָא לְאִתְרַקְּבָא, וְנִשְׁמָתָא אִתְפָּרְשָׁא <Nonei></i>מִנֵּיהּ.</p>\n<p>וּתְנַן, לְעוֹלָם יַרְגִּיז אָדָם יֵצֶר טוֹב עַל יֵצֶר הָרָע, וְיִשְׁתַּדֵּל אֲבַתְרֵיהּ. אִי אָזִיל מִנֵּיהּ, יָאוֹת. וְאִי לָאו, יִשְׁתַּדַּל בְּאוֹרַיְיתָא. דְּהָא לֵית לָךְ מִלָּה לְתַבְרָא יֵצֶר הָרָע אֶלָּא אוֹרַיְיתָא. אִי אָזִיל, מוּטָב. וְאִי לָאו, יַדְכַּר לֵיהּ יוֹמָא דְמוֹתָא, בְּגִין לְתַבְּרָא לֵיהּ.</p>\n<p>הָכָא אִית לְאִסְתַּכָּלָא, דְהָא דָא הוּא (קסא ב) יֵצֶר הָרָע, וְדָא הוּא מַלְאַךְ הַמָּוֶת. וְכִי מַלְאַךְ הַמָּוֶת מִתְבַּר מִקַּמֵּי יוֹמָא דְמוֹתָא. וְהָא אִיהוּ קָטוֹלָא דִּבְנִי נָשָׁא הֲוֵי, וְאִשְׁתְּמַע דְּחֶדְוָה הוּא דִילֵיהּ. וּבְגִין כָּךְ אַסְטֵי לוֹן לִבְנִי נָשָׁא תָּדִיר, בְּגִין לְאַמְשָׁכָא לוֹן לְדָא.</p>\n<p>אֶלָּא וַדַּאי מַה דְּאִתְּמָר, דְּיִדְכּוֹר לֵיהּ בַּר נָשׁ הַהוּא יוֹמָא דְמוֹתָא. וַדַּאי הָכִי הוּא, בְּגִין דְּמִתְבַּר לִבָּא דְבַר נָשׁ. דְּהָא יֵצֶר הָרָע לָא שַׁרְיָא אֶלָּא בְּאֲתַר דְּאִשְׁתַּכַּח חֶדְוָה דְחַמְרָא, וְגַסּוּתָא דְרוּחָא. וְכַד אִשְׁתַּכַּח רוּחָא תְּבִירָא, כְּדֵין אִתְפְּרַשׁ מִנֵּיהּ, וְלָא שַׁרְיָא בַּהֲדֵיהּ. וּבְגִין כָּךְ בָּעֵי לְאַדְכָּרָא לֵיהּ יוֹמָא דְמוֹתָא, וְיִתְבַּר גּוּפֵיהּ, וְאִיהוּ אָזִיל לֵיהּ.</p>\n<p>תָּא חֲזֵי, יֵצֶר טוֹב בָּעֵי חֶדְוָה דְאוֹרַיְיתָא, וְיֵצֶר רָע חֶדְוָה דְחַמְרָא, וְנִיאוּפִין וְגַסּוּתָא דְרוּחָא. וּבְגִין כָּךְ בָּעֵי בַּר נָשׁ לְאַרְגָּזָא (ליה) תָּדִיר, מֵהַהוּא יוֹמָא רַבָּא, יוֹמָא דְדִינָא, יוֹמָא דְּחוּשְׁבְּנָא. דְּלֵית לֵיהּ לְבַר נָשׁ לַאֲגָנָא עֲלֵיהּ, אֶלָּא עוֹבָדוֹי דְּכַשְׁרָן, דְּאִיהוּ עָבִיד בְּהַאי עַלְמָא. בְּגִין דְּיָגִינוּ עֲלֵיהּ בְּהַהִיא שַׁעְתָּא.</p>\n<p>תָּא חֲזֵי, וַיִּירְאוּ הָאֲנָשִׁים כִּי הוּבְאוּ בֵּית יוֹסֵף. וּמַה כֻּלְּהוּ הֲווּ גִּיבָּרִין, כֻּלְּהוּ תַּקִּיפִין, וְחַד עוּלֵימָא דְּאַיְיתֵי לוֹן לְבֵיתָא דְיוֹסֵף, דַּחֲלוּ. כַּד יֵיתֵי קוּדְשָׁא בְּרִיךְ הוּא לְמִתְבַּע לֵיהּ לְדִינָא לְבַר נָשׁ, עַל אַחַת כַּמָּה וְכַמָּה.</p>\n<p>בְּגִין כָּךְ בָּעֵי לֵיהּ לְבַר נָשׁ, לְאִזְדַּהֲרָא בְּהַאי עַלְמָא. לְאִתְתַּקְפָא בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא, וְיַשְׁוֵי בֵּיהּ רוֹחֲצָנֵיהּ. דְּאַף עַל גַּב דְּאִיהוּ חָטֵי, אִי יֶהדַר מִנֵּיהּ בִּתְיוּבְתָּא שְׁלֵימָתָא, הָא תַּקִּיף אִיהוּ, וְיִתְתַּקַּף בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא, כְּאִילּוּ לָא חָטָא.</p>\n<p>דְּהָא שִׁבְטִין, בְּגִין דְּחָטוּ עַל גְּנֵיבַת יוֹסֵף, הֲווּ דַּחֲלִין. דְּאִלְּמָלֵא לָא חָטוּ, לָא הֲווּ דָּחֲלִין כְּלַל. בְּגִין דְּחוֹבוֹי דְּבַר נָשׁ מְתַבְּרִין לִבֵּיהּ, וְלֵית לֵיהּ חֵילָא כְּלַל. מַאי טַעְמָא, דְּהָא הַהוּא יֵצֶר הַטּוֹב אִתְבַּר עִמֵּיהּ, וְלֵית לֵיהּ חֵילָא לְאִתְתַּקְּפָא עַל הַהוּא יֵצֶר הָרָע. וְעַל דָּא כְּתִיב, (דברים כ׳:ח׳) מִי הָאִישׁ הַיָּרֵא וְרַךְ הַלֵּבָב, הַיָּרֵא (דיראה דא) מֵחוֹבִין דְּבִידוֹי, דְּאִינוּן תְּבִירָא דְּלִבָּא דְּבַר נָשׁ.</p>\n<p>וְתָּא חֲזֵי, לְכַמָּה דָרִין אִתְפְּרַע קוּדְשָׁא בְּרִיךְ הוּא, מֵאִינוּן חוֹבִין דְּשִׁבְטִין, דְּהָא לָא אִתְאֲבִיד מִקַּמֵּיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא כְּלוּם. וְאִתְפְּרַע מִדָּרָא לְדָרָא, וְדִינָא קָיְימָא קַמֵּיהּ תָּדִיר, עַד דְּאִתְפְּרַע, וְשָׁרֵי דִינָא בְּאֲתַר דְּאִצְטְרִיךְ.</p>\n<p>מְנָלָן, מֵחִזְקִיָּהוּ. חִזְקִיָּהוּ חָב הַהוּא חוֹבָא, דְּגָלֵי סְתִירִין דְּקוּדְשָׁא בְּרִיךְ הוּא, לִשְׁאָר עַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, דְּלָא הֲוָה אִצְטְרִיךְ לְגַלָּאָה. וְקוּדְשָׁא בְּרִיךְ הוּא שַׁדַּר לֵיהּ לִישַׁעְיָהוּ, וְאָמַר לֵיהּ, (ישעיהו ל״ט:ו׳) הִנֵּה יָמִים בָּאִים וְנִשָּׂא כָּל אֲשֶׁר בְּבֵיתֶךָ וַאֲשֶׁר אָצְרוּ אֲבוֹתֶיךָ עַד הַיּוֹם הַזֶּה וְגו'.</p>\n<p>תָּא חֲזֵי, כַּמָּה גָרִים הַהוּא חוֹבָא, בְּגִין דְּגַלֵּי מַה דְּהֲוָה סָתִים. דְּכֵיוָן דְּאִתְגְּלֵי, אִתְיְיהִיב דּוּכְתָּא לְאֲתַר אָחֳרָא דְּלָא אִצְטְרִיךְ, לְשַׁלְּטָאָה עֲלֵיהּ. בְּגִין כָּךְ לָאו בְּרָכָה שַׁרְיָא, אֶלָּא בְּאֲתַר סָתִים. וְאוּקְמוּהָ, מַה דְּאִיהוּ (הוה) סָתִים, בְּרָכָה (דהוה) שַׁרְיָא עֲלוֹי, כֵּיוָן דְּאִתְגְּלֵי אִתְיְיהִיב דּוּכְתָּא, לְאֲתַר אָחֳרָא לְשַׁלְטָאָה עֲלוֹי.</p>\n<p>כְּתִיב, (איכה א׳:ח׳) כָּל מְכַבְּדֶיהָ הִזִּילוּהָ כִּי רָאוּ עֶרְוָתָהּ, וְאוּקְמוּהָ. אֲבָל כָּל מְכַבְּדֶיהָ הִזִּילוּהָ, דָּא הוּא מַלְכוּת בָּבֶל, דְּהָא מִתַּמָּן אִשְׁתַּדַּר דּוֹרוֹן לִיְרוּשְׁלֵם. דִּכְתִיב, (ישעיהו ל״ט:א׳) בָּעֵת הַהִיא שָׁלַח מְרוֹדָךְ בַּלְאֲדָן בֶּן בַּלְאֲדָן מֶלֶךְ בָּבֶל סְפָרִים וּמִנְחָה אֶל חִזְקִיָּהוּ.</p>\n<p>וּמַה כְּתִיב בְּהוּ, שְׁלָם לְחִזְקִיָהוּ מֶלֶךְ יְהוּדָה, וּשְׁלָם לֵאלָהָא רַבָּא וּשְׁלָם לִיְרוּשְׁלֵם. כֵּיוָן דְּנָפַק פִּתְקֵיהּ מִנֵּיהּ, אַהֲדַר לְלִבֵּיהּ וְאֲמַר, לָא יָאוֹת עָבְדִית לְאַקְדָּמָא שְׁלָמָא דְעַבְדָא, לִשְׁלָמָא דְמָארֵיהּ. קָם מִכּוּרְסְיֵהּ וּפָסַע ג' פְּסִיעָן וְאַהֲדַר פִּתְקֵיהּ, וְכָתַב אָחֳרָנִין תְּחוֹתַיְיהוּ, וְכָתַב הָכִי. שְׁלָם לֵאלָהָא רַבָּא, שְׁלָם לִיְרוּשָׁלַ ם, וּשְׁלָם לְחִזְקִיָּה, וְדָא הוּא מְכַבְּדֶיהָ.</p>\n<p><Nonei></i>וּלְבָתַר הִזִּילוּהָ, מַאי טַעְמָא הִזִּילוּהָ. בְּגִין כִּי רָאוּ עֶרְוָתָה, דְּאַחְזֵי לוֹן חִזְקִיָּה. דְּאִלְמָלֵא כָּךְ, לא הִזִּילוּהָ לְבָתַר. מִגּוֹ דְּהֲוָה זַכָּאָה חִזְקִיָּהוּ יַתִּיר, אִתְעַכַּב מִלָּה מִלְּאַיְיתָאָה, וְלָא אֲתָא בְּיוֹמוֹי. דִּכְתִיב, (ישעיהו ל״ט:ח׳) כִּי יִהְיֶה שָׁלוֹם וְאֱמֶת בְּיָמַי. וּלְבָתַר פַּקִּיד הַהוּא חוֹבָא לִבְנוֹי אַבַּתְרֵיהּ.</p>\n<p>כְּגַוְונָא דָא, הַהוּא חוֹבָא דְּשִׁבְטִין, קָאִים עַד לְבָתַר. בְּגִין דְּדִינָא דִלְעֵילָא, לָא יָכִיל לְשַׁלְּטָאָה עֲלַיְיהוּ, עַד דְּאִשְׁתַּכַּח שַׁעְתָּא לְאִתְפָּרְעָא, וְאִתְפְּרַע מִינַּיְיהוּ. וּבְּגִין כָּךְ כָּל מַאן דְּאִית חוֹבִין בִּידוֹי, דָּחִיל תָּדִיר. כְּמָה דְאַתְּ אָמֵר, (דברים כ״ח:ס״ו) וּפָחַדְתָּ לַיְלָה וְיוֹמָם וְגו'. וְעַל דָּא וַיִּירְאוּ הָאֲנָשִׁים כִּי הוּבְאוּ וְגו':</p>"],[9520011408,"<p>וַיִּשָּׂא עֵינָיו וַיַּרְא אֶת בִּנְיָמִין אָחִיו בֶּן אִמּוֹ וְגו'. רִבִּי חִיָּיא פָּתַח וְאֲמַר, (משלי י״ג:י״ב) תּוֹחֶלֶת מְמוּשָׁכָה מַחֲלָה לֵב וְעֵץ חַיִּים תַּאֲוָה בָאָה. דָּא הוּא דִּתְנַן, דְּלֵית לֵיהּ לְבַר נָשׁ לְאִסְתַּכָּלָא בְּבָעוּתֵיהּ לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא, אִי אָתֵי, אִי לָא אָתֵי. מַאי טַעְמָא, בְּגִין דְּאִי אִיהוּ אִסְתַּכֵּל בֵּיהּ, כַּמָּה מָארֵיהוֹן דְּדִינָא, אָתוּ לְאִסְתַּכָּלָא בֵּיהּ בְּעוֹבָדוֹי.</p>\n<p>וְרָזָא אִיהוּ, דְּהָא הַהוּא אִסְתַּכְּלוּתָא, דְּאִיהוּ מִסְתַּכֵּל בְּהַהוּא בָּעוּתָא, גָּרִים לֵיהּ לְמַחֲלַת לֵב. מַאי מַחֲלָה לֵב, דָּא אִיהוּ מַאן דְּקָאִים תָּדִיר עֲלֵיהּ דְּבַר נָשׁ, לְאַסְטָאָה לְעֵילָא וְתַתָּא.</p>\n<p>וְעֵץ חַיִּים תַּאֲוָה בָאָה. תָּנִינָן, מַאן דְּבָעֵי דְּקוּדְשָׁא בְּרִיךְ הוּא יְקַבֵּל צְלוֹתֵיהּ, יִשְׁתַּדַּל בְּאוֹרַיְיתָא, דְּאִיהִי עֵץ חַיִּים. וּכְדֵין תַּאֲוָה בָאָה. מַאן תַּאֲוָה, דָּא הוּא דַּרְגָּא דְּכָל צְלוֹתִין דְּעַלְמָא בִּידֵיהּ, וְעֲאִיל לוֹן קַמֵּי מַלְכָּא עִלָּאָה. כְּתִיב הָכָא בָאָה, וּכְתִיב הָתָם, (אסתר ב׳:י״ד) בָּעֶרֶב הִיא בָאָה. וְדָא הוּא תַּאֲוָה בָאָה, בָּאָה קַמֵּי מַלְכָּא עִלָּאָה, לְאַשְׁלָמָא רְעוּתָא דְהַהוּא בַּר נָשׁ.</p>\n<p>דָּבָר אַחֵר, תּוֹחֶלֶת מְמוּשָׁכָה מַחֲלָה לֵב, דָּא הוּא אֲתַר, דְּאִתְיְיהִיב הַהִיא מִלָּה, בְּאֲתַר אָחֳרָא דְּלָא אִצְטְרִיךְ. וְאִתְמַשְּׁכָא עַד דְּאִתְיְיהִיב מִיָּדָא לְיָדָא, וּלְזִמְנִין דְּלָא יִיִתֵי. מַאי טַעְמָא, בְּגִין דְּאִתְפַּשְּׁטָא וְאִתְמַשְּׁכָא בְּכָל אִינוּן מְמַנָּן, לְנַחֲתָא לֵיהּ לְעַלְמָא.</p>\n<p>וְעֵץ חַיִּים תַּאֲוָה בָאָה, דָּא הוּא תּוֹחֶלֶת, דְּלָא אִתְמַשְּׁכָא, בְּגִין אִינוּן מְמַנָּן רְתִיכִין, אֶלָּא דְּקוּדְשָׁא בְּרִיךְ הוּא יָהִיב (לון) לֵיהּ לְאַלְתָּר. בְּגִין דְּכַד אִתְמַשְּׁכָא בֵּין אִינוּן מְמַנָּן רְתִיכִין, כַּמָּה אִינוּן מָארֵיהוֹן דְּדִינָא דְּאִתְיְיהִיב לוֹן רְשׁוּתָא. לְעַיְינָא וּלְאִסְתַּכְּלָא בְּדִינֵיהּ, עַד לָא יִנָּתְנוּן לֵיהּ. וּמַה דְּנָפִיק מִבֵּי מַלְכָּא וְאִתְיְיהִיב לֵיהּ לְבַר נָשׁ, בֵּין דְּזָכֵי, בֵּין דְּלָא זָכֵי, אִתְיְיהִיב מִיָּד. וְדָא הוּא עֵץ חַיִים תַּאֲוָה בָאָה.</p>\n<p>דָּבָר אַחֵר, תּוֹחֶלֶת מְמוּשָׁכָה, דָּא יַעֲקֹב. דְּאִתְמַשְּׁכָא לֵיהּ תּוֹחַלְתָּא דְיוֹסֵף עַד זְמַן אָרִיךְ. וְעֵץ חַיִּים תַּאֲוָה בָאָה, דָּא הוּא בִּנְיָמִן. דְּהָא מִזִּמְנָא דְּתָבַע לֵיהּ יוֹסֵף, עַד הַהוּא זִמְנָא דְּאָתָא לְגַבֵּיהּ, לָא הֲוָה אֶלָּא זִמְנָא זְעֵיר. דְּלָא אִתְמַשְּׁכָא הַהוּא זִמְנָא. הֲדָא הוּא דִכְתִיב, וַיִּשָּׂא עֵינָיו וַיַּרְא אֶת בִּנְיָמִין אָחִיו בֶּן אִמּוֹ. מַאי בֶּן אִמּוֹ. דְּדִיוּקְנֵיהּ דְּאִמֵּיהּ הֲוָה בֵּיהּ, וְהֲוָה דָמֵי דִּיוּקְנֵיהּ לְדִיוּקְנָא דְּרָחֵל. בְגִין כָּךְ כְּתִיב, וַיִּשָּׂא עֵינָיו וַיַּרְא אֶת בִּנְיָמִן אָחִיו בֶּן אִמּוֹ.</p>\n<p>רִבִּי יוֹסֵי אָמַר, וְהָא כְּתִיב בְּקַדְמִיתָא, וַיַּרְא יוֹסֵף אִתָּם אֶת בִּנְיָמִן. וְהַשְׁתָּא כְּתִיב, וַיִּשָּׂא עֵינָיו וַיַּרְא אֶת בִּנְיָמִין אָחִיו. מַאי רְאִיָה הָכָא. אֶלָּא חָמָא בְּרוּחָא דְקוּדְשָׁא לְבִנְיָמִן, דְּחוּלָקֵיהּ הֲוָה עִמְּהוֹן בְּאַרְעָא. וּבְחוּלָקֵיהּ דְּבִנְיָמִן וִיהוּדָה תִּשְׁרֵי שְׁכִינְתָא. דְּהָא חָמָא לֵיהּ לִיהוּדָה וּבִנְיָמִן, דִּבְחוּלְקֵהוֹן הֲוָה מַקְדְּשָׁא. וְדָא הוּא וַיַּרְא יוֹסֵף אִתָּם אֶת בִּנְיָמִן. לֵיהּ חָמָא עִמְּהוֹן, וְיוֹסֵף דְּהֲוָה אֲחוּהָ לָא חָמָא עִמְּהוֹן בְּהַהוּא חוּלָקָא.</p>\n<p>אוּף הָכָא, וַיִּשָּׂא עֵינָיו וַיַּרְא אֶת בִּנְיָמִין אָחִיו בֶּן אִמּוֹ. מַה כְּתִיב בַּתְרֵיהּ. וַיְמַהֵר יוֹסֵף כִּי נִכְמְרוּ רַחֲמָיו אֶל אָחִיו וַיְבַקֵּשׁ לִבְכּוֹת וַיָּבֹא הַחַדְרָה וַיֵּבְךִ שָׁמָּה.</p>\n<p>רִבִּי חִזְקִיָּה פָּתַח וְאֲמַר, (ישעיהו כ״ב:א׳) מַשָּׂא גֵיא חִזָּיוֹן מַה לָּךְ אֵיפֹה כִּי עָלִית כֻּלָּךְ לַגַּגּוֹת. תָּא חֲזֵי, הָא אוּקְמוּהָ בְּזִמְנָא דְּאִתְחָרִיב בֵּי מַקְדְּשָׁא, וְהָיוּ מוֹקְדִין לֵיהּ בְּנוּרָא, סְלִיקוּ כָּל אִינוּן כַּהֲנֵי <Nonei></i>עַל כּוֹתְלֵיהוֹן (נ\"א גגיהון) דְּמַקְדְּשָׁא, וְכָל מַפְתֵּחִין בִּידַיְיהוּ, וְאָמְרוּ. עַד הָכָא הֲוֵינָא גִזְבָּרִין דִּילָךְ, מִכָּאן וָאֵילָךְ טוֹל דִּילָךְ.</p>\n<p>אֲבָל תָּא חֲזֵי, גֵּיא חִזָּיוֹן, דָּא שְׁכִינְתָּא דְּהֲוַת בְּמַקְדְּשָׁא. וְכָל בְּנֵי עַלְמָא, מִינָהּ הֲווּ יָנְקִין יְנִיקוּ דִּנְבוּאָה. דְּאַף עַל גַּב דְּכָל נְבִיאִין, קָא הֲווּ מִתְנַבְּאִין מֵאֲתַר אָחֳרָא, מִגַּוָּוהּ הֲווּ יָנְקִין נְבוּאַתְהוֹן. וְעַל דָּא אִתְקְרֵי אִיהִי גֵּיא חִזָּיוֹן. חִזָּיוֹן, הָא אוּקְמוּהָ, דְאִיהוּ חֵיזוּ דְּכָל גְּוָונִין עִלָּאִין.</p>\n<p>מַה לָּךְ אֵיפֹה כִּי עָלִית כֻּלָּךְ לַגַּגּוֹת, דְּהָא כַּד אִתְחָרַב מַקְדְּשָׁא, שְׁכִינְתָּא אָתָאת, וּסְלִיקַת בְּכָל אִינוּן אַתְרִין, דְּהֲוָה מְדוֹרָהּ בְּהוּ בְּקַדְמִיתָא. וַהֲוַת בָּכַת עַל בֵּית מְדוֹרָהּ, וְעַל יִשְׂרָאֵל דְּאֲזְלוּ בְּגָלוּתָא, וְעַל כָּל אִינוּן צַדִּיקֵי וַחֲסִידֵי דְּהֲווּ תַּמָּן וְאִתְאֲבִידוּ. וּמְנָלָן, דִּכְתִיב, (ירמיהו ל״א:ט״ו) כֹּה אָמַר יְיָ קוֹל בְּרָמָה נִשְׁמָע נְהִי בְּכִי תַמְרוּרִים רָחֵל מְבַכָּה עַל בָּנֶיהָ, וְהָא אִתְּמָר. וּכְדֵין קוּדְשָׁא בְּרִיךְ הוּא שָׁאִיל לָהּ לִשְׁכִינְתָּא, וְאָמַר לָהּ. מַה לָּךְ אֵיפֹה כִּי עָלִית כֻּלָּךְ לַגַּגּוֹת.</p>\n<p>מַהוּ כֻּלָּךְ, דְּהָא כִּי עָלִית סַגְיָא, מַהוּ כֻּלָּךְ. לְאַכְלָלָא בַּהֲדָהּ כָּל חֵילִין וְכָל רְתִיכִין אָחֳרָנִין, דְּכֻלְּהוּ בְּכוּ עִמָּהּ עַל חֻרְבַּן בֵּי מַקְדְּשָׁא.</p>\n<p>וּבְגִין כָּךְ, מַה לָּךְ אֵיפֹה. אָמְרָה קַמֵּיהּ, וְכִי בָּנַי בְּגָלוּתָא, וּמַקְדְּשָׁא אִתּוֹקְדָא, וְאֲנָא מַה לִּי הָכָא. שָׁרִיאַת וְאֲמְרַת, (ישעיהו כ״ב:ב׳) תְּשׁוּאוֹת מְלֵאָה עִיר הוֹמִיָּה קִרְיָה עַלִּיזָה חֲלָלַיִךְ לא חַלְלֵי חֶרֶב וְלֹא מֵתֵי מִלְחָמָה עַל כֵּן אָמַרְתִּי שְׁעוּ מִנִּי אֲמָרֵר בַּבֶּכִי וְגו'. וְהָא אוֹקִימְנָא, דְּקוּדְשָׁא בְּרִיךְ הוּא אָמַר לָהּ, (ירמיהו ל״א:ט״ז) כֹּה אָמַר יְיָ מִנְעִי קוֹלֵךְ מִבֶּכִי וְגו'.</p>\n<p>וְתָּא חֲזֵי, מִיּוֹמָא דְּאִתְחָרִיב בֵּי מַקְדְּשָׁא, לָא הֲוָה יוֹמָא דְּלָא אִשְׁתַּכַּח בֵּיהּ לְוָוטִין. בְּגִין דְּכַד בֵּי מַקְדְּשָׁא הֲוָה קַיָּים, הֲווּ יִשְׂרָאֵל פָּלְחִין פּוּלְחָנִין וְקָרְבִין עִלַּוָּון וְקָרְבָּנִין, וּשְׁכִינְתָּא שַׁרְיָא בְּבֵי מַקְדְּשָׁא עֲלַיְיהוּ, כְּאִמָּא דִּרְבִיעָא עַל בְּנַיָיא. וְהֲווּ כָּל אַנְפִּין נְהִירִין, עַד דְּאִשְׁתַּכָּחוּ בִּרְכָאן לְעֵילָא וְתַתָּא. וְלָא הֲוָה יוֹמָא, דְּלָא אִשְׁתַּכַּח בֵּיהּ בִּרְכָאן וְחֶדְוָון. וְהֲווּ יִשְׂרָאֵל שָׁרָאן לְרָחֲצָן בְּאַרְעָא, וְכָל עַלְמָא הֲוָה אִתְּזָן בְּגִינַיְיהוּ.</p>\n<p>הַשְׁתָּא דְּאִתְחָרִיב בֵּי מַקְדְּשָׁא, וּשְׁכִינְתָּא עִמְּהוֹן בְּגָלוּתָא, לֵית לָךְ יוֹמָא דְּלָא אִשְׁתַּכַּח בֵּיהּ לְוָוטִין, וְעַלְמָא אִתְלַטְיָא. וְחֶדְוָון לָא אִשְׁתַּכָּחוּ לְעֵילָא וְתַתָּא.</p>\n<p>וְזַמִּין קוּדְשָׁא בְּרִיךְ הוּא, לְאֲקַמָא לָהּ לִכְנְסֶת יִשְׂרָאֵל מֵעַפְרָא, כְּמָה דְאִתְּמָר. וּלְמֶחֱדֵי עַלְמָא בְּכֹלָּא. כְּמָה דְאַתְּ אָמֵר, (ישעיהו נ״ו:ז׳) וַהֲבִיאוֹתִים אֶל הַר קָדְשִׁי וְשִׂמַּחְתִּים בְּבֵית תְּפִלָּתִי וְגו'. וּכְתִיב, (ירמיהו ל״א:ט׳) בִּבְכִי יָבוֹאוּ וּבְתַחֲנוּנִים אוֹבִילֵם. כְּמָה דִּבְקַדְמִּיתָא, דִּכְתִיב, (איכה א׳:ב׳) בָּכֹה תִבְכֶּה בַּלַּיְלָה וְדִמְעָתָהּ עַל לֶחיָהּ. הָכִי נָמֵי לְבָתַר, בִּבְכִי יִתְהַדְּרוּן. דִּכְתִיב, בִּבְכִי יָבֹאוּ וְגו':</p>"],[9520011409,"<p>הַבֹּקֶר אוֹר וְהָאֲנָשִׁים שֻׁלְּחוּ הֵמָּה וַחֲמוֹרֵיהֶם, רִבִּי אֶלְעָזָר אָמַר, הָכָא אִית לְאִסְתַּכָּלָא, אִי אִינוּן הֲווּ אָזְלֵי וְאִשְׁתַּדָּרוּ, מַה לָּן לְמִכְתַּב בְּאוֹרַיְיתָא, הֵמָּה וַחֲמוֹרֵיהֶם. אֶלָּא בְּגִין דִּכְתִיב וְלָקַחַת אוֹתָנוּ לַעֲבָדִים וְאֶת חֲמוֹרֵינוּ, בְּגִין כָּךְ וְהָאֲנָשִׁים שֻׁלְּחוּ הֵמָּה וַחֲמוֹרֵיהֶם. בְּגִין דְּלָא יִשְׁתָּאֲרוּן אִינוּן וַחֲמוֹרֵיהוֹן, כִּדְקָאֲמְרוּ.</p>\n<p>פָּתַח וְאֲמַר, (בראשית כ״ב:ג׳) וַיַּשְׁכֵּם אַבְרָהָם בַּבֹּקֶר וַיַּחֲבשׁ אֶת חֲמוֹרוֹ וְגו', הַהוּא בֹּקֶר דְּאַבְרָהָם הֲוָה נָהִיר, לְקַיְימָא עֲלַיְיהוּ בִּזְכוּתֵיהּ. כְּדֵין זְכוּתָא דְאַבְרָהָם קָיְימָא עֲלַיְיהוּ, וְאֲזְלוּ בִּשְׁלָם, וְאִשְׁתְּזִיבוּ מִן דִּינָא. בְּגִין דְּהַהִיא שַׁעְתָּא, קָיְימָא עֲלַיְיהוּ דִינָא, לְאִתְפָּרְעָא מִנַּיְיהוּ. בַּר דִּזְכוּתָא דְּהַהוּא בֹּקֶר דְּאַבְרָהָם, אָגִין עֲלַיְיהוּ. וְאִשְׁתַּלָּחוּ מִן דִּינָא, דְּלָא שַׁלִּיט עֲלַיְיהוּ בְּהַהוּא זִמְנָא.</p>\n<p>רִבִּי יְהוּדָה פָּתַח, (שמואל ב כ״ג:ד׳) וּכְאוֹר בֹּקֶר יִזְרַח שֶׁמֶשׁ. דָּא הוּא נְהוֹרָא, דְּהַהוּא בֹּקֶר דְּאַבְרָהָם. יִזְרַח שֶׁמֶשׁ, דָּא הוּא שִׁמְשָׁא דְיַעֲקֹב. דִּכְתִיב, (בראשית לכ) וַיִּזְרַח לוֹ הַשֶּׁמֶשׁ. בֹּקֶר לֹא עָבוֹת, דְּהַהוּא בֹּקֶר לָא אִיהוּ עָבוֹת כָּל כָּךְ, אֶלָּא מִנֹּגַהּ מִמָּטָר. נֹגַהּ מִמָּטָר, אִיהוּ מִטְּרָא דְּאָתֵי מִסִּטְרָא דְיִצְחָק, דְּהַהוּא מִטְרָא אַפִּיק דֶּשֶׁא מֵאָרֶץ.</p>\n<p>דָּבָר אַחֵר, וּכְאוֹר בֹּקֶר, בְּהַהוּא נְהִירוּ דְּבֹקֶר דְּאַבְרָהָם. <Nonei></i>יִזְרַח שֶׁמֶשׁ, דָּא הוּא יַעֲקֹב. דִּנְהִירוּ דִילֵיהּ, כִּנְהִירוּ דְּהַהוּא בֹּקֶר. בֹּקֶר לֹא עָבוֹת, בְּגִין דְּהַהוּא בֹּקֶר, לָאו אִיהוּ חָשׁוּךְ, אֶלָּא נָהִיר. דְּהָא בְּשַׁעְתָּא דְּאָתֵי בֹּקֶר, לָא שָׁלְטָא דִינָא כְּלַל. אֶלָּא כֹּלָּא נָהִיר, בְּסִטְרָא דְאַבְרָהָם. מִנֹּגַהּ מִמָּטָר, דָּא הוּא סִטְרָא דְיוֹסֵף הַצַּדִּיק, דְּאִיהוּ אַמְטִיר עַל אַרְעָא, לְאֲפָקָא דִשְׂאָה, וְכָל טִיבוּ דְעָלְמָא.</p>\n<p>אָמַר רִבִּי שִׁמְעוֹן, תָּא חֲזֵי, בְּשַׁעְתָּא דְּלֵילְיָא עָאל, וּפָרִישׂ גַּדְפוֹי עַל עַלְמָא, כַּמָּה גַּרְדִּינֵי טְהִירִין, זְמִינִין לְנַפְקָא, וּלְשַׁלְּטָאָה בְּעַלְמָא. וְכַמָּה מָארֵיהוֹן דְּדִינִין, מִתְעָרִין בְּכַמָּה סִטְרִין לִזְנַיְיהוּ, וְשָׁלְטֵי עַל עַלְמָא. כֵּיוָן דְּאָתֵי צַפְרָא וְנָהִיר, כֻּלְּהוּ מִסְתַּלְּקֵי, וְלָא שָׁלְטֵי, וְכָל חַד וְחַד עָאל לְדוּכְתֵּיהּ, וְתָב לְאַתְרֵיהּ.</p>\n<p>כְּמָה דְאַתְּ אָמֵר, הַבֹּקֶר אוֹר, דָּא בֹּקֶר דְּאַבְרָהָם. וְהָאֲנָשִׁים שֻׁלְּחוּ, אִלֵּין מָארֵיהוֹן דְּדִינָא, דְּהֲווּ שָׁלְטִין בְּלֵילְיָא. הֵמָּה וַחֲמוֹרֵיהֶם (ס\"א המה אינון מאריהון דדינא דקאמרן, וחמוריהם) אִינוּן גַּרְדִּינֵי נִימוּסִין, דְּאַתְיָין מִסִּטְרָא דִּמְסָאֲבָא. דְּלָאו אִינוּן קַדִּישִׁין, וְלָא שָׁלְטִין, וְלָא אִתְחֲזוּן מֵכִי אָתֵי צַפְרָא. וְאִינוּן מִסִּטְרָא דְּאִינוּן חֲמָרִי, גַּרְדִּינִי נִימוּסִין דְקָאֲמְרוּ.</p>\n<p>דְּהָא לֵית לָךְ דַּרְגִּין עִלָּאִין. דְּלָא אִיתָאי (אית) בְּהוּ יְמִינָא וּשְׂמָאלָא, רַחֲמֵי וְדִינָא. דַּרְגִּין עַל דַּרְגִּין קַדִּישִׁין, מִסִּטְרָא דִּקְדוּשָּׁה. וּמְסָאֲבִין, מִסִּטְרָא דִּמְסָאֲבָא. וְכֻלְּהוּ דַּרְגִּין עַל דַּרְגִּין, אִלֵּין עַל אִלֵּין.</p>\n<p>וּבְכָל אֲתַר דְּבֹקֶר דְּאַבְרָהָם אִתְעַר בְּעַלְמָא, כֻּלְּהוּ מִתְעַבְרֵי, וְלָא שָׁלְטֵי. בְּגִין דְּלֵית לוֹן (ז\"ח קיומא) לְקָיְימָא בִּסְטַר יְמִינָא, אֶלָּא בִּסְטַר שְׂמָאלָא. וְקוּדְשָׁא בְּרִיךְ הוּא עָבַד יְמָמָא וְלֵילְיָא, לְאַנְהָגָא כָּל חַד וְחַד לְסִטְרֵיהּ כְּדְקָא חָזֵי לֵיהּ. זַכָּאָה חוּלָקֵיהוֹן דְּיִשְׂרָאֵל, בְּעַלְמָא דֵין, וּבְעַלְמָא דְאָתֵי.</p>\n<p>רִבִּי חִיָּיא פָּתַח וְאֲמַר, (מלאכי ג׳:כ׳) וְזָרְחָה לָכֶם יִרְאֵי שְׁמִי שֶׁמֶשׁ צְדָקָה וּמַרְפֵּא בִּכְנָפֶיהָ. תָּא חֲזֵי, זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאַנְהָרָא לוֹן לְיִשְׂרָאֵל, הַהוּא שִׁמְשָׁא, דְּגָנִיז קוּדְשָׁא בְּרִיךְ הוּא, מִיּוֹמָא דְּאִתְבְּרֵי עַלְמָא. (דגניז קודשא בריך הוא) מִקַּמֵּי רַשִּׁיעֵי דְעַלְמָא. כְּמָה דִּכְתִיב, (איוב ל״ח:ט״ו) וַיִּמְנַע מֵרְשָׁעִים אוֹרָם.</p>\n<p>וְהַהוּא נְהוֹרָא גָּנִיז לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא. דְּכַד נָפַק בְּקַדְמִיתָא, הֲוָה נָהִיר מִסְּיָיפֵי עַלְמָא, וְעַד סְיָיפֵי עַלְמָא. כֵּיוָן דְּאִסְתַּכַּל בְּדָרֵיהּ דֶּאֱנוֹשׁ וּבְדָרֵיהּ דְּמַבּוּל. וּבְדָרֵיהּ דְּהַפְלָגָה, וּבְכָל אִינוּן חַיָּיבַיָא. גָּנִיז לֵיהּ לְהַהוּא נְהוֹרָא.</p>\n<p>כֵּיוָן דְּאָתָא יַעֲקֹב, וְאִתְדָּבַּק בְּהַהוּא מְמַנָּא רַבְרְבָא דְעֵשָׂו, וְאַכִּישׁ לֵיהּ בְּיַרְכָא דִילֵיהּ, וְהֲוָה נָכֵי. כְּדֵין מַה כְּתִיב, וַיִּזְרַח לוֹ הַשֶּׁמֶשׁ, מַאן שֶׁמֶשׁ, הַהוּא שִׁמְשָׁא דְגָנֵיז. בְּגִין דְּאִית בֵּיהּ אֲסוּתָא, לְאִתְּסָאָה לֵיהּ מֵאַרְכּוּבָתֵיהּ, וּלְבָתַר אִתְּסֵי בְּהַהוּא שִׁמְשָׁא. דִּכְתִיב, (בראשית ל״ג:י״ח) וַיָּבֹא יַעֲקֹב שָׁלֵם, שָׁלֵם בְּגוּפֵיהּ דְּאִתְּסֵי.</p>\n<p>וְעַל דָּא, זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְגַלָּאָה הַהוּא שִׁמְשָׁא, וּלְאַנְהָרָא לֵיהּ לְיִשְׂרָאֵל. דִּכְתִיב, וְזָרְחָה לָכֶם יִרְאֵי שְׁמִי שֶׁמֶשׁ צְדָקָה, מַאי שֶׁמֶשׁ צְדָקָה. דָּא שִׁמְשָׁא דְּיַעֲקֹב, דְּאִתְּסֵי בֵּיהּ. וּמַרְפֵּא בִּכְנָפֶיהָ, דְּהַהוּא שִׁמְשָׁא, יִתְּסוּן כֻּלְּהוּ. בְּגִין דְּהָא בְּזִמְנָא דִּיקוּמוּן יִשְׂרָאֵל מֵעַפְרָא, כַּמָּה חִגְרִין וְכַמָּה סוּמִין יְהוֹן בְּהוֹן. וּכְדֵין קוּדְשָׁא בְּרִיךְ הוּא יַנְהִיר לוֹן הַהוּא שִׁמְשָׁא לְאִתְּסָאָה בָּהּ. דִּכְתִיב וּמַרְפֵּא בִּכְנָפֶיהָ.</p>\n<p>וּכְדֵין, יִתְנְהִיר הַהוּא שִׁמְשָׁא, מִסְּיְיפֵי עַלְמָא, עַד סְיָיפֵי עַלְמָא. וּלְיִשְׂרָאֵל יְהֵא אַסְוָותָא, וְעַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת בֵּיהּ יִתּוֹקְדוּן. אֲבָל לְיִשְׂרָאֵל מַה כְּתִיב, (ישעיהו נ״ח:ח׳) אָז יִבָּקַע כַּשַּׁחַר אוֹרֶךָ וַאֲרֻכָתְךָ מְהֵרָה תִצְמָח וְהָלַךְ לְפָנֶיךָ צִדְקֶךָ כְּבוֹד יְיָ יַאַסְפֶךָ.</p>"],[9520011410,"<p>אַהֲדַרְנָא לְמִילֵי קַדְמָאֵי: וּלְיוֹסֵף יֻלָּד שְׁנִי בָנִים בְּטֶרֶם תָּבוֹא שְׁנַת הָרָעָב וְגו'. רִבִּי יִצְחָק פָּתַח, (מיכה ה׳:ו׳) וְהָיָה שְׁאֵרִית יַעֲקֹב בַּגּוֹיִם בְּקֶרֶב עַמִּים רַבִּים כְּטַל מֵאֵת יְיָ כִּרְבִיבִים עֲלֵי עֵשֶׂב אֲשֶׁר לֹא יְק1ַוְּה לְאִישׁ וְלֹא יְיַחֵל לִבְנֵי אָדָם. תָּא חֲזֵי, בְּכָל יוֹמָא וְיוֹמָא, כַּד נְהוֹרָא סָלְקָא. אִתְעַר חַד צִיפֳּרָא בְּאִילָנָא דְּגִנְתָא דְעֵדֶן, וְקָרֵי תְּלַת זִמְנִין. וְשַׁרְבִיטָא יִזְדָּקַּף, וְכָרוֹזָא קָרֵי בְחָיִל, לְכוֹן אָמְרִין, הוּרְמָנִי דְּבוֹרְיָירֵי. מַאן מִנְּכוֹן דְּחָמֵי וְלָא חָמֵי. דְּקָיְימָא בְּעַלְמָא, וְלָא יָדְעֵי עַל מַה קָּיְימֵי, לָא מַשְׁגִּיחִין בִּיקָרָא דְמָארֵיהוֹן. <Nonei></i>אוֹרַיְיתָא קָיְימָא קַמַּיְיהוּ, וְלָא מִשְׁתַּדְּלֵי בָהּ. טַב לוֹן דְּלָא יִבָּרוּן, עַל מַה יְּקוּמוּן בְּלָא סָכְלְתָנוּ. וַוי לוֹן כַּד יִתְעָרוּן יוֹמֵי דְרַע עֲלַיְיהוּ, וְיִטְרְדוּן לְהוֹן מֵעָלְמָא.</p>\n<p>מַאן אִינוּן יוֹמִין דְּרַע, אִי סַלְקָא דַעְתָּךְ דְּאִינוּן יוֹמֵי דְּסִיבוּ, לָאו הָכִי. דְּהָא יוֹמֵי דְסִיבוּ, אִי זָכָה בִּבְנִין וּבְנִי בְנִין, יוֹמֵי דְטַב אִינוּן. מַאן אִינוּן יוֹמִין דְּרַע,</p>\n<p>אֶלָּא אִינוּן כְּמָה דְאִתְּמָר. דִּכְתִיב, (קהלת י״ב:א׳) וּזְכוֹר אֶת בּוֹרְאֶךָ בִּימֵי בְחוּרוֹתֶיךָ עַד אֲשֶׁר לֹא יָבֹאוּ יְמֵי הָרָעָה, לָאו אִינוּן יוֹמִין דְּסִיבוּ. אֶלָּא רָזָא דְמִלָּה, כַּד בָּרָא קוּדְשָׁא בְּרִיךְ הוּא עַלְמָא, בָּרָא לֵיהּ בְּאַתְוָון דְּאוֹרַיְיתָא. וְכָל אָת וְאָת עָאֳלַת קַמֵּיהּ, עַד דְּאִתְקָיְימוּ כֻּלְּהוּ אַתְוָון בְּאָת בֵי\"ת. וְכָל אִינוּן אַלְפָא בֵּיתוֹת דְּאִתְגַּלְגְּלוּ אַתְוָון, כֻּלְּהוּ קָיְימֵי (כלהו) לְמִבְרִי עָלְמָא.</p>\n<p>כֵּיוָן דְּאִתְגַּלְגְּלוּ וְאִתְחַבָּרוּ תְּרֵין אַתְוָון אִלֵּין ט\"ר כְּחֲדָא, סַלְקָא טי\"ת וְלָא אִתְיַישְׁבַת, עַד דְּגָעַר בָּהּ קוּדְשָׁא בְּרִיךְ הוּא. וְאָמַר לָהּ, טי\"ת טי\"ת, עַל מָה אַתְּ סָלְקָא וְלָא אִתְיַישְׁבַת בְּדוּכְתִּיךְ. אָמְרָה קַמֵּיהּ. וְכִי עָבְדַת לִי לְמֶהוֵי אָת בְּרֵישָׁא דְטוֹב, דְּהָא אוֹרַיְיתָא פָּתַח בִּי כִּי טוֹב. הֵיךְ אֲנָא מִתְחַבְּרָא לְאִתְיַישְׁבָא בְּאָת רַע.</p>\n<p>אָמַר לָהּ, תּוּב לְאַתְרִיךְ, דְּהָא אַתְּ צָרִיךְ לָהּ. דְּהָא בַר נָשׁ דְּאֲנָא בָּעֵי לְמִבְרֵי בְּכוֹן, תַּרְוַויְיכוּ אִתְכְּלִיל כְּחֲדָא, וְיִתְבְּרֵי. אֲבָל אַתְּ לִימִינָא, וְאִיהִי לִשְׂמָאלָא. וּכְדֵין תָּבוּ וְאִתְיַישְׁבוּ דָּא בְּדָא כְּחֲדָא.</p>\n<p>בְּהַהִיא שַׁעְתָּא פָּרִישׁ לוֹן קוּדְשָׁא בְּרִיךְ הוּא, וּבָרָא לוֹן לְכָל חַד וְחַד, יוֹמִין וּשְׁנִין יְדִיעָן. אִלֵּין לִימִינָא וְאִלֵּין לִשְׂמָאלָא. אִלֵּין דְּיָמִינָא, אִתְקְרוּן יְמֵי הַטּוֹב, וְאִלֵּין דִּשְׂמָאלָא אִתְקְרוּן יְמֵי הָרָעָה. וְעַל דָּא אָמַר שְׁלמֹה, עַד אֲשֶׁר לֹא יָבֹאוּ יְמֵי הָרָעָה. דְּאִלֵּין מְסַחֲרִין לֵיהּ לְבַר נָשׁ בְּחוֹבוֹי דְּאִיהוּ עָבִיד. כֵּיוָן דְּאִתְבְּרוּן יוֹמִין דְּטוֹב, וְיוֹמִין דְּרַע, כְּדֵין תָּבוּ וְאִתְיַישְׁבוּ, לְאִתְכְּלָלָא בְּהוּ בְּבַר נָשׁ.</p>\n<p>וּבְגִינֵי כָךְ אָמַר דָּוִד, (תהילים מ״ט:ו׳) לָמָּה אִירָא בִּימֵי רָע עֲוֹן עֲקֵבַי יְסֻבֵּנִי. יְמֵי רָע וַדַּאי. וְרָזָא דָא, אִלֵּין אִקְרוּן יְמֵי רָעָב, שְׁנִין דְּרָעָב, וְאִלֵּין אִקְרוּן יְמֵי שָׂבָע, שְׁנֵי שָׂבָע.</p>\n<p>וְרָזָא דְמִלָּה, דְּלָא לְאֲפָקָא מַבּוּעָא דִּבְרִית קַדִּישָׁא, בְּיוֹמֵי רָעָב, בִּשְׁנַת הָרָעָב. וּבְגִין כָּךְ יוֹסֵף דְּאִיהוּ רָזָא דִבְרִית, סָתִים מַבּוּעֵיהּ בִּשְׁנַת הָרָעָב. וְלָא יָהַב לֵיהּ דּוּכְתָּא לְאַסְגָּאָה בְּעַלְמָא. וְדָא בָּעֵי לֵיהּ לְבַר נָשׁ, דְכַד שָׁלְטָא שְׁנַת הָרָעָב, דְּיַסְתִּים מַבּוּעָא דִּבְרִית קַדִּישָׁא דִילֵיהּ. בְּגִין דְּלָא יָהַב לֵיהּ דּוּכְתָּא לְאַסְגָּאָה בְּעַלְמָא.</p>\n<p>רִבִּי שִׁמְעוֹן אָמַר, רָזָא דָא אִיהוּ רָזָא עִלָּאָה. בְּהַהִיא שְׁנַת הָרָעָב, כֵּיוָן דְּאִיהִי שָׁלְטָא, בָּעֵי לְאַסְתָּמָא מַבּוּעֵיהּ. בְּגִין דְּאִי לָא סָתִים לֵיהּ, גָּרִים לְאַמְשָׁכָא רוּחָא לְהַהוּא וַלְדָא מֵהַהוּא סִטְרָא. וְיָהִיב דּוּכְתָּא לְהַהוּא סִטְרָא לְמִפְשֵׁי בְּעַלְמָא, סִטְרָא דִּמְסָאֲבָא בְּסִטְרָא דְּקוּדְשָׁא. וְתוּ רָזָא, דִּכְתִיב, (משלי ל׳:כ״א) תַּחַת שָׁלשׁ רָגְזָה אֶרֶץ וְגו'.</p>\n<p>וּבְּגִין כָּךְ יוֹסֵף צַדִּיקָא, רָזָא דִבְרִית, סָלִיק וְסָתִים מַבּוּעֵיהּ, בִּשְׁנַת הָרָעָב. דְּלָא לְאִתְעָרְבָא בַּהֲדָהּ כְּלַל, וּלְמֵיהַב לָהּ דּוּכְתָּא. וּמַאן דְּאַפְתַּח מַבּוּעֵיהּ בְּהַהוּא זִמְנָא, עֲלֵיהּ כְּתִיב, (הושע ה׳:ז׳) בַּיְיָ בָּגָדוּ כִּי בָנִים זָרִים יָלָדוּ עַתָּה יֹאכְלֵם וְגו'. דְּהָא אִלֵּין אִקְרוּן בָּנִים זָרִים וַדַּאי. בַּיְיָ בָּגָדוּ וַדַּאי. וּבְּגִין כָּךְ זַכָּאָה חוּלַקְהוֹן דְּיִשְׂרָאֵל קַדִּישִׁין, דְּלָא אִתְחַלְּפוּ דּוּכְתָּא קַדִּישָׁא, בְּדוּכְתָּא מְסָאֲבָא.</p>\n<p>וְעַל דָּא כְּתִיב, וּלְיוֹסֵף יֻלָּד שְׁנִי בָנִים בְּטֶרֶם תָּבוֹא שְׁנַת הָרָעָב. דְּהָא מֵהַהוּא זִמְנָא דְּשָׁלְטָא שְׁנַת הָרָעָב, אַסְתִּים מַבּוּעֵיהּ וְסָלִיק מְקוֹרֵיהּ, דְּלָא לְמֵיהַב בְּנִין לְסִטְרָא מְסָאֲבָא, וְלָא לְאַחְלָפָא דּוּכְתָּא דְּקוּדְשָׁא, בְּדוּכְתָּא דִּמְסָאֲבָא. וּבָעֵי בַר נָשׁ לְחַכָּאָה לְמָארֵיהּ דְּקוּדְשָׁא, כַּד יֵיתֵי וְיִשְׁלוֹט, כְּדִכְתִיב, (ישעיהו ח׳:י״ז) וְחִכֵּיתִי לַיְיָ הַמַּסְתִּיר פָּנָיו מִבֵּית יַעֲקֹב וְקִוִּיתִי לוֹ.</p>\n<p>זַכָּאִין אִינוּן צַדִּיקַיָא, דְּיָדְעִין אוֹרְחוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא, וְנָטְרֵי פִּקּוּדֵי דְּאוֹרַיְיתָא לְמֵיהַךְ בְּהוּ. דִּכְתִיב, (הושע י״ד:י׳) כִּי יְשָׁרִים דַּרְכֵי יְיָ וְצַדִּיקִים יֵלְכוּ בָם וּפשְׁעִים יִכָּשְׁלוּ בָם. וּכְתִיב, (דברים ד׳:ד׳) וְאַתֶּם הַדְּבֵקִים בַּיְיָ אֱלהֵיכֶם חַיִּים כֻּלְּכֶם הַיּוֹם. (ד\"א ל\"ג דכתיב והתקדשתם והייתם קדושים כי קדוש אני (יי). דהא, קודשא בריך הוא בעא לקדשא להו לישראל בכלא ולא יהא לון בסטרא דמסאבא כלום) (תא חזי כד סטרא דא שלטא בעלמא לא אצטריך ליה לבר נש לאתחזאה בשוקא קמיה בגין דיכיל לנזקא ואתייהיב ליה רשותא לחבלא. ותא חזי ביעקב מה כתיב ויאמר יעקב לבניו למה תתראו, דלא בעי לאתחזאה קמיה).</p>\n<p><Nonei></i>וּבְגִין דָא, קוּדְשָׁא בְּרִיךְ הוּא אַזְהַר לְהוּ לְיִשְׂרָאֵל לְאִתְקַדָּשָׁא. (כמה דאת אמר) (ד\"א דכתיב), וִהְיִיתֶם קְדוֹשִׁים כִּי קָדוֹשׁ אָנִי. מַאן אָנִי. דָּא קוּדְשָׁא בְּרִיךְ הוּא, מַלְכוּת שָׁמַיִם קַדִּישָׁא. מַלְכוּתָא אַחֲרָא דְּעוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, אִקְרֵי אַחֵר. דִּכְתִיב, (שמות לה) כִּי לא תִשְׁתַּחֲוֶה לְאֵל אַחֵר כִּי יְיָ קַנָּא שְׁמוֹ.</p>\n<p>וְתָּא חֲזֵי, אֲנִי, שָׁלְטָנוּ דְּעַלְמָא דֵין, וְעַלְמָא דְאָתֵי, וְכֹלָּא בֵּיהּ תַּלְיָא. אַחֵר, סִטְרָא מְסָאֲבָא. אַחֵר, סִטְרָא אָחֳרָא בְּסִטְרָא מְסָאֲבָא, וְשׁוּלְטָנוּ דִּילֵיהּ בְּהַאי עַלְמָא, וְלֵית לֵיהּ בְּעַלְמָא דְאָתֵי כְּלוּם. וּבְגִין דָא מַאן דְּאִתְדָּבַּק בְּהַאי אֲנִי, אִית לֵיהּ חוּלָקָא בְּעַלְמָא דֵין וּבְעַלְמָא דְאָתֵי.</p>\n<p>וּמַאן דְּאִתְדָּבַּק בְּהַאי אַחֵר, אִתְאֲבִיד מֵהַהוּא עַלְמָא, וְלֵית לֵיהּ חוּלָקָא בְּעַלְמָא דְאָתֵי. וְאִית לֵיהּ חוּלָקָא בְּהַאי עַלְמָא, בִּמְסָאֲבוּ. בְּגִין דְּהַהוּא מַלְכוּ אַחֲרָא עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, כַּמָּה אִינוּן תְּרֵיסִין גַּרְדִּינִין מְמַנָּן בֵּיהּ, לְשַׁלְּטָאָה בְּהַאי עַלְמָא.</p>\n<p>וּבְגִינֵי כָּךְ, אֱלִישָׁע אַחֵר, דְּנָחַת וְאִתְדָּבַּק בְּהַאי דַרְגָא, אִתְטְרִיד מֵהַהוּא עַלְמָא דְאָתֵי, וְלָא אִתְיְיהִיב לֵיהּ רְשׁוּ לְמֶהדַר בִּתְיוּבְתָּא, וְאִתְטְרִיד מֵהַהוּא עַלְמָא, וְעַל דָּא אִקְרֵי אַחֵר.</p>\n<p>וּבְּגִין כָּךְ בָּעֵי בַר נָשׁ לְאִתְפְּרָשָׁא מִכָּל סִטְרִין, דְּלָא לְאִסְתָּאֲבָא בְּהַהוּא סִטְרָא, לְמִזְכֵּי בְּהַאי עַלְמָא וּבְעַלְמָא דְאָתֵי. וְעַל דָּא, דָּא בְּרָכָה, וְדָא קְלָלָה. דָּא שָׂבָע, וְדָא רָעָב. כֹּלָּא בְּהִפּוּכָא דָּא מִן דָּא. וְהָא אוֹקִימְנָא.</p>\n<p>וּבְגִין כָּךְ, בְּהַהוּא זִמְנָא דִּשְׁנַת הָרָעָב, לֵית לֵיהּ לְבַר נָשׁ לְאִתְחֲזָאָה בְּשׁוּקָא, וְלָא לְאִפְתְּחָא מַבּוּעֵיהּ לְאוֹלָדָא, לְמֵיהַב בְּנִין לְאֵל אַחֵר, וְהָא אִתְּמָר.</p>\n<p>זַכָּאָה אִיהוּ בַר נָשׁ דְּאִסְתַּמַּר לְמֵיהַךְ בְּאֹרַח קְשׁוֹט, וּלְאִתְדַּבְּקָא בְּמָארֵיהּ תָּדִיר. דִּכְתִיב, (דברים י׳:כ׳) וּבוֹ תִדְבָּק. (וכתיב, את יי אלהיך תירא אתו תעבד ובו תדבק) וּבִשְׁמוֹ תִּשָּׁבֵעַ, וּבוֹ תִשָּׁבֵעַ. לָא כְּתִיב, אֶלָּא וּבִשְׁמוֹ. מַאי תִשָּׁבֵעַ, כְּמָה דְאוֹקִימְנָא, לְמֶהֱוֵי מִתְדְּבַּק בְּרָזָא דִמְהֵימְנוּתָא.</p>\n<p>שִׁבְעָה דַּרְגִּין לְעֵילָא עִלָּאִין עַל כֹּלָּא, רָזָא דִּשְׁלִימוּ דִּמְהֵימְנוּתָא. וְרָזָא דְּשִׁבְעָה דַרְגִּין דִּלְתַתָּא מִנַּיְיהוּ, דְּאִינוּן חִבּוּרָא חַד, וְקִשּׁוּרָא חַד, אִלֵּין בְּאִלֵּין, לְמֶהֱוֵי כֻּלְּהוּ חַד. וּבְגִין כָּךְ כְּתִיב, (מלכים א ח׳:ס״ה) שִׁבְעַת יָמִים וְשִׁבְעַת יָמִים י\"ד יוֹם. וְכֹלָּא חַד, וְקִשּׁוּרָא חַד, וְעַל דָּא כְּתִיב וּבִשְׁמוֹ תִּשָּׁבֵעַ, מִלְּעֵילָא וּמִתַּתָּא.</p>\n<p>זַכָּאָה אִיהוּ (נ\"א מאן דזכי לאתדבקא ביה בקודשא בריך הוא כדקא יאות. זכאה הוא בעלמא דין ובעלמא דאתי. דקודשא בריך הוא פתח ליה אוצרין טבין קדישין בשעתא דאצטריך לקבלא צלותא כמה דאת אמר). (נ\"א ומאן דמייחד אלין באלין, עליה כתיב), (דברים כ״ח:י״ב) יִפְתַּח יְיָ לְךָ אֶת אוֹצָרוֹ הַטּוֹב אֶת הַשָּׁמַיִם, אִלֵּין אוֹצָרִין דִּלְעֵילָא וְתַתָּא. שִׁבְעַת יָמִים וְשִׁבְעַת יָמִים כֻּלְּהוּ חַד. דִּכְתִיב, אֶת אוֹצָרוֹ הַטּוֹב אֶת הַשָּׁמַיִם. אוֹצָרוֹ חַד, וְאִיהוּ אֶת הַשָּׁמַיִם. (זכריה ד׳:ב׳) שִׁבְעָה וְשִׁבְעָה מוּצָקוֹת, וְאִינוּן חַד.</p>\n<p>רִבִּי חִיָּיא וְרִבִּי יוֹסֵי הֲווּ אָזְלֵי בְאָרְחָא, אַדְּהָכִי חָמוּ חַד בַר נָשׁ דְּהֲוָה אָתֵי, מִתְעַטֵּף בְּעִטּוּפָא דְמִצְוָה וּכְלֵי זַיְינִין קְטוּרִין תְּחוֹתוֹי. אָמַר רִבִּי חִיָּיא, בַר נָשׁ דֵּין, חַד מִתְּרִין אִית בֵּיהּ. אוֹ זַכָּאָה שְׁלִים אִיהוּ, אוֹ לְרַמָּאָה (את) בְּנֵי עַלְמָא אִיהוּ.</p>\n<p>אָמַר לֵיהּ רִבִּי יוֹסֵי, הָא חֲסִידֵי עֶלְיוֹנִין אָמְרוּ, הֱוֵי דָן לְכָל בַר נָשׁ לִזְכוּ. הָא תָּנִינָן, בַּר נָשׁ דְּנָפִיק לְאָרְחָא, יִתְכַּוֵּין לִתְלַת מִלִּין. לְדוֹרוֹן, לִקְרָבָא, לִצְלוֹתָא. מִנָּלָן מִיַּעֲקֹב, דְּהָא לִתְלַת אִלֵּין אִתְכַּוֵּון, וְזַרִיז גַּרְמֵיהּ לְדוֹרוֹן, לִקְרָבָא, לִצְלוֹתָא. וְהַאי בַר נָשׁ, אָזִיל בְּאָרְחָא אִיהוּ. הָא בֵּיהּ עִטּוּפָא דְמִצְוָה, לִצְלוֹתָא. וְהָא בֵּיהּ כְּלֵי זַיְינִין, לִקְרָבָא. כֵּיוָן דִּתְרֵין אִלֵּין אִית בֵּיהּ, תְּלִיתָאי לָא לְמִרְדַּף אֲבַתְרָהּ.</p>\n<p>כַּד קָרִיב לְגַבַּיְיהוּ, יַהֲבוּ לֵיהּ שְׁלָם וְלָא אָתִיב לוֹן. אָמַר רִבִּי חִיָּיא, הָא חַד מֵאִינוּן <Nonei></i>תְּרֵין, דְּאִתְחַזְּיָין לְמֶהוֵי בֵּיהּ לֵית בֵּיהּ, דְּהָא לָא אַתְקִין גַּרְמֵיהּ לְדוֹרוֹן, וּבְדוֹרוֹן שְׁלָמָא כָּלִיל בֵּיהּ. אָמַר רִבִּי יוֹסֵי, דִּילְמָא אִיהוּ מִשְׁתַּדֵּל בִּצְלוֹתֵיהּ, אוֹ מַרְחִישׁ תַּלְמוּדֵיהּ בְּגִין דְּלָא יְעָקַר לֵיהּ.</p>\n<p>אַזְלֵי כְּחֲדָא, וְלָא מַלִּיל הַהוּא בַר נָשׁ בַּהֲדַיְיהוּ. לְבָתַר אִשְׁתְּמִיטוּ רִבִּי חִיָּיא וְרִבִּי יוֹסֵי וְאִשְׁתַּדָּלוּ בְּאוֹרַיְיתָא. כֵּיוָן דְּחָמָא הַהוּא בַר נָשׁ דְּהֲווּ מִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא, קָרִיב לְגַבַּיְיהוּ וְיָהִיב לוֹן שְׁלָם.</p>\n<p>אָמַר לוֹן, רַבּוֹתַי, בְּמָּה חֲשַׁדְתּוּן לִי, כַּד יַהֲבִיתּוּ לִי שְׁלָם, וְלָא אֲתִיבְנָא לְכוּ. אָמַר לֵיהּ רִבִּי יוֹסֵי, דִּילְמָא צְלוֹתָא הֲוֵית אָמַר, אוֹ מַרְחִישׁ בְּתַלְמוּדָךְ. אָמַר לוֹן, קוּדְשָׁא בְּרִיךְ הוּא יָדִין לְכוּ לְכַף זְכוּ.</p>\n<p>אֲבָל אֵימָא לְכוּ. יוֹמָא חַד הֲוֵינָא אָזִיל בְּאָרְחָא, אַשְׁכַּחְנָא חַד בַר נָשׁ, וְאַקְדִימְנָא לֵיהּ שְׁלָם. וְהַהוּא גַבְרָא הֲוָה לִסְטִים, וְקָם עָלַי, וְצִעֵר לִי. וְאִלְמָלֵא דְאִתְתַּקַּפְנָא בֵּיהּ אִצְטָעַרְנָא. מֵהַהוּא יוֹמָא נָדַרְנָא, דְּלָא לְאַקְדָּמָא שְׁלָם, בַּר לְבַר נָשׁ זַכָּאָה. אֶלָּא אִי יְדַעְנָא בֵּיהּ בְּקַדְמִיתָא, בְּגִין דְּיָכִיל לְצַעֲרָא לִי, וְיִתַתַּקַּף בִּי בְּחֵילָא. בְּגִין דְּאָסִיר לְאַקְדָּמָא שְׁלָם לְבַר נָשׁ חַיָּיבָא. דִּכְתִיב, (ישעיה מט) אֵין שָׁלוֹם אָמַר יְיָ לָרְשָׁעִים.</p>\n<p>וְהַהִיא שַׁעְתָּא דְּחָמֵינָא לְכוּ, וְיַהֲבִיתּוּ לִי שְׁלָם וְלָא אֲתִיבְנָא לְכוּ. חֲשִׁידְנָא לְכוּ. בְּגִין דְּלָא חָמֵינָא בְּכוּ מִצְוָה דְּאִתְחֲזֵי לְבַר. וַהֲוֵינָא כְּמוֹ כֵן מְהַדַּר תַּלְמוּדָאי. אֲבָל הַשְׁתָּא דְּחָמֵינָא בְכוֹ דְּאַתּוּן זַכָּאִין, הָא אָרְחָא מִתְתַּקְּנָא קֳדָמָי.</p>\n<p>פָּתַח וְאֲמַר, (תהילים ע״ג:א׳) מִזְמוֹר לְאָסָף אַךְ טוֹב לְיִשְׂרָאֵל אֱלֹהִים לְבָרֵי לֵבָב. תָּא חֲזֵי, קוּדְשָׁא בְּרִיךְ הוּא עָבַד יְמִינָא וְעָבַד שְׂמָאלָא, לְאַנְהָגָא עַלְמָא. חַד אִקְרֵי טוֹב וְחַד אִקְרֵי רָע. וּבִתְרֵין אִלֵּין אִתְכְּלִיל בַּר נָשׁ, וְאִתְקְרִיב בְּכֹלָּא.</p>\n<p>וְהַהוּא רַע דְּאִיהוּ שְׂמָאלָא, אִתְכְּלִילוּ בֵּיהּ עַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, וְאִתְיְהִיב בְּסִטְרָא דִלְהוֹן. בְּגִין דְּאִינוּן עַרְלֵי לִבָּא, וְעַרְלֵי בִּשְׂרָא, וּלְאִסְתָּאֳבָא בֵּיהּ. אֲבָל בְּיִשְׂרָאֵל מַה כְּתִיב, אַךְ טוֹב לְיִשְׂרָאֵל (כתיב).</p>\n<p>וְאִי תֵימָא לְכֻלְּהוּ, לָאו. אֶלָּא לְאִינוּן דְּלָא אִסְתַאֲבֵי בַּהֲדֵי הַהוּא רָע. דִּכְתִיב, לְבָרֵי לֵבָב. בְּגִין דְּדָא טוֹב וְדָא רַע. טוֹב לְיִשְׂרָאֵל בִּלְחוֹדַיְיהוּ, וְרַע לְעַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת. אַךְ טוֹב לְיִשְׂרָאֵל, בְּגִין לְאִדְבָּקָא בֵּיהּ. וּבְהַאי אִתְדַּבָּקוּ יִשְׂרָאֵל, בְּרָזָא עִלָּאָה, בְּרָזָא דִמְהֵימְנוּתָא, לְמֶהֱוֵי כֹּלָּא חַד. אָמַר רִבִּי יוֹסֵי, זַכָּאִין אֲנַן, דְּלָא שַׁבַּשְׁנָא בָּךְ. וְהָא קוּדְשָׁא בְּרִיךְ הוּא שַׁדְּרָךְ לְגַבָּן.</p>\n<p>אָמַר רִבִּי יוֹסֵי, בְּגִין דְּטוֹב הוּא לְיִשְׂרָאֵל, יִשְׂרָאֵל אִית לוֹן חוּלָקָא בְּעַלְמָא דֵין וּבְעַלְמָא דְאָתֵי. לְמֶחמֵי עֵינָא בְּעֵינָא חֵיזוּ יְקָרָא. כְּמָה דִּכְתִיב, (ישעיהו נ״ב:ח׳) כִּי עַיִן בְּעַיִן יִרְאוּ בְּשׁוּב יְיָ צִיּוֹן. בָּרוּךְ יְיָ לְעוֹלָם אָמֵן וְאָמֵן: (ע\"כ פרשת מקץ)</p>"],[9520011411,"<p>וַיִּגַּשׁ אֵלָיו יְהוּדָה וְגו', רִבִּי אֶלְעָזָר פָּתַח, (ישעיהו ס״ג:ט״ז) כִּי אַתָּה אָבִינוּ כִּי אַבְרָהָם לא יָדְעָנוּ וְיִשְׂרָאֵל לא יַכִּירֶנּוּ אַתָּה ה' אָבִינוּ גוֹאֲלֵנוּ מֵעוֹלָם שְׁמֶךָ. הַאי קְרָא אוּקְמוּהָ, אֲבָל תָּא חֲזֵי, כַּד בָּרָא קוּדְשָׁא בְּרִיךְ הוּא עַלְמָא, כָּל יוֹמָא וְיוֹמָא, עָבִיד עֲבִידְתָּא כְּדְקָא חָזֵי. בְּכָל יוֹמָא וְיוֹמָא כְּמָה דְאִצְטְרִיךְ. כֵּיוָן דְּאָתָא יוֹמָא שְׁתִיתָאָה וְאִצְטְרִיךְ לְמִבְרִי אָדָם, אָתַת אוֹרַיְיתָא קַמֵּיהּ. אָמְרָה (קמי קודשא בריך הוא). הַאי אָדָם דְּאַתְּ <Nonei></i>בָּעֵי לְמִבְרֵי, זַמִּין הוּא לְאַרְגָּזָא קַמָּךְ. אִלְמָלֵא לָא תַאֲרִיךְ רוּגְזָא, טַב לֵיהּ דְּלָא יִתְבְּרֵי. אָמַר לָהּ קוּדְשָׁא בְּרִיךְ הוּא, וְכִי לְמַגָּנָא אִתְקְרֵינָא אֶרֶךְ אַפַּיִם.</p>\n<p>אֶלָּא, כֹּלָּא בְּאוֹרַיְיתָא אִתְבְּרֵי, וְכֹלָּא בְּאוֹרַיְיתָא אִשְׁתַּכְלַל. בְּגִין דְּעַד לָא בָּרָא קוּדְשָׁא בְּרִיךְ הוּא עַלְמָא, אַתְיָין כָּל אַתְוָון קַמֵּיהּ, וְעָאלוּ כָּל חַד וְחַד לְמַפְרֵעַ.</p>\n<p>עָאֳלַת תי\"ו. אָמְרָה קַמֵּיהּ, רְעוּתָךְ לְמִבְרֵי בִּי עַלְמָא, אָמַר לַהּ לָאו, דְּבָךְ זְמִינִין כַּמָּה צַדִּיקַיָא לְמֵימַת, דִּכְתִיב, (יחזקאל ט׳:ד׳) וְהִתְוֵיתָ תָּיו עַל מִצְחוֹת הָאֲנָשִׁים וְגו'. וְתָנִינָן, דִּכְתִיב וּמִמִּקְדָּשִׁי תָּחֵלּוּ. אַל תִּקְרֵי מִמִּקְדָּשִׁי, אֶלָּא מִמְקוּדָּשַׁי. וּבְגִין כָּךְ עַלְמָא לָא יִתְבְּרֵי בָּךְ.</p>\n<p>עָאלוּ תְּלַת אַתְוָון, שִׁי\"ן, קוּ\"ף, רֵי\"שׁ, כָּל חַד וְחַד בִּלְחוֹדוֹי. אָמַר לְהּוּ קוּדְשָׁא בְּרִיךְ הוּא, לָאו אַתּוּן כְּדַאי לְמִבְרֵי בְּכוּ עַלְמָא, דְּהָא אַתּוּן אַתְוָון דְּאִתְקְרֵי בְּכוּ שֶׁקֶר, וְשֶׁקֶר לָאו אִיהוּ כְּדַאי לְמֵיקַם קַמַּאי, וְהָא אוּקְמוּהָ.</p>\n<p>וְעָלוּ פּ\"א צד\"י, וְכֵן כֻּלְּהוּ, עַד דְּמָטוּ אַתְוָון לְאָת כ\"ף. כֵּיוָן דְּנָחַת כּ\"ף מֵעַל כִּתְרָא, אִזְדַּעְזָעוּ עִלָּאֵי וְתַתָּאֵי כו', עַד דְּאִתְקַיֵּים כְּלָא בְּאָת בֵּי\"ת, דְּאִיהוּ סִימָן בְּרָכָה, וּבֵיהּ אִשְׁתָּכְלַל עַלְמָא וְאִתְבְּרֵי.</p>\n<p>וְאִי תֵימָא, דְּאל\"ף אִיהוּ רֵישָׁא דְּכָל (אינון) אַתְוָון, (לאו) יָאוֹת אִיהוּ. אֶלָּא בְּגִין דְּאִתְקְרֵי בֵּיהּ אָרוּר (ובגין דאתקרי בה ארור). וּבְגִין דָּא לָא אִתְבְּרֵי בֵּיהּ עַלְמָא, אַף עַל גַּב דְּאל\"ף אִיהוּ אָת דְּרָזָא עִלָּאָה. בְּגִין דְּלָא לְמֵיהַב דּוּכְתָּא לְסִטְרָא אָחֳרָא דְּאִקְרֵי אָרוּר, לָא אִתְבְּרֵי בֵּיהּ עַלְמָא. וְאִשְׁתַּכְלַל בְּבֵי\"ת עַלְמָא, וּבֵיהּ אִתְבְּרֵי.</p>\n<p>תָּא חֲזֵי, כִּי אַתָּה אָבִינוּ, בְּגִין דְּהַאי עַלְמָא, בְּהַאי דַרְגָּא אִשְׁתַּכְלַל וְאִתְבְּרֵי. וּבַר נַשׁ בֵּיהּ אִתְבְּרֵי, וְנָפַק לְעַלְמָא.</p>\n<p>כִּי אַבְרָהָם לֹא יְדָעָנוּ, דְּהָא אַף עַל גַּב דְּבֵיהּ קִיּוּמָא דְעַלְמָא. לָא אִשְׁתַּדַּל עֲלָן, כְּמָה דְאִשְׁתַּדַּל עַל יִשְׁמָעֵאל. דְּאָמַר, (בראשית י״ז:י״ח) לוּ יִשְׁמָעֵאל יִחְיֶה לְפָנֶיךָ. וְיִשְׂרָאֵל לֹא יַכִּירֶנּוּ, בְּגִין דְּכָל בִּרְכָאן דְּאִצְטְרִיךְ לְבָרְכָא לִבְנוֹי, שָׁבַק לְהַאי דַרְגָּא לְבָרְכָא כֻּלְּהוּ.</p>\n<p>אַתָּה ה' אָבִינוּ, דְּהָא אַנְתְּ קָיְימַת עֲלָן תָּדִיר לְבָרְכָא, וּלְאַשְׁגָּחָא עֲלָן, כְּאַבָּא דְאַשְׁגַּח עַל בְּנִין בְּכָל מַה דְּאִצְטְרִיךְ לוֹן. גּוֹאֲלֵנוּ מֵעוֹלָם שְׁמֶךָ, דְּהָא אַנְתְּ הוּא גוֹאֵל, דְּהָכִי אִתְקְרֵי הַמַּלְאָךְ הַגּוֹאֵל. וְדָא גוֹאֲלֵנוּ מֵעוֹלָם שְׁמֶךָ, שְׁמֶךָ וַדַּאי. תָּנִינָן, אֵין מַפְסִיקִין בֵּין גְּאוּלָּה לִתְפִלָּה, כְּמָה דְלָא מַפְסִיקִין בֵּין תְּפִלָּה שֶׁל יַד לִתְפִלָּה שֶׁל רֹאשׁ. דְּבָעֵי לְמֶחזֵי דְּכֹלָּא חַד, וְהָא אוּקְמוּהָ.</p>"],[9520011412,"<p>רִבִּי יִצְחָק וְרִבִּי יְהוּדָה הֲווּ יַתְבֵי לֵילְיָא חַד וְלָעָאן בְּאוֹרַיְיתָא. אָמַר רִבִּי יִצְחָק לְרִבִּי יְהוּדָה, הָא תָּנִינָן דְּכַד בָּרָא קוּדְשָׁא בְּרִיךְ הוּא עַלְמָא, עֲבַד עַלְמָא תַּתָּאָה כְּגַוְונָא דְעַלְמָא עִלָּאָה. וְכֹלָּא דָּא לָקֳבֵל דָּא. (ד\"א ציין זה למהוי דא לקבל דא) וְאִיהוּ יְקָרֵיהּ לְעֵילָא וְתַתָּא.</p>\n<p>אָמַר רִבִּי יְהוּדָה, הָכִי הוּא וַדַּאי. וּבָרָא אָדָם עַל כֹּלָּא, הֲדָא הוּא דִכְתִיב, (ישעיה מ) אָנֹכִי עָשִׂיתִי אֶרֶץ וְאָדָם עָלֶיהָ בָּרָאתִי. אָנֹכִי עָשִׂיתִי אֶרֶץ וַדַּאי. מַאי טַעְמָא עָשִׂיתִי אֶרֶץ, בְּגִין דְּאָדָם עָלֶיהָ בָּרָאתִי, דְּאִיהוּ קִיוּמָא דְעַלְמָא, לְמֶהֱוֵי כֹּלָּא בִּשְׁלִימוּ חַד.</p>\n<p>פָּתַח וְאָמַר, (ישעיהו מ״ב:ה׳) כֹּה אָמַר הָאֵל ה' בּוֹרֵא הַשָּׁמַיִם וְנוֹטֵיהֶם רוֹקַע הָאָרֶץ וְצֶאֱצָאֶיהָ נוֹתֵן נְשָׁמָה לָעָם עָלֶיהָ וְרוּחַ לַהוֹלְכִים בָּהּ. הַאי קְרָא אוּקְמוּהָ, אֲבָל, כֹּה אָמַר הָאֵל ה' בּוֹרֵא הַשָּׁמַיִם וְנוֹטֵיהֶם, דָּא קוּדְשָׁא בְּרִיךְ הוּא לְעֵילָא לְעֵילָא. דְּאִיהוּ בּוֹרֵא הַשָּׁמַיִם, וְאַתְקִין לֵיהּ תָּדִיר בְּכָל זִמְנָא. רוֹקַע הָאָרֶץ וְצֶאֱצָאֶיהָ, דָּא אַרְעָא קַדִּישָׁא, צְרוֹרָא דְחַיֵּי. נוֹתֵן נְשָׁמָה לָעָם עָלֶיהָ. (הארץ) דָּא הִיא דְּיַהֲבָה נְשָׁמָה וְגו'.</p>\n<p>אָמַר רִבִּי יִצְחָק, כֹּלָּא אִיהוּ לְעֵילָא, דְּהָא מִתַּמָּן נָפְקָא נִשְׁמָתָא דְחַיֵּי, לְהַאי אֶרֶץ. וְהַאי אֶרֶץ, נָקְטָא נִשְׁמָתָא לְמֵיהַב לְכֹלָּא. בְּגִין דְּהַהוּא נָהָר דְּנָגִיד וְנָפִיק, אִיהוּ יָהִיב וְעָיִיל נִשְׁמָתִין לְהַאי אֶרֶץ, וְאִיהוּ נָקְטָא לוֹן וְיָהֲבָא לְכֹלָּא.</p>\n<p>תָּא חֲזֵי, כַּד בָּרָא קוּדְשָׁא בְּרִיךְ הוּא לֵיהּ לְאָדָם, אַכְנִישׁ עַפְרֵיהּ מֵאַרְבַּע סִטְרִין דְּעַלְמָא. וְעֲבַד גַּרְמֵיהּ בְּאֲתַר דְּמַקְדְּשָׁא לְתַתָּא, וְאַמְשִׁיךְ עֲלֵיהּ נִשְׁמָתָא דְחַיֵּי מִבֵּי מַקְדְּשָׁא לְעֵילָא.</p>\n<p>וְנִשְׁמָתָא אִיהִי כְּלִילָא בִּתְלַת דַּרְגִּין, וְעַל דָּא <Nonei></i>תְּלַת שְׁמָהָן אִינוּן לְנִשְׁמָתָא, כְּגַוְונָא דְרָזָא עִלָּאָה. נֶפֶ\"שׁ, רוּ\"חַ, נְשָׁמָ\"ה. נֶפֶשׁ, הָא אוּקְמוּהָ דְּאִיהִי תַּתָּאָה מִכֹּלָּא. רוּחַ, אִיהוּ קִיּוּמָא דְּשָׁלְטָא עַל נֶפֶשׁ, וְאִיהוּ דַרְגָּא עִלָּאָה עֲלָהּ, לְקָיְימָא עֲלָהּ בְּכֹלָּא כְּדְקָא חָזֵי. נְשָׁמָה, אִיהִי קִיּוּמָא עִלָּאָה עַל כֹּלָּא, וְשָׁלְטָא עַל כֹּלָּא, דַּרְגָּא קַדִּישָׁא עִלָּאָה עַל כֻּלְּהוּ.</p>\n<p>וְאִלֵּין תְּלַת דַּרְגִּין, כְּלִילָן בְּהוּ בִּבְנֵי נָשָׁא, לְאִינוּן דְּזָכָאן לְפוּלְחָנָא דְּמָארֵיהוֹן. דְּהָא בְּקַדְמִיתָא אִית בֵּיהּ נֶפֶשׁ, וְאִיהוּ תִּקּוּנָא קַדִּישָׁא לְאִתְתַּקָּנָא בָּהּ בַּר נָשׁ. כֵּיוָן דְּאָתֵי בַּר נָשׁ לְאִתְדַּכָּאָה בְּהַאי דַרְגָא, אִתְתַּקַּן לְאִתְעַטְּרָא בְּרוּחַ. דְּאִיהוּ דַרְגָּא קַדִּישָׁא דְּשָׁרְיָא עַל נֶפֶשׁ לְאִתְעַטְּרָא בֵּיהּ בַּר נָשׁ, הַהוּא דְזָכֵי.</p>\n<p>כֵּיוָן דְּאִסְתַּלַּק בְּהוּ, בְּנֶפֶשׁ וְרוּחַ, וְעָאל וְאִתְתַּקַּן בְּפוּלְחָנָא דְמָארֵיהּ כְּדְקָא יְאוּת. כְּדֵין שַׁרְיָא עֲלֵיהּ נְשָׁמָה. דַּרְגָּא עִלָּאָה קַדִּישָׁא, דְּשָׁלְטָא עַל כֹּלָּא. בְּגִין לְאִתְעַטְּרָא בְּדַרְגָּא עִלָּאָה קַדִּישָׁא. וּכְדֵין אִיהוּ שְׁלִימָא דְּכֹלָּא, שְׁלִים בְּכָל סִטְרִין, לְמִזְכֵּי בְּעַלְמָא דְאָתֵי. וְאִיהוּ רְחִימָא דְּקוּדְשָׁא בְּרִיךְ הוּא, כְּמָא דְאַתְּ אָמֵר, (משלי ח׳:כ״א) לְהַנְחִיל אוֹהֲבַי יֵשׁ. מַאן אִינוּן אוֹהֲבַי, אִלֵּין אִינוּן דְּנִשְׁמָתָא קַדִּישָׁא בְּהוּ.</p>\n<p>אָמַר רִבִּי יְהוּדָה, אִי הָכִי הָא כְּתִיב, (בראשית ז׳:כ״ב) כֹּל אֲשֶׁר נִשְׁמַת רוּחַ חַיִּים בְּאַפָּיו וְגו'. אָמַר לֵיהּ, הָכִי הוּא וַדַּאי. דְּהָא לָא אִשְׁתָּאַר בְּהוּ. מִכָּל אִינוּן דְּהֲווּ בְּהוּ נִשְׁמָתָא קַדִּישָׁא. כְּגוֹן חֲנוֹךְ, יֶרֶד וְכֻלְּהוּ צַדִּיקַיָּא, בְּגִין לַאֲגָנָא עַל אַרְעָא, דְּלָא יִשְׁתֵּצֵי בְּגִינַיְיהוּ. הֲדָא הוּא דִכְתִיב, כֹּל אֲשֶׁר נִשְׁמַת רוּחַ חַיִּים בְּאַפָּיו מִכֹּל אֲשֶׁר בֶּחָרָבָה מֵתוּ. כְּבָר מֵתוּ וְאִסְתַּלָּקוּ מֵעַלְמָא, וְלָא אִשְׁתָּאַר מִנְּהוֹן מַאן דְּיָגִין עַל עַלְמָא בְּהַהוּא זִמְנָא.</p>\n<p>תָּא חֲזֵי, כֹּלָּא אִינוּן דַּרְגִּין, אִלֵּין עַל אִלֵּין. נֶפֶ\"שׁ, רוּ\"חַ, נְשָׁמָ\"ה. דַּרְגָּא עַל דַּרְגָּא. נֶפֶשׁ בְּקַדְמִיתָא, וְאִיהִי דַרְגָּא תַּתָּאָה כִּדְקָאֲמָרָן. רוּחַ לְבָתַר, דְּשַׁרְיָא עַל נֶפֶשׁ וְקָיְימָא עֲלָהּ. נְשָׁמָה, דַּרְגָּא דְסָלְקָא עַל כֹּלָּא, וְאוּקְמוּהָ.</p>\n<p>נֶפֶשׁ, דָּא נֶפֶשׁ דָּוִד, וְאִיהִי דְקָיְימָא לְקַבְּלָא נֶפֶשׁ מֵהַהוּא נָהָר דְּנָגִיד וְנָפִיק. רוּחַ, דָּא רוּחַ דְּקָיְימָא עֲלֵיהּ דְּנַפְשָׁא, וְלֵית קִיּוּמָא לְנֶפֶשׁ אֶלָּא בְּרוּחַ. וְדָא אִיהוּ רוּחַ דְּשַׁרְיָא בֵּין אֶשָּׁא וּמַיָּא, וּמֵהָכָא אִתְּזָן הַאי נֶפֶשׁ.</p>\n<p>רוּחַ, קָיְימָא בְּקִיּוּמָא דְדַרְגָּא אוֹחֲרָא עִלָּאָה דְּאִקְרֵי נְשָׁמָה, דְּהָא מִתַּמָּן נָפְקֵי נֶפֶשׁ וְרוּחַ. מִתַּמָּן אִתְּזָן רוּחַ. וְכַד נָטִיל רוּחַ, כְּדֵין נָטְלָא נֶפֶשׁ, וְכֹלָּא חַד. וְאִתְקְרִיבוּ דָּא בְּדָא. נֶפֶשׁ אִתְקְרִיב בְּרוּחַ, וְרוּחַ אִתְקְרִיב בִּנְשָׁמָה, וְכֹלָּא חַד.</p>\n<p>תָּא חֲזֵי, וַיִּגַּשׁ אֵלָיו, תִּקְרוּבְתָּא דְעַלְמָא בְּעַלְמָא, לְאִתְאַחֲדָא דָּא בְּדָא לְמֶהוֵי כֹּלָּא חַד. בְּגִין דִּיְהוּדָה אִיהוּ מֶלֶךְ וְיוֹסֵף מֶלֶךְ. אִתְקְרִיבוּ דָא בְּדָא, וְאִתְאֲחִידוּ דָּא בְּדָא.</p>"],[9520011413,"<p>רִבִּי יְהוּדָה פָּתַח וְאָמַר, (תהילים מ״ח:ה׳) כִּי הִנֵּה הַמְלָכִים נוֹעֲדוּ, דָּא יְהוּדָה וְיוֹסֵף. בְּגִין דְּתַרְוַויְיהוּ מְלָכִים, וְאִתְקְרִיבוּ דָּא בְּדָא לְאִתְוַוכְּחָא תַּרְוַויְיהוּ כָּחֲדָא. בְּגִין דִּיְהוּדָה אִתְעָרֵב בֵּיהּ בְּבִנְיָמִן, וְהֲוָה עָרֵב לְגַבֵּיהּ דְּאֲבוֹי בֵּיהּ, בְּהַאי עַלְמָא וּבְעַלְמָא דְאָתֵי. וְעַל דָּא אִתְקְרִיב קַמֵּיהּ דְּיוֹסֵף, לְאִתְוַוכְּחָא עִמֵּיהּ עַל עִסְקָא דְבִנְיָמִן, דְּלָא לְמֶהוֵי בְּנִדּוּי. בְּהַאי עַלְמָא וּבְעַלְמָא דְאָתֵי. כְּמָא דְאַתְּ אָמֵר, (בראשית מ״ג:ט׳) אָנֹכִי אֶעֶרְבֶנּוּ מִיָּדִי תְּבַקְּשֶׁנּוּ אִם לא הֲבִיאוֹתִיו אֵלֶיךָ וְהִצַּגְתִּיו לְפָנְיךָ וְחָטָאתִי לְאָבִי כָּל הַיָּמִים. בְּהַאי עַלְמָא וּבְעַלְמָא דְאָתֵי.</p>\n<p>וְעַל דָּא, כִּי הִנֵּה הַמְּלָכִים נוֹעֲדוּ עָבְרוּ יַחְדָּיו, אִתְרְגִיזוּ כְּחֲדָא, וְאִתְרְגִּיזוּ דָּא בְּדָא בְּגִינֵיהּ דְּבִנְיָמִן. מַה כְּתִיב, הֵמָּה רָאוּ כֵּן תָּמָהוּ נִבְהֲלוּ נֶחְפָּזוּ רְעָדָה אֲחָזָתַם שָׁם, לְכָל אִינוּן דְּהֲווּ תַּמָּן. (לכלהו שאר שבטין דהוו תמן).</p>\n<p>חִיל כַּיּוֹלֵדָה, בְּגִין דְּהֲווּ דַּחֲלִין, לְקָטְלָא וּלְאִתְקְטָלָא, וְכֹלָּא בְּגִינֵיהּ דְּבִנְיָמִן. (ד\"א ציין זה מה כתיב כן תמהו נבהלו נחפזו וכלא בגיניה) דְּהָא יוֹסֵף אִזְדַּבַּן בְּגִינֵיהּ דִּיהוּדָה, וְאִתְאֲבִיד מֵאֲבוֹי. וְהַשְׁתָּא אִתְעָרַב בֵּיהּ בְּבִנְיָמִין, וְדָחִיל דְּלָא יִתְאֲבִיד. וּבְגִין כָּךְ וַיִּגַּשׁ אֵלָיו יְהוּדָה.</p>\n<p>דָּבָר אַחֵר, כִּי הִנֵּה הַמְּלָכִים נוֹעֲדוּ, דָּא יְהוּדָה וְיוֹסֵף, <Nonei></i>דְּאִזְדַּמְּנוּ לְאִתְוַכְּחָא דָּא עִם דָּא, לְאִתְוַכְּחָא תַּרְוַויְיהוּ כְּחֲדָא. בְּגִין דִּיהוּדָה הֲוָה מֶלֶךְ, וְיוֹסֵף הֲוָה מֶלֶךְ, וְתַרְוַויְיהוּ אָתוּ כְּחֲדָא לְאִתְוַכְּחָא דָּא עִם דָּא. דָּא עַל בִּנְיָמִן, וְדָא עַל בִּנְיָמִן.</p>\n<p>כִּי הִנֵּה הַמְּלָכִים, אָמַר רִבִּי יְהוּדָה, רָזָא דִמְהֵימְנוּתָא הָכָא, דְּהָא כַּד רְעוּתָא אִשְׁתַּכַּח, וְקִשּׁוּרָא אִתְעַטַּר כְּחֲדָא, כְּדֵין תְּרֵין עָלְמִין מִתְקַשְּׁרָן כְּחֲדָא וְאִזְדַּמְּנָן כְּחֲדָא. דָּא לְאַפְתָּחָא אוֹצָרָא, וְדָא לְלַקְּטָא וּלְמִכְנַשׁ בְּגַוֵּיהּ. וּכְדֵין כִּי הִנֵּה הַמְּלָכִים נוֹעֲדוּ, תְּרֵין עָלְמִין קַדִּישִׁין, עַלְמָא עִלָּאָה וְעַלְמָא תַּתָּאָה.</p>\n<p>עָבְרוּ יַחְדָּיו, רָזָא דְמִלָּה, דְּכַד מִתְחַבְּרָן כְּחֲדָא, כְּדֵין עָבְרוּ יַחְדָּיו. בְּגִין דְּכָל חִיּוּבִין דְּעַלְמָא לָא אִתְעַבְרָן לְאִתְכַּפְיָא, עַד דְּמִתְחַבְּרָן כְּחֲדָא. כְּדִכְתִיב, (מיכה ז׳:י״ח) וְעוֹבֵר עַל פֶּשַׁע. וְעַל דָּא עָבְרוּ יַחְדָּיו. עָבְרוּ, אִינוּן חוֹבִין אִתְכַּפָּרוּ. בְּגִין דְּהָא כְדֵין כָּל אַנְפִּין נְהִירִין, וְכָל חוֹבִין אִתְעֲבָרוּ.</p>\n<p>רִבִּי חִיָּיא אָמַר, רָזָא דָא בְתִקּוּנָא דְּקָרְבָּנָא אִיהוּ. דְּהָא כַּד קָרְבָּנָא אִתְקְרִיב וְכֹלָּא מִסְתַּפְּקִין, וְכָל חַד וְחַד כְּדְקָא חָזֵי לֵיהּ, כְּדֵין אִתְקַשַּׁר כֹּלָּא כְּחֲדָא. וְכָל אַנְפִּין נְהִירִין, וְקִשּׁוּרָא חַד אִשְׁתַּכַּח. וּכְדֵין הַמְּלָכִים נוֹעֲדוּ וְאִזְדַּמְּנוּ כְּחֲדָא, לְכַפָּרָא עַל חוֹבִין, לְאַעֲבָרָא עֲלַיְיהוּ. וּכְדֵין הַמְּלָכִים נוֹעֲדוּ, וְאִתְקַשְּׁרָן כְּחֲדָא. עָבְרוּ יַחְדָּיו, לְאַנְהָרָא כָּל אַנְפִּין, וּלְמֶהֱוֵי כֹּלָּא רְעוּתָא חָדָא.</p>\n<p>הֵמָּה רָאוּ כֵּן תָּמָהוּ, סַלְקָא דַעְתָּךְ דְּאִינוּן מְלָכִים. אֶלָּא אִלֵּין מָארֵיהוֹן דְּדִינִין, דְּחֶדְוָה דִלְהוֹן לְמֶעְבַּד הַהוּא דִינָא דְּאִתְפַּקְּדוּ עֲלֵיהּ. וּכְדֵין, כַּד מְלָכִים אִזְדַּמְּנוּ תַּרְוַויְיהוּ בִּרְעוּתָא חָדָא, כְּדֵין הֵמָה רָאוּ הַהוּא רְעוּתָא דִתְרֵין עָלְמִין. כֵּן תָּמָהוּ נִבְהֲלוּ נֶחְפָּזוּ, בְּגִין דְּכֻלְּהוּ מָארֵי דְדִינָא אִתְכַּפְיָין וּמִתְעַבְרָן מֵעַלְמָא, וְלָא יָכְלֵי לְשַׁלְּטָאָה. וּכְדֵין מִתְעַבְרִין קִיּוּמֵיהוֹן, מְעַבְרִין שָׁלְטָנְהוֹן.</p>\n<p>רִבִּי אֶלְעָזָר אָמַר, וַיִּגַשׁ אֵלָיו יְהוּדָה. מַאי טַעְמָא יְהוּדָה, בְּגִין דְּהָכִי אִצְטְרִיךְ, דְּאִיהוּ עָרַב. כְּמָא דְאַתְּ אָמֵר, כִּי עַבְדְּךָ עָרַב אֶת הַנַּעַר. וְרָזָא דְמִלָּה, יְהוּדָה וְיוֹסֵף הָכִי אִצְטְרִיכוּ לְאִתְקָרְבָא כְּחֲדָא. בְּגִין דְּיוֹסֵף אִיהוּ צַדִּיק, יְהוּדָה אִיהוּ מֶלֶךְ. וְעַל דָּא וַיִּגַּשׁ אֵלָיו יְהוּדָה. בְּגִין דְּקוּרְבָא דִלְהוֹן דְאִתְקְרִיבוּ כְּחֲדָא, גָּרַם כַּמָּה טָבִין לְעַלְמָא. גָּרַם שְׁלָמָא לְכֻלְּהוּ שִׁבְטִין. גָּרַם שְׁלָמָא בֵּינַייהוּ. גָּרַם לְיַעֲקֹב דְּאִתְקְיַּים רוּחָא דִילֵיהּ. כְּמָא דְאַתְּ אָמֵר, (בראשית מ״ה:כ״ז) וַתְּחִי רוּחַ יַעֲקֹב אֲבִיהֶם. וְעַל דָּא קְרִיבוּ דְּדָא עִם דָּא אִצְטְרִיךְ, בְּכֻלְּהוּ סִטְרִין לְעֵילָא וְתַתָּא.</p>"],[9520011414,"<p>רִבִּי אַבָּא פָּתַח וְאָמַר, (תהילים מ״ח:ג׳) יְפֵה נוֹף מְשׂוֹשׂ כָּל הָאָרֶץ הַר צִיּוֹן יַרְכְּתֵי צָפוֹן קִרְיַת מֶלֶךְ רָב. הַאי קְרָא רָזָא דִמְהֵימְנוּתָא אִיהוּ. יְפֵה נוֹף, דָּא אִיהוּ יוֹסֵף הַצַּדִּיק, דִּכְתִיב בֵּיהּ, וַיְהִי יוֹסֵף יְפֵה תֹאַר וִיפֵה מַרְאֶה. מְשׂוֹשׂ כָּל הָאָרֶץ, אִיהוּ חֶדְוָה וְחֵדוּ לְעֵילָא וְתַתָּא. הַר צִיּוֹן יַרְכְּתֵי צָפוֹן, בְּגִין דִּבְחוּלָקֵיהּ קָאִים מַשְׁכְּנָא דְשִׁילֹה, הַר צִיּוֹן דָּא יְרוּשָׁלַ ם. יַרְכְּתֵי צָפוֹן, הָכִי הוּא וַדַּאי לְעֵילָא וְתַתָּא.</p>\n<p>קִרְיַת מֶלֶךְ רָב, אֲתַר אִיהוּ מְתַקְּנָא, לָקֳבֵיל מֶלֶךְ רָב, דָּא מַלְכָּא עִלָּאָה דְּכֹלָּא, קֹדֶשׁ הַקֳּדָשִׁים. דְּהָא מִתַּמָּן אַתְיָא כָּל נְהִירוּ וְכָל בִּרְכָאן וְכָל חֵידוּ דְּכֹלָּא. דְּהָא מִתַּמָּן נָהֲרִין כָּל אַנְפִּין, וּבֵי מַקְדְּשָׁא אִתְבָּרְכָא מִתַּמָּן. וְכַד אִיהִי מִתְבָּרְכָא, מִתַּמָּן נָפְקֵי בִּרְכָאן לְכָל עַלְמָא, דְּהָא כָּל עַלְמָא מִתַּמָּן אִתְבָּרְכָא.</p>"]]});
